INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('855d8967-d433-4ec4-8968-cb53bec512b0', '題華十二判官汝州宅內亭', '題华十二判官汝州宅內亭', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["高居勝景誰能有，佳意幽情共可歡。","新柳遶門青翡翠，修篁浮徑碧琅玕。","步兵阮籍空除屏，彭澤陶潛謾挂冠。","只在城隍也趨府，豈如吾子道斯安。"]', '["高居勝景誰能有，佳意幽情共可歡。","新柳遶门青翡翠，修篁浮徑碧琅玕。","步兵阮籍空除屏，彭澤陶潛謾挂冠。","只在城隍也趨府，豈如吾子道斯安。"]', '诗', 'shi', '', NULL, '題華十二判官汝州宅內亭 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01cc00ab-b96f-4f24-aedd-8e3f0981fdbe', '薛舍人使君觀察韓判官侍御許雨晴到所居既霽先呈即事', '薛舍人使君观察韓判官侍御許雨晴到所居既霽先呈即事', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["江臯昨夜雨收梅，寂寂衡門與釣臺。","西島落花隨水至，前山飛鳥出雲來。","觀風駟馬能言駐，行縣雙旌許蹔迴。","豈不偶然聊爲竹，空令石逕掃莓苔。"]', '["江臯昨夜雨收梅，寂寂衡门與釣台。","西島落花隨水至，前山飞鸟出云来。","观风駟马能言駐，行縣雙旌許蹔迴。","豈不偶然聊爲竹，空令石逕掃莓苔。"]', '诗', 'shi', '', NULL, '薛舍人使君觀察韓判官侍御許雨晴到所居既霽先呈即事 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff32e672-5b8e-45e2-b1dd-c14d0ad909ee', '元日陪早朝', '元日陪早朝', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["斗柄東迴歲又新，邃旒南面挹來賓。","和光髣髴樓臺曉，休氣氛氳天地春。","儀籥不唯丹穴鳥，稱觴半是越裳人。","江臯腐草今何幸，亦與恒星拱北辰。"]', '["斗柄东迴歲又新，邃旒南面挹来賓。","和光髣髴楼台晓，休氣氛氳天地春。","儀籥不唯丹穴鸟，稱觴半是越裳人。","江臯腐草今何幸，亦與恒星拱北辰。"]', '诗', 'shi', '', NULL, '元日陪早朝 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5689f7b8-86c8-4a2d-91e2-2d192f8818ef', '和太原鄭中丞登龍興寺閣', '和太原鄭中丞登龙兴寺閣', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["青窗朱戶半天開，極目凝神望幾迴。","晉國頹墉生草樹，皇家瑞氣在樓臺。","千條水入黃河去，萬點山從紫塞來。","獨恨侍遊違長者，不知高意是誰陪。"]', '["青窗朱戶半天开，極目凝神望幾迴。","晉国頹墉生草樹，皇家瑞氣在楼台。","千條水入黄河去，万点山從紫塞来。","独恨侍游違长者，不知高意是誰陪。"]', '诗', 'shi', '', NULL, '和太原鄭中丞登龍興寺閣 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91ae8451-d75e-4354-9ffa-5a93b3e50c78', '詠德上太原李尚書', '詠德上太原李尚书', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["那以公方郭細侯，幷州非復舊幷州。","九重帝宅司丹地，十萬兵樞擁碧油。","鏘玉半爲趨閤吏，腰金皆是走庭流。","王襃見德空知頌，身在三千最上頭。"]', '["那以公方郭細侯，幷州非复旧幷州。","九重帝宅司丹地，十万兵樞擁碧油。","鏘玉半爲趨閤吏，腰金皆是走庭流。","王襃见德空知頌，身在三千最上头。"]', '诗', 'shi', '', NULL, '詠德上太原李尚書 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d35e86d0-1748-4524-b21a-7e0f05d410a2', '和嚴長官秋日登太原龍興寺閣野望', '和嚴长官秋日登太原龙兴寺閣野望', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["百丈化城樓，君登最上頭。","九霄回棧路，八到視幷州。","煙火遺堯庶，山河啓聖猷。","短垣齊介嶺，片白指分流。","清鐸中天籟，哀鳴下界秋。","境閑知道勝，心遠見名浮。","豈念乘肥馬，方應駕大牛。","自憐蓬逐吹，不得與良遊。"]', '["百丈化城楼，君登最上头。","九霄回棧路，八到視幷州。","煙火遺堯庶，山河啓聖猷。","短垣齊介嶺，片白指分流。","清鐸中天籟，哀鳴下界秋。","境闲知道勝，心远见名浮。","豈念乘肥马，方應駕大牛。","自怜蓬逐吹，不得與良游。"]', '诗', 'shi', '', NULL, '和嚴長官秋日登太原龍興寺閣野望 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c38a63bc-bf26-4379-8a83-eaebcab303b6', '小苑春望宮池柳色', '小苑春望宮池柳色', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["東風韶景至，垂柳御溝新。","媚作千門秀，連爲一道春。","柔荑生女指，嫩葉長龍鱗。","舞絮迴青岸，翻煙拂綠蘋。","王孫初命賞，佳客欲傷神。","芳意堪相贈，一枝先遠人。"]', '["东风韶景至，垂柳御溝新。","媚作千门秀，連爲一道春。","柔荑生女指，嫩葉长龙鱗。","舞絮迴青岸，翻煙拂綠蘋。","王孫初命賞，佳客欲傷神。","芳意堪相贈，一枝先远人。"]', '诗', 'shi', '', NULL, '小苑春望宮池柳色 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97fa05d3-e555-40af-aa33-ac4bb3750bf0', '蜀門與林藴分路後屢有山川似閩中因寄林藴藴亦閩人也', '蜀门與林藴分路後屢有山川似閩中因寄林藴藴亦閩人也', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["村步如延壽，川原似福平。","無人相共識，獨自故鄉情。"]', '["村步如延壽，川原似福平。","無人相共識，独自故乡情。"]', '诗', 'shi', '', NULL, '蜀門與林藴分路後屢有山川似閩中因寄林藴藴亦閩人也 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a794755-ce81-4b97-a3d2-48cbdb28ae9e', '讀周太公傳', '读周太公傳', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["論兵去商虐，講德興周道。","屠沽未遇時，豈異茲川老。"]', '["論兵去商虐，講德兴周道。","屠沽未遇时，豈異茲川老。"]', '诗', 'shi', '', NULL, '讀周太公傳 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eda2e48-d0fb-418a-8b38-84d705bd4cde', '樂津店北陂', '乐津店北陂', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["嬋娟有麗玉如也，美笑當予繫予馬。","羅幃碧簟豈相容，行到山頭憶山下。"]', '["嬋娟有丽玉如也，美笑當予繫予马。","羅幃碧簟豈相容，行到山头憶山下。"]', '诗', 'shi', '', NULL, '樂津店北陂 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7cddc61-5ae5-4032-a44e-43c6e1da0566', '出蜀門', '出蜀门', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["北客今朝出蜀門，翛然領得入時魂。","遊人莫道歸來易，三不曾聞古老言。"]', '["北客今朝出蜀门，翛然領得入时魂。","游人莫道归来易，三不曾闻古老言。"]', '诗', 'shi', '', NULL, '出蜀門 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ec74fde-5b02-4481-88f7-07670a452d04', '題第五司戶侍御', '題第五司戶侍御', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["曾稱野鶴比羣公，忽作長松向府中。","驄馬不騎人不識，冷然三尺別生風。"]', '["曾稱野鹤比羣公，忽作长松向府中。","驄马不騎人不識，冷然三尺別生风。"]', '诗', 'shi', '', NULL, '題第五司戶侍御 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7c69883-1ef7-4791-aad3-a5f030d5eed0', '建溪行待陳詡', '建溪行待陳詡', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["偕行那得會心期，先者貪前後者遲。","空憶麗詞能狀物，每看奇異但相思。"]', '["偕行那得會心期，先者貪前後者遲。","空憶丽词能狀物，每看奇異但相思。"]', '诗', 'shi', '', NULL, '建溪行待陳詡 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7070422c-8945-4916-baa0-31ab2febfb20', '述德上興元嚴僕射', '述德上兴元嚴僕射', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["推車閫外主恩新，今日梁川草遍春。","玉色據鞍雙節下，揚兵百萬路無塵。"]', '["推车閫外主恩新，今日梁川草遍春。","玉色據鞍雙節下，揚兵百万路無塵。"]', '诗', 'shi', '', NULL, '述德上興元嚴僕射 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cb358f3-1e3d-4422-b218-56eb2d719e8b', '許州送張中丞出臨潁鎮', '許州送張中丞出臨潁鎮', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["心誦陰符口不言，風驅千騎出轅門。","孫吳去後無長策，誰敵留侯直下孫。"]', '["心誦陰符口不言，风驱千騎出轅门。","孫吳去後無长策，誰敵留侯直下孫。"]', '诗', 'shi', '', NULL, '許州送張中丞出臨潁鎮 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f05df1de-4fe9-47c8-82c3-1dc42796bc22', '覩亡友題詩處', '覩亡友題诗处', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["舊友親題壁上詩，傷看緣跡不緣詞。","門前猶是長安道，無復迴車下筆時。"]', '["旧友親題壁上诗，傷看緣跡不緣词。","门前猶是长安道，無复迴车下笔时。"]', '诗', 'shi', '', NULL, '覩亡友題詩處 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66255388-5cf2-427f-861f-7809a38dde30', '題秦嶺', '題秦嶺', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["南下斯須隔帝鄉，北行一步掩南方。","悠悠煙景兩邊意，蜀客秦人各斷腸。"]', '["南下斯須隔帝乡，北行一步掩南方。","悠悠煙景兩邊意，蜀客秦人各斷腸。"]', '诗', 'shi', '', NULL, '題秦嶺 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80ae0056-53e2-4922-9a5d-aa6822753297', '自南山却赴京師石臼嶺頭即事寄嚴僕射', '自南山却赴京師石臼嶺头即事寄嚴僕射', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["鳥企蛇盤地半天，下窺千仞到浮煙。","因高回望沾恩處，認得梁州落日邊。"]', '["鸟企蛇盤地半天，下窺千仞到浮煙。","因高回望沾恩处，認得梁州落日邊。"]', '诗', 'shi', '', NULL, '自南山却赴京師石臼嶺頭即事寄嚴僕射 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bed5209b-488b-44e0-b075-3a9d5c10a43b', '與洪孺卿自梁州迴途中經駱谷見野果有閩中懸壺子即同採摘因呈之洪亦閩人', '與洪孺卿自梁州迴途中經駱谷见野果有閩中懸壺子即同採摘因呈之洪亦閩人', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["青苞朱實忽離離，摘得盈筐淚更垂。","上德同之豈無意，故園山路一枝枝。"]', '["青苞朱實忽離離，摘得盈筐泪更垂。","上德同之豈無意，故园山路一枝枝。"]', '诗', 'shi', '', NULL, '與洪孺卿自梁州迴途中經駱谷見野果有閩中懸壺子即同採摘因呈之洪亦閩人 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb341afc-6306-4758-9cc0-48d26463dd66', '韋晤宅聽歌', '韋晤宅听歌', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["服製虹霓鬢似雲，蕭郎屋裏上清人。","等閑逐酒傾杯樂，飛盡虹梁一夜塵。"]', '["服製虹霓鬢似云，蕭郎屋裏上清人。","等闲逐酒傾杯乐，飞尽虹梁一夜塵。"]', '诗', 'shi', '', NULL, '韋晤宅聽歌 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef440ea8-c82e-480f-a12a-c0bb31f8c8ca', '與林藴同之蜀途次嘉陵江認得越鳥聲呈林林亦閩中人也', '與林藴同之蜀途次嘉陵江認得越鸟声呈林林亦閩中人也', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["正是閩中越鳥聲，幾回留聽暗沾纓。","傷心激念君深淺，共有離鄉萬里情。"]', '["正是閩中越鸟声，幾回留听暗沾纓。","傷心激念君深淺，共有離乡万里情。"]', '诗', 'shi', '', NULL, '與林藴同之蜀途次嘉陵江認得越鳥聲呈林林亦閩中人也 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b8e247e-6bcc-476b-94d8-1cdff649e142', '送聞上人遊嵩山', '送闻上人游嵩山', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["二室峯峯昔願遊，從雲從鶴思悠悠。","丹梯石路君先去，爲上青冥最上頭。"]', '["二室峯峯昔願游，從云從鹤思悠悠。","丹梯石路君先去，爲上青冥最上头。"]', '诗', 'shi', '', NULL, '送聞上人遊嵩山 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58a44419-4efb-4b61-b76c-2f8c54a9e852', '永安寺照上人房', '永安寺照上人房', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["草席蒲團不掃塵，松閑石上似無人。","羣陰欲午鐘聲動，自煮溪蔬養幻身。"]', '["草席蒲團不掃塵，松闲石上似無人。","羣陰欲午鐘声动，自煮溪蔬養幻身。"]', '诗', 'shi', '', NULL, '永安寺照上人房 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f14cd215-be6a-4661-80b6-ebfbca36c438', '山中老僧', '山中老僧', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["笑向來人話古時，繩牀竹杖自扶持。","秋深頭冷不能剃，白黑蒼然髪到眉。"]', '["笑向来人話古时，繩牀竹杖自扶持。","秋深头冷不能剃，白黑蒼然髪到眉。"]', '诗', 'shi', '', NULL, '山中老僧 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee3a748c-e210-472d-99bb-71831799d10d', '贈魯山李明府', '贈魯山李明府', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["外戶通宵不閉關，抱孫弄子萬家閑。","若將邑號稱賢宰，又是皇唐李魯山。"]', '["外戶通宵不閉关，抱孫弄子万家闲。","若將邑號稱賢宰，又是皇唐李魯山。"]', '诗', 'shi', '', NULL, '贈魯山李明府 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ca644ee-c880-47fa-a80b-ed18ae8d973d', '泉州赴上都留別舍弟及故人', '泉州赴上都留別舍弟及故人', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["天長地闊多岐路，身即飛蓬共水萍。","匹馬將驅豈容易，弟兄親故滿離亭。"]', '["天长地闊多岐路，身即飞蓬共水萍。","匹马將驱豈容易，弟兄親故满離亭。"]', '诗', 'shi', '', NULL, '泉州赴上都留別舍弟及故人 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8931a16d-73b3-48c5-bb27-b856f92a700d', '送張驃騎邠寧行營', '送張驃騎邠寧行營', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["寶馬琱弓金僕姑，龍驤虎視出皇都。","揚鞭莫怪輕胡虜，曾在漁陽敵萬夫。"]', '["寶马琱弓金僕姑，龙驤虎視出皇都。","揚鞭莫怪轻胡虜，曾在漁陽敵万夫。"]', '诗', 'shi', '', NULL, '送張驃騎邠寧行營 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f1f1858-9efe-4e97-b679-db52d06f08e1', '題棃嶺', '題棃嶺', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["南北風煙即異方，連峯危棧倚蒼蒼。","哀猨咽水偏高處，誰不沾衣望故鄉。"]', '["南北风煙即異方，連峯危棧倚蒼蒼。","哀猨咽水偏高处，誰不沾衣望故乡。"]', '诗', 'shi', '', NULL, '題棃嶺 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7b91849-3907-488f-ba7f-e3e758b5cccd', '秋夜寄僧', '秋夜寄僧', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["尚被浮名誘此身，今時誰與德爲鄰。","遙知是夜檀溪上，月照千峯爲一人。"]', '["尚被浮名誘此身，今时誰與德爲鄰。","遙知是夜檀溪上，月照千峯爲一人。"]', '诗', 'shi', '', NULL, '秋夜寄僧 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8caeacee-deaf-4bd0-8239-0e17328c4d13', '觀送葬', '观送葬', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["何事悲酸淚滿巾，浮生共是北邙塵。","他時不見北山路，死者還曾哭送人。"]', '["何事悲酸泪满巾，浮生共是北邙塵。","他时不见北山路，死者還曾哭送人。"]', '诗', 'shi', '', NULL, '觀送葬 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0a09c3b-54ff-48e6-b5e6-371387278537', '宿建溪中宵即事', '宿建溪中宵即事', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["𥳌{𥫗/窮}一席眠還坐，蛙噪螢飛夜未央。","僮僕舟人空寂寂，隔簾微月入中倉。"]', '["𥳌{𥫗/窮}一席眠還坐，蛙噪螢飞夜未央。","僮僕舟人空寂寂，隔簾微月入中倉。"]', '诗', 'shi', '', NULL, '宿建溪中宵即事 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c55d61ca-f437-40dd-b84d-92fda8e2a83f', '題王明府郊亭', '題王明府郊亭', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["日日郊亭啓竹扉，論桑勸穡是常機。","山城要得牛羊下，方與農人分背歸。"]', '["日日郊亭啓竹扉，論桑勸穡是常機。","山城要得牛羊下，方與農人分背归。"]', '诗', 'shi', '', NULL, '題王明府郊亭 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fbde34e-6692-4e18-bd4c-71ad7b3dbbac', '塞上行', '塞上行', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["聞說胡兵欲利秋，昨來投筆到營州。","驍雄已許將軍用，邊塞無勞天子憂。"]', '["闻说胡兵欲利秋，昨来投笔到營州。","驍雄已許將軍用，邊塞無勞天子憂。"]', '诗', 'shi', '', NULL, '塞上行 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af215778-668a-4186-bf55-d25cc6791ec9', '題別業', '題別業', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["千山江上背斜暉，一徑中峯見所歸。","不信扁舟迴在晚，宿雲先已到柴扉。"]', '["千山江上背斜暉，一徑中峯见所归。","不信扁舟迴在晚，宿云先已到柴扉。"]', '诗', 'shi', '', NULL, '題別業 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ee4a403-4578-4bde-bb43-b5e7e5f296ed', '九日廣陵登高懷邵二先輩', '九日廣陵登高懷邵二先輩', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["簪萸泛菊俯平阡，飲過三杯却惘然。","十歲此辰同醉友，登高各處已三年。"]', '["簪萸泛菊俯平阡，饮過三杯却惘然。","十歲此辰同醉友，登高各处已三年。"]', '诗', 'shi', '', NULL, '九日廣陵登高懷邵二先輩 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4001fe9b-8bc2-44f7-9b23-9436708a523b', '題延平劒潭', '題延平劒潭', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["想象精靈欲見難，通津一去水漫漫。","空餘昔日凌霜色，長與澄潭生晝寒。"]', '["想象精靈欲见难，通津一去水漫漫。","空餘昔日凌霜色，长與澄潭生晝寒。"]', '诗', 'shi', '', NULL, '題延平劒潭 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27114f2b-7cd1-4aea-8020-c80155a8885e', '晚泊漳州營頭亭', '晚泊漳州營头亭', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["迴峯疊嶂遶庭隅，散點煙霞勝畫圖。","日暮華軒卷長箔，太清雲上對蓬壺。"]', '["迴峯叠嶂遶庭隅，散点煙霞勝畫圖。","日暮华軒卷长箔，太清云上对蓬壺。"]', '诗', 'shi', '', NULL, '晚泊漳州營頭亭 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85864d15-6ae3-468a-9559-08a310507242', '贈山南嚴兵馬使', '贈山南嚴兵马使', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["爲鴈爲鴻弟與兄，如雕如鶚傑連英。","天旋地轉煙雲黑，共鼓長風六合清。"]', '["爲鴈爲鴻弟與兄，如雕如鶚傑連英。","天旋地轉煙云黑，共鼓长风六合清。"]', '诗', 'shi', '', NULL, '贈山南嚴兵馬使 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68479c4e-2461-4f27-8810-95565529446b', '除夜侍酒呈諸兄示舍弟', '除夜侍酒呈諸兄示舍弟', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["莫歎明朝又一春，相看堪共貴茲身。","悠悠寰宇同今夜，膝下傳杯有幾人。"]', '["莫歎明朝又一春，相看堪共貴茲身。","悠悠寰宇同今夜，膝下傳杯有幾人。"]', '诗', 'shi', '', NULL, '除夜侍酒呈諸兄示舍弟 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('506593fa-4613-495c-99df-9cc35ac6e058', '皇武 一', '皇武 一', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["皇耆其武，于溵于淮。","既巾乃車，環蔡具來。","狡衆昏嚚，甚毒于酲。","狂奔呌呶，以干大刑。"]', '["皇耆其武，于溵于淮。","既巾乃车，环蔡具来。","狡衆昏嚚，甚毒于酲。","狂奔呌呶，以干大刑。"]', '诗', 'shi', '', NULL, '皇武 一 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7300491-6061-4e49-980c-76ca3da9882d', '皇武 二', '皇武 二', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["皇咨于度，惟汝一德。","曠誅四紀，其徯汝克。","錫汝斧鉞，其往視師。","師是蔡人，以宥以釐。"]', '["皇咨于度，惟汝一德。","曠誅四紀，其徯汝克。","錫汝斧鉞，其往視師。","師是蔡人，以宥以釐。"]', '诗', 'shi', '', NULL, '皇武 二 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('301414a1-bb58-41cb-94e3-c80b09371490', '皇武 三', '皇武 三', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["度拜稽首，廟于元龜。","既禡既類，于社是宜。","金節煌煌，錫盾雕戈。","犀甲熊旂，威命是荷。"]', '["度拜稽首，廟于元龟。","既禡既類，于社是宜。","金節煌煌，錫盾雕戈。","犀甲熊旂，威命是荷。"]', '诗', 'shi', '', NULL, '皇武 三 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25d55e99-63e4-49b3-b303-45e00cd6baa6', '皇武 四', '皇武 四', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["度拜稽首，出次于東。","天子餞之，罍斝是崇。","鼎臑俎胾，五獻百籩。","凡百卿士，班以周旋。"]', '["度拜稽首，出次于东。","天子餞之，罍斝是崇。","鼎臑俎胾，五獻百籩。","凡百卿士，班以周旋。"]', '诗', 'shi', '', NULL, '皇武 四 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f9780ae-224e-4f08-9238-354c2fbdb3e3', '皇武 五', '皇武 五', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["既涉于滻，乃翼乃前。","孰圖厥猶，其佐多賢。","宛宛周道，于山于川。","遠揚邇昭，陟降連連。"]', '["既涉于滻，乃翼乃前。","孰圖厥猶，其佐多賢。","宛宛周道，于山于川。","远揚邇昭，陟降連連。"]', '诗', 'shi', '', NULL, '皇武 五 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67c391a9-e57e-46f3-a213-27338f012939', '皇武 六', '皇武 六', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["我斾我旗，于道于陌。","訓于羣帥，拳勇來格。","公曰徐之，無恃頟頟。","式和爾容，惟義之宅。"]', '["我斾我旗，于道于陌。","訓于羣帥，拳勇来格。","公曰徐之，無恃頟頟。","式和爾容，惟義之宅。"]', '诗', 'shi', '', NULL, '皇武 六 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7823b47b-9a7a-41e8-b6b8-859b4c9e039e', '皇武 七', '皇武 七', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["進次于郾，彼昏卒狂。","裒兇鞠頑，鋒蝟斧螗。","赤子匍匐，厥父是亢。","怒其萌芽，以悖太陽。"]', '["進次于郾，彼昏卒狂。","裒兇鞠頑，鋒蝟斧螗。","赤子匍匐，厥父是亢。","怒其萌芽，以悖太陽。"]', '诗', 'shi', '', NULL, '皇武 七 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c311edd-164b-446a-a252-c938fb7ea498', '皇武 八', '皇武 八', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["王旅渾渾，是佚是怙。","既獲敵師，若飢得餔。","蔡兇伊窘，悉起來聚。","左擣其虛，靡愆厥慮。"]', '["王旅渾渾，是佚是怙。","既獲敵師，若飢得餔。","蔡兇伊窘，悉起来聚。","左擣其虛，靡愆厥慮。"]', '诗', 'shi', '', NULL, '皇武 八 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('088bc124-269b-4db3-8529-582b48e9964c', '皇武 九', '皇武 九', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["載闢載袚，丞相是臨。","弛其武刑，諭我德心。","其危既安，有長如林。","曾是讙譊，化爲謳吟。"]', '["載闢載袚，丞相是臨。","弛其武刑，諭我德心。","其危既安，有长如林。","曾是讙譊，化爲謳吟。"]', '诗', 'shi', '', NULL, '皇武 九 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc0557d9-6129-43d9-a338-783f33ca8cc2', '皇武 十', '皇武 十', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["皇曰來歸，汝復相予。","爵之成國，胙以夏區。","度拜稽首，天子聖神。","度拜稽首，皇祐下人。"]', '["皇曰来归，汝复相予。","爵之成国，胙以夏區。","度拜稽首，天子聖神。","度拜稽首，皇祐下人。"]', '诗', 'shi', '', NULL, '皇武 十 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5df4d53a-2b2b-43ea-939c-40b4b751b22f', '皇武 十一', '皇武 十一', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["淮夷既平，震是朔南。","宜廟宜郊，以告德音。","歸牛休馬，豐稼于埜。","我武惟皇，永保無疆。"]', '["淮夷既平，震是朔南。","宜廟宜郊，以告德音。","归牛休马，豐稼于埜。","我武惟皇，永保無疆。"]', '诗', 'shi', '', NULL, '皇武 十一 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03d78bae-f4c6-409f-b13b-93818f3af0ed', '方城 一', '方城 一', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["方城臨臨，王卒峙之。","匪徼匪競，皇有正命。","皇命于愬，往舒余仁。","踣彼艱頑，柔惠是馴。"]', '["方城臨臨，王卒峙之。","匪徼匪競，皇有正命。","皇命于愬，往舒余仁。","踣彼艱頑，柔惠是馴。"]', '诗', 'shi', '', NULL, '方城 一 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a4cf46c-0a8a-4a6a-b73f-58816987dc24', '方城 二', '方城 二', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["愬拜即命，于皇之訓。","既礪既攻，以後厥刃。","王師嶷嶷，熊羆是式。","銜勇韜力，日思予殛。"]', '["愬拜即命，于皇之訓。","既礪既攻，以後厥刃。","王師嶷嶷，熊羆是式。","銜勇韜力，日思予殛。"]', '诗', 'shi', '', NULL, '方城 二 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0a54d7f-1aba-417d-b1c8-1ca7d6720816', '方城 三', '方城 三', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["寇昏以狂，敢蹈愬疆。","士獲厥心，大袒高驤。","長戟酋矛，粲其綏章。","右翦左屠，聿禽其良。"]', '["寇昏以狂，敢蹈愬疆。","士獲厥心，大袒高驤。","长戟酋矛，粲其綏章。","右翦左屠，聿禽其良。"]', '诗', 'shi', '', NULL, '方城 三 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c897bd8-5e07-4329-b856-820eeefb9d9a', '方城 四', '方城 四', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["其良既宥，告以父母。","恩柔于肌，卒貢爾有。","維彼攸恃，乃偵乃誘維彼攸宅，乃發乃守。"]', '["其良既宥，告以父母。","恩柔于肌，卒貢爾有。","維彼攸恃，乃偵乃誘維彼攸宅，乃發乃守。"]', '诗', 'shi', '', NULL, '方城 四 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60ec9b1a-f3d4-4b7f-bdcb-f8e140012d97', '方城 五', '方城 五', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["其恃爰獲，我功我多。","陰諜厥圖，以究爾訛。","雨雪洋洋，大風來加。","于燠其寒，于邇其遐。"]', '["其恃爰獲，我功我多。","陰諜厥圖，以究爾訛。","雨雪洋洋，大风来加。","于燠其寒，于邇其遐。"]', '诗', 'shi', '', NULL, '方城 五 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82cd4938-3373-4c37-b947-bb908cd2d306', '方城 六', '方城 六', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["汝陰之茫，懸瓠之峨。","是震是拔，大殲厥家。","狡虜既縻，輸于國都。","示之市人，即社行誅。"]', '["汝陰之茫，懸瓠之峨。","是震是拔，大殲厥家。","狡虜既縻，輸于国都。","示之市人，即社行誅。"]', '诗', 'shi', '', NULL, '方城 六 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('101f6bee-402d-4a35-971d-367297b35963', '方城 七', '方城 七', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["乃諭乃止，蔡有厚喜。","完其室家，仰父俯子。","汝水沄沄，既清而瀰。","蔡人行歌，我步逶遲。"]', '["乃諭乃止，蔡有厚喜。","完其室家，仰父俯子。","汝水沄沄，既清而瀰。","蔡人行歌，我步逶遲。"]', '诗', 'shi', '', NULL, '方城 七 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b80e7522-fde3-4d6f-88cf-7681955a0aac', '方城 八', '方城 八', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["蔡人歌矣，蔡風和矣。","孰颣蔡初，胡甈爾居。","式慕以康，爲愿有餘。","是究是咨，皇德既舒。"]', '["蔡人歌矣，蔡风和矣。","孰颣蔡初，胡甈爾居。","式慕以康，爲愿有餘。","是究是咨，皇德既舒。"]', '诗', 'shi', '', NULL, '方城 八 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd9c37f9-68e7-4ff9-85bd-0c77906e91a2', '方城 九', '方城 九', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["皇曰咨愬，裕乃父功。","昔我文祖，惟西平是庸。","內誨于家，外刑于邦。","孰是蔡人，而不率從。"]', '["皇曰咨愬，裕乃父功。","昔我文祖，惟西平是庸。","內誨于家，外刑于邦。","孰是蔡人，而不率從。"]', '诗', 'shi', '', NULL, '方城 九 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e27f410-6881-456b-b383-588a75931af9', '方城 十', '方城 十', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["蔡人率止，惟西平有子。","西平有子，惟我有臣。","疇允大邦，俾惠我人。","于廟告功，以顧萬方。"]', '["蔡人率止，惟西平有子。","西平有子，惟我有臣。","疇允大邦，俾惠我人。","于廟告功，以顧万方。"]', '诗', 'shi', '', NULL, '方城 十 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5dd74de-3d63-4970-b23d-1374ed88ad76', '唐鐃歌妓吹曲十二篇', '唐鐃歌妓吹曲十二篇', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["晉陽武，奮義威。","煬之渝，德焉歸。","氓畢屠，綏者誰。","皇烈烈，專天機。","號以仁，揚其旗。","日之昇，九土晞。","斥田坼，流洪輝。","有其二，翼餘隋。","斮梟鷔，連熊螭。","枯以肉，勍者羸。","后土蕩，玄穹彌。","合之育，莾然施。","惟德輔，慶無期。"]', '["晉陽武，奮義威。","煬之渝，德焉归。","氓畢屠，綏者誰。","皇烈烈，專天機。","號以仁，揚其旗。","日之昇，九土晞。","斥田坼，流洪輝。","有其二，翼餘隋。","斮梟鷔，連熊螭。","枯以肉，勍者羸。","后土蕩，玄穹彌。","合之育，莾然施。","惟德輔，慶無期。"]', '诗', 'shi', '', NULL, '唐鐃歌妓吹曲十二篇 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b54e6d4e-5c99-4e41-84b0-1be53f3c3da9', '唐鐃歌妓吹曲十二篇', '唐鐃歌妓吹曲十二篇', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["獸之窮，奔大麓。","天厚黃德，狙獷服。","甲之櫜，弓弭矢箙。","皇旅靖，敵逾蹙。","自亡其徒，匪予戮。","屈𧸾猛，虔慄慄。","縻以尺組，噉以秩。","黎之陽，土茫茫。","富兵戎，盈倉箱。","乏者德，莫能享。","驅豺兕，授我疆。"]', '["獸之窮，奔大麓。","天厚黄德，狙獷服。","甲之櫜，弓弭矢箙。","皇旅靖，敵逾蹙。","自亡其徒，匪予戮。","屈𧸾猛，虔慄慄。","縻以尺組，噉以秩。","黎之陽，土茫茫。","富兵戎，盈倉箱。","乏者德，莫能享。","驱豺兕，授我疆。"]', '诗', 'shi', '', NULL, '唐鐃歌妓吹曲十二篇 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccc2ad15-c3f4-4611-9460-b9890b904aca', '唐鐃歌妓吹曲十二篇', '唐鐃歌妓吹曲十二篇', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["戰武牢，動河朔。","逆之助，圖掎角。","怒鷇麛，抗喬嶽。","翹萌牙，傲霜雹。","王謀內定，申掌握。","鋪施芟夷，二主縛。","憚華戎，廓封略。","命之瞢，卑以斮。","歸有德，唯先覺。"]', '["戰武牢，动河朔。","逆之助，圖掎角。","怒鷇麛，抗喬嶽。","翹萌牙，傲霜雹。","王謀內定，申掌握。","鋪施芟夷，二主縛。","憚华戎，廓封略。","命之瞢，卑以斮。","归有德，唯先覺。"]', '诗', 'shi', '', NULL, '唐鐃歌妓吹曲十二篇 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a6b9cdc-85a0-4ec8-aae6-f2e9c7ab3348', '唐鐃歌妓吹曲十二篇', '唐鐃歌妓吹曲十二篇', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["涇水黃，隴野茫。","負太白，騰天狼。","有鳥鷙立，羽翼張。","鈎喙決前，鉅趯傍。","怒飛飢嘯，翾不可當。","老雄死，子復良。","巢岐飲渭，肆翱翔。","頓地紘，提天綱。","列缺掉幟，招搖耀鋩。","鬼神來助，夢嘉祥。","腦塗原野，魄飛揚。","星辰復，恢一方。"]', '["涇水黄，隴野茫。","負太白，腾天狼。","有鸟鷙立，羽翼張。","鈎喙決前，鉅趯傍。","怒飞飢嘯，翾不可當。","老雄死，子复良。","巢岐饮渭，肆翱翔。","頓地紘，提天綱。","列缺掉幟，招搖耀鋩。","鬼神来助，梦嘉祥。","腦塗原野，魄飞揚。","星辰复，恢一方。"]', '诗', 'shi', '', NULL, '唐鐃歌妓吹曲十二篇 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75ddf192-9207-4c1a-96b7-782817cc3c51', '唐鐃歌妓吹曲十二篇', '唐鐃歌妓吹曲十二篇', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["奔鯨沛，盪海垠。","吐霓翳日，腥浮雲。","帝怒下顧，哀墊昏。","授以神柄，推元臣。","手援天矛，截脩鱗。","披攘蒙霿，開海門。","地平水靜，浮天根。","羲和顯耀，乘清氛。","赫炎溥暢，融大鈞。"]', '["奔鯨沛，盪海垠。","吐霓翳日，腥浮云。","帝怒下顧，哀墊昏。","授以神柄，推元臣。","手援天矛，截脩鱗。","披攘蒙霿，开海门。","地平水静，浮天根。","羲和显耀，乘清氛。","赫炎溥暢，融大鈞。"]', '诗', 'shi', '', NULL, '唐鐃歌妓吹曲十二篇 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc95ff9b-7918-4588-9624-6dbe9678c325', '唐鐃歌妓吹曲十二篇', '唐鐃歌妓吹曲十二篇', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["苞枿𪒶矣，惟根之蟠。","彌巴蔽荆，負南極以安。","[冃]我舊梁氏，緝綏艱難。","江漢之阻，都邑固以完。","聖人作，神武用。","有臣勇智，奮不以衆。","投跡死地，謀猷縱。","化敵爲家，慮則中。","浩浩海裔，不威而同。","係縲降王，定厥功。","澶漫萬里，宣唐風。","蠻夷九譯，咸來從。","凱旋金奏，象形容。","震赫萬國，罔不龔。"]', '["苞枿𪒶矣，惟根之蟠。","彌巴蔽荆，負南極以安。","[冃]我旧梁氏，緝綏艱难。","江漢之阻，都邑固以完。","聖人作，神武用。","有臣勇智，奮不以衆。","投跡死地，謀猷縱。","化敵爲家，慮則中。","浩浩海裔，不威而同。","係縲降王，定厥功。","澶漫万里，宣唐风。","蠻夷九譯，咸来從。","凱旋金奏，象形容。","震赫万国，罔不龔。"]', '诗', 'shi', '', NULL, '唐鐃歌妓吹曲十二篇 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95d51064-c607-44b7-96ee-11b063501b4f', '唐鐃歌妓吹曲十二篇', '唐鐃歌妓吹曲十二篇', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["河右澶漫，頑爲之魁。","王師如雷震，崑崙以頹。","上聾下聰，驁不可廻。","助讎抗有德，惟人之災。","乃潰乃奮，執縛歸厥命。","萬室蒙其仁，一夫則病。","濡以鴻澤，皇之聖。","威畏德懷，功以定。","順之于理，物咸遂厥性。"]', '["河右澶漫，頑爲之魁。","王師如雷震，崑崙以頹。","上聾下聰，驁不可廻。","助讎抗有德，惟人之災。","乃潰乃奮，執縛归厥命。","万室蒙其仁，一夫則病。","濡以鴻澤，皇之聖。","威畏德懷，功以定。","順之于理，物咸遂厥性。"]', '诗', 'shi', '', NULL, '唐鐃歌妓吹曲十二篇 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dca1e577-5542-42ce-bb3c-51e641e8be32', '唐鐃歌妓吹曲十二篇', '唐鐃歌妓吹曲十二篇', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["鐵山碎，大漠舒。","二虜勁，連穹廬。","背北海，專坤隅。","歲來侵邊，或傅于都。","天子命元帥，奮其雄圖。","破定襄，降魁渠。","窮竟窟宅，斥余吾。","百蠻破膽，邊氓蘇。","威武輝耀，明鬼區。","利澤彌萬祀，功不可踰。","官臣拜手，惟帝之暮。"]', '["鐵山碎，大漠舒。","二虜勁，連穹廬。","背北海，專坤隅。","歲来侵邊，或傅于都。","天子命元帥，奮其雄圖。","破定襄，降魁渠。","窮竟窟宅，斥余吾。","百蠻破膽，邊氓蘇。","威武輝耀，明鬼區。","利澤彌万祀，功不可踰。","官臣拜手，惟帝之暮。"]', '诗', 'shi', '', NULL, '唐鐃歌妓吹曲十二篇 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a1008e6-8028-4155-9d26-0df2cd3a9fbf', '唐鐃歌妓吹曲十二篇', '唐鐃歌妓吹曲十二篇', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["本邦伊晉，惟時不靖。","根柢之搖，枯葉攸病。","守臣不任，勩于神聖。","惟越之興，翦焉則定。","洪惟我理，式和以敬。","羣頑既夷，庶績咸正。","皇謩載大，惟人之慶。"]', '["本邦伊晉，惟时不靖。","根柢之搖，枯葉攸病。","守臣不任，勩于神聖。","惟越之兴，翦焉則定。","洪惟我理，式和以敬。","羣頑既夷，庶績咸正。","皇謩載大，惟人之慶。"]', '诗', 'shi', '', NULL, '唐鐃歌妓吹曲十二篇 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('623937c4-d618-4c10-b326-b8324ce70bd4', '唐鐃歌妓吹曲十二篇', '唐鐃歌妓吹曲十二篇', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["吐谷渾盛彊，背西海以夸。","歲侵擾我疆，退匿險且遐。","帝謂神武師。","往征靖皇家。","烈烈斾其旗，熊虎雜龍蛇。","王旅千萬人，銜枚默無譁。","束刃踰山徼，張翼縱漠沙。","一舉刈羶腥，尸骸積如麻。","除惡務本根，況敢遺萌芽。","洋洋西海水，威命窮天涯。","係虜來王都，犒樂窮休嘉。","登高望還師，竟野如春華。","行者靡不歸，親戚勸要遮。","凱旋獻清廟，萬國思無邪。"]', '["吐谷渾盛彊，背西海以夸。","歲侵擾我疆，退匿險且遐。","帝謂神武師。","往征靖皇家。","烈烈斾其旗，熊虎杂龙蛇。","王旅千万人，銜枚默無譁。","束刃踰山徼，張翼縱漠沙。","一舉刈羶腥，尸骸積如麻。","除惡務本根，況敢遺萌芽。","洋洋西海水，威命窮天涯。","係虜来王都，犒乐窮休嘉。","登高望還師，竟野如春华。","行者靡不归，親戚勸要遮。","凱旋獻清廟，万国思無邪。"]', '诗', 'shi', '', NULL, '唐鐃歌妓吹曲十二篇 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e689817f-e0cc-4a57-9464-c6c7de3df9bc', '唐鐃歌妓吹曲十二篇', '唐鐃歌妓吹曲十二篇', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["麴氏雄西北，別絕臣外區。","既恃遠且險，縱傲不我虞。","烈烈王者師，熊螭以爲徒。","龍旂翻海浪，馹騎馳坤隅。","賁育搏嬰兒，一掃不復餘。","平沙際天極，但見黃雲驅。","臣靖執長纓，智勇伏囚拘。","文皇南面坐，夷狄千羣趨。","咸稱天子神，往古不得俱。","獻號天可汗，以覆我國都。","兵戎不交害，各保性與軀。"]', '["麴氏雄西北，別絕臣外區。","既恃远且險，縱傲不我虞。","烈烈王者師，熊螭以爲徒。","龙旂翻海浪，馹騎驰坤隅。","賁育搏嬰兒，一掃不复餘。","平沙際天極，但见黄云驱。","臣靖執长纓，智勇伏囚拘。","文皇南面坐，夷狄千羣趨。","咸稱天子神，往古不得俱。","獻號天可汗，以覆我国都。","兵戎不交害，各保性與軀。"]', '诗', 'shi', '', NULL, '唐鐃歌妓吹曲十二篇 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d9fe521-fbe8-4d7d-9734-5f611bc276b6', '唐鐃歌妓吹曲十二篇', '唐鐃歌妓吹曲十二篇', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["東蠻有謝氏，冠帶理海中。","自言我異世，雖聖莫能通。","王卒如飛翰，鵬鶱駭羣龍。","轟然自天墜，乃信神武功。","繫虜君臣人，累累來自東。","無思不服從，唐業如山崇。","百辟拜稽首，咸願圖形容。","如周王會書，永永傳無窮。","睢盱萬狀乖，咿嗢九譯重。","廣輪撫四海，浩浩知皇風。","歌詩鐃鼓閒，以壯我元戎。"]', '["东蠻有謝氏，冠带理海中。","自言我異世，雖聖莫能通。","王卒如飞翰，鵬鶱駭羣龙。","轟然自天墜，乃信神武功。","繫虜君臣人，累累来自东。","無思不服從，唐業如山崇。","百辟拜稽首，咸願圖形容。","如周王會书，永永傳無窮。","睢盱万狀乖，咿嗢九譯重。","廣輪撫四海，浩浩知皇风。","歌诗鐃鼓閒，以壯我元戎。"]', '诗', 'shi', '', NULL, '唐鐃歌妓吹曲十二篇 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95e30faf-c17c-4627-8fca-c189788361ee', '貞符', '貞符', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["於穆敬德，黎人皇之。","惟貞厥符，浩浩將之。","仁函于膚，刃莫畢屠。","澤熯于爨，𩰾炎以澣。","殄厥兇德，乃敺乃夷。","懿其休風，是喣是吹。","父子熙熙，相寧以嬉。","賦徹而藏，厚我糗粻。","刑輕以清，我肌靡傷。","貽我子孫，百代是康。","十聖嗣于理，仁后之子。","子思孝父，易患于已。","拱之戴之，神具爾宜。","載揚于雅，承天之嘏。","天之誠神，宜鑒于仁。","神之曷依，宜仁之歸。","濮沿于北，祝栗于南。","幅員西東，祗一乃心。","祝唐之紀，後天罔墜。","祝皇之壽，與地咸久。","曷徒祝之，心誠篤之。","神協人同，道以告之。","俾彌億萬年，不震不危。","我代之延，永永毗之。","仁增以崇，曷不爾思。","有號于天，僉曰嗚呼。","咨爾皇靈，無替厥符。"]', '["於穆敬德，黎人皇之。","惟貞厥符，浩浩將之。","仁函于膚，刃莫畢屠。","澤熯于爨，𩰾炎以澣。","殄厥兇德，乃敺乃夷。","懿其休风，是喣是吹。","父子熙熙，相寧以嬉。","賦徹而藏，厚我糗粻。","刑轻以清，我肌靡傷。","貽我子孫，百代是康。","十聖嗣于理，仁后之子。","子思孝父，易患于已。","拱之戴之，神具爾宜。","載揚于雅，承天之嘏。","天之誠神，宜鑒于仁。","神之曷依，宜仁之归。","濮沿于北，祝栗于南。","幅員西东，祗一乃心。","祝唐之紀，後天罔墜。","祝皇之壽，與地咸久。","曷徒祝之，心誠篤之。","神協人同，道以告之。","俾彌億万年，不震不危。","我代之延，永永毗之。","仁增以崇，曷不爾思。","有號于天，僉曰嗚呼。","咨爾皇靈，無替厥符。"]', '诗', 'shi', '', NULL, '貞符 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de76d823-85a2-459b-b16c-8340efcb915f', '眎民詩', '眎民诗', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["帝眎民情，匪幽匪明。","慘或在腹，已如色聲。","亦無動威，亦無止力。","弗動弗止，惟民之極。","帝懷民眎，乃降明德。","乃生明翼，明翼者何。","迺房迺杜，惟房與杜。","實爲民路，迺定天子。","迺開萬國，萬國既分。","迺釋蠹民，迺學與仕。","迺播與食，迺器與用。","迺貨與通，有作有遷。","無遷無作，士實蕩蕩。","農實董董，工實蒙蒙。","賈實融融，左右惟一。","出入惟同，攝儀以引。","以遵以肆，其風既流。","品物載休，惟天子守。","乃二公之久，惟天子明。","乃二公之成，惟百辟正。","乃二公之令，惟百辟穀。","乃二公之祿，二公行矣。","弗敢憂縱，是獲憂共。","二公居矣，弗敢泰止。","是獲泰已，既柔一德。","四夷是則，四夷是則，永懷不忒。"]', '["帝眎民情，匪幽匪明。","慘或在腹，已如色声。","亦無动威，亦無止力。","弗动弗止，惟民之極。","帝懷民眎，乃降明德。","乃生明翼，明翼者何。","迺房迺杜，惟房與杜。","實爲民路，迺定天子。","迺开万国，万国既分。","迺釋蠹民，迺学與仕。","迺播與食，迺器與用。","迺貨與通，有作有遷。","無遷無作，士實蕩蕩。","農實董董，工實蒙蒙。","賈實融融，左右惟一。","出入惟同，攝儀以引。","以遵以肆，其风既流。","品物載休，惟天子守。","乃二公之久，惟天子明。","乃二公之成，惟百辟正。","乃二公之令，惟百辟穀。","乃二公之祿，二公行矣。","弗敢憂縱，是獲憂共。","二公居矣，弗敢泰止。","是獲泰已，既柔一德。","四夷是則，四夷是則，永懷不忒。"]', '诗', 'shi', '', NULL, '眎民詩 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37d48834-7fd0-4ce2-b952-e10dc7fc983c', '同劉二十八院長述舊言懷感時書事奉寄澧州張員外使君五十二韻之作因其韻增至八十通贈二君子', '同劉二十八院长述旧言懷感时书事奉寄澧州張員外使君五十二韻之作因其韻增至八十通贈二君子', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["弱歲游玄圃，先容幸棄瑕。","名勞長者記，文許後生誇。","鷃翼嘗披隼，蓬心類倚麻。","繼酬天祿署，俱尉甸侯家。","憲府初收迹，丹墀共拜嘉。","分行參瑞獸，傳點亂宮鴉。","執簡寧循枉，持書每去邪。","鸞鳳標魏闕，熊武負崇牙。","辨色宜相顧，傾心自不譁。","金爐仄流月，紫殿啓晨赮。","未竟遷喬樂，俄成失路嗟。","還如渡遼水，更似謫長沙。","別怨秦城暮，途窮越嶺斜。","訟庭閒枳棘，候吏逐麋䴥。","三載皇恩暢，千年聖曆遐。","朝宗延駕海，師役罷梁溠。","京邑搜貞幹，南宮步渥洼。","世惟材是梓，人仰驥中驊。","歘刺苗人地，仍逾贛石崖。","禮容垂珌琫，戍備響錏鍜。","寵即郎官舊，威從太守加。","建旟翻鷙鳥，負弩繞文蛇。","冊府榮八命，中闈盛六珈。","肯隨胡質矯，方惡馬融奢。","褒德符新換，懷仁道併遮。","俗嫌龍節晚，朝訝介圭賒。","禹貢輸苞匭，周官賦秉秅。","雄風吞七澤，異產控三巴。","即事觀農稼，因時展物華。","秋原被蘭葉，春渚漲桃花。","令肅軍無擾，程懸市禁貰。","不應虞竭澤，寧復歎棲苴。","蹀躞騶先駕，籠銅鼓報衙。","染毫東國素，濡印錦溪砂。","貨積舟難泊，人歸山倍畬。","吳歈工折柳，楚舞舊傳芭。","隱几松爲曲，傾罇石作汙。","寒初榮橘柚，夏首薦枇杷。","祀變荆巫禱，風移魯婦髽。","已聞施愷悌，還覩正奇衺。","慕友慚連璧，言姻喜附葭。","沈埋全死地，流落半生涯。","入郡腰恒折，逢人手盡叉。","敢辭親耻汙，唯恐長疵瘕。","善幻迷冰火，齊諧笑柏塗。","東門牛屢飯，中散蝨空爬。","逸戲看猿鬬，殊音辨馬撾。","渚行狐作孽，林宿鳥爲𣩈。","同病憂能老，新聲厲似姱。","豈知千仞墜，秖爲一毫差。","守道甘長絕，明心欲自𠜲。","貯愁聽夜雨，隔淚數殘葩。","梟族音常聒，豺羣喙競呀。","岸蘆翻毒蜃，磎竹鬬狂{广/秝/牛}。","野鶩行看弋，江魚或共扠。","瘴氛恒積潤，訛火亟生煆。","耳靜煩喧蟻，魂驚怯怒蛙。","風枝散陳葉，霜蔓綖寒瓜。","霧密前山桂，冰枯曲沼蕸。","思鄉比莊舄，遯世遇眭夸。","漁舍茨荒草，村橋臥古槎。","御寒衾用罽，挹水勺仍椰。","窗蠹惟潛蝎，甍涎競綴蝸。","引泉開故竇，護藥插新笆。","樹怪花因槲，蟲憐目待蝦。","驟歌喉易嗄，饒醉鼻成皻。","曳捶牽羸馬，垂簑牧艾豭。","已看能類鼈，猶訝雉爲鷨。","誰采中原菽，徒巾下澤車。","俚兒供苦筍，傖父饋酸樝。","勸策扶危杖，邀持當酒茶。","道流徵短褐，禪客會袈裟。","香飯舂菰米，珍蔬折五茄。","方期飲甘露，更欲吸流霞。","屋鼠從穿兀，林狙任攫拏。","春衫裁白紵，朝帽挂烏紗。","屢歎恢恢網，頻搖肅肅罝。","衰榮因蓂莢，盈缺幾蝦蟇。","路識溝邊柳，城聞隴上笳。","共思捐佩處，千騎擁青緺。"]', '["弱歲游玄圃，先容幸棄瑕。","名勞长者記，文許後生誇。","鷃翼嘗披隼，蓬心類倚麻。","繼酬天祿署，俱尉甸侯家。","憲府初收迹，丹墀共拜嘉。","分行參瑞獸，傳点亂宮鴉。","執簡寧循枉，持书每去邪。","鸾鳳標魏闕，熊武負崇牙。","辨色宜相顧，傾心自不譁。","金爐仄流月，紫殿啓晨赮。","未竟遷喬乐，俄成失路嗟。","還如渡遼水，更似謫长沙。","別怨秦城暮，途窮越嶺斜。","訟庭閒枳棘，候吏逐麋䴥。","三載皇恩暢，千年聖曆遐。","朝宗延駕海，師役罷梁溠。","京邑搜貞幹，南宮步渥洼。","世惟材是梓，人仰驥中驊。","歘刺苗人地，仍逾贛石崖。","禮容垂珌琫，戍備响錏鍜。","寵即郎官旧，威從太守加。","建旟翻鷙鸟，負弩繞文蛇。","冊府榮八命，中闈盛六珈。","肯隨胡質矯，方惡马融奢。","褒德符新換，懷仁道併遮。","俗嫌龙節晚，朝訝介圭賒。","禹貢輸苞匭，周官賦秉秅。","雄风吞七澤，異產控三巴。","即事观農稼，因时展物华。","秋原被蘭葉，春渚漲桃花。","令肅軍無擾，程懸市禁貰。","不應虞竭澤，寧复歎棲苴。","蹀躞騶先駕，籠銅鼓報衙。","染毫东国素，濡印錦溪砂。","貨積舟难泊，人归山倍畬。","吳歈工折柳，楚舞旧傳芭。","隐几松爲曲，傾罇石作汙。","寒初榮橘柚，夏首薦枇杷。","祀变荆巫禱，风移魯婦髽。","已闻施愷悌，還覩正奇衺。","慕友慚連璧，言姻喜附葭。","沈埋全死地，流落半生涯。","入郡腰恒折，逢人手尽叉。","敢辞親耻汙，唯恐长疵瘕。","善幻迷冰火，齊諧笑柏塗。","东门牛屢飯，中散蝨空爬。","逸戲看猿鬬，殊音辨马撾。","渚行狐作孽，林宿鸟爲𣩈。","同病憂能老，新声厲似姱。","豈知千仞墜，秖爲一毫差。","守道甘长絕，明心欲自𠜲。","貯愁听夜雨，隔泪數殘葩。","梟族音常聒，豺羣喙競呀。","岸蘆翻毒蜃，磎竹鬬狂{广/秝/牛}。","野鶩行看弋，江鱼或共扠。","瘴氛恒積潤，訛火亟生煆。","耳静煩喧蟻，魂驚怯怒蛙。","风枝散陳葉，霜蔓綖寒瓜。","霧密前山桂，冰枯曲沼蕸。","思乡比莊舄，遯世遇眭夸。","漁舍茨荒草，村橋臥古槎。","御寒衾用罽，挹水勺仍椰。","窗蠹惟潛蝎，甍涎競綴蝸。","引泉开故竇，護藥插新笆。","樹怪花因槲，蟲怜目待蝦。","驟歌喉易嗄，饒醉鼻成皻。","曳捶牽羸马，垂簑牧艾豭。","已看能類鼈，猶訝雉爲鷨。","誰采中原菽，徒巾下澤车。","俚兒供苦筍，傖父饋酸樝。","勸策扶危杖，邀持當酒茶。","道流徵短褐，禪客會袈裟。","香飯舂菰米，珍蔬折五茄。","方期饮甘露，更欲吸流霞。","屋鼠從穿兀，林狙任攫拏。","春衫裁白紵，朝帽挂烏紗。","屢歎恢恢網，頻搖肅肅罝。","衰榮因蓂莢，盈缺幾蝦蟇。","路識溝邊柳，城闻隴上笳。","共思捐佩处，千騎擁青緺。"]', '诗', 'shi', '', NULL, '同劉二十八院長述舊言懷感時書事奉寄澧州張員外使君五十二韻之作因其韻增至八十通贈二君子 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a6e14a5-ee60-480f-8a82-38b2c5210833', '弘農公以碩德偉材屈於誣枉左官三歲復爲大僚天監昭明人心感悅宗元竄伏湘浦拜賀末由謹獻詩五十韻以畢微志', '弘農公以碩德偉材屈於誣枉左官三歲复爲大僚天監昭明人心感悅宗元竄伏湘浦拜賀末由謹獻诗五十韻以畢微志', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["知命儒爲貴，時中聖所臧。","處心齊寵辱，遇物任行藏。","關識新安地，封傳臨晉鄉。","挺生推豹蔚，遐步仰龍驤。","幹有千尋竦，精聞百鍊鋼。","茂功期舜禹，高韻狀羲黃。","足逸詩書囿，鋒搖翰墨場。","雅歌張仲德，頌祝魯侯昌。","憲府初騰價，神州轉耀鋩。","右言盈簡策，左轄備條綱。","響切晨趨佩，煙濃近侍香。","司儀六禮洽，論將七兵揚。","合樂來儀鳳，尊祠重餼羊。","卿材優柱石，公器擅巖廊。","峻節臨衡嶠，和風滿豫章。","人歸父母育，郡得股肱良。","細故誰留念，煩言肯過防。","璧非真盜客，金有誤持郎。","龜虎休前寄，貂蟬冠舊行。","訓刑方命呂，理劇復推張。","直用明銷惡，還將道勝剛。","敬逾齊國社，恩比召南棠。","希怨猶逢怒，多容競忤彊。","火炎侵琬琰，鷹擊謬鸞凰。","刻木終難對，焚芝未改芳。","遠遷逾桂嶺，中徙滯餘杭。","顧土雖懷趙，知天詎畏匡。","論嫌齊物誕，騷愛遠游傷。","麗澤周羣品，重明照萬方。","斗間收紫氣，臺上挂清光。","福爲深仁集，妖從盛德禳。","秦民啼畎畝，周士舞康莊。","采綬還垂艾，華簪更截肪。","高居遷鼎邑，遙傅好書王。","碧樹環金谷，丹霞映上陽。","留歡唱容與，要醉對清涼。","故友仍同里，常僚每合堂。","淵龍過許劭，冰鯉弔王祥。","玉漏天門靜，銅駝御路荒。","澗瀍秋瀲灧，嵩少暮微茫。","遵渚徒云樂，沖天自不遑。","降神終入輔，種德會明敭。","獨棄傖人國，難窺夫子牆。","通家殊孔李，舊好即潘楊。","世議排張摯，時情棄仲翔。","不言縲紲枉，徒恨纆徽長。","賈賦愁單閼，鄒書怯大梁。","炯心那自是，鳴玉機全息，懷沙事不忘。","戀恩何敢死，垂淚對清湘。"]', '["知命儒爲貴，时中聖所臧。","处心齊寵辱，遇物任行藏。","关識新安地，封傳臨晉乡。","挺生推豹蔚，遐步仰龙驤。","幹有千尋竦，精闻百鍊鋼。","茂功期舜禹，高韻狀羲黄。","足逸诗书囿，鋒搖翰墨場。","雅歌張仲德，頌祝魯侯昌。","憲府初腾價，神州轉耀鋩。","右言盈簡策，左轄備條綱。","响切晨趨佩，煙濃近侍香。","司儀六禮洽，論將七兵揚。","合乐来儀鳳，尊祠重餼羊。","卿材優柱石，公器擅巖廊。","峻節臨衡嶠，和风满豫章。","人归父母育，郡得股肱良。","細故誰留念，煩言肯過防。","璧非真盜客，金有誤持郎。","龟虎休前寄，貂蟬冠旧行。","訓刑方命呂，理劇复推張。","直用明銷惡，還將道勝剛。","敬逾齊国社，恩比召南棠。","希怨猶逢怒，多容競忤彊。","火炎侵琬琰，鷹擊謬鸾凰。","刻木終难对，焚芝未改芳。","远遷逾桂嶺，中徙滯餘杭。","顧土雖懷趙，知天詎畏匡。","論嫌齊物誕，騷愛远游傷。","丽澤周羣品，重明照万方。","斗间收紫氣，台上挂清光。","福爲深仁集，妖從盛德禳。","秦民啼畎畝，周士舞康莊。","采綬還垂艾，华簪更截肪。","高居遷鼎邑，遙傅好书王。","碧樹环金谷，丹霞映上陽。","留歡唱容與，要醉对清涼。","故友仍同里，常僚每合堂。","淵龙過許劭，冰鯉弔王祥。","玉漏天门静，銅駝御路荒。","澗瀍秋瀲灧，嵩少暮微茫。","遵渚徒云乐，沖天自不遑。","降神終入輔，種德會明敭。","独棄傖人国，难窺夫子牆。","通家殊孔李，旧好即潘楊。","世議排張摯，时情棄仲翔。","不言縲紲枉，徒恨纆徽长。","賈賦愁單閼，鄒书怯大梁。","炯心那自是，鳴玉機全息，懷沙事不忘。","戀恩何敢死，垂泪对清湘。"]', '诗', 'shi', '', NULL, '弘農公以碩德偉材屈於誣枉左官三歲復爲大僚天監昭明人心感悅宗元竄伏湘浦拜賀末由謹獻詩五十韻以畢微志 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7a459f1-85fa-46c8-aac4-c23cc89c6d48', '酬韶州裴曹長使君寄道州呂八大使以見示二十韻一首', '酬韶州裴曹长使君寄道州呂八大使以见示二十韻一首', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["金馬嘗齊入，銅魚亦共頒。","疑山看積翠，湞水想澄灣。","標牓同驚俗，清明兩照姦。","乘軺參孔僅，按節服侯狦。","賈傅辭寧切，虞童髪未䰔。","秉心方的的，騰口任㘖㘖。","聖理高懸象，爰書降罰鍰。","德風流海外，和氣滿人寰。","禦魅恩猶貸，思賢淚自潸。","在亡均寂寞，零落間惸鰥。","夙志隨憂盡，殘肌觸瘴𤸷。","月光搖淺瀨，風韻碎枯菅。","海俗衣猶卉，山夷髻不鬟。","泥沙潛虺蜮，榛莽鬬豺獌。","循省誠知懼，安排秖自𢢀。","食貧甘莽鹵，被褐謝斕斒。","遠物裁青罽，時珍饌白鷴。","長捐楚客佩，未賜大夫環。","異政徒云仰，高蹤不可攀。","空勞慰顦顇，妍唱劇妖㛠。"]', '["金马嘗齊入，銅鱼亦共頒。","疑山看積翠，湞水想澄灣。","標牓同驚俗，清明兩照姦。","乘軺參孔僅，按節服侯狦。","賈傅辞寧切，虞童髪未䰔。","秉心方的的，腾口任㘖㘖。","聖理高懸象，爰书降罰鍰。","德风流海外，和氣满人寰。","禦魅恩猶貸，思賢泪自潸。","在亡均寂寞，零落间惸鰥。","夙志隨憂尽，殘肌觸瘴𤸷。","月光搖淺瀨，风韻碎枯菅。","海俗衣猶卉，山夷髻不鬟。","泥沙潛虺蜮，榛莽鬬豺獌。","循省誠知懼，安排秖自𢢀。","食貧甘莽鹵，被褐謝斕斒。","远物裁青罽，时珍饌白鷴。","长捐楚客佩，未賜大夫环。","異政徒云仰，高蹤不可攀。","空勞慰顦顇，妍唱劇妖㛠。"]', '诗', 'shi', '', NULL, '酬韶州裴曹長使君寄道州呂八大使以見示二十韻一首 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44cea862-5bd3-4705-aeae-2a7b899a201a', '酬婁秀才將之淮南見贈之什', '酬婁秀才將之淮南见贈之什', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["遠棄甘幽獨，誰云值故人。","好音憐鎩羽，濡沫慰窮鱗。","困志情惟舊，相知樂更新。","浪遊輕費日，醉舞詎傷春。","風月歡寧間，星霜分益親。","已將名是患，還用道爲鄰。","機事齊飄瓦，嫌猜比拾塵。","高冠余肯賦，長鋏子忘貧。","晼晚驚移律，睽攜忽此辰。","開顏時不再，絆足去何因。","海上銷魂別，天邊弔影身。","秖應西澗水，寂寞但垂綸。"]', '["远棄甘幽独，誰云值故人。","好音怜鎩羽，濡沫慰窮鱗。","困志情惟旧，相知乐更新。","浪游轻費日，醉舞詎傷春。","风月歡寧间，星霜分益親。","已將名是患，還用道爲鄰。","機事齊飄瓦，嫌猜比拾塵。","高冠余肯賦，长鋏子忘貧。","晼晚驚移律，睽携忽此辰。","开顏时不再，絆足去何因。","海上銷魂別，天邊弔影身。","秖應西澗水，寂寞但垂綸。"]', '诗', 'shi', '', NULL, '酬婁秀才將之淮南見贈之什 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df70911c-bbed-45b7-919f-e381838d6961', '酬婁秀才寓居開元寺早秋月夜病中見寄', '酬婁秀才寓居开元寺早秋月夜病中见寄', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["客有故園思，瀟湘生夜愁。","病依居士室，夢繞羽人丘。","味道憐知止，遺名得自求。","壁空殘月曙，門掩候蟲秋。","謬委雙金重，難徵雜佩酬。","碧霄無枉路，徒此助離憂。"]', '["客有故园思，瀟湘生夜愁。","病依居士室，梦繞羽人丘。","味道怜知止，遺名得自求。","壁空殘月曙，门掩候蟲秋。","謬委雙金重，难徵杂佩酬。","碧霄無枉路，徒此助離憂。"]', '诗', 'shi', '', NULL, '酬婁秀才寓居開元寺早秋月夜病中見寄 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96314951-671b-423f-a172-4f10ec08a6f2', '初秋夜坐贈吳武陵', '初秋夜坐贈吳武陵', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["稍稍雨侵竹，翻翻鵲驚叢。","美人隔湘浦，一夕生秋風。","積霧杳難極，滄波浩無窮。","相思豈云遠，即席莫與同。","若人抱奇音，朱弦緪枯桐。","清商激西顥，泛灧凌長空。","自得本無作，天成諒非功。","希聲閟大樸，聾俗何由聰。"]', '["稍稍雨侵竹，翻翻鵲驚叢。","美人隔湘浦，一夕生秋风。","積霧杳难極，滄波浩無窮。","相思豈云远，即席莫與同。","若人抱奇音，朱弦緪枯桐。","清商激西顥，泛灧凌长空。","自得本無作，天成諒非功。","希声閟大樸，聾俗何由聰。"]', '诗', 'shi', '', NULL, '初秋夜坐贈吳武陵 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2954ddd2-f1c7-41b1-8c9e-42058398cde0', '晨詣超師院讀禪經', '晨詣超師院读禪經', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["汲井漱寒齒，清心拂塵服。","閒持貝葉書，步出東齋讀。","真源了無取，妄跡世所逐。","遺言冀可冥，繕性何由熟。","道人庭宇靜，苔色連深竹。","日出霧露餘，青松如膏沐。","澹然離言說，悟悅心自足。"]', '["汲井漱寒齒，清心拂塵服。","閒持貝葉书，步出东斋读。","真源了無取，妄跡世所逐。","遺言冀可冥，繕性何由熟。","道人庭宇静，苔色連深竹。","日出霧露餘，青松如膏沐。","澹然離言说，悟悅心自足。"]', '诗', 'shi', '', NULL, '晨詣超師院讀禪經 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5f1a8ad-737d-4f10-bd3a-782747054253', '贈江華長老', '贈江华长老', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["老僧道機熟，默語心皆寂。","去歲別舂陵，沿流此投跡。","室空無侍者，巾履唯掛壁。","一飯不願餘，跏趺便終夕。","風牕疎竹響，露井寒松滴。","偶地即安居，滿庭芳草積。"]', '["老僧道機熟，默語心皆寂。","去歲別舂陵，沿流此投跡。","室空無侍者，巾履唯掛壁。","一飯不願餘，跏趺便終夕。","风牕疎竹响，露井寒松滴。","偶地即安居，满庭芳草積。"]', '诗', 'shi', '', NULL, '贈江華長老 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b060055f-cb85-4656-8297-035e68b380ed', '巽上人以竹閒自採新茶見贈酬之以詩', '巽上人以竹閒自採新茶见贈酬之以诗', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["芳叢翳湘竹，零露凝清華。","復此雪山客，晨朝掇靈芽。","蒸煙俯石瀨，咫尺凌丹崖。","圓方麗奇色，圭璧無纖瑕。","呼兒爨金鼎，餘馥延幽遐。","滌慮發真照，還源蕩昏邪。","猶同甘露飯，佛事薰毗耶。","咄此蓬瀛侶，無乃貴流霞。"]', '["芳叢翳湘竹，零露凝清华。","复此雪山客，晨朝掇靈芽。","蒸煙俯石瀨，咫尺凌丹崖。","圓方丽奇色，圭璧無纖瑕。","呼兒爨金鼎，餘馥延幽遐。","滌慮發真照，還源蕩昏邪。","猶同甘露飯，佛事薰毗耶。","咄此蓬瀛侶，無乃貴流霞。"]', '诗', 'shi', '', NULL, '巽上人以竹閒自採新茶見贈酬之以詩 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e387aad0-cefb-4e70-b299-855d181a36ab', '零陵贈李卿元侍御簡吳武陵', '零陵贈李卿元侍御簡吳武陵', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["理世固輕士，棄捐湘之湄。","陽光競四溟，敲石安所施。","鎩羽集枯幹，低昂互鳴悲。","朔雲吐風寒，寂歷窮秋時。","君子尚容與，小人守兢危。","慘悽日相視，離憂坐自滋。","尊酒聊可酌，放歌諒徒爲。","惜無協律者，窈眇絃吾詩。"]', '["理世固轻士，棄捐湘之湄。","陽光競四溟，敲石安所施。","鎩羽集枯幹，低昂互鳴悲。","朔云吐风寒，寂歷窮秋时。","君子尚容與，小人守兢危。","慘悽日相視，離憂坐自滋。","尊酒聊可酌，放歌諒徒爲。","惜無協律者，窈眇絃吾诗。"]', '诗', 'shi', '', NULL, '零陵贈李卿元侍御簡吳武陵 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88d529e0-7481-45fa-8568-bf134ec06a59', '界圍巖水簾', '界圍巖水簾', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["界圍匯湘曲，青壁環澄流。","懸泉粲成簾，羅注無時休。","韻磬叩凝碧，鏘鏘徹巖幽。","丹霞冠其巔，想像凌虛遊。","靈境不可狀，鬼工諒難求。","忽如朝玉皇，天冕垂前旒。","楚臣昔南逐，有意仍丹丘。","今我始北旋，新詔釋縲囚。","采真誠眷戀，許國無淹留。","再來寄幽夢，遺貯催行舟。"]', '["界圍匯湘曲，青壁环澄流。","懸泉粲成簾，羅注無时休。","韻磬叩凝碧，鏘鏘徹巖幽。","丹霞冠其巔，想像凌虛游。","靈境不可狀，鬼工諒难求。","忽如朝玉皇，天冕垂前旒。","楚臣昔南逐，有意仍丹丘。","今我始北旋，新詔釋縲囚。","采真誠眷戀，許国無淹留。","再来寄幽梦，遺貯催行舟。"]', '诗', 'shi', '', NULL, '界圍巖水簾 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bdc2c58-e651-49d0-9142-85ab23847cf3', '古東門行', '古东门行', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["漢家三十六將軍，東方雷動橫陣雲。","雞鳴函谷客如霧，貌同心異不可數。","赤丸夜語飛電光，徼巡司隸眠如羊。","當街一叱百吏走，馮敬胷中函匕首。","兇徒側耳潛愜心，悍臣破膽皆杜口。","魏王臥內藏兵符，子西掩袂真無辜。","羗胡轂下一朝起，敵國舟中非所擬。","安陵誰辨削礪功，韓國詎明深井里。","絕臙斷骨那下補，萬金寵贈不如土。"]', '["漢家三十六將軍，东方雷动橫陣云。","雞鳴函谷客如霧，貌同心異不可數。","赤丸夜語飞電光，徼巡司隸眠如羊。","當街一叱百吏走，馮敬胷中函匕首。","兇徒側耳潛愜心，悍臣破膽皆杜口。","魏王臥內藏兵符，子西掩袂真無辜。","羗胡轂下一朝起，敵国舟中非所擬。","安陵誰辨削礪功，韓国詎明深井里。","絕臙斷骨那下補，万金寵贈不如土。"]', '诗', 'shi', '', NULL, '古東門行 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37fce2eb-8608-4641-9ee8-3e367d534cf9', '寄韋珩', '寄韋珩', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["初拜柳州出東郊，道旁相送皆賢豪。","廻眸炫晃別羣玉，獨赴異域穿蓬蒿。","炎煙六月咽口鼻，胷鳴肩舉不可逃。","桂州西南又千里，灕水鬬石麻蘭高。","陰森野葛交蔽日，懸蛇結虺如蒲萄。","到官數宿賊滿野，縛壯殺老啼且號。","饑行夜坐設方略，籠銅枹鼓手所操。","奇瘡釘骨狀如箭，鬼手脫命爭纖毫。","今年噬毒得霍疾，支心攪腹戟與刀。","邇來氣少筋骨露，蒼白瀄汩盈顛毛。","君今矻矻又竄逐，辭賦已復窮詩騷。","神兵廟略頻破虜，四溟不日清風濤。","聖恩倘忽念行葦，十年踐蹈久已勞。","幸因解網入鳥獸，畢命江海終遊遨。","願言未果身益老，起望東北心滔滔。"]', '["初拜柳州出东郊，道旁相送皆賢豪。","廻眸炫晃別羣玉，独赴異域穿蓬蒿。","炎煙六月咽口鼻，胷鳴肩舉不可逃。","桂州西南又千里，灕水鬬石麻蘭高。","陰森野葛交蔽日，懸蛇結虺如蒲萄。","到官數宿賊满野，縛壯殺老啼且號。","饑行夜坐設方略，籠銅枹鼓手所操。","奇瘡釘骨狀如箭，鬼手脫命爭纖毫。","今年噬毒得霍疾，支心攪腹戟與刀。","邇来氣少筋骨露，蒼白瀄汩盈顛毛。","君今矻矻又竄逐，辞賦已复窮诗騷。","神兵廟略頻破虜，四溟不日清风濤。","聖恩倘忽念行葦，十年踐蹈久已勞。","幸因解網入鸟獸，畢命江海終游遨。","願言未果身益老，起望东北心滔滔。"]', '诗', 'shi', '', NULL, '寄韋珩 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4020eb95-6f63-4c86-bdcb-34ec37b63cfa', '奉和楊尚書郴州追和故李中書夏日登北樓十韻之作依本詩韻次用', '奉和楊尚书郴州追和故李中书夏日登北楼十韻之作依本诗韻次用', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["郡樓有遺唱，新和敵南金。","境以道情得，人期幽夢尋。","層軒隔炎暑，迥野恣窺臨。","鳳去徽音續，芝焚芳意深。","游鱗出陷浦，唳鶴繞仙岑。","風起三湘浪，雲生萬里陰。","宏規齊德宇，麗藻競詞林。","靜契分憂術，閑同遲客心。","驊騮當遠步，鶗鴂莫相侵。","今日登高處，還聞梁父吟。"]', '["郡楼有遺唱，新和敵南金。","境以道情得，人期幽梦尋。","層軒隔炎暑，迥野恣窺臨。","鳳去徽音續，芝焚芳意深。","游鱗出陷浦，唳鹤繞仙岑。","风起三湘浪，云生万里陰。","宏規齊德宇，丽藻競词林。","静契分憂術，闲同遲客心。","驊騮當远步，鶗鴂莫相侵。","今日登高处，還闻梁父吟。"]', '诗', 'shi', '', NULL, '奉和楊尚書郴州追和故李中書夏日登北樓十韻之作依本詩韻次用 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ad733c4-5502-4869-80b9-07e3ab4129d6', '楊尚書寄郴筆知是小生本樣令更商榷使盡其功輙獻長句', '楊尚书寄郴笔知是小生本樣令更商榷使尽其功輙獻长句', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["截玉銛錐作妙形，貯雲含霧到南溟。","尚書舊用裁天詔，內史新將寫道經。","曲藝豈能裨損益，微辭秖欲播芳馨。","桂陽卿月光輝徧，毫末應傳顧兔靈。"]', '["截玉銛錐作妙形，貯云含霧到南溟。","尚书旧用裁天詔，內史新將寫道經。","曲藝豈能裨損益，微辞秖欲播芳馨。","桂陽卿月光輝徧，毫末應傳顧兔靈。"]', '诗', 'shi', '', NULL, '楊尚書寄郴筆知是小生本樣令更商榷使盡其功輙獻長句 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('604ee73f-05ea-4201-80bd-c068e47ed590', '南省轉牒欲具江國圖令盡通風俗故事', '南省轉牒欲具江国圖令尽通风俗故事', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["聖代提封盡海壖，狼荒猶得紀山川。","華夷圖上應初錄，風土記中殊未傳。","椎髻老人難借問，黃茆深峒敢留連。","南宮有意求遺俗，試檢周書王會篇。"]', '["聖代提封尽海壖，狼荒猶得紀山川。","华夷圖上應初錄，风土記中殊未傳。","椎髻老人难借问，黄茆深峒敢留連。","南宮有意求遺俗，試檢周书王會篇。"]', '诗', 'shi', '', NULL, '南省轉牒欲具江國圖令盡通風俗故事 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65d61708-16c4-4937-9f25-ddc2656a532d', '與浩初上人同看山寄京華親故', '與浩初上人同看山寄京华親故', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["海畔尖山似劒鋩，秋來處處割愁腸。","若爲化得身千億，散上峰頭望故鄉。"]', '["海畔尖山似劒鋩，秋来处处割愁腸。","若爲化得身千億，散上峰头望故乡。"]', '诗', 'shi', '', NULL, '與浩初上人同看山寄京華親故 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac2f736a-0a3d-4ec1-a855-374f26faff25', '再至界圍巖水簾遂宿巖下', '再至界圍巖水簾遂宿巖下', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["發春念長違，中夏欣再覩。","是時植物秀，杳若臨懸圃。","歊陽訝垂冰，白日驚雷雨。","笙簧潭際起，鸛鶴雲間舞。","古苔凝青枝，陰草濕翠羽。","蔽空素彩列，激浪寒光聚。","的皪沈珠淵，鏘鳴捐佩浦。","幽巖畫屏倚，新月玉鈎吐。","夜涼星滿川，忽疑眠洞府。"]', '["發春念长違，中夏欣再覩。","是时植物秀，杳若臨懸圃。","歊陽訝垂冰，白日驚雷雨。","笙簧潭際起，鸛鹤云间舞。","古苔凝青枝，陰草濕翠羽。","蔽空素彩列，激浪寒光聚。","的皪沈珠淵，鏘鳴捐佩浦。","幽巖畫屏倚，新月玉鈎吐。","夜涼星满川，忽疑眠洞府。"]', '诗', 'shi', '', NULL, '再至界圍巖水簾遂宿巖下 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80751d99-7945-44a5-925b-21fdd94a79f2', '詔追赴都廻寄零陵親故', '詔追赴都廻寄零陵親故', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["每憶纖鱗遊尺澤，翻愁弱羽上丹霄。","岸傍古堠應無數，次第行看別路遙。"]', '["每憶纖鱗游尺澤，翻愁弱羽上丹霄。","岸傍古堠應無數，次第行看別路遙。"]', '诗', 'shi', '', NULL, '詔追赴都廻寄零陵親故 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f40f6ab5-543f-4405-818e-3a2603d82151', '過衡山見新花開却寄弟', '過衡山见新花开却寄弟', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["故國名園久別離，今朝楚樹發南枝。","晴天歸路好相逐，正是峰前廻雁時。"]', '["故国名园久別離，今朝楚樹發南枝。","晴天归路好相逐，正是峰前廻雁时。"]', '诗', 'shi', '', NULL, '過衡山見新花開却寄弟 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('194a53e4-d7f8-49a6-92eb-3e36d41fd32c', '汨羅遇風', '汨羅遇风', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["南來不作楚臣悲，重入脩門自有期。","爲報春風汨羅道，莫將波浪枉明時。"]', '["南来不作楚臣悲，重入脩门自有期。","爲報春风汨羅道，莫將波浪枉明时。"]', '诗', 'shi', '', NULL, '汨羅遇風 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('134e6050-0242-4e9c-92cb-b6a4e6412581', '朗州竇常員外寄劉二十八詩見促行騎走筆酬贈', '朗州竇常員外寄劉二十八诗见促行騎走笔酬贈', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["投荒垂一紀，新詔下荆扉。","疑比莊周夢，情如蘇武歸。","賜環留逸響，五馬助征騑。","不羨衡陽雁，春來前後飛。"]', '["投荒垂一紀，新詔下荆扉。","疑比莊周梦，情如蘇武归。","賜环留逸响，五马助征騑。","不羨衡陽雁，春来前後飞。"]', '诗', 'shi', '', NULL, '朗州竇常員外寄劉二十八詩見促行騎走筆酬贈 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e52b13f4-9bb3-477c-952e-64a36965d159', '離觴不醉至驛却寄相送諸公', '離觴不醉至驛却寄相送諸公', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["無限居人送獨醒，可憐寂寞到長亭。","荆州不遇高陽侶，一夜春寒滿下廳。"]', '["無限居人送独醒，可怜寂寞到长亭。","荆州不遇高陽侶，一夜春寒满下廳。"]', '诗', 'shi', '', NULL, '離觴不醉至驛却寄相送諸公 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2a912f4-d7b3-4b92-a25b-8d87e3ac47c3', '北還登漢陽北原題臨川驛', '北還登漢陽北原題臨川驛', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["驅車方向闕，廻首一臨川。","多壘非余耻，無謀終自憐。","亂松知野寺，餘雪記山田。","惆悵樵漁事，今還又落然。"]', '["驱车方向闕，廻首一臨川。","多壘非余耻，無謀終自怜。","亂松知野寺，餘雪記山田。","惆悵樵漁事，今還又落然。"]', '诗', 'shi', '', NULL, '北還登漢陽北原題臨川驛 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6a022f3-1760-4dd6-863a-60aa5fc68d26', '善謔驛和劉夢得酹淳于先生', '善謔驛和劉梦得酹淳于先生', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["水上鵠已去，亭中鳥又鳴。","辭因使楚重，名爲救齊成。","荒壠遽千古，羽觴難再傾。","劉伶今日意，異代是同聲。"]', '["水上鵠已去，亭中鸟又鳴。","辞因使楚重，名爲救齊成。","荒壠遽千古，羽觴难再傾。","劉伶今日意，異代是同声。"]', '诗', 'shi', '', NULL, '善謔驛和劉夢得酹淳于先生 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5be6ce26-fcc6-494d-a684-c3c3bafce78d', '詔追赴都二月至灞亭上', '詔追赴都二月至灞亭上', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["十一年前南渡客，四千里外北歸人。","詔書許逐陽和至，驛路開花處處新。"]', '["十一年前南渡客，四千里外北归人。","詔书許逐陽和至，驛路开花处处新。"]', '诗', 'shi', '', NULL, '詔追赴都二月至灞亭上 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6cccae4-2e01-4f12-ad32-efc5fe5c5dd7', '李西川薦琴石', '李西川薦琴石', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["遠師騶忌鼓鳴琴，去和南風愜舜心。","從此他山千古重，殷勤曾是奉徽音。"]', '["远師騶忌鼓鳴琴，去和南风愜舜心。","從此他山千古重，殷勤曾是奉徽音。"]', '诗', 'shi', '', NULL, '李西川薦琴石 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dd7d4eb-5662-4dae-ab12-25882cd10835', '同劉二十八哭呂衡州兼寄江陵李元二侍御', '同劉二十八哭呂衡州兼寄江陵李元二侍御', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["衡岳新摧天柱峰，士林顦顇泣相逢。","祗令文字傳青簡，不使功名上景鐘。","三畝空留懸磬室，九原猶寄若堂封。","遙想荆州人物論，幾回中夜惜元龍。"]', '["衡岳新摧天柱峰，士林顦顇泣相逢。","祗令文字傳青簡，不使功名上景鐘。","三畝空留懸磬室，九原猶寄若堂封。","遙想荆州人物論，幾回中夜惜元龙。"]', '诗', 'shi', '', NULL, '同劉二十八哭呂衡州兼寄江陵李元二侍御 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22e86cb8-863c-4c69-8dd1-b843de7de4c7', '奉酬楊侍郎丈因送八叔拾遺戲贈詔追南來諸賓二首 一', '奉酬楊侍郎丈因送八叔拾遺戲贈詔追南来諸賓二首 一', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["貞一來時送彩牋，一行歸雁慰驚弦。","翰林寂寞誰爲主，鳴鳳應須早上天。"]', '["貞一来时送彩牋，一行归雁慰驚弦。","翰林寂寞誰爲主，鳴鳳應須早上天。"]', '诗', 'shi', '', NULL, '奉酬楊侍郎丈因送八叔拾遺戲贈詔追南來諸賓二首 一 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34a154bb-90c1-4527-aa74-deae218dc562', '奉酬楊侍郎丈因送八叔拾遺戲贈詔追南來諸賓二首 二', '奉酬楊侍郎丈因送八叔拾遺戲贈詔追南来諸賓二首 二', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["一生判却歸休，謂著南冠到頭。","冶長雖解縲絏，無由得見東周。"]', '["一生判却归休，謂著南冠到头。","冶长雖解縲絏，無由得见东周。"]', '诗', 'shi', '', NULL, '奉酬楊侍郎丈因送八叔拾遺戲贈詔追南來諸賓二首 二 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3b573aa-58b9-41ef-b21c-4799f3c98a56', '商山臨路有孤松往來斫以爲明好事者憐之編竹成楥遂其生植感而賦詩', '商山臨路有孤松往来斫以爲明好事者怜之編竹成楥遂其生植感而賦诗', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["孤松停翠蓋，託根臨廣路。","不以險自防，遂爲明所誤。","幸逢仁惠意，重此藩籬護。","猶有半心存，時將承雨露。"]', '["孤松停翠蓋，託根臨廣路。","不以險自防，遂爲明所誤。","幸逢仁惠意，重此藩籬護。","猶有半心存，时將承雨露。"]', '诗', 'shi', '', NULL, '商山臨路有孤松往來斫以爲明好事者憐之編竹成楥遂其生植感而賦詩 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d475032-daa2-4ee7-bbaa-dbd8d0bc2dca', '衡陽與夢得分路贈別', '衡陽與梦得分路贈別', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["十年顦顇到秦京，誰料翻爲嶺外行。","伏波故道風煙在，翁仲遺墟草樹平。","直以慵疎招物議，休將文字占時名。","今朝不用臨河別，垂淚千行便濯纓。"]', '["十年顦顇到秦京，誰料翻爲嶺外行。","伏波故道风煙在，翁仲遺墟草樹平。","直以慵疎招物議，休將文字占时名。","今朝不用臨河別，垂泪千行便濯纓。"]', '诗', 'shi', '', NULL, '衡陽與夢得分路贈別 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe6a4fdb-7d32-47ad-b976-da9d50df4368', '重別夢得', '重別梦得', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["二十年來萬事同，今朝岐路忽西東。","皇恩若許歸田去，晚歲當爲鄰舍翁。"]', '["二十年来万事同，今朝岐路忽西东。","皇恩若許归田去，晚歲當爲鄰舍翁。"]', '诗', 'shi', '', NULL, '重別夢得 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d28f7fa2-d327-44a2-9d39-c432e24ccb15', '三贈劉員外', '三贈劉員外', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["信書成自誤，經事漸知非。","今日臨岐別，何年待汝歸。"]', '["信书成自誤，經事漸知非。","今日臨岐別，何年待汝归。"]', '诗', 'shi', '', NULL, '三贈劉員外 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d60160ba-08f7-45a8-85c5-a96ed2c09449', '再上湘江', '再上湘江', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["好在湘江水，今朝又上來。","不知從此去，更遣幾年迴。"]', '["好在湘江水，今朝又上来。","不知從此去，更遣幾年迴。"]', '诗', 'shi', '', NULL, '再上湘江 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd6aa460-87be-4520-94c6-ccdfc93d1431', '清水驛叢竹天水趙云余手種一十二莖', '清水驛叢竹天水趙云余手種一十二莖', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["簷下疎篁十二莖，襄陽從事寄幽情。","祗應更指伶倫見，寫盡雌雄雙鳳鳴。"]', '["簷下疎篁十二莖，襄陽從事寄幽情。","祗應更指伶倫见，寫尽雌雄雙鳳鳴。"]', '诗', 'shi', '', NULL, '清水驛叢竹天水趙云余手種一十二莖 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3779cd3c-8ef9-4259-8f2a-f3110b4aac09', '長沙驛前南樓感舊', '长沙驛前南楼感旧', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["海鶴一爲別，存亡三十秋。","今來數行淚，獨上驛南樓。"]', '["海鹤一爲別，存亡三十秋。","今来數行泪，独上驛南楼。"]', '诗', 'shi', '', NULL, '長沙驛前南樓感舊 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1165e3b-828f-4c97-8494-e9347cbb61f9', '桂州北望秦驛手開竹徑至釣磯留待徐容州', '桂州北望秦驛手开竹徑至釣磯留待徐容州', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["幽徑爲誰開，美人城北來。","王程倘餘暇，一上子陵臺。"]', '["幽徑爲誰开，美人城北来。","王程倘餘暇，一上子陵台。"]', '诗', 'shi', '', NULL, '桂州北望秦驛手開竹徑至釣磯留待徐容州 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d26433c-a673-4094-8c83-cadb1b08412a', '登柳州城樓寄漳汀封連四州', '登柳州城楼寄漳汀封連四州', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["城上高樓接大荒，海天愁思正茫茫。","驚風亂颭芙蓉水，密雨斜侵薜荔牆。","嶺樹重遮千里目，江流曲似九廻腸。","共來百越文身地，猶自音書滯一鄉。"]', '["城上高楼接大荒，海天愁思正茫茫。","驚风亂颭芙蓉水，密雨斜侵薜荔牆。","嶺樹重遮千里目，江流曲似九廻腸。","共来百越文身地，猶自音书滯一乡。"]', '诗', 'shi', '', NULL, '登柳州城樓寄漳汀封連四州 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('424c1536-61e0-48ae-8333-1eec727f5eb6', '柳州寄丈人周韶州', '柳州寄丈人周韶州', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["越絕孤城千萬峰，空齋不語坐高舂。","印文生綠經旬合，硯匣留塵盡日封。","梅嶺寒煙藏翡翠，桂江秋水露鰅鳙。","丈人本自忘機事，爲想年來憔悴容。"]', '["越絕孤城千万峰，空斋不語坐高舂。","印文生綠經旬合，硯匣留塵尽日封。","梅嶺寒煙藏翡翠，桂江秋水露鰅鳙。","丈人本自忘機事，爲想年来憔悴容。"]', '诗', 'shi', '', NULL, '柳州寄丈人周韶州 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d41a204e-f263-4b55-aa31-5b92bc8e3c78', '登柳州峨山', '登柳州峨山', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["荒山秋日午，獨上意悠悠。","如何望鄉處，西北是融州。"]', '["荒山秋日午，独上意悠悠。","如何望乡处，西北是融州。"]', '诗', 'shi', '', NULL, '登柳州峨山 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('212bf7ea-f6b1-4e8e-a98f-695166f02597', '得盧衡州書因以詩寄', '得盧衡州书因以诗寄', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["臨蒸且莫歎炎方，爲報秋來雁幾行。","林邑東廻山似戟，牂牁南下水如湯。","蒹葭浙瀝含秋霧，橘柚玲瓏透夕陽。","非是白蘋洲畔客，還將遠意問瀟湘。"]', '["臨蒸且莫歎炎方，爲報秋来雁幾行。","林邑东廻山似戟，牂牁南下水如湯。","蒹葭浙瀝含秋霧，橘柚玲瓏透夕陽。","非是白蘋洲畔客，還將远意问瀟湘。"]', '诗', 'shi', '', NULL, '得盧衡州書因以詩寄 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d153ce7-5125-419a-bec6-72bc18d34967', '答劉連州邦字', '答劉連州邦字', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["連璧本難雙，分符刺小邦。","崩雲下灕水，劈箭上潯江。","負弩啼寒狖，鳴枹驚夜狵。","遙憐郡山好，謝守但臨窗。"]', '["連璧本难雙，分符刺小邦。","崩云下灕水，劈箭上潯江。","負弩啼寒狖，鳴枹驚夜狵。","遙怜郡山好，謝守但臨窗。"]', '诗', 'shi', '', NULL, '答劉連州邦字 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('382c265b-130c-43b1-b500-f49215b85f2e', '嶺南江行', '嶺南江行', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["瘴江南去入雲煙，望盡黃茆是海邊。","山腹雨晴添象跡，潭心日暖長蛟涎。","射工巧伺遊人影，颶母偏驚旅客船。","從此憂來非一事，豈容華髪待流年。"]', '["瘴江南去入云煙，望尽黄茆是海邊。","山腹雨晴添象跡，潭心日暖长蛟涎。","射工巧伺游人影，颶母偏驚旅客船。","從此憂来非一事，豈容华髪待流年。"]', '诗', 'shi', '', NULL, '嶺南江行 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4219b728-27b9-41d8-93bb-504ae1465338', '柳州峒氓', '柳州峒氓', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["郡城南下接通津，異服殊音不可親。","青箬裹鹽歸峒客，綠荷包飯趂虛人。","鵝毛禦臘縫山罽，雞骨占年拜水神。","愁向公庭問重譯，欲投章甫作文身。"]', '["郡城南下接通津，異服殊音不可親。","青箬裹鹽归峒客，綠荷包飯趂虛人。","鵝毛禦臘縫山罽，雞骨占年拜水神。","愁向公庭问重譯，欲投章甫作文身。"]', '诗', 'shi', '', NULL, '柳州峒氓 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('959dee20-a6ce-46d5-87a5-b2c84bd68332', '酬徐二中丞普寧郡內池館即事見寄', '酬徐二中丞普寧郡內池館即事见寄', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["鵷鴻念舊行，虛館對芳塘。","落日明朱檻，繁花照羽觴。","泉歸滄海近，樹入楚山長。","榮賤俱爲累，相期在故鄉。"]', '["鵷鴻念旧行，虛館对芳塘。","落日明朱檻，繁花照羽觴。","泉归滄海近，樹入楚山长。","榮賤俱爲累，相期在故乡。"]', '诗', 'shi', '', NULL, '酬徐二中丞普寧郡內池館即事見寄 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79a30dfa-4ed0-4d45-98d3-1ac80b0defc1', '酬賈鵬山人郡內新栽松寓興見贈二首 一', '酬賈鵬山人郡內新栽松寓兴见贈二首 一', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["芳巧自爲別，無心乃玄功。","夭夭日放花，榮耀將安窮。","青松遺澗底，擢蒔茲庭中。","積雪表明秀，寒花助葱蘢。","貞幽夙有慕，持以延清風。"]', '["芳巧自爲別，無心乃玄功。","夭夭日放花，榮耀將安窮。","青松遺澗底，擢蒔茲庭中。","積雪表明秀，寒花助葱蘢。","貞幽夙有慕，持以延清风。"]', '诗', 'shi', '', NULL, '酬賈鵬山人郡內新栽松寓興見贈二首 一 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87b71056-e4f5-4cc5-b42b-63d2ee7fa562', '酬賈鵬山人郡內新栽松寓興見贈二首 二', '酬賈鵬山人郡內新栽松寓兴见贈二首 二', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["無能常閉閣，偶以靜見名。","奇姿來遠山，忽似人家生。","勁色不改舊，芳心與誰榮。","喧卑豈所安，任物非我情。","清韻動竽瑟，諧此風中聲。"]', '["無能常閉閣，偶以静见名。","奇姿来远山，忽似人家生。","勁色不改旧，芳心與誰榮。","喧卑豈所安，任物非我情。","清韻动竽瑟，諧此风中声。"]', '诗', 'shi', '', NULL, '酬賈鵬山人郡內新栽松寓興見贈二首 二 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bc9518f-6506-4720-89f8-b49b2958a855', '種柳戲題', '種柳戲題', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["柳州柳刺史，種柳柳江邊。","談笑爲故事，推移成昔年。","垂陰當覆地，聳幹會參天。","好作思人樹，慚無惠化傳。"]', '["柳州柳刺史，種柳柳江邊。","談笑爲故事，推移成昔年。","垂陰當覆地，聳幹會參天。","好作思人樹，慚無惠化傳。"]', '诗', 'shi', '', NULL, '種柳戲題 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5679526b-d077-4f1f-a67e-fc430e4643a9', '柳州二月榕葉落盡偶題', '柳州二月榕葉落尽偶題', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["宦情羈思共悽悽，春半如秋意轉迷。","山城過雨百花盡，榕葉滿庭鶯亂啼。"]', '["宦情羈思共悽悽，春半如秋意轉迷。","山城過雨百花尽，榕葉满庭鶯亂啼。"]', '诗', 'shi', '', NULL, '柳州二月榕葉落盡偶題 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('354d1430-5c88-4520-9397-3e7d5ceaa076', '浩初上人見貽絕句欲登仙人山因以酬之', '浩初上人见貽絕句欲登仙人山因以酬之', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["珠樹玲瓏隔翠微，病來方外事多違。","仙山不屬分符客，一任凌空錫杖飛。"]', '["珠樹玲瓏隔翠微，病来方外事多違。","仙山不屬分符客，一任凌空錫杖飞。"]', '诗', 'shi', '', NULL, '浩初上人見貽絕句欲登仙人山因以酬之 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fb004f1-ffec-441c-8a85-0e022d75f293', '雨中贈仙人山賈山人', '雨中贈仙人山賈山人', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["寒江夜雨聲潺潺，曉雲遮盡仙人山。","遙知玄豹在深處，下笑羈絆泥塗間。"]', '["寒江夜雨声潺潺，晓云遮尽仙人山。","遙知玄豹在深处，下笑羈絆泥塗间。"]', '诗', 'shi', '', NULL, '雨中贈仙人山賈山人 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf3a0ecd-c2dd-468d-adf6-26b1e3d92f76', '別舍弟宗一', '別舍弟宗一', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["零落殘紅倍黯然，雙垂別淚越江邊。","一身去國六千里，萬死投荒十二年。","桂嶺瘴來雲似墨，洞庭春盡水如天。","欲知此後相思夢，長在荆門郢樹煙。"]', '["零落殘紅倍黯然，雙垂別泪越江邊。","一身去国六千里，万死投荒十二年。","桂嶺瘴来云似墨，洞庭春尽水如天。","欲知此後相思梦，长在荆门郢樹煙。"]', '诗', 'shi', '', NULL, '別舍弟宗一 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bd52da1-5075-49d7-bcde-6680d97e5441', '奉和周二十丈酬郴州侍郎衡江夜泊得韶州書幷附當州生黃茶一封率然成篇代意之作', '奉和周二十丈酬郴州侍郎衡江夜泊得韶州书幷附當州生黄茶一封率然成篇代意之作', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["丘山仰德耀，天路下征騑。","夢喜三刀近，書嫌五載違。","凝情江月落，屬思嶺雲飛。","會入司徒府，還邀周掾歸。"]', '["丘山仰德耀，天路下征騑。","梦喜三刀近，书嫌五載違。","凝情江月落，屬思嶺云飞。","會入司徒府，還邀周掾归。"]', '诗', 'shi', '', NULL, '奉和周二十丈酬郴州侍郎衡江夜泊得韶州書幷附當州生黃茶一封率然成篇代意之作 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd90f31a-75b7-4f67-b707-f8a21fd135bc', '殷賢戲批書後寄劉連州幷示孟崙二童', '殷賢戲批书後寄劉連州幷示孟崙二童', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["書成欲寄庾安西，紙背應勞手自題。","聞到盡來諸子弟，臨池尋已厭家雞。"]', '["书成欲寄庾安西，紙背應勞手自題。","闻到尽来諸子弟，臨池尋已厭家雞。"]', '诗', 'shi', '', NULL, '殷賢戲批書後寄劉連州幷示孟崙二童 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeeaecf4-1f4f-4809-81f3-13040acb9e04', '重贈二首 一', '重贈二首 一', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["聞道將雛向墨池，劉家還有異同詞。","如今試遣隈牆問，已道世人那得知。"]', '["闻道將雛向墨池，劉家還有異同词。","如今試遣隈牆问，已道世人那得知。"]', '诗', 'shi', '', NULL, '重贈二首 一 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c75f28d6-1e45-4499-89cd-ce3224eb9043', '重贈二首 二', '重贈二首 二', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["世上悠悠不識真，薑芽盡是捧心人。","若道柳家無子弟，往年何事乞西賓。"]', '["世上悠悠不識真，薑芽尽是捧心人。","若道柳家無子弟，往年何事乞西賓。"]', '诗', 'shi', '', NULL, '重贈二首 二 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e752c7ea-b896-4dd1-881c-1ae06f7951d3', '疊前', '叠前', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["小學新翻墨沼波，羨君瓊樹散枝柯。","左家弄玉唯嬌女，空覺庭前鳥跡多。"]', '["小学新翻墨沼波，羨君瓊樹散枝柯。","左家弄玉唯嬌女，空覺庭前鸟跡多。"]', '诗', 'shi', '', NULL, '疊前 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc1afe59-acba-49a3-ac70-655752a51636', '疊後', '叠後', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["事業無成耻藝成，南宮起草舊連名。","勸君火急添功用，趂取當時二妙聲。"]', '["事業無成耻藝成，南宮起草旧連名。","勸君火急添功用，趂取當时二妙声。"]', '诗', 'shi', '', NULL, '疊後 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9765ae66-ebe0-4cc1-9114-84514dcb0c94', '銅魚使赴都寄親友', '銅鱼使赴都寄親友', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["行盡關山萬里餘，到時閭井是荒墟。","附庸唯有銅魚使，此後無因寄遠書。"]', '["行尽关山万里餘，到时閭井是荒墟。","附庸唯有銅鱼使，此後無因寄远书。"]', '诗', 'shi', '', NULL, '銅魚使赴都寄親友 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8266d738-14bb-4717-a174-470b71253311', '韓漳州書報徹上人亡因寄二絕 一', '韓漳州书報徹上人亡因寄二絕 一', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["早歲京華聽越吟，聞君江海分逾深。","他時若寫蘭亭會，莫畫高僧支道林。"]', '["早歲京华听越吟，闻君江海分逾深。","他时若寫蘭亭會，莫畫高僧支道林。"]', '诗', 'shi', '', NULL, '韓漳州書報徹上人亡因寄二絕 一 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6705464-4bc5-4f1b-944b-ed96dc055204', '韓漳州書報徹上人亡因寄二絕 二', '韓漳州书報徹上人亡因寄二絕 二', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["頻把瓊書出袖中，獨吟遺句立秋風。","桂江日夜流千里，揮淚何時到甬東。"]', '["頻把瓊书出袖中，独吟遺句立秋风。","桂江日夜流千里，揮泪何时到甬东。"]', '诗', 'shi', '', NULL, '韓漳州書報徹上人亡因寄二絕 二 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67d3c773-4fd0-410c-8f19-d2ffd45b8934', '柳州城西北隅種柑樹', '柳州城西北隅種柑樹', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["手種黃柑二百株，春來新葉徧城隅。","方同楚客憐皇樹，不學荆州利木奴。","幾歲開花聞噴雪，何人摘實見垂珠。","若教坐待成林日，滋味還堪養老夫。"]', '["手種黄柑二百株，春来新葉徧城隅。","方同楚客怜皇樹，不学荆州利木奴。","幾歲开花闻噴雪，何人摘實见垂珠。","若教坐待成林日，滋味還堪養老夫。"]', '诗', 'shi', '', NULL, '柳州城西北隅種柑樹 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a09b5f48-59f0-4139-9efa-1a97582dbc9e', '聞徹上人亡寄侍郎楊丈', '闻徹上人亡寄侍郎楊丈', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["東越高僧還姓湯，幾時瓊佩觸鳴璫。","空花一散不知處，誰采金英與侍郎。"]', '["东越高僧還姓湯，幾时瓊佩觸鳴璫。","空花一散不知处，誰采金英與侍郎。"]', '诗', 'shi', '', NULL, '聞徹上人亡寄侍郎楊丈 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d29596db-d8ae-4411-ac71-3e408a2f3801', '段九秀才處見亡友呂衡州書迹', '段九秀才处见亡友呂衡州书迹', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["交侶平生意最親，衡陽往事似分身。","袖中忽見三行字，拭淚相看是故人。"]', '["交侶平生意最親，衡陽往事似分身。","袖中忽见三行字，拭泪相看是故人。"]', '诗', 'shi', '', NULL, '段九秀才處見亡友呂衡州書迹 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2af1834-05f0-4b2b-abee-1fa3116c5ea0', '柳州寄京中親故', '柳州寄京中親故', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["林邑山連瘴海秋，牂牁水向郡前流。","勞君遠問龍城地，正北三千到錦州。"]', '["林邑山連瘴海秋，牂牁水向郡前流。","勞君远问龙城地，正北三千到錦州。"]', '诗', 'shi', '', NULL, '柳州寄京中親故 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40932cc3-cb8e-4e0f-ba48-9bd1bd6ca4f7', '種木槲花', '種木槲花', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["上苑年年占物華，飄零今日在天涯。","祗因長作龍城守，剩種庭前木槲花。"]', '["上苑年年占物华，飄零今日在天涯。","祗因长作龙城守，剩種庭前木槲花。"]', '诗', 'shi', '', NULL, '種木槲花 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a8f448f-d34b-4f01-95ca-4c0111970197', '摘櫻桃贈元居士時在望仙亭南樓與朱道士同處', '摘櫻桃贈元居士时在望仙亭南楼與朱道士同处', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["海上朱櫻贈所思，樓居況是望仙時。","蓬萊羽客如相訪，不是偷桃一小兒。"]', '["海上朱櫻贈所思，楼居況是望仙时。","蓬萊羽客如相訪，不是偷桃一小兒。"]', '诗', 'shi', '', NULL, '摘櫻桃贈元居士時在望仙亭南樓與朱道士同處 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79c4501d-99f2-4e89-86a2-93f3a8636022', '酬曹侍御過象縣見寄', '酬曹侍御過象縣见寄', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["破額山前碧玉流，騷人遙駐木蘭舟。","春風無限瀟湘意，欲採蘋花不自由。"]', '["破額山前碧玉流，騷人遙駐木蘭舟。","春风無限瀟湘意，欲採蘋花不自由。"]', '诗', 'shi', '', NULL, '酬曹侍御過象縣見寄 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2298ea36-2160-44bf-9c71-7149e2d34dfa', '法華寺石門精舍三十韻', '法华寺石门精舍三十韻', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["拘情病幽鬱，曠志寄高爽。","願言懷名緇，東峰旦夕仰。","始欣雲雨霽，尤悅草木長。","道同有愛弟，披拂恣心賞。","松谿𥦖窱入，石棧夤緣上。","蘿葛綿層甍，莓苔侵標牓。","密林互對聳，絕壁儼雙敞。","塹峭出蒙籠，墟險臨滉瀁。","稍疑地脉斷，悠若天梯往。","結構罩羣崖，廻環驅萬象。","小劫不逾瞬，大千若在掌。","體空得化元，觀有遺細想。","喧煩困蠛蠓，跼蹐疲魍魎。","寸進諒何營，尋直非所枉。","探奇極遙矚，窮妙閟清響。","理會方在今，神開庶殊曩。","茲遊苟不嗣，浩氣竟誰養。","道異誠所希，名賓匪余仗。","超攄藉外獎，俯默有內朗。","鑑爾揖古風，終焉乃吾黨。","潛軀委韁鎖，高步謝塵坱。","蓄志徒爲勞，追縱將焉倣。","淹留值頹暮，眷戀睇遐壤。","映日雁聯軒，翻雲波泱漭。","殊風紛已萃，鄉路悠且廣。","羈木畏漂浮，離旌倦搖蕩。","昔人歎違志，出處今已兩。","何用期所歸，浮圖有遺像。","幽蹊不盈尺，虛室有函丈。","微言信可傳，申旦稽吾顙。"]', '["拘情病幽鬱，曠志寄高爽。","願言懷名緇，东峰旦夕仰。","始欣云雨霽，尤悅草木长。","道同有愛弟，披拂恣心賞。","松谿𥦖窱入，石棧夤緣上。","蘿葛綿層甍，莓苔侵標牓。","密林互对聳，絕壁儼雙敞。","塹峭出蒙籠，墟險臨滉瀁。","稍疑地脉斷，悠若天梯往。","結構罩羣崖，廻环驱万象。","小劫不逾瞬，大千若在掌。","體空得化元，观有遺細想。","喧煩困蠛蠓，跼蹐疲魍魎。","寸進諒何營，尋直非所枉。","探奇極遙矚，窮妙閟清响。","理會方在今，神开庶殊曩。","茲游苟不嗣，浩氣竟誰養。","道異誠所希，名賓匪余仗。","超攄藉外獎，俯默有內朗。","鑑爾揖古风，終焉乃吾黨。","潛軀委韁鎖，高步謝塵坱。","蓄志徒爲勞，追縱將焉倣。","淹留值頹暮，眷戀睇遐壤。","映日雁聯軒，翻云波泱漭。","殊风紛已萃，乡路悠且廣。","羈木畏漂浮，離旌倦搖蕩。","昔人歎違志，出处今已兩。","何用期所归，浮圖有遺像。","幽蹊不盈尺，虛室有函丈。","微言信可傳，申旦稽吾顙。"]', '诗', 'shi', '', NULL, '法華寺石門精舍三十韻 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('653e7422-5ea4-4ab0-b23b-6f457b9a54f3', '遊朝陽巖遂登西亭二十韻', '游朝陽巖遂登西亭二十韻', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["謫棄殊隱淪，登陟非遠郊。","所懷緩伊鬱，詎欲肩夷巢。","高巖瞰清江，幽窟潛神蛟。","開曠延陽景，廻薄攢林梢。","西亭搆其巓，反字臨呀庨。","背瞻星辰興，下見雲雨交。","惜非吾鄉土，得以蔭菁茆。","羈貫去江介，世仕尚函崤。","故墅即灃川，數畝均肥磽。","臺館葺荒丘，池塘疏沈坳。","會有圭組戀，遂貽山林嘲。","薄軀信無庸，瑣屑劇斗筲。","囚居固其宜，厚羞久已包。","庭除植蓬艾，隟牖懸蠨蛸。","所賴山川客，扁舟枉長梢。","挹流敵清觴，掇野代嘉肴。","適道有高言，取樂非絃匏。","逍遙屏幽昧，淡薄辭喧呶。","晨雞不余欺，風雨聞嘐嘐。","再期永日閒，提挈移中庖。"]', '["謫棄殊隐淪，登陟非远郊。","所懷緩伊鬱，詎欲肩夷巢。","高巖瞰清江，幽窟潛神蛟。","开曠延陽景，廻薄攢林梢。","西亭搆其巓，反字臨呀庨。","背瞻星辰兴，下见云雨交。","惜非吾乡土，得以蔭菁茆。","羈貫去江介，世仕尚函崤。","故墅即灃川，數畝均肥磽。","台館葺荒丘，池塘疏沈坳。","會有圭組戀，遂貽山林嘲。","薄軀信無庸，瑣屑劇斗筲。","囚居固其宜，厚羞久已包。","庭除植蓬艾，隟牖懸蠨蛸。","所賴山川客，扁舟枉长梢。","挹流敵清觴，掇野代嘉肴。","適道有高言，取乐非絃匏。","逍遙屏幽昧，淡薄辞喧呶。","晨雞不余欺，风雨闻嘐嘐。","再期永日閒，提挈移中庖。"]', '诗', 'shi', '', NULL, '遊朝陽巖遂登西亭二十韻 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6338edb-f09e-4d88-adcd-f1752a9195a6', '湘口館瀟湘二水所會', '湘口館瀟湘二水所會', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["九疑濬傾奔，臨源委縈廻。","會合屬空曠，泓澄停風雷。","高館軒霞表，危樓臨山隈。","茲辰始澂霽，纖雲盡褰開。","天秋日正中，水碧無塵埃。","杳杳漁父吟，呌呌羈鴻哀。","境勝豈不豫，慮分固難裁。","升高欲自舒，彌使遠念來。","歸流駛且廣，汎舟絕沿洄。"]', '["九疑濬傾奔，臨源委縈廻。","會合屬空曠，泓澄停风雷。","高館軒霞表，危楼臨山隈。","茲辰始澂霽，纖云尽褰开。","天秋日正中，水碧無塵埃。","杳杳漁父吟，呌呌羈鴻哀。","境勝豈不豫，慮分固难裁。","升高欲自舒，彌使远念来。","归流駛且廣，汎舟絕沿洄。"]', '诗', 'shi', '', NULL, '湘口館瀟湘二水所會 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20491a26-8ddd-490c-bc26-c8d48929d779', '登蒲州石磯望橫江口潭島深逈斜對香零山', '登蒲州石磯望橫江口潭島深逈斜对香零山', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["隱憂倦永夜，凌霧臨江津。","猿鳴稍已疎，登石娛清淪。","日出洲渚靜，澄明皛無垠。","浮暉翻高禽，沈景照文鱗。","雙江匯西奔，詭怪潛坤珍。","孤山乃北峙，森爽棲靈神。","洄潭或動容，島嶼疑搖振。","陶埴茲擇土，蒲魚相與鄰。","信美非所安，羈心屢逡巡。","糺結良可解，紆鬱亦已伸。","高歌返故室，自誷非所欣。"]', '["隐憂倦永夜，凌霧臨江津。","猿鳴稍已疎，登石娛清淪。","日出洲渚静，澄明皛無垠。","浮暉翻高禽，沈景照文鱗。","雙江匯西奔，詭怪潛坤珍。","孤山乃北峙，森爽棲靈神。","洄潭或动容，島嶼疑搖振。","陶埴茲擇土，蒲鱼相與鄰。","信美非所安，羈心屢逡巡。","糺結良可解，紆鬱亦已伸。","高歌返故室，自誷非所欣。"]', '诗', 'shi', '', NULL, '登蒲州石磯望橫江口潭島深逈斜對香零山 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e20e81c8-9fb7-47ee-adf9-b6cf3d62ed56', '南磵中題', '南磵中題', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["秋氣集南磵，獨遊亭午時。","廻風一蕭瑟，林影久參差。","始至若有得，稍深遂忘疲。","羈禽響幽谷，寒藻舞淪漪。","去國魂已遠，懷人淚空垂。","孤生易爲感，失路少所宜。","索寞竟何事，徘徊秖自知。","誰爲後來者，當與此心期。"]', '["秋氣集南磵，独游亭午时。","廻风一蕭瑟，林影久參差。","始至若有得，稍深遂忘疲。","羈禽响幽谷，寒藻舞淪漪。","去国魂已远，懷人泪空垂。","孤生易爲感，失路少所宜。","索寞竟何事，徘徊秖自知。","誰爲後来者，當與此心期。"]', '诗', 'shi', '', NULL, '南磵中題 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25d5785e-b764-498d-b08a-887987b2513c', '遊石角過小嶺至長烏村', '游石角過小嶺至长烏村', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["志適不期貴，道存豈偷生。","久忘上封事，復笑昇天行。","竄逐宦湘浦，搖心劇懸旌。","始驚陷世議，終欲逃天刑。","歲月殺憂慄，慵疎寡將迎。","追遊疑所愛，且復舒吾情。","石角恣幽步，長烏遂遐征。","磴廻茂樹斷，景晏寒川明。","曠望少行人，時聞田鸛鳴。","風篁冒水遠，霜稻侵山平。","稍與人事閒，益知身世輕。","爲農信可樂，居寵真虛榮。","喬木餘故國，願言果丹誠。","四支反田畝，釋至東臯耕。"]', '["志適不期貴，道存豈偷生。","久忘上封事，复笑昇天行。","竄逐宦湘浦，搖心劇懸旌。","始驚陷世議，終欲逃天刑。","歲月殺憂慄，慵疎寡將迎。","追游疑所愛，且复舒吾情。","石角恣幽步，长烏遂遐征。","磴廻茂樹斷，景晏寒川明。","曠望少行人，时闻田鸛鳴。","风篁冒水远，霜稻侵山平。","稍與人事閒，益知身世轻。","爲農信可乐，居寵真虛榮。","喬木餘故国，願言果丹誠。","四支反田畝，釋至东臯耕。"]', '诗', 'shi', '', NULL, '遊石角過小嶺至長烏村 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ef0fcb1-5259-4a80-a64e-9bba53c50f36', '與崔策登西山', '與崔策登西山', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["鶴鳴楚山靜，露白秋江曉。","連袂度危橋，縈廻出林杪。","西岑極遠目，毫末皆可了。","重疊九疑高，微茫洞庭小。","逈窮兩儀際，高出萬象表。","馳景泛頹波，遙風遞寒篠。","謫居安所習，稍厭從紛擾。","生同胥靡遺，壽比彭鏗夭。","蹇連困顛踣，愚蒙怯幽眇。","非令親愛疎，誰使心神悄。","偶茲遁山水，得以觀魚鳥。","吾子幸淹留，緩我愁腸繞。"]', '["鹤鳴楚山静，露白秋江晓。","連袂度危橋，縈廻出林杪。","西岑極远目，毫末皆可了。","重叠九疑高，微茫洞庭小。","逈窮兩儀際，高出万象表。","驰景泛頹波，遙风遞寒篠。","謫居安所習，稍厭從紛擾。","生同胥靡遺，壽比彭鏗夭。","蹇連困顛踣，愚蒙怯幽眇。","非令親愛疎，誰使心神悄。","偶茲遁山水，得以观鱼鸟。","吾子幸淹留，緩我愁腸繞。"]', '诗', 'shi', '', NULL, '與崔策登西山 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c328476f-ca1d-4e6f-b9db-19075cb5c39a', '構法華寺西亭', '構法华寺西亭', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["竄身楚南極，山水窮險艱。","步登最高寺，蕭散任疎頑。","西垂下斗絕，欲似窺人寰。","反如在幽谷，榛翳不可攀。","命童恣披翦，葺宇橫斷山。","割如判清濁，飄若升雲間。","遠岫攢衆頂，澄江抱清灣。","夕照臨軒墮，棲鳥當我還。","菡萏溢嘉色，篔簹遺清斑。","神舒屏羈鎖，志適忘幽孱。","棄逐久枯槁，迨今始開顏。","賞心難久留，離念來相關。","北望間親愛，南瞻雜夷蠻。","置之勿復道，且寄須臾閑。"]', '["竄身楚南極，山水窮險艱。","步登最高寺，蕭散任疎頑。","西垂下斗絕，欲似窺人寰。","反如在幽谷，榛翳不可攀。","命童恣披翦，葺宇橫斷山。","割如判清濁，飄若升云间。","远岫攢衆頂，澄江抱清灣。","夕照臨軒墮，棲鸟當我還。","菡萏溢嘉色，篔簹遺清斑。","神舒屏羈鎖，志適忘幽孱。","棄逐久枯槁，迨今始开顏。","賞心难久留，離念来相关。","北望间親愛，南瞻杂夷蠻。","置之勿复道，且寄須臾闲。"]', '诗', 'shi', '', NULL, '構法華寺西亭 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('812dcc1c-9da1-41ae-9b8a-734c021c631f', '夏夜苦熱登西樓', '夏夜苦熱登西楼', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["苦熱中夜起，登樓獨褰衣。","山澤凝暑氣，星漢湛光輝。","火晶燥露滋，野靜停風威。","探湯汲陰井，煬竈開重扉。","憑闌久彷徨，流汗不可揮。","莫辯亭毒意，仰訴璿與璣。","諒非姑射子，靜勝安能希。"]', '["苦熱中夜起，登楼独褰衣。","山澤凝暑氣，星漢湛光輝。","火晶燥露滋，野静停风威。","探湯汲陰井，煬竈开重扉。","憑闌久彷徨，流汗不可揮。","莫辯亭毒意，仰訴璿與璣。","諒非姑射子，静勝安能希。"]', '诗', 'shi', '', NULL, '夏夜苦熱登西樓 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47e1560e-42f1-4da5-9900-cf0b820e975d', '覺衰', '覺衰', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["久知老會至，不謂便見侵。","今年宜未衰，稍已來相尋。","齒疎髪就種，奔走力不任。","咄此可奈何，未必傷我心。","彭聃安在哉？周孔亦已沈。","古稱壽聖人，曾不留至今。","但願得美酒，朋友常共酙。","是時春向暮，桃李生繁陰。","日照天正綠，杳杳歸鴻吟。","出門呼所親，扶杖登西林。","高歌足自快，商頌有遺音。"]', '["久知老會至，不謂便见侵。","今年宜未衰，稍已来相尋。","齒疎髪就種，奔走力不任。","咄此可奈何，未必傷我心。","彭聃安在哉？周孔亦已沈。","古稱壽聖人，曾不留至今。","但願得美酒，朋友常共酙。","是时春向暮，桃李生繁陰。","日照天正綠，杳杳归鴻吟。","出门呼所親，扶杖登西林。","高歌足自快，商頌有遺音。"]', '诗', 'shi', '', NULL, '覺衰 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc7a8ce9-52d5-4b83-9a3c-8018aa5bab36', '遊南亭夜還敘志七十韻', '游南亭夜還敘志七十韻', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["夙抱丘壑尚，率性恣遊遨。","中爲吏役牽，十祀空悁勞。","外曲徇塵轍，私心寄英髦。","進乏廓廟器，退非鄉曲豪。","天命斯不易，鬼責將安逃。","屯難果見凌，剝喪宜所遭。","神明固浩浩，衆口徒嗷嗷。","投跡山水地，放情詠離騷。","再懷曩歲期，容與馳輕舠。","虛館背山郭，前軒面江臯。","重疊間浦溆，邐迤驅巖㟼。","積翠浮澹灧，始疑負靈鼇。","叢林留衝飆，石礫迎飛濤。","曠朗天景霽，樵蘇遠相號。","澄潭涌沈鷗，半壁跳懸猱。","鹿鳴驗食埜，魚樂知觀濠。","孤賞誠所悼，暫欣良足襃。","留連俯櫺檻，注我壺中醪。","朵頤進芰實，擢手持蟹螯。","炊稻視爨鼎，膾鮮聞操刀。","埜蔬盈傾筐，頗雜池沼芼。","緬慕鼓枻翁，嘯詠哺其糟。","退想於陵子，三咽資李螬。","斯道難爲偕，沈憂安所韜。","曲渚怨鴻鵠，環洲彫蘭𦺆。","暮景迴西岑，北流逝滔滔。","徘徊遂昏黑，遠火明連艘。","木落寒山靜，江空秋月高。","歛袂戒還徒，善游矜所操。","趣淺戢長枻，乘深屏輕篙。","曠望援深竿，哀歌叩鳴艚。","中川恣超忽，漫若翔且翱。","淹泊遂所止，埜風自颾颾。","澗急驚鱗奔，蹊荒饑獸嗥。","入門守拘縶，悽戚增鬱陶。","慕士情未忘，懷人首徒搔。","內顧乃無有，德輶甚鴻毛。","名竊久自欺，食浮固雲叨。","問牛悲釁鐘，說彘驚臨牢。","永遁刀筆吏，寧期簿書曹。","中興遂羣物，裂壤分鞬櫜。","岷凶既云捕，吳虜亦已鏖。","捍禦盛方虎，謨明富伊咎。","披山窮木禾，駕海逾蟠桃。","重來越裳雉，再返西旅獒。","左右抗槐棘，縱橫羅雁羔。","三辟咸肆宥，衆生均覆燾。","安得奉皇靈，在宥解天弢。","歸誠慰松梓，陳力開蓬篙。","卜室有鄠杜，名田占灃澇。","磻溪近餘基，阿城連故濠。","螟蛑願親燎，荼堇甘自薅。","飢食期農耕，寒衣俟蠶繰。","及骭足爲溫，滿腹寧復饕。","安將蒯及菅，誰慕粱與膏。","弋林敺雀鷃，漁澤從鰌魛。","觀象嘉素履，陳詩謝干旄。","方託麋鹿羣，敢同騏驥槽。","處賤無溷濁，固窮匪淫慆。","踉蹌辭束縛，悅懌換煎熬。","登年徒負版，興役趨代鼛。","目眩絕渾渾，耳喧息嘈嘈。","茲焉畢餘命，富貴非吾曹。","長沙哀糺纆，漢陰嗤桔槔。","苟伸擊壤情，機事息秋豪。","海霧多蓊鬱，越風饒腥臊。","寧唯迫魑魅，所懼齊焄藨。","知罃懷褚中，范叔戀綈袍。","伊人不可期，慷慨徒忉忉。"]', '["夙抱丘壑尚，率性恣游遨。","中爲吏役牽，十祀空悁勞。","外曲徇塵轍，私心寄英髦。","進乏廓廟器，退非乡曲豪。","天命斯不易，鬼責將安逃。","屯难果见凌，剝喪宜所遭。","神明固浩浩，衆口徒嗷嗷。","投跡山水地，放情詠離騷。","再懷曩歲期，容與驰轻舠。","虛館背山郭，前軒面江臯。","重叠间浦溆，邐迤驱巖㟼。","積翠浮澹灧，始疑負靈鼇。","叢林留衝飆，石礫迎飞濤。","曠朗天景霽，樵蘇远相號。","澄潭涌沈鷗，半壁跳懸猱。","鹿鳴驗食埜，鱼乐知观濠。","孤賞誠所悼，暫欣良足襃。","留連俯櫺檻，注我壺中醪。","朵頤進芰實，擢手持蟹螯。","炊稻視爨鼎，膾鲜闻操刀。","埜蔬盈傾筐，頗杂池沼芼。","緬慕鼓枻翁，嘯詠哺其糟。","退想於陵子，三咽資李螬。","斯道难爲偕，沈憂安所韜。","曲渚怨鴻鵠，环洲彫蘭𦺆。","暮景迴西岑，北流逝滔滔。","徘徊遂昏黑，远火明連艘。","木落寒山静，江空秋月高。","歛袂戒還徒，善游矜所操。","趣淺戢长枻，乘深屏轻篙。","曠望援深竿，哀歌叩鳴艚。","中川恣超忽，漫若翔且翱。","淹泊遂所止，埜风自颾颾。","澗急驚鱗奔，蹊荒饑獸嗥。","入门守拘縶，悽戚增鬱陶。","慕士情未忘，懷人首徒搔。","內顧乃無有，德輶甚鴻毛。","名竊久自欺，食浮固云叨。","问牛悲釁鐘，说彘驚臨牢。","永遁刀笔吏，寧期簿书曹。","中兴遂羣物，裂壤分鞬櫜。","岷凶既云捕，吳虜亦已鏖。","捍禦盛方虎，謨明富伊咎。","披山窮木禾，駕海逾蟠桃。","重来越裳雉，再返西旅獒。","左右抗槐棘，縱橫羅雁羔。","三辟咸肆宥，衆生均覆燾。","安得奉皇靈，在宥解天弢。","归誠慰松梓，陳力开蓬篙。","卜室有鄠杜，名田占灃澇。","磻溪近餘基，阿城連故濠。","螟蛑願親燎，荼堇甘自薅。","飢食期農耕，寒衣俟蠶繰。","及骭足爲溫，满腹寧复饕。","安將蒯及菅，誰慕粱與膏。","弋林敺雀鷃，漁澤從鰌魛。","观象嘉素履，陳诗謝干旄。","方託麋鹿羣，敢同騏驥槽。","处賤無溷濁，固窮匪淫慆。","踉蹌辞束縛，悅懌換煎熬。","登年徒負版，兴役趨代鼛。","目眩絕渾渾，耳喧息嘈嘈。","茲焉畢餘命，富貴非吾曹。","长沙哀糺纆，漢陰嗤桔槔。","苟伸擊壤情，機事息秋豪。","海霧多蓊鬱，越风饒腥臊。","寧唯迫魑魅，所懼齊焄藨。","知罃懷褚中，范叔戀綈袍。","伊人不可期，慷慨徒忉忉。"]', '诗', 'shi', '', NULL, '遊南亭夜還敘志七十韻 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fc1b3da-3ed1-4d9b-96ad-d17f5ecb4225', '韋道安', '韋道安', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["道安本儒士，頗擅弓劒名。","二十遊太行，暮聞號哭聲。","疾驅前致問，有叟垂華纓。","言我故刺史，失職還西京。","偶爲羣盜得，毫縷無餘贏。","貨財足非恡，二女皆娉婷。","蒼黃見驅逐，誰識死與生。","便當此殞命，休復事晨征。","一聞激高義，眥裂肝膽橫。","挂弓問所在，趫捷超崢嶸。","見盜寒磵陰，羅列方忿爭。","一矢斃酋帥，餘黨號且驚。","麾令遞束縛，纆索相拄撐。","彼姝久褫魄，刃下俟誅刑。","却立不親授，諭以從父行。","捃收自擔肩，轉道趨前程。","夜發敲石火，山林如晝明。","父子更抱持，涕血紛交零。","頓首願歸貨，納女稱舅甥。","道安舊衣去，義重利固輕。","師婚古所病，合姓非用兵。","朅來事儒術，十載所能逞。","慷慨張徐州，朱邸揚前旌。","投區獲所願，前馬出王城。","轅門立奇士，淮水秋風生。","君侯既即世，麾下相欹傾。","立孤抗王命，鐘鼓四野鳴。","橫潰非所壅，逆節非所嬰。","舉頭自引[刃]，顧義誰顧形。","烈士不忘死，所死在忠貞。","咄嗟徇權子，翕習尤趨榮。","我歌非悼死，所悼時世情。"]', '["道安本儒士，頗擅弓劒名。","二十游太行，暮闻號哭声。","疾驱前致问，有叟垂华纓。","言我故刺史，失職還西京。","偶爲羣盜得，毫縷無餘贏。","貨財足非恡，二女皆娉婷。","蒼黄见驱逐，誰識死與生。","便當此殞命，休复事晨征。","一闻激高義，眥裂肝膽橫。","挂弓问所在，趫捷超崢嶸。","见盜寒磵陰，羅列方忿爭。","一矢斃酋帥，餘黨號且驚。","麾令遞束縛，纆索相拄撐。","彼姝久褫魄，刃下俟誅刑。","却立不親授，諭以從父行。","捃收自擔肩，轉道趨前程。","夜發敲石火，山林如晝明。","父子更抱持，涕血紛交零。","頓首願归貨，納女稱舅甥。","道安旧衣去，義重利固轻。","師婚古所病，合姓非用兵。","朅来事儒術，十載所能逞。","慷慨張徐州，朱邸揚前旌。","投區獲所願，前马出王城。","轅门立奇士，淮水秋风生。","君侯既即世，麾下相欹傾。","立孤抗王命，鐘鼓四野鳴。","橫潰非所壅，逆節非所嬰。","舉头自引[刃]，顧義誰顧形。","烈士不忘死，所死在忠貞。","咄嗟徇權子，翕習尤趨榮。","我歌非悼死，所悼时世情。"]', '诗', 'shi', '', NULL, '韋道安 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca80ebc1-d68e-4ba3-9a03-1df39d1fd7a2', '哭連州凌員外司馬', '哭連州凌員外司马', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["廢逐人所棄，遂爲鬼神欺。","才難不其然，卒與大患期。","凌人古受氏，吳世夸雄姿。","寂寞富春水，英氣方在斯。","六學誠一貫，精義窮發揮。","著書逾十年，幽頥靡不推。","天庭掞高文，萬字若波馳。","記室征西府，宏謀耀其奇。","輶軒下東越，列郡蘇疲羸。","宛宛凌江羽，來棲翰林枝。","孝文留弓劒，中外方危疑。","抗聲促遺詔，定命由陳辭。","徒隸肅曹官，征賦參有司。","出守烏江滸，老遷湟水湄。","高堂傾故國，葬祭限囚羈。","仲叔繼幽淪，狂呌唯童兒。","一門既無主，焉用徒生爲。","舉聲但呼天，孰知神者誰。","泣盡目無見，腎傷足不持。","溘死委炎荒，臧獲守靈帷。","平生負國譴，骸骨非敢私。","蓋棺未塞責，孤旐凝寒颸。","念昔始相遇，腑腸爲君知。","進身齊選擇，失路同瑕疵。","本期濟仁義，今爲衆所嗤。","滅名竟不試，世義安可支。","恬死百憂盡，苟生萬慮滋。","顧余九逝魂，與子各何之。","我歌誠自慟，非獨爲君悲。"]', '["廢逐人所棄，遂爲鬼神欺。","才难不其然，卒與大患期。","凌人古受氏，吳世夸雄姿。","寂寞富春水，英氣方在斯。","六学誠一貫，精義窮發揮。","著书逾十年，幽頥靡不推。","天庭掞高文，万字若波驰。","記室征西府，宏謀耀其奇。","輶軒下东越，列郡蘇疲羸。","宛宛凌江羽，来棲翰林枝。","孝文留弓劒，中外方危疑。","抗声促遺詔，定命由陳辞。","徒隸肅曹官，征賦參有司。","出守烏江滸，老遷湟水湄。","高堂傾故国，葬祭限囚羈。","仲叔繼幽淪，狂呌唯童兒。","一门既無主，焉用徒生爲。","舉声但呼天，孰知神者誰。","泣尽目無见，腎傷足不持。","溘死委炎荒，臧獲守靈帷。","平生負国譴，骸骨非敢私。","蓋棺未塞責，孤旐凝寒颸。","念昔始相遇，腑腸爲君知。","進身齊選擇，失路同瑕疵。","本期濟仁義，今爲衆所嗤。","滅名竟不試，世義安可支。","恬死百憂尽，苟生万慮滋。","顧余九逝魂，與子各何之。","我歌誠自慟，非独爲君悲。"]', '诗', 'shi', '', NULL, '哭連州凌員外司馬 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d839121-570a-4a3b-a7ec-123ef750b664', '旦攜謝山人至愚池', '旦携謝山人至愚池', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["新沐換輕幘，曉池風露清。","自諧塵外意，況與幽人行。","霞散衆山逈，天高數雁鳴。","機心付當路，聊適羲皇情。"]', '["新沐換轻幘，晓池风露清。","自諧塵外意，況與幽人行。","霞散衆山逈，天高數雁鳴。","機心付當路，聊適羲皇情。"]', '诗', 'shi', '', NULL, '旦攜謝山人至愚池 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ff00086-6ece-4a0d-ad85-3ee36fb24f77', '獨覺', '独覺', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["覺來窗牖空，寥落雨聲曉。","良遊怨遲暮，末事驚紛擾。","爲問經世心，古人難盡了。"]', '["覺来窗牖空，寥落雨声晓。","良游怨遲暮，末事驚紛擾。","爲问經世心，古人难尽了。"]', '诗', 'shi', '', NULL, '獨覺 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62f80556-3154-4531-8866-26abd2553f1e', '首春逢耕者', '首春逢耕者', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["南楚春候早，餘寒已滋榮。","土膏釋原埜，百蟄競所營。","綴景未及郊，穡人先耦耕。","園林幽鳥囀，渚澤新泉清。","農事誠素務，羈囚阻平生。","故池想蕪沒，遺畝當榛荆。","慕隱既有繫，圖功遂無成。","聊從田父言，款曲陳此情。","眷然撫耒耜，回首煙雲橫。"]', '["南楚春候早，餘寒已滋榮。","土膏釋原埜，百蟄競所營。","綴景未及郊，穡人先耦耕。","园林幽鸟囀，渚澤新泉清。","農事誠素務，羈囚阻平生。","故池想蕪沒，遺畝當榛荆。","慕隐既有繫，圖功遂無成。","聊從田父言，款曲陳此情。","眷然撫耒耜，回首煙云橫。"]', '诗', 'shi', '', NULL, '首春逢耕者 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('469dec8b-ba5e-4faf-b52f-2ad203e38d81', '溪居', '溪居', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["久爲簪組累，幸此南夷謫。","閑依農圃鄰，偶似山林客。","曉耕翻露草，夜榜響溪石。","來往不逢人，長歌楚天碧。"]', '["久爲簪組累，幸此南夷謫。","闲依農圃鄰，偶似山林客。","晓耕翻露草，夜榜响溪石。","来往不逢人，长歌楚天碧。"]', '诗', 'shi', '', NULL, '溪居 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f361785-7997-4aa1-9a4f-e0068085f49f', '夏初雨後尋愚溪', '夏初雨後尋愚溪', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["悠悠雨初霽，獨繞清溪曲。","引杖試荒泉，解帶圍新竹。","沈吟亦何事，寂寞固所欲。","幸此息營營，嘯歌靜炎燠。"]', '["悠悠雨初霽，独繞清溪曲。","引杖試荒泉，解带圍新竹。","沈吟亦何事，寂寞固所欲。","幸此息營營，嘯歌静炎燠。"]', '诗', 'shi', '', NULL, '夏初雨後尋愚溪 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('260bc544-c174-4872-b312-831142afb9b0', '入黃溪聞猿', '入黄溪闻猿', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["溪路千里曲，哀猿何處鳴。","孤臣淚已盡，虛作斷腸聲。"]', '["溪路千里曲，哀猿何处鳴。","孤臣泪已尽，虛作斷腸声。"]', '诗', 'shi', '', NULL, '入黃溪聞猿 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5906e6f6-f3a8-468b-8e7e-1cbe696c239c', '韋使君黃溪祈雨見召從行至祠下口號', '韋使君黄溪祈雨见召從行至祠下口號', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["驕陽愆歲事，良牧念菑畬。","列騎低殘月，鳴笳度碧虛。","稍窮樵客路，遙駐野人居。","谷口寒流淨，叢祠古木疎。","焚香秋霧濕，奠玉曉光初。","肸蠁巫言報，精誠禮物餘。","惠風仍偃草，靈雨會隨車。","俟罪非真吏，翻慚奉簡書。"]', '["驕陽愆歲事，良牧念菑畬。","列騎低殘月，鳴笳度碧虛。","稍窮樵客路，遙駐野人居。","谷口寒流淨，叢祠古木疎。","焚香秋霧濕，奠玉晓光初。","肸蠁巫言報，精誠禮物餘。","惠风仍偃草，靈雨會隨车。","俟罪非真吏，翻慚奉簡书。"]', '诗', 'shi', '', NULL, '韋使君黃溪祈雨見召從行至祠下口號 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7906dd95-6598-4cae-9297-58ac173f8713', '郊居歲暮', '郊居歲暮', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["屏居負山郭，歲暮驚離索。","野逈樵唱來，庭空燒燼落。","世紛因事遠，心賞隨年薄。","默默諒何爲，徒成今與昨。"]', '["屏居負山郭，歲暮驚離索。","野逈樵唱来，庭空燒燼落。","世紛因事远，心賞隨年薄。","默默諒何爲，徒成今與昨。"]', '诗', 'shi', '', NULL, '郊居歲暮 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cfb1372-3aec-4131-ab6f-2ac73a29e2f8', '秋曉行南谷經荒村', '秋晓行南谷經荒村', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["杪秋霜露重，晨起行幽谷。","黃葉覆溪橋，荒村唯古木。","寒花疎寂歷，幽泉微斷續。","機心久已忘，何事驚麋鹿。"]', '["杪秋霜露重，晨起行幽谷。","黄葉覆溪橋，荒村唯古木。","寒花疎寂歷，幽泉微斷續。","機心久已忘，何事驚麋鹿。"]', '诗', 'shi', '', NULL, '秋曉行南谷經荒村 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('360ea23a-2963-4444-91b6-1ee5d44e6669', '雨後曉行獨至愚溪北池', '雨後晓行独至愚溪北池', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["宿雲散洲渚，曉日明村塢。","高樹臨清池，風驚夜來雨。","予心適無事，偶此成賓主。"]', '["宿云散洲渚，晓日明村塢。","高樹臨清池，风驚夜来雨。","予心適無事，偶此成賓主。"]', '诗', 'shi', '', NULL, '雨後曉行獨至愚溪北池 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22b36a7a-dc90-47d9-b5cb-0f1fcef619c0', '中夜起望西園值月上', '中夜起望西园值月上', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["覺聞繁露墜，開戶臨西園。","寒月上東嶺，泠泠疎竹根。","石泉遠逾響，山鳥時一喧。","倚楹遂至旦，寂寞將何言。"]', '["覺闻繁露墜，开戶臨西园。","寒月上东嶺，泠泠疎竹根。","石泉远逾响，山鸟时一喧。","倚楹遂至旦，寂寞將何言。"]', '诗', 'shi', '', NULL, '中夜起望西園值月上 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f72f173-5cf6-4fef-a8e8-eb6f9b68044c', '零陵春望', '零陵春望', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["平埜春草綠，曉鶯啼遠林。","日晴瀟湘渚，雲斷岣嶁岑。","仙駕不可望，世途非所任。","凝情空景慕，萬里蒼梧陰。"]', '["平埜春草綠，晓鶯啼远林。","日晴瀟湘渚，云斷岣嶁岑。","仙駕不可望，世途非所任。","凝情空景慕，万里蒼梧陰。"]', '诗', 'shi', '', NULL, '零陵春望 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('869a83a3-d57f-420b-a67f-45bc55c74e4e', '從崔中丞過盧少尹郊居', '從崔中丞過盧少尹郊居', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["寓居湘岸四無鄰，世網難嬰每自珍。","蒔藥閑庭延國老，開罇虛室值賢人。","泉迴淺石依高柳，逕轉垂藤閒綠筠。","聞道偏爲五禽戲，出門鷗鳥更相親。"]', '["寓居湘岸四無鄰，世網难嬰每自珍。","蒔藥闲庭延国老，开罇虛室值賢人。","泉迴淺石依高柳，逕轉垂藤閒綠筠。","闻道偏爲五禽戲，出门鷗鸟更相親。"]', '诗', 'shi', '', NULL, '從崔中丞過盧少尹郊居 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0944daf0-fb7e-4fdf-a2d4-e827e672356a', '夏晝偶作', '夏晝偶作', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["南州溽暑醉如酒，隱几熟眠開北牖。","日午獨覺無餘聲，山童隔竹敲茶臼。"]', '["南州溽暑醉如酒，隐几熟眠开北牖。","日午独覺無餘声，山童隔竹敲茶臼。"]', '诗', 'shi', '', NULL, '夏晝偶作 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dff12ec8-f20f-4b87-94af-d7c845d40b95', '雨晴至江渡', '雨晴至江渡', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["江雨初晴思遠步，日西獨向愚溪渡。","渡頭水落村逕成，撩亂浮槎在高樹。"]', '["江雨初晴思远步，日西独向愚溪渡。","渡头水落村逕成，撩亂浮槎在高樹。"]', '诗', 'shi', '', NULL, '雨晴至江渡 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f92134b-bca9-46eb-b2fe-87b30413041a', '江雪', '江雪', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["千山鳥飛絕，萬逕人蹤滅。","孤舟蓑笠翁，獨釣寒江雪。"]', '["千山鸟飞絕，万逕人蹤滅。","孤舟蓑笠翁，独釣寒江雪。"]', '诗', 'shi', '', NULL, '江雪 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa268e1e-5c77-4914-b549-609cf2c647f6', '冉溪', '冉溪', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["少時陳力希公侯，許國不復爲身謀。","風波一跌逝萬里，壯心瓦解空縲囚。","縲囚終老無餘事，願卜湘西冉溪地。","却學壽張樊敬侯，種漆南園待成器。"]', '["少时陳力希公侯，許国不复爲身謀。","风波一跌逝万里，壯心瓦解空縲囚。","縲囚終老無餘事，願卜湘西冉溪地。","却学壽張樊敬侯，種漆南园待成器。"]', '诗', 'shi', '', NULL, '冉溪 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10be461a-6b02-4e28-9c7a-28c27abb5838', '法華寺西亭夜飲', '法华寺西亭夜饮', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["[祇]樹夕陽亭，共傾三昧酒。","霧暗水連堦，月明花復牖。","莫厭尊前醉，相看未白首。"]', '["[祇]樹夕陽亭，共傾三昧酒。","霧暗水連堦，月明花复牖。","莫厭尊前醉，相看未白首。"]', '诗', 'shi', '', NULL, '法華寺西亭夜飲 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ccd8d2d-59c0-4dc8-a7c2-555fcbc7322e', '戲題石門長老東軒', '戲題石门长老东軒', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["石門長老身如夢，旃檀成林手所種。","坐來念念非昔人，萬徧蓮花爲誰用。","如今七十自忘機，貪愛都忘筋力微。","莫向東軒春埜望，花開日出雉皆飛。"]', '["石门长老身如梦，旃檀成林手所種。","坐来念念非昔人，万徧蓮花爲誰用。","如今七十自忘機，貪愛都忘筋力微。","莫向东軒春埜望，花开日出雉皆飞。"]', '诗', 'shi', '', NULL, '戲題石門長老東軒 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9eb3661-12d0-4bab-bbbd-443609889a30', '茅簷下始栽竹', '茅簷下始栽竹', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["瘴茅葺爲宇，溽暑常侵肌。","適有重膇疾，蒸鬱寧所宜。","東鄰幸導我，樹竹邀涼颸。","欣然愜吾志，荷鍤西巖垂。","楚壤多怪石，墾鑿力已疲。","江風忽云暮，輿曳還相追。","蕭瑟過極浦，旖旎附幽墀。","貞根期永固，貽爾寒泉滋。","夜牕遂不掩，羽扇寧復持。","清泠集濃露，枕簟淒已知。","網蟲依密葉，曉禽棲逈枝。","豈伊紛囂閒，重以心慮怡。","嘉爾亭亭質，自遠棄幽期。","不見野蔓草，蓊蔚有華姿。","諒無淩寒色，豈與青山辭。"]', '["瘴茅葺爲宇，溽暑常侵肌。","適有重膇疾，蒸鬱寧所宜。","东鄰幸導我，樹竹邀涼颸。","欣然愜吾志，荷鍤西巖垂。","楚壤多怪石，墾鑿力已疲。","江风忽云暮，輿曳還相追。","蕭瑟過極浦，旖旎附幽墀。","貞根期永固，貽爾寒泉滋。","夜牕遂不掩，羽扇寧复持。","清泠集濃露，枕簟淒已知。","網蟲依密葉，晓禽棲逈枝。","豈伊紛囂閒，重以心慮怡。","嘉爾亭亭質，自远棄幽期。","不见野蔓草，蓊蔚有华姿。","諒無淩寒色，豈與青山辞。"]', '诗', 'shi', '', NULL, '茅簷下始栽竹 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c7ef80d-0348-48c2-b3ad-43d4d8d164a8', '種仙靈毗', '種仙靈毗', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["窮陋闕自養，癘氣劇囂煩。","隆冬乏霜霰，日夕南風溫。","杖藜下庭際，曳踵不及門。","門有野田吏，慰我飄零魂。","及言有靈藥，近在湘西原。","服之不盈旬，蹩𨇨皆騰鶱。","笑忭前即吏，爲我擢其根。","蔚蔚遂充庭，英翹忽已繁。","晨起自採曝，杵臼通夜喧。","靈和理內藏，攻疾貴自源。","擁覆逃積霧，伸舒委餘暄。","奇功苟可徵，寧復資蘭蓀。","我聞畸人術，一氣中夜存。","能令深深息，呼吸還歸跟。","疎放固難效，且以藥餌論。","痿者不忘起，窮者寧復言。","神哉輔吾足，幸及兒女奔。"]', '["窮陋闕自養，癘氣劇囂煩。","隆冬乏霜霰，日夕南风溫。","杖藜下庭際，曳踵不及门。","门有野田吏，慰我飄零魂。","及言有靈藥，近在湘西原。","服之不盈旬，蹩𨇨皆腾鶱。","笑忭前即吏，爲我擢其根。","蔚蔚遂充庭，英翹忽已繁。","晨起自採曝，杵臼通夜喧。","靈和理內藏，攻疾貴自源。","擁覆逃積霧，伸舒委餘暄。","奇功苟可徵，寧复資蘭蓀。","我闻畸人術，一氣中夜存。","能令深深息，呼吸還归跟。","疎放固难效，且以藥餌論。","痿者不忘起，窮者寧复言。","神哉輔吾足，幸及兒女奔。"]', '诗', 'shi', '', NULL, '種仙靈毗 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe3c260c-affc-4234-87e6-2615321980a0', '種朮', '種朮', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["守閒事服餌，採朮東山阿。","東山幽且阻，疲苶煩經過。","戒徒斸靈根，封植閟天和。","違爾澗底石，徹我庭中莎。","土膏滋玄液，松露墜繁柯。","南東自成畝，繚繞紛相羅。","晨步佳色媚，夜眠幽氣多。","離憂苟可怡，孰能知其他。","爨竹茹芳葉，寧慮瘵與瘥。","留連樹蕙辭，婉娩採薇歌。","悟拙甘自足，激清媿同波。","單豹且理內，高門復如何。"]', '["守閒事服餌，採朮东山阿。","东山幽且阻，疲苶煩經過。","戒徒斸靈根，封植閟天和。","違爾澗底石，徹我庭中莎。","土膏滋玄液，松露墜繁柯。","南东自成畝，繚繞紛相羅。","晨步佳色媚，夜眠幽氣多。","離憂苟可怡，孰能知其他。","爨竹茹芳葉，寧慮瘵與瘥。","留連樹蕙辞，婉娩採薇歌。","悟拙甘自足，激清媿同波。","單豹且理內，高门复如何。"]', '诗', 'shi', '', NULL, '種朮 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('202641be-8d53-4de4-b477-fcbef11c89bf', '種白蘘荷', '種白蘘荷', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["血蟲化爲癘，夷俗多所神。","銜猜每腊毒，謀富不爲仁。","蔬果自遠至，盃酒盈肆陳。","言甘中必苦，何用知其真。","華潔事外飾，尤病中州人。","錢刀恐賈害，飢至益逡巡。","竄伏常戰慄，懷故逾悲辛。","庶氏有嘉草，攻禬事久泯。","炎帝垂靈編，言此殊足珍。","崎嶇乃有得，託以全余身。","紛敷碧樹陰，眄睞心所親。"]', '["血蟲化爲癘，夷俗多所神。","銜猜每腊毒，謀富不爲仁。","蔬果自远至，盃酒盈肆陳。","言甘中必苦，何用知其真。","华潔事外飾，尤病中州人。","錢刀恐賈害，飢至益逡巡。","竄伏常戰慄，懷故逾悲辛。","庶氏有嘉草，攻禬事久泯。","炎帝垂靈編，言此殊足珍。","崎嶇乃有得，託以全余身。","紛敷碧樹陰，眄睞心所親。"]', '诗', 'shi', '', NULL, '種白蘘荷 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cb983f0-34c5-40ff-89e0-dbdd4da26eb2', '新植海石榴', '新植海石榴', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["弱植不盈尺，遠意駐蓬瀛。","月寒空堦曙，幽夢綵雲生。","糞壤擢珠樹，莓苔插瓊英。","芳根閟顏色，徂歲爲誰榮。"]', '["弱植不盈尺，远意駐蓬瀛。","月寒空堦曙，幽梦綵云生。","糞壤擢珠樹，莓苔插瓊英。","芳根閟顏色，徂歲爲誰榮。"]', '诗', 'shi', '', NULL, '新植海石榴 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2b75195-273f-4dbf-af3d-7306de9d55d6', '戲題堦前芍藥', '戲題堦前芍藥', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["凡卉與時謝，妍華麗茲晨。","欹紅醉濃露，窈窕留餘春。","孤賞白日暮，暄風動搖頻。","夜牕藹芳氣，幽臥知相親。","願致溱洧贈，悠悠南國人。"]', '["凡卉與时謝，妍华丽茲晨。","欹紅醉濃露，窈窕留餘春。","孤賞白日暮，暄风动搖頻。","夜牕藹芳氣，幽臥知相親。","願致溱洧贈，悠悠南国人。"]', '诗', 'shi', '', NULL, '戲題堦前芍藥 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31aff727-0102-427a-a1e0-21966f5509ff', '始見白髪題所植海石榴', '始见白髪題所植海石榴', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["幾年封植愛芳叢，韶豔朱顏竟不同。","從此休論上春事，看成古木對衰翁。"]', '["幾年封植愛芳叢，韶豔朱顏竟不同。","從此休論上春事，看成古木对衰翁。"]', '诗', 'shi', '', NULL, '始見白髪題所植海石榴 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9138d2a-488e-4d70-8bb4-d0e3aac0d1fa', '植靈壽木', '植靈壽木', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["白華照寒水，怡我適野情。","前趨問長老，重復欣嘉名。","蹇連易衰朽，方剛謝經營。","敢期齒杖賜，聊且移孤莖。","叢萼中競秀，分房外舒英。","柔條乍反植，勁節常對生。","循翫足忘疲，稍覺步武輕。","安能事翦伐，持用資徒行。"]', '["白华照寒水，怡我適野情。","前趨问长老，重复欣嘉名。","蹇連易衰朽，方剛謝經營。","敢期齒杖賜，聊且移孤莖。","叢萼中競秀，分房外舒英。","柔條乍反植，勁節常对生。","循翫足忘疲，稍覺步武轻。","安能事翦伐，持用資徒行。"]', '诗', 'shi', '', NULL, '植靈壽木 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39115c15-994b-43ec-b1e5-388a495629f1', '自衡陽移桂十餘本植零陵所住精舍', '自衡陽移桂十餘本植零陵所住精舍', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["謫官去南裔，清湘繞靈岳。","晨登蒹葭岸，霜景霽紛濁。","離披得幽桂，芳本欣盈握。","火耕困煙燼，薪採久摧剝。","道旁且不願，岑嶺況悠邈。","傾筐壅故壤，棲息期鸞鷟。","路遠清涼宮，一雨悟無學。","南人始珍重，微我誰先覺。","芳意不可傳，丹心徒自渥。"]', '["謫官去南裔，清湘繞靈岳。","晨登蒹葭岸，霜景霽紛濁。","離披得幽桂，芳本欣盈握。","火耕困煙燼，薪採久摧剝。","道旁且不願，岑嶺況悠邈。","傾筐壅故壤，棲息期鸾鷟。","路远清涼宮，一雨悟無学。","南人始珍重，微我誰先覺。","芳意不可傳，丹心徒自渥。"]', '诗', 'shi', '', NULL, '自衡陽移桂十餘本植零陵所住精舍 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12c990df-c417-480a-aa17-39836764b4ef', '湘岸移木芙蓉植龍興精舍', '湘岸移木芙蓉植龙兴精舍', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["有美不自蔽，安能守孤根。","盈盈湘西岸，秋至風露繁。","麗影別寒水，穠芳委前軒。","芰荷諒難雜，反此生高原。"]', '["有美不自蔽，安能守孤根。","盈盈湘西岸，秋至风露繁。","丽影別寒水，穠芳委前軒。","芰荷諒难杂，反此生高原。"]', '诗', 'shi', '', NULL, '湘岸移木芙蓉植龍興精舍 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68ae20e0-130a-43ef-b672-8ce0d95abb8b', '早梅', '早梅', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["早梅發高樹，逈映楚天碧。","朔吹飄夜香，繁霜滋曉白。","欲爲萬里贈，杳杳山水隔。","寒英坐銷落，何用慰遠客。"]', '["早梅發高樹，逈映楚天碧。","朔吹飄夜香，繁霜滋晓白。","欲爲万里贈，杳杳山水隔。","寒英坐銷落，何用慰远客。"]', '诗', 'shi', '', NULL, '早梅 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c3dbac0-97ae-499a-9161-50f86235aa6c', '南中榮橘柚', '南中榮橘柚', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["橘柚懷貞質，受命此炎方。","密林耀朱綠，晚歲有餘芳。","殊風限清漢，飛雪滯故鄉。","攀條何所歎，北望熊與湘。"]', '["橘柚懷貞質，受命此炎方。","密林耀朱綠，晚歲有餘芳。","殊风限清漢，飞雪滯故乡。","攀條何所歎，北望熊與湘。"]', '诗', 'shi', '', NULL, '南中榮橘柚 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cddea3a9-a11d-4fdb-8faf-e4d2bbeb68f8', '紅蕉', '紅蕉', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["晚英值窮節，綠潤含朱光。","以茲正陽色，窈窕凌清霜。","遠物世所重，旅人心獨傷。","回暉眺林際，摵摵無遺芳。"]', '["晚英值窮節，綠潤含朱光。","以茲正陽色，窈窕凌清霜。","远物世所重，旅人心独傷。","回暉眺林際，摵摵無遺芳。"]', '诗', 'shi', '', NULL, '紅蕉 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45949e82-08fb-4b8e-94b1-9c2e0f5e541e', '巽公院五詠 淨土堂', '巽公院五詠 淨土堂', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["結習自無始，淪溺窮苦源。","流形及茲世，始悟三空門。","華堂開淨域，圖像煥且繁。","清冷焚衆香，微妙歌法言。","稽首媿導師，超遙謝塵昏。"]', '["結習自無始，淪溺窮苦源。","流形及茲世，始悟三空门。","华堂开淨域，圖像煥且繁。","清冷焚衆香，微妙歌法言。","稽首媿導師，超遙謝塵昏。"]', '诗', 'shi', '', NULL, '巽公院五詠 淨土堂 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9ad6fd9-f748-4df2-a5e7-3a188cf5198b', '巽公院五詠 曲講堂', '巽公院五詠 曲講堂', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["寂滅本非斷，文字安可離。","曲堂何爲設，高士方在斯。","聖默寄言宣，分別乃無知。","趣中即空假，名相與誰期。","願言絕聞得，忘意聊思惟。"]', '["寂滅本非斷，文字安可離。","曲堂何爲設，高士方在斯。","聖默寄言宣，分別乃無知。","趣中即空假，名相與誰期。","願言絕闻得，忘意聊思惟。"]', '诗', 'shi', '', NULL, '巽公院五詠 曲講堂 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d057127-c006-4a03-932b-1b0f3839e9d7', '巽公院五詠 禪堂', '巽公院五詠 禪堂', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["發地結菁茅，團團抱虛白。","山花落幽戶，中有忘機客。","涉有本非取，照空不待析。","萬籟俱緣生，窅然喧中寂。","心境本洞如，鳥飛無遺跡。"]', '["發地結菁茅，團團抱虛白。","山花落幽戶，中有忘機客。","涉有本非取，照空不待析。","万籟俱緣生，窅然喧中寂。","心境本洞如，鸟飞無遺跡。"]', '诗', 'shi', '', NULL, '巽公院五詠 禪堂 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('599ff2eb-7a17-414b-bae8-6b537724eec2', '巽公院五詠 芙蓉亭', '巽公院五詠 芙蓉亭', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["新亭俯朱檻，嘉木開芙蓉。","清香晨風遠，溽彩寒露濃。","瀟灑出人世，低昂多異容。","嘗聞色空喻，造物誰爲工。","留連秋月晏，迢遞來山鐘。"]', '["新亭俯朱檻，嘉木开芙蓉。","清香晨风远，溽彩寒露濃。","瀟灑出人世，低昂多異容。","嘗闻色空喻，造物誰爲工。","留連秋月晏，迢遞来山鐘。"]', '诗', 'shi', '', NULL, '巽公院五詠 芙蓉亭 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e26e57f-c6df-4f7a-81d3-538b04cc4dac', '巽公院五詠 苦竹橋', '巽公院五詠 苦竹橋', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["危橋屬幽徑，繚繞穿疎林。","迸籜分苦節，輕筠抱虛心。","俯瞰涓涓流，仰聆蕭蕭吟。","差池下煙日，嘲异常鳴山禽。","諒無要津用，棲息有餘陰。"]', '["危橋屬幽徑，繚繞穿疎林。","迸籜分苦節，轻筠抱虛心。","俯瞰涓涓流，仰聆蕭蕭吟。","差池下煙日，嘲异常鳴山禽。","諒無要津用，棲息有餘陰。"]', '诗', 'shi', '', NULL, '巽公院五詠 苦竹橋 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ecbed64-2409-4f6d-ade3-ccfec85ff92c', '梅雨', '梅雨', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["梅實迎時雨，蒼茫值晚春。","愁深楚猿夜，夢斷越雞晨。","海霧連南極，江雲暗北津。","素衣今盡化，非爲帝京塵。"]', '["梅實迎时雨，蒼茫值晚春。","愁深楚猿夜，梦斷越雞晨。","海霧連南極，江云暗北津。","素衣今尽化，非爲帝京塵。"]', '诗', 'shi', '', NULL, '梅雨 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1534d3f-c9c2-4eb1-872a-1bb24ea99cb7', '零陵早春', '零陵早春', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["問春從此去，幾日到秦原。","憑寄還鄉夢，殷勤入故園。"]', '["问春從此去，幾日到秦原。","憑寄還乡梦，殷勤入故园。"]', '诗', 'shi', '', NULL, '零陵早春 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28d14ca6-9080-4341-9945-1a6a8ff01622', '田家三首 一', '田家三首 一', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["蓐食徇所務，驅牛向東阡。","雞鳴村巷白，夜色歸暮田。","札札耒耜聲，飛飛來烏鳶。","竭茲筋力事，持用窮歲年。","盡輸助徭役，聊就空自眠。","子孫日已長，世世還復然。"]', '["蓐食徇所務，驱牛向东阡。","雞鳴村巷白，夜色归暮田。","札札耒耜声，飞飞来烏鳶。","竭茲筋力事，持用窮歲年。","尽輸助徭役，聊就空自眠。","子孫日已长，世世還复然。"]', '诗', 'shi', '', NULL, '田家三首 一 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19eddc03-4ac4-4c71-b850-2d2ff638428e', '田家三首 二', '田家三首 二', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["籬落隔煙火，農談四鄰夕。","庭際秋蟲鳴，疎麻方寂歷。","蠶絲盡輸稅，機杼空倚壁。","里胥夜經過，雞黍事筵席。","各言官長峻，文字多督責。","東鄉後租期，車轂陷泥澤。","公門少推恕，鞭朴恣狼籍。","努力慎經營，肌膚真可惜。","迎新在此歲，唯恐踵前跡。"]', '["籬落隔煙火，農談四鄰夕。","庭際秋蟲鳴，疎麻方寂歷。","蠶絲尽輸稅，機杼空倚壁。","里胥夜經過，雞黍事筵席。","各言官长峻，文字多督責。","东乡後租期，车轂陷泥澤。","公门少推恕，鞭朴恣狼籍。","努力慎經營，肌膚真可惜。","迎新在此歲，唯恐踵前跡。"]', '诗', 'shi', '', NULL, '田家三首 二 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97465f06-fe21-4b2c-901d-9483805fa85b', '田家三首 三', '田家三首 三', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["古道饒蒺藜，縈迴古城曲。","蓼花被堤岸，陂水寒更綠。","是時收穫竟，落日多樵牧。","風高榆柳疎，霜重棃棗熟。","行人迷去住，野鳥競棲宿。","田翁笑相念，昏黑慎原陸。","今年幸少豐，無厭饘與粥。"]', '["古道饒蒺藜，縈迴古城曲。","蓼花被堤岸，陂水寒更綠。","是时收穫竟，落日多樵牧。","风高榆柳疎，霜重棃棗熟。","行人迷去住，野鸟競棲宿。","田翁笑相念，昏黑慎原陸。","今年幸少豐，無厭饘與粥。"]', '诗', 'shi', '', NULL, '田家三首 三 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31ac5443-ea10-4e3f-8762-d65aec27490b', '行路難三首 一', '行路难三首 一', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["君不見夸父逐日窺虞淵，跳踉北海超崑崙。","披霄決漢出沆漭，瞥裂左右遺星辰。","須臾力盡道渴死，狐鼠蜂蟻爭噬吞。","北方竫人長九寸，開口抵掌更笑喧。","啾啾飲食滴與粒，生死亦足終天年。","睢盱大志小成遂，坐使兒女相悲憐。"]', '["君不见夸父逐日窺虞淵，跳踉北海超崑崙。","披霄決漢出沆漭，瞥裂左右遺星辰。","須臾力尽道渴死，狐鼠蜂蟻爭噬吞。","北方竫人长九寸，开口抵掌更笑喧。","啾啾饮食滴與粒，生死亦足終天年。","睢盱大志小成遂，坐使兒女相悲怜。"]', '诗', 'shi', '', NULL, '行路難三首 一 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f017dd9b-1d9c-465f-a7da-7e6b1ad28aa7', '行路難三首 二', '行路难三首 二', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["虞衡斤斧羅千山，工命采斫杙與椽。","深林土剪十取一，百牛連鞅摧雙轅。","萬圍千尋妨道路，東西蹶倒山火焚。","遺餘毫末不見保，躪躒磵壑何當存。","羣材未成質已夭，突兀哮豁空巖巒。","柏梁天災武庫火，匠石狼顧相愁冤。","君不見南山棟梁益稀少，愛材養育誰復論。"]', '["虞衡斤斧羅千山，工命采斫杙與椽。","深林土剪十取一，百牛連鞅摧雙轅。","万圍千尋妨道路，东西蹶倒山火焚。","遺餘毫末不见保，躪躒磵壑何當存。","羣材未成質已夭，突兀哮豁空巖巒。","柏梁天災武庫火，匠石狼顧相愁冤。","君不见南山棟梁益稀少，愛材養育誰复論。"]', '诗', 'shi', '', NULL, '行路難三首 二 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('918ea01d-553d-44cb-ad8d-b508452b8ab6', '行路難三首 三', '行路难三首 三', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["飛雪斷道冰成梁，侯家熾炭雕玉房。","蟠龍吐耀虎喙張，熊蹲豹躑爭低昂。","攢巒叢㟧射朱光，丹霞翠霧飄奇香。","美人四向迴明璫，雪山冰谷晞太陽。","星躔奔走不得止，奄忽雙燕棲虹梁。","風臺露榭生光飾，死灰棄置參與商。","盛時一去貴反賤，桃笙葵扇安可當。"]', '["飞雪斷道冰成梁，侯家熾炭雕玉房。","蟠龙吐耀虎喙張，熊蹲豹躑爭低昂。","攢巒叢㟧射朱光，丹霞翠霧飄奇香。","美人四向迴明璫，雪山冰谷晞太陽。","星躔奔走不得止，奄忽雙燕棲虹梁。","风台露榭生光飾，死灰棄置參與商。","盛时一去貴反賤，桃笙葵扇安可當。"]', '诗', 'shi', '', NULL, '行路難三首 三 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1682a191-1a61-4cb4-b5a7-ac1aea1d71c7', '聞籍田有感', '闻籍田有感', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["天田不日降皇輿，留滯長沙歲又除。","宣室無由問釐事，周南何處託成書。"]', '["天田不日降皇輿，留滯长沙歲又除。","宣室無由问釐事，周南何处託成书。"]', '诗', 'shi', '', NULL, '聞籍田有感 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0453ea5-ee4e-46ad-85c2-36d2d5a301c1', '跂烏詞', '跂烏词', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["城上日出羣烏飛，鵶鵶爭赴朝陽枝。","刷毛伸翼和且樂，爾獨落魄今何爲。","無乃慕高近白日，三足妬爾令爾疾。","無乃飢啼走道旁，貪鮮攫肉人所傷。","翹肖獨足下叢薄，口銜低枝始能躍。","還顧泥涂備螻蟻，仰看棟梁防燕雀。","左右六翮利如刀，踊身失勢不得高。","支離無趾猶自免，努力低飛逃後患。"]', '["城上日出羣烏飞，鵶鵶爭赴朝陽枝。","刷毛伸翼和且乐，爾独落魄今何爲。","無乃慕高近白日，三足妬爾令爾疾。","無乃飢啼走道旁，貪鲜攫肉人所傷。","翹肖独足下叢薄，口銜低枝始能躍。","還顧泥涂備螻蟻，仰看棟梁防燕雀。","左右六翮利如刀，踊身失勢不得高。","支離無趾猶自免，努力低飞逃後患。"]', '诗', 'shi', '', NULL, '跂烏詞 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c3dc50a-50fb-4b40-8e05-9bbee262aeb1', '籠鷹詞', '籠鷹词', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["淒風淅瀝飛嚴霜，蒼鷹上擊翻曙光。","雲披霧裂虹蜺斷，霹靂掣電捎平岡。","砉然勁翮翦荆棘，下攫狐兔騰蒼茫。","爪毛吻血百鳥逝，獨立四顧時激昂。","炎風溽暑忽然至，羽翼脫落自摧藏。","草中狸鼠足爲患，一夕十顧驚且傷。","但願清商復爲假，拔去萬累雲間翔。"]', '["淒风淅瀝飞嚴霜，蒼鷹上擊翻曙光。","云披霧裂虹蜺斷，霹靂掣電捎平岡。","砉然勁翮翦荆棘，下攫狐兔腾蒼茫。","爪毛吻血百鸟逝，独立四顧时激昂。","炎风溽暑忽然至，羽翼脫落自摧藏。","草中狸鼠足爲患，一夕十顧驚且傷。","但願清商复爲假，拔去万累云间翔。"]', '诗', 'shi', '', NULL, '籠鷹詞 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f873e56a-180a-4ee6-ab81-a78c6dd98021', '放鷓鴣詞', '放鷓鴣词', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["楚越有鳥甘且腴，嘲嘲自名爲鷓鴣。","徇媒得食不復慮，機械潛發罹罝罦。","羽毛摧折觸籠籞，煙火煽赫驚庖廚。","鼎前芍藥調五味，膳夫攘腕左右視。","齊王不忍觳觫牛，簡子亦放邯鄲鳩。","二子得意猶念此，況我萬里爲孤囚。","破籠展翅當遠去，同類相呼莫相顧。"]', '["楚越有鸟甘且腴，嘲嘲自名爲鷓鴣。","徇媒得食不复慮，機械潛發罹罝罦。","羽毛摧折觸籠籞，煙火煽赫驚庖廚。","鼎前芍藥調五味，膳夫攘腕左右視。","齊王不忍觳觫牛，簡子亦放邯鄲鳩。","二子得意猶念此，況我万里爲孤囚。","破籠展翅當远去，同類相呼莫相顧。"]', '诗', 'shi', '', NULL, '放鷓鴣詞 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34730a4b-0b2f-489b-b33e-129117aa2622', '龜背戲', '龟背戲', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["長安新技出宮掖，喧喧初徧王侯宅。","玉盤滴瀝黃金錢，皎如文龜麗秋天。","八方定位開神卦，六甲離離齊上下。","投變轉動玄機卑，星流霞破相參差。","四分五裂勢未已，出無入有誰能知。","乍驚散漫無處所，須臾羅列已如故。","徒言萬事有盈虛，終朝一擲知勝負。","脩門象棋不復貴，魏宮妝奩世所棄。","豈如瑞質耀奇文，願持千歲壽吾君。","廟堂巾笥非余慕，錢刀兒女徒紛紛。"]', '["长安新技出宮掖，喧喧初徧王侯宅。","玉盤滴瀝黄金錢，皎如文龟丽秋天。","八方定位开神卦，六甲離離齊上下。","投变轉动玄機卑，星流霞破相參差。","四分五裂勢未已，出無入有誰能知。","乍驚散漫無处所，須臾羅列已如故。","徒言万事有盈虛，終朝一擲知勝負。","脩门象棋不复貴，魏宮妝奩世所棄。","豈如瑞質耀奇文，願持千歲壽吾君。","廟堂巾笥非余慕，錢刀兒女徒紛紛。"]', '诗', 'shi', '', NULL, '龜背戲 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('617121d0-e2bb-4f15-8062-2cf925e33f57', '聞黃鸝', '闻黄鸝', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["倦聞子規嘲暮聲，不意忽有黃鸝鳴。","一聲夢斷楚江曲，滿眼故園春意生。","目極千里無山河，麥芒際天搖清波。","王畿優本少賦役，務閑酒熟饒經過。","此時晴煙最深處，舍南巷北遙相語。","翻日迥度昆明飛，凌風邪看細柳翥。","我今誤落千萬山，身同傖人不思還。","鄉禽何事亦來此，令我生心憶桑梓。","閉聲迴翅歸務速，西林紫椹行當熟。"]', '["倦闻子規嘲暮声，不意忽有黄鸝鳴。","一声梦斷楚江曲，满眼故园春意生。","目極千里無山河，麦芒際天搖清波。","王畿優本少賦役，務闲酒熟饒經過。","此时晴煙最深处，舍南巷北遙相語。","翻日迥度昆明飞，凌风邪看細柳翥。","我今誤落千万山，身同傖人不思還。","乡禽何事亦来此，令我生心憶桑梓。","閉声迴翅归務速，西林紫椹行當熟。"]', '诗', 'shi', '', NULL, '聞黃鸝 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26e0cd7b-3bd0-4c1f-a7b4-105bb299106a', '渾鴻臚宅聞歌效白紵', '渾鴻臚宅闻歌效白紵', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["翠帷雙卷出傾城，龍劒破匣霜月明。","朱脣掩仰悄無聲，金簧玉磬宮中生。","下沈秋火激太清，天高地逈凝日晶，羽觴蕩漾何事傾。"]', '["翠帷雙卷出傾城，龙劒破匣霜月明。","朱脣掩仰悄無声，金簧玉磬宮中生。","下沈秋火激太清，天高地逈凝日晶，羽觴蕩漾何事傾。"]', '诗', 'shi', '', NULL, '渾鴻臚宅聞歌效白紵 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee01573c-048a-4c12-9edd-d9525c9252f2', '楊白花', '楊白花', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["楊白花，風吹渡江水。","坐令宮樹無顏色，搖蕩春光千萬里。","茫茫曉日下長秋，哀歌未斷城鴉起。"]', '["楊白花，风吹渡江水。","坐令宮樹無顏色，搖蕩春光千万里。","茫茫晓日下长秋，哀歌未斷城鴉起。"]', '诗', 'shi', '', NULL, '楊白花 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51b1aeeb-9a66-412d-b15c-4afaa6c6b1d7', '漁翁', '漁翁', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["漁翁夜傍西巖宿，曉汲清湘燃楚竹。","煙銷日出不見人，[欸]乃一聲山水綠。","迴看天際下中流，巖上無心雲相逐。"]', '["漁翁夜傍西巖宿，晓汲清湘燃楚竹。","煙銷日出不见人，[欸]乃一声山水綠。","迴看天際下中流，巖上無心云相逐。"]', '诗', 'shi', '', NULL, '漁翁 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a356172a-b00b-48ca-ae06-2e6fa81d9817', '飲酒', '饮酒', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["今夕少愉樂，起坐開清尊。","舉觴酹先酒，爲我驅憂煩。","須臾心自殊，頓覺天地暄。","連山變幽晦，綠水函晏溫。","藹藹南郭門，樹木一何繁。","清陰可自庇，竟夕聞佳言。","盡醉無復辭，偃臥有芳蓀。","彼哉晉楚富，此道未必存。"]', '["今夕少愉乐，起坐开清尊。","舉觴酹先酒，爲我驱憂煩。","須臾心自殊，頓覺天地暄。","連山变幽晦，綠水函晏溫。","藹藹南郭门，樹木一何繁。","清陰可自庇，竟夕闻佳言。","尽醉無复辞，偃臥有芳蓀。","彼哉晉楚富，此道未必存。"]', '诗', 'shi', '', NULL, '飲酒 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51c99f73-8a33-4c3b-b8b3-9e625e71805f', '讀書', '读书', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["幽沈謝世事，俛默窺唐虞。","上下觀古今，起伏千萬途。","遇欣或自笑，感戚亦以吁。","縹帙各舒散，前後互相逾。","瘴痾擾靈府，日與往昔殊。","臨文乍了了，徹卷兀若無。","竟夕誰與言，但與竹素俱。","倦極便倒臥，熟寐乃一蘇。","欠伸展肢體，吟詠心自愉。","得意適其適，非願爲世儒。","道盡即閉口，蕭散捐囚拘。","巧者爲我拙，智者爲我愚。","書史足自悅，安用勤與劬。","貴爾六尺軀，勿爲名所驅。"]', '["幽沈謝世事，俛默窺唐虞。","上下观古今，起伏千万途。","遇欣或自笑，感戚亦以吁。","縹帙各舒散，前後互相逾。","瘴痾擾靈府，日與往昔殊。","臨文乍了了，徹卷兀若無。","竟夕誰與言，但與竹素俱。","倦極便倒臥，熟寐乃一蘇。","欠伸展肢體，吟詠心自愉。","得意適其適，非願爲世儒。","道尽即閉口，蕭散捐囚拘。","巧者爲我拙，智者爲我愚。","书史足自悅，安用勤與劬。","貴爾六尺軀，勿爲名所驱。"]', '诗', 'shi', '', NULL, '讀書 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('276645b8-28df-46f9-9235-aea982772911', '感遇二首 一', '感遇二首 一', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["西陸動涼氣，驚烏號北林。","棲息豈殊性，集枯安可任。","鴻鵠去不返，勾吳阻且深。","徒嗟日沈湎，丸鼓騖奇音。","東海久搖蕩，南風已駸駸。","坐使青天暮，小星愁太陰。","衆情嗜姦利，居貨捐千金。","危根一以振，齊斧來相尋。","攬衣中夜起，感物涕盈襟。","微霜衆所踐，誰念歲寒心。"]', '["西陸动涼氣，驚烏號北林。","棲息豈殊性，集枯安可任。","鴻鵠去不返，勾吳阻且深。","徒嗟日沈湎，丸鼓騖奇音。","东海久搖蕩，南风已駸駸。","坐使青天暮，小星愁太陰。","衆情嗜姦利，居貨捐千金。","危根一以振，齊斧来相尋。","攬衣中夜起，感物涕盈襟。","微霜衆所踐，誰念歲寒心。"]', '诗', 'shi', '', NULL, '感遇二首 一 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b0f160b-13ae-4b9d-a7f2-0edce38709a5', '感遇二首 二', '感遇二首 二', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["旭日照寒野，鸒斯起蒿萊。","啁啾有餘樂，飛舞西陵隈。","迴風旦夕至，零葉委陳荄。","所棲不足恃，鷹隼縱橫來。"]', '["旭日照寒野，鸒斯起蒿萊。","啁啾有餘乐，飞舞西陵隈。","迴风旦夕至，零葉委陳荄。","所棲不足恃，鷹隼縱橫来。"]', '诗', 'shi', '', NULL, '感遇二首 二 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83df3e51-a4a9-4fb7-a0fc-3478ff49f9cf', '詠史', '詠史', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["燕有黃金臺，遠致望諸君。","嗛嗛事強怨，三歲有奇勳。","悠哉辟疆理，東海漫浮雲。","寧知世情異，嘉穀坐熇焚。","致令委金石，誰願蠢蠕羣。","風波歘潛構，遺恨意紛紜。","豈不善圖後，交私非所聞。","爲忠不顧內，晏子亦垂文。"]', '["燕有黄金台，远致望諸君。","嗛嗛事強怨，三歲有奇勳。","悠哉辟疆理，东海漫浮云。","寧知世情異，嘉穀坐熇焚。","致令委金石，誰願蠢蠕羣。","风波歘潛構，遺恨意紛紜。","豈不善圖後，交私非所闻。","爲忠不顧內，晏子亦垂文。"]', '诗', 'shi', '', NULL, '詠史 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bad2d2b-66f0-498a-849b-902355e11bf3', '詠三良', '詠三良', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["束帶值明后，顧盼流輝光。","一心在陳力，鼎列夸四方。","款款效忠信，恩義皎如霜。","生時亮同體，死沒寧分張。","壯軀閉幽隧，猛志填黃腸。","殉死禮所非，況乃用其良。","霸基弊不振，晉楚更張皇。","疾病命固亂，魏氏言有章。","從邪陷厥父，吾欲討彼狂。"]', '["束带值明后，顧盼流輝光。","一心在陳力，鼎列夸四方。","款款效忠信，恩義皎如霜。","生时亮同體，死沒寧分張。","壯軀閉幽隧，猛志填黄腸。","殉死禮所非，況乃用其良。","霸基弊不振，晉楚更張皇。","疾病命固亂，魏氏言有章。","從邪陷厥父，吾欲討彼狂。"]', '诗', 'shi', '', NULL, '詠三良 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b67a24e-33da-4a40-941a-e7a42931b390', '詠荆軻', '詠荆軻', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["燕秦不兩立，太子已爲虞。","千金奉短計，匕首荆卿趨。","窮年徇所欲，兵勢且見屠。","微言激幽憤，怒目辭燕都。","朔風動易水，揮爵前長驅。","函首致宿怨，獻田開版圖。","炯然耀電光，掌握罔正夫。","造端何其銳，臨事竟趑趄。","長虹吐白日，倉卒反受誅。","按劒赫憑怒，風雷助號呼。","慈父斷子首，狂走無容軀。","夷城芟七族，臺觀皆焚汙。","始期憂患弭，卒動災禍樞。","秦皇本詐力，事與桓公殊。","奈何效曹子，實謂勇且愚。","世傳故多謬，太史徵無且。"]', '["燕秦不兩立，太子已爲虞。","千金奉短計，匕首荆卿趨。","窮年徇所欲，兵勢且见屠。","微言激幽憤，怒目辞燕都。","朔风动易水，揮爵前长驱。","函首致宿怨，獻田开版圖。","炯然耀電光，掌握罔正夫。","造端何其銳，臨事竟趑趄。","长虹吐白日，倉卒反受誅。","按劒赫憑怒，风雷助號呼。","慈父斷子首，狂走無容軀。","夷城芟七族，台观皆焚汙。","始期憂患弭，卒动災禍樞。","秦皇本詐力，事與桓公殊。","奈何效曹子，實謂勇且愚。","世傳故多謬，太史徵無且。"]', '诗', 'shi', '', NULL, '詠荆軻 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1369c08e-0001-4134-897d-678dbdb42f69', '掩役夫張進骸', '掩役夫張進骸', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["生死悠悠爾，一氣聚散之。","偶來紛喜怒，奄忽已復辭。","爲役孰賤辱，爲貴非神奇。","一朝纊息定，枯巧無妍媸。","生平勤皂櫪，剉秣不告疲。","既死給槥櫝，葬之東山基。","奈何值崩湍，蕩析臨路垂。","髐然暴百骸，散亂不復支。","從者幸告余，睠之涓然悲。","猫虎獲迎祭，犬馬有蓋帷。","佇立唁爾魂，豈復識此爲。","畚鍤載埋瘞，溝瀆護其危。","我心得所安，不謂爾有知。","掩骼著春令，茲焉適其時。","及物非吾事，聊且顧爾私。"]', '["生死悠悠爾，一氣聚散之。","偶来紛喜怒，奄忽已复辞。","爲役孰賤辱，爲貴非神奇。","一朝纊息定，枯巧無妍媸。","生平勤皂櫪，剉秣不告疲。","既死給槥櫝，葬之东山基。","奈何值崩湍，蕩析臨路垂。","髐然暴百骸，散亂不复支。","從者幸告余，睠之涓然悲。","猫虎獲迎祭，犬马有蓋帷。","佇立唁爾魂，豈复識此爲。","畚鍤載埋瘞，溝瀆護其危。","我心得所安，不謂爾有知。","掩骼著春令，茲焉適其时。","及物非吾事，聊且顧爾私。"]', '诗', 'shi', '', NULL, '掩役夫張進骸 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2237377e-d00e-4e7a-9ce4-1ea09940c89c', '省試觀慶雲圖詩', '省試观慶云圖诗', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["設色既成象，卿雲示國都。","九天開秘祉，百辟贊嘉謨。","抱日依龍衮，非煙近御爐。","高標連汗漫，逈望接虛無。","裂素榮光發，舒華瑞色敷。","恒將配堯德，垂慶代河圖。"]', '["設色既成象，卿云示国都。","九天开秘祉，百辟贊嘉謨。","抱日依龙衮，非煙近御爐。","高標連汗漫，逈望接虛無。","裂素榮光發，舒华瑞色敷。","恒將配堯德，垂慶代河圖。"]', '诗', 'shi', '', NULL, '省試觀慶雲圖詩 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb1a266b-a490-4cef-8446-5837e25a5c7f', '春懷故園', '春懷故园', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["九扈鳴已晚，楚鄉農事春。","悠悠故池水，空待灌園人。"]', '["九扈鳴已晚，楚乡農事春。","悠悠故池水，空待灌园人。"]', '诗', 'shi', '', NULL, '春懷故園 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bf0a2a0-b7dc-4c56-8396-dcf54882cb22', '團扇詩', '團扇诗', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["團扇復團扇，奉君清暑殿。","秋風入庭樹，從此不相見。","上有乘鸞女，蒼蒼蟲網遍。","明年入懷袖，別是機中練。"]', '["團扇复團扇，奉君清暑殿。","秋风入庭樹，從此不相见。","上有乘鸾女，蒼蒼蟲網遍。","明年入懷袖，別是機中練。"]', '诗', 'shi', '', NULL, '團扇詩 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c126cc6-4904-4d77-a178-e58b68cc45a5', '宜城歌', '宜城歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["野水繞空城，行塵起孤驛。","荒臺側生樹，石碣陽鐫額。","靡靡度行人，溫風吹宿麥。"]', '["野水繞空城，行塵起孤驛。","荒台側生樹，石碣陽鐫額。","靡靡度行人，溫风吹宿麦。"]', '诗', 'shi', '', NULL, '宜城歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adba6369-f910-4b4d-9e1b-c4a4e174e9b7', '順陽歌', '順陽歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["朝辭官軍驛，前望順陽路。","野水齧荒墳，秋蟲鏤宮樹。","曾聞天寶末，胡馬西南騖。","城守魯將軍，拔城從此去。"]', '["朝辞官軍驛，前望順陽路。","野水齧荒墳，秋蟲鏤宮樹。","曾闻天寶末，胡马西南騖。","城守魯將軍，拔城從此去。"]', '诗', 'shi', '', NULL, '順陽歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81738668-4372-4467-bea2-f9474e6616fb', '莫猺歌', '莫猺歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["莫猺自生長，名字無符籍。","市易雜鮫人，婚姻通木客。","星居占泉眼，火種開山脊。","夜渡千仞谿，含沙不能射。"]', '["莫猺自生长，名字無符籍。","市易杂鮫人，婚姻通木客。","星居占泉眼，火種开山脊。","夜渡千仞谿，含沙不能射。"]', '诗', 'shi', '', NULL, '莫猺歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a862348-178c-4de0-856d-38dd13eadb51', '度桂嶺歌', '度桂嶺歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["桂陽嶺，下下復高高。","人稀鳥獸駭，地遠草木豪。","寄言千金子，知余歌者勞。"]', '["桂陽嶺，下下复高高。","人稀鸟獸駭，地远草木豪。","寄言千金子，知余歌者勞。"]', '诗', 'shi', '', NULL, '度桂嶺歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc861eb1-384f-4048-8904-b3bbd290a37e', '插田歌', '插田歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["岡頭花草齊，燕子東西飛。","田塍望如線，白水光參差。","農婦白紵裙，農父綠蓑衣。","齊唱郢中歌，嚶儜如竹枝。","但聞怨響音，不辨俚語詞。","時時一大笑，此必相嘲嗤。","水平苗漠漠，煙火生墟落。","黃犬往復還，赤雞鳴且啄。","路旁誰家郎，烏帽衫袖長。","自言上計吏，年幼離帝鄉。","田夫語計吏，君家儂定諳。","一來長安道，眼大不相參。","計吏笑致辭，長安真大處。","省門高軻峨，儂入無度數。","昨來補衛士，唯用筒竹布。","君看二三年，我作官人去。"]', '["岡头花草齊，燕子东西飞。","田塍望如線，白水光參差。","農婦白紵裙，農父綠蓑衣。","齊唱郢中歌，嚶儜如竹枝。","但闻怨响音，不辨俚語词。","时时一大笑，此必相嘲嗤。","水平苗漠漠，煙火生墟落。","黄犬往复還，赤雞鳴且啄。","路旁誰家郎，烏帽衫袖长。","自言上計吏，年幼離帝乡。","田夫語計吏，君家儂定諳。","一来长安道，眼大不相參。","計吏笑致辞，长安真大处。","省门高軻峨，儂入無度數。","昨来補衛士，唯用筒竹布。","君看二三年，我作官人去。"]', '诗', 'shi', '', NULL, '插田歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('867efd8c-98d1-45c8-99bf-8635532444c0', '葡萄歌', '葡萄歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["野田生葡萄，纏繞一枝高。","移來碧墀下，張王日日高。","分岐浩繁縟，脩蔓蟠詰曲。","揚翹向庭柯，意思如有屬。","爲之立長檠，布濩當軒綠。","米液溉其根，理疎看滲漉。","繁葩組綬結，懸實珠璣蹙。","馬乳帶輕霜，龍鱗曜初旭。","有客汾陰至，臨堂瞪雙目。","自言我晉人，種此如種玉。","釀之成美酒，令人飲不足。","爲君持一斗，往取涼州牧。"]', '["野田生葡萄，纏繞一枝高。","移来碧墀下，張王日日高。","分岐浩繁縟，脩蔓蟠詰曲。","揚翹向庭柯，意思如有屬。","爲之立长檠，布濩當軒綠。","米液溉其根，理疎看滲漉。","繁葩組綬結，懸實珠璣蹙。","马乳带轻霜，龙鱗曜初旭。","有客汾陰至，臨堂瞪雙目。","自言我晉人，種此如種玉。","釀之成美酒，令人饮不足。","爲君持一斗，往取涼州牧。"]', '诗', 'shi', '', NULL, '葡萄歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbffe2fa-ff43-4c02-aa8d-fb8208ba0967', '蠻子歌', '蠻子歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["蠻語鉤輈音，蠻衣斑斕布。","熏狸掘沙鼠，時節祠盤瓠。","忽逢乘馬客，恍若驚麏顧。","腰斧上高山，意行無舊路。"]', '["蠻語鉤輈音，蠻衣斑斕布。","熏狸掘沙鼠，时節祠盤瓠。","忽逢乘马客，恍若驚麏顧。","腰斧上高山，意行無旧路。"]', '诗', 'shi', '', NULL, '蠻子歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cb22c8a-88d6-44c1-8f31-3e2de9127945', '馬嵬行', '马嵬行', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["綠野扶風道，黃塵馬嵬驛。","路邊楊貴人，墳高三四尺。","乃問里中兒，皆言幸蜀時。","軍家誅戚族，天子捨妖姬。","羣吏伏門屏，貴人牽帝衣。","低回轉美目，風日爲無暉。","貴人飲金屑，倏忽舜英暮。","平生服杏丹，顏色真如故。","屬車塵已遠，里巷來窺覰。","共愛宿妝妍，君王畫眉處。","履綦無復有，履組光未滅。","不見巖畔人，空見凌波襪。","郵童愛踪跡，私手解鞶結。","傳看千萬眼，縷絕香不歇。","指環照骨明，首飾敵連城。","將入咸陽市，猶得賈胡驚。"]', '["綠野扶风道，黄塵马嵬驛。","路邊楊貴人，墳高三四尺。","乃问里中兒，皆言幸蜀时。","軍家誅戚族，天子捨妖姬。","羣吏伏门屏，貴人牽帝衣。","低回轉美目，风日爲無暉。","貴人饮金屑，倏忽舜英暮。","平生服杏丹，顏色真如故。","屬车塵已远，里巷来窺覰。","共愛宿妝妍，君王畫眉处。","履綦無复有，履組光未滅。","不见巖畔人，空见凌波襪。","郵童愛踪跡，私手解鞶結。","傳看千万眼，縷絕香不歇。","指环照骨明，首飾敵連城。","將入咸陽市，猶得賈胡驚。"]', '诗', 'shi', '', NULL, '馬嵬行 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8d612ee-0090-4cab-a883-406f4520e195', '百花行', '百花行', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["長安百花時，風景宜輕薄。","無人不沽酒，何處不聞樂。","春風連夜動，微雨凌曉濯。","紅焰出牆頭，雪光映樓角。","繁紫韻松竹，遠黃繞籬落。","臨路不勝愁，輕煙去何託。","滿庭蕩魂魄，照廡成丹渥。","爛熳簇顛狂，飄零勸行樂。","時節易晼晚，清陰覆池閣。","唯有安石榴，當軒慰寂寞。"]', '["长安百花时，风景宜轻薄。","無人不沽酒，何处不闻乐。","春风連夜动，微雨凌晓濯。","紅焰出牆头，雪光映楼角。","繁紫韻松竹，远黄繞籬落。","臨路不勝愁，轻煙去何託。","满庭蕩魂魄，照廡成丹渥。","爛熳簇顛狂，飄零勸行乐。","时節易晼晚，清陰覆池閣。","唯有安石榴，當軒慰寂寞。"]', '诗', 'shi', '', NULL, '百花行 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51b1fbda-3484-45a7-ab12-efc1119c14ee', '壯士行', '壯士行', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["陰風振寒郊，猛虎正咆哮。","徐行出燒地，連吼入黃茅。","壯士走馬去，鐙前彎玉弰。","叱之使人立，一發如鈹交。","悍睛忽星墮，飛血濺林梢。","彪炳爲我席，羶腥充我庖。","里中欣害除，賀酒紛呶號。","明日長橋上，傾城看斬蛟。"]', '["陰风振寒郊，猛虎正咆哮。","徐行出燒地，連吼入黄茅。","壯士走马去，鐙前彎玉弰。","叱之使人立，一發如鈹交。","悍睛忽星墮，飞血濺林梢。","彪炳爲我席，羶腥充我庖。","里中欣害除，賀酒紛呶號。","明日长橋上，傾城看斬蛟。"]', '诗', 'shi', '', NULL, '壯士行 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed7ef6eb-8c75-4ce9-8b03-2ad22ed6d8b0', '苦雨行', '苦雨行', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["悠悠飛走情，同樂在陽和。","歲中三百日，常恐風雨多。","天人信遐遠，時節易蹉跎。","洞房有明燭，無乃酣且歌。"]', '["悠悠飞走情，同乐在陽和。","歲中三百日，常恐风雨多。","天人信遐远，时節易蹉跎。","洞房有明燭，無乃酣且歌。"]', '诗', 'shi', '', NULL, '苦雨行 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea9d2b45-7a22-492a-9893-f1315219bda5', '華山歌', '华山歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["洪罏作高山，元氣鼓其橐。","俄然神功就，峻拔在寥廓。","靈跡露指爪，殺氣見稜角。","凡木不敢生，神僊聿來託。","天資帝王宅，以我爲關鑰。","能令下國人，一見換神骨。","高山固無限，如此方爲嶽。","丈夫無特達，雖貴猶碌碌。"]', '["洪罏作高山，元氣鼓其橐。","俄然神功就，峻拔在寥廓。","靈跡露指爪，殺氣见稜角。","凡木不敢生，神僊聿来託。","天資帝王宅，以我爲关鑰。","能令下国人，一见換神骨。","高山固無限，如此方爲嶽。","丈夫無特達，雖貴猶碌碌。"]', '诗', 'shi', '', NULL, '華山歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af352613-12f5-4a88-90b7-cc6ffc141997', '拋毬樂詞 一', '拋毬乐词 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["五綵繡團圓，登君玳瑁筵。","最宜紅燭下，偏稱落花前。","上客如先起，應須贈一船。"]', '["五綵繡團圓，登君玳瑁筵。","最宜紅燭下，偏稱落花前。","上客如先起，應須贈一船。"]', '诗', 'shi', '', NULL, '拋毬樂詞 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a930bf4-38e2-4320-900f-3d9d17d99a58', '拋毬樂詞 二', '拋毬乐词 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["春早見花枝，朝朝恨發遲。","及看花落後，却憶未開時。","幸有拋球樂，一杯君莫辭。"]', '["春早见花枝，朝朝恨發遲。","及看花落後，却憶未开时。","幸有拋球乐，一杯君莫辞。"]', '诗', 'shi', '', NULL, '拋毬樂詞 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efdb19c5-4ea9-4742-a22d-a201935a9495', '華清詞', '华清词', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["日出驪山東，裴回照溫泉。","樓臺影玲瓏，稍稍開白煙。","言昔太上皇，常居此祈年。","風中聞清樂，往往來列仙。","翠華入五雲，紫氣歸上玄。","哀哀生人淚，泣盡弓劒前。","聖道本自我，凡情徒顒然。","小臣感玄化，一望青冥天。"]', '["日出驪山东，裴回照溫泉。","楼台影玲瓏，稍稍开白煙。","言昔太上皇，常居此祈年。","风中闻清乐，往往来列仙。","翠华入五云，紫氣归上玄。","哀哀生人泪，泣尽弓劒前。","聖道本自我，凡情徒顒然。","小臣感玄化，一望青冥天。"]', '诗', 'shi', '', NULL, '華清詞 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8ebb16f-31c7-491b-bb3a-965c2da744dc', '送春曲三首 一', '送春曲三首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["春向晚，春晚思悠哉。","風雲日已改，花葉自相摧。","漠漠空中去，何時天際來。"]', '["春向晚，春晚思悠哉。","风云日已改，花葉自相摧。","漠漠空中去，何时天際来。"]', '诗', 'shi', '', NULL, '送春曲三首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04cbe110-8003-4d0c-8b03-b15a1a154d5f', '送春曲三首 二', '送春曲三首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["春已暮，冉冉如人老。","映葉見殘花，連天是青草。","可憐桃與李，從此同桑棗。"]', '["春已暮，冉冉如人老。","映葉见殘花，連天是青草。","可怜桃與李，從此同桑棗。"]', '诗', 'shi', '', NULL, '送春曲三首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dba141f-3a7d-4102-8ccc-d0f1316c509a', '送春曲三首 三', '送春曲三首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["春景去，此去何時回。","遊人千萬恨，落日上高臺。","寂寞繁花盡，流鸎歸莫來。"]', '["春景去，此去何时回。","游人千万恨，落日上高台。","寂寞繁花尽，流鸎归莫来。"]', '诗', 'shi', '', NULL, '送春曲三首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f19b213-3290-42f4-a18e-a4abe5623253', '初夏曲三首 一', '初夏曲三首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["銅壺方促夜，斗柄暫南回。","稍嫌單衣重，初憐北戶開。","西園花已盡，新月爲誰來。"]', '["銅壺方促夜，斗柄暫南回。","稍嫌單衣重，初怜北戶开。","西园花已尽，新月爲誰来。"]', '诗', 'shi', '', NULL, '初夏曲三首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24b01880-dc52-4fc6-a3de-fcd0af996101', '初夏曲三首 二', '初夏曲三首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["時節過繁華，陰陰千萬家。","巢禽命子戲，園果墜枝斜。","寂寞孤飛蝶，窺叢覓晚花。"]', '["时節過繁华，陰陰千万家。","巢禽命子戲，园果墜枝斜。","寂寞孤飞蝶，窺叢覓晚花。"]', '诗', 'shi', '', NULL, '初夏曲三首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bd83e81-1d93-4e02-90d9-a0cc53781f73', '初夏曲三首 三', '初夏曲三首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["綠水風初暖，青林露早晞。","麥隴雉朝雊，桑野人暮歸。","百舌悲花盡，平蕪來去飛。"]', '["綠水风初暖，青林露早晞。","麦隴雉朝雊，桑野人暮归。","百舌悲花尽，平蕪来去飞。"]', '诗', 'shi', '', NULL, '初夏曲三首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b439500e-b770-4ad5-a23e-cd6158cd4d03', '擣衣曲', '擣衣曲', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["爽砧應秋律，繁杵含淒風。","一一遠相續，家家音不同。","戶庭凝露清，伴侶明月中。","長裾委襞積，輕佩垂𤧚瓏。","汗餘衫更馥，鈿移麝半空。","報寒驚邊鴈，促思聞候蟲。","天狼正芒角，虎落定相攻。","盈篋寄何處，征人如轉蓬。"]', '["爽砧應秋律，繁杵含淒风。","一一远相續，家家音不同。","戶庭凝露清，伴侶明月中。","长裾委襞積，轻佩垂𤧚瓏。","汗餘衫更馥，鈿移麝半空。","報寒驚邊鴈，促思闻候蟲。","天狼正芒角，虎落定相攻。","盈篋寄何处，征人如轉蓬。"]', '诗', 'shi', '', NULL, '擣衣曲 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87b2aaa6-533b-4792-8f8e-129aad0b84b8', '畬田行', '畬田行', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處好畬田，團團縵山腹。","鑚龜得雨卦，上山燒臥木。","驚麏走且顧，羣雉聲咿喔。","紅焰遠成霞，輕煤飛入郭。","風引上高岑，獵獵度青林。","青林望靡靡，赤光低復起。","照潭出老蛟，爆竹驚山鬼。","夜色不見山，孤明星漢間。","如星復如月，俱逐曉風滅。","本從敲石光，遂至烘天熱。","下種暖灰中，乘陽拆牙孽。","蒼蒼一雨後，苕頴如雲發。","巴人拱手吟，耕耨不關心。","由來得地勢，徑寸有餘金。"]', '["何处好畬田，團團縵山腹。","鑚龟得雨卦，上山燒臥木。","驚麏走且顧，羣雉声咿喔。","紅焰远成霞，轻煤飞入郭。","风引上高岑，獵獵度青林。","青林望靡靡，赤光低复起。","照潭出老蛟，爆竹驚山鬼。","夜色不见山，孤明星漢间。","如星复如月，俱逐晓风滅。","本從敲石光，遂至烘天熱。","下種暖灰中，乘陽拆牙孽。","蒼蒼一雨後，苕頴如云發。","巴人拱手吟，耕耨不关心。","由来得地勢，徑寸有餘金。"]', '诗', 'shi', '', NULL, '畬田行 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6b2b649-2b2b-4c35-bb15-5681cbdd1775', '鶗鴂吟', '鶗鴂吟', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["朝陽有鳴鳳，不聞千萬祀。","鶗鴂摧衆芳，晨間先入耳。","秋風白露晞，從是爾啼時。","如何上春日，唧唧滿庭飛。"]', '["朝陽有鳴鳳，不闻千万祀。","鶗鴂摧衆芳，晨间先入耳。","秋风白露晞，從是爾啼时。","如何上春日，唧唧满庭飞。"]', '诗', 'shi', '', NULL, '鶗鴂吟 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b8940d5-7966-47ab-bbf9-55efadf169b3', '觀雲篇', '观云篇', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["興雲感陰氣，疾足如見機。","晴來意態行，有若功成歸。","葱蘢含晚景，潔白凝秋暉。","夜深度銀漢，漠漠仙人衣。"]', '["兴云感陰氣，疾足如见機。","晴来意態行，有若功成归。","葱蘢含晚景，潔白凝秋暉。","夜深度銀漢，漠漠仙人衣。"]', '诗', 'shi', '', NULL, '觀雲篇 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('113e7136-2be2-46a0-9e3b-25d3036d1d40', '養鷙詞', '養鷙词', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["養鷙非玩形，所資擊鮮力。","少年昧其理，日日哺不息。","探雛網黃口，旦暮有餘食。","寧知下韝時，翅重飛不得。","毰毸止林表，狡兔自南北。","飲啄既已盈，安能勞羽翼。"]', '["養鷙非玩形，所資擊鲜力。","少年昧其理，日日哺不息。","探雛網黄口，旦暮有餘食。","寧知下韝时，翅重飞不得。","毰毸止林表，狡兔自南北。","饮啄既已盈，安能勞羽翼。"]', '诗', 'shi', '', NULL, '養鷙詞 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('261fca31-93b2-4e5e-b6a8-65a79ac156dd', '別友人後得書因以詩贈', '別友人後得书因以诗贈', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["前時送君去，揮手青門橋。","路轉不相見，猶聞馬蕭蕭。","今得出關書，行程日已遙。","春還遲君至，共結芳蘭苕。"]', '["前时送君去，揮手青门橋。","路轉不相见，猶闻马蕭蕭。","今得出关书，行程日已遙。","春還遲君至，共結芳蘭苕。"]', '诗', 'shi', '', NULL, '別友人後得書因以詩贈 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fc97122-a0f4-4483-b254-454821da29a1', '送華陰尉張苕赴邕府使幕', '送华陰尉張苕赴邕府使幕', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["昔忝南宮郎，往來東觀頻。","嘗披燕公傳，聳若窺三辰。","翊聖崇國本，像賢正朝倫。","高視緬今古，清風敻無鄰。","蘭錡照通衢，一家十朱輪。","酇國嗣侯絕，韋卿世業貧。","夫子承大名，少年振芳塵。","青袍仙掌下，矯首凌煙旻。","公冶本非罪，潘郎一爲民。","風霜苦搖落，堅白無緇磷。","一旦逢良時，天光燭幽淪。","重爲長裾客，佐彼觀風臣。","分野窮禹畫，人煙過虞巡。","不言此行遠，所樂相知新。","雨起巫山陽，鳥鳴湘水濱。","離筵出蒼莽，別曲多悲辛。","今朝一杯酒，明日千里人。","從此孤舟去，悠悠天海春。"]', '["昔忝南宮郎，往来东观頻。","嘗披燕公傳，聳若窺三辰。","翊聖崇国本，像賢正朝倫。","高視緬今古，清风敻無鄰。","蘭錡照通衢，一家十朱輪。","酇国嗣侯絕，韋卿世業貧。","夫子承大名，少年振芳塵。","青袍仙掌下，矯首凌煙旻。","公冶本非罪，潘郎一爲民。","风霜苦搖落，堅白無緇磷。","一旦逢良时，天光燭幽淪。","重爲长裾客，佐彼观风臣。","分野窮禹畫，人煙過虞巡。","不言此行远，所乐相知新。","雨起巫山陽，鸟鳴湘水濱。","離筵出蒼莽，別曲多悲辛。","今朝一杯酒，明日千里人。","從此孤舟去，悠悠天海春。"]', '诗', 'shi', '', NULL, '送華陰尉張苕赴邕府使幕 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61e77b5c-983a-4b10-afb5-a76563ba71ef', '送湘陽熊判官孺登府罷歸鍾陵因寄呈江西裴中丞二十三兄', '送湘陽熊判官孺登府罷归鍾陵因寄呈江西裴中丞二十三兄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["射策志未就，從事歲云除。","篋留馬卿賦，袖有劉弘書。","忽見夏木深，悵然憶吾廬。","復持州民刺，歸謁專城居。","君家誠易知，勝絕傾里閭。","人言北郭生，門有卿相輿。","鍾陵靄千里，帶郭西江水。","朱檻照河宮，旗亭綠雲裏。","前年初缺守，慎簡由宸扆。","臨軒弄郡章，得人方付此。","是時左馮翊，天下第一理。","貴臣持牙璋，優詔發青紙。","迎風姦吏免，先令疲人喜。","何武劾腐儒，陳蕃禮高士。","昔升君子堂，腰下綬猶黃。","汾陰有寶氣，赤堇多奇鋩。","束簡下曲臺，佩鞬來歷陽。","綺筵陪一笑，蘭室襲餘芳。","風水忽異勢，江湖遂相忘。","因君倘借問，爲話老滄浪。"]', '["射策志未就，從事歲云除。","篋留马卿賦，袖有劉弘书。","忽见夏木深，悵然憶吾廬。","复持州民刺，归謁專城居。","君家誠易知，勝絕傾里閭。","人言北郭生，门有卿相輿。","鍾陵靄千里，带郭西江水。","朱檻照河宮，旗亭綠云裏。","前年初缺守，慎簡由宸扆。","臨軒弄郡章，得人方付此。","是时左馮翊，天下第一理。","貴臣持牙璋，優詔發青紙。","迎风姦吏免，先令疲人喜。","何武劾腐儒，陳蕃禮高士。","昔升君子堂，腰下綬猶黄。","汾陰有寶氣，赤堇多奇鋩。","束簡下曲台，佩鞬来歷陽。","綺筵陪一笑，蘭室襲餘芳。","风水忽異勢，江湖遂相忘。","因君倘借问，爲話老滄浪。"]', '诗', 'shi', '', NULL, '送湘陽熊判官孺登府罷歸鍾陵因寄呈江西裴中丞二十三兄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92e10d9d-a268-4f67-a55f-07bc0334c08c', '送韋秀才道沖赴制舉', '送韋秀才道沖赴制舉', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["驚禽一辭巢，棲息無少安。","秋扇一離手，流塵蔽霜紈。","故侶不可追，涼風日已寒。","遠逢杜陵士，別盡平生歡。","逐客無印綬，楚江多芷蘭。","因居暇時遊，長鋏不復彈。","閱書南軒霽，絙瑟清夜闌。","萬境身外寂，一杯腹中寬。","伊昔玄宗朝，冬卿冠鴛鸞。","肅穆升內殿，從容領儒冠。","游夏無措詞，陽秋垂不刊。","至今羣玉府，學者空縱觀。","世人希德門，揭若攀峰巒。","之子尚明訓，鏘如振琅玕。","一旦西上書，斑衣拂征鞍。","荆臺宿暮雨，漢水浮春瀾。","君門起天中，多士如星攢。","煙霞覆雙闕，抃舞羅千官。","清漏滴銅壺，仙廚下雕槃。","熒煌仰金榜，錯落濡飛翰。","古來才傑士，所嗟遭時難。","一鳴從此始，相望青雲端。"]', '["驚禽一辞巢，棲息無少安。","秋扇一離手，流塵蔽霜紈。","故侶不可追，涼风日已寒。","远逢杜陵士，別尽平生歡。","逐客無印綬，楚江多芷蘭。","因居暇时游，长鋏不复彈。","閱书南軒霽，絙瑟清夜闌。","万境身外寂，一杯腹中寬。","伊昔玄宗朝，冬卿冠鴛鸾。","肅穆升內殿，從容領儒冠。","游夏無措词，陽秋垂不刊。","至今羣玉府，学者空縱观。","世人希德门，揭若攀峰巒。","之子尚明訓，鏘如振琅玕。","一旦西上书，斑衣拂征鞍。","荆台宿暮雨，漢水浮春瀾。","君门起天中，多士如星攢。","煙霞覆雙闕，抃舞羅千官。","清漏滴銅壺，仙廚下雕槃。","熒煌仰金榜，錯落濡飞翰。","古来才傑士，所嗟遭时难。","一鳴從此始，相望青云端。"]', '诗', 'shi', '', NULL, '送韋秀才道沖赴制舉 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7965c42-0b1a-4fb9-97bd-1e5e375a819b', '送李策秀才還湖南因寄幕中親故兼簡衡州呂八郎中', '送李策秀才還湖南因寄幕中親故兼簡衡州呂八郎中', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["深春風日淨，晝長幽鳥鳴。","僕夫前致詞，門有白面生。","攝衣相問訊，解帶坐南榮。","端志見眉睫，苦言發精誠。","因出懷中文，調孤詞亦清。","悄如促柱弦，掩抑多不平。","乃言本蜀士，世降岷山靈。","前人秉藝文，高視來上京。","曳綬司徒府，所從信國楨。","析薪委寶林，善響繼家聲。","何處翳附郭，幾人思郈成。","雲天望喬木，風水悲流萍。","前與計吏西，始列貢士名。","森然就筆札，從試春官卿。","帝城岐路多，萬足伺晨星。","茫茫風塵中，工拙同有營。","寒女勞夜織，山苗榮寸莖。","侯門方擊鐘，衣褐誰將迎。","弱羽果摧頹，壯心鬱怦怦。","諒無蟠木容，聊復蓬累行。","昨日訊靈龜，繇言利艱貞。","當求捨拔中，必在審已明。","誓將息薄遊，焦思窮筆精。","蒔蘭在幽渚，安得揚芬馨。","曰余摧落者，散質負華纓。","一聆苦辛詞，再動伊鬱情。","身棄言不動，愛才心尚驚。","恨無羊角風，使爾化北溟。","論罷情益親，涉旬忘歸程。","日攜邑中客，閑眺江上城。","晝憩命金罍，宵談轉璿衡。","薰風香麈尾，月露濡桃笙。","忽被戒羸驂，薄言事南征。","火雲蔚千里，旅思浩已盈。","湘江含碧虛，衡嶺浮翠晶。","豈伊山水異，適與人事幷。","油幕侶昆丘，粲然疊瑤瓊。","庾樓見清月，孔坐多綠醽。","復有衡山守，本自雲龍庭。","抗志在靈府，發越侔咸英。","一揮出滎陽，惠彼嗤嗤氓。","隼旟辭灞水，居者皆涕零。","惟昔與伊人，交歡經宿齡。","一從雲雨散，滋我鄙吝萌。","北渚不堪愁，南音誰復聽。","離憂若去水，浩漾無時停。","嘗聞祝融峰，上有神禹銘。","古石琅玕姿，秘文螭虎形。","聖功奠遠服，神物擁休禎。","賢人在其下，彷彿疑蓬瀛。","君行歷郡齋，大袂拂雙旌。","飾容遇朗鑒，肝鬲可以呈。","昔日馬相如，臨邛坐盡傾。","勉君刷羽翰，蚤取凌青冥。"]', '["深春风日淨，晝长幽鸟鳴。","僕夫前致词，门有白面生。","攝衣相问訊，解带坐南榮。","端志见眉睫，苦言發精誠。","因出懷中文，調孤词亦清。","悄如促柱弦，掩抑多不平。","乃言本蜀士，世降岷山靈。","前人秉藝文，高視来上京。","曳綬司徒府，所從信国楨。","析薪委寶林，善响繼家声。","何处翳附郭，幾人思郈成。","云天望喬木，风水悲流萍。","前與計吏西，始列貢士名。","森然就笔札，從試春官卿。","帝城岐路多，万足伺晨星。","茫茫风塵中，工拙同有營。","寒女勞夜织，山苗榮寸莖。","侯门方擊鐘，衣褐誰將迎。","弱羽果摧頹，壯心鬱怦怦。","諒無蟠木容，聊复蓬累行。","昨日訊靈龟，繇言利艱貞。","當求捨拔中，必在審已明。","誓將息薄游，焦思窮笔精。","蒔蘭在幽渚，安得揚芬馨。","曰余摧落者，散質負华纓。","一聆苦辛词，再动伊鬱情。","身棄言不动，愛才心尚驚。","恨無羊角风，使爾化北溟。","論罷情益親，涉旬忘归程。","日携邑中客，闲眺江上城。","晝憩命金罍，宵談轉璿衡。","薰风香麈尾，月露濡桃笙。","忽被戒羸驂，薄言事南征。","火云蔚千里，旅思浩已盈。","湘江含碧虛，衡嶺浮翠晶。","豈伊山水異，適與人事幷。","油幕侶昆丘，粲然叠瑤瓊。","庾楼见清月，孔坐多綠醽。","复有衡山守，本自云龙庭。","抗志在靈府，發越侔咸英。","一揮出滎陽，惠彼嗤嗤氓。","隼旟辞灞水，居者皆涕零。","惟昔與伊人，交歡經宿齡。","一從云雨散，滋我鄙吝萌。","北渚不堪愁，南音誰复听。","離憂若去水，浩漾無时停。","嘗闻祝融峰，上有神禹銘。","古石琅玕姿，秘文螭虎形。","聖功奠远服，神物擁休禎。","賢人在其下，彷彿疑蓬瀛。","君行歷郡斋，大袂拂雙旌。","飾容遇朗鑒，肝鬲可以呈。","昔日马相如，臨邛坐尽傾。","勉君刷羽翰，蚤取凌青冥。"]', '诗', 'shi', '', NULL, '送李策秀才還湖南因寄幕中親故兼簡衡州呂八郎中 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('781aeee0-2331-4e7d-8f6c-d29b134c98a1', '送張盥赴舉詩', '送張盥赴舉诗', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["爾生始懸弧，我作座上賓。","引箸舉湯餅，祝詞天麒麟。","今成一丈夫，坎坷愁風塵。","長裾來謁我，自號廬山人。","道舊與撫孤，悄然傷我神。","依依見眉睫，嘿嘿含悲辛。","永懷同年友，追想出谷晨。","三十二君子，齊飛凌煙旻。","曲江一會時，後會已凋淪。","況今三十載，閱世難重陳。","盛時一已過，來者日日新。","不如搖落樹，重有明年春。","火後見琮璜，霜餘識松筠。","肅風乃獨秀，武部亦絕倫。","爾今持我詩，西見二重臣。","成賢必念舊，保貴在安貧。","清時爲丞郎，氣力侔陶鈞。","乞取斗升水，因之雲漢津。"]', '["爾生始懸弧，我作座上賓。","引箸舉湯餅，祝词天麒麟。","今成一丈夫，坎坷愁风塵。","长裾来謁我，自號廬山人。","道旧與撫孤，悄然傷我神。","依依见眉睫，嘿嘿含悲辛。","永懷同年友，追想出谷晨。","三十二君子，齊飞凌煙旻。","曲江一會时，後會已凋淪。","況今三十載，閱世难重陳。","盛时一已過，来者日日新。","不如搖落樹，重有明年春。","火後见琮璜，霜餘識松筠。","肅风乃独秀，武部亦絕倫。","爾今持我诗，西见二重臣。","成賢必念旧，保貴在安貧。","清时爲丞郎，氣力侔陶鈞。","乞取斗升水，因之云漢津。"]', '诗', 'shi', '', NULL, '送張盥赴舉詩 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd292dd0-64dd-45dd-9755-f8bfac267b1f', '和州送錢侍御自宣州幕拜官便於華州覲省', '和州送錢侍御自宣州幕拜官便於华州覲省', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["五綵繡衣裳，當年正相稱。","春風舊關路，歸去真多興。","蘭陔行可採，蓮府猶回瞪。","楊家紺幰迎，謝守瑤華贈。","御街草泛灧，臺柏煙含凝。","曾是平生遊，無因理歸乘。"]', '["五綵繡衣裳，當年正相稱。","春风旧关路，归去真多兴。","蘭陔行可採，蓮府猶回瞪。","楊家紺幰迎，謝守瑤华贈。","御街草泛灧，台柏煙含凝。","曾是平生游，無因理归乘。"]', '诗', 'shi', '', NULL, '和州送錢侍御自宣州幕拜官便於華州覲省 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb93206b-92a8-4440-aeb5-4cc3bbe596ea', '送僧方及南謁柳員外', '送僧方及南謁柳員外', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["昔事廬山遠，精舍虎溪東。","朝陽照瀑水，樓閣虹霓中。","騁望羨游雲，振衣若秋蓬。","舊房閉松月，遠思吟江風。","古寺歷頭陀，奇峰扳祝融。","南登小桂嶺，却望歸塞鴻。","衣裓貯文章，自言學雕蟲。","搶榆念陵厲，覆簣圖穹崇。","遠郡多暇日，有詩訪禪宮。","石門聳峭絕，竹院含空濛。","幽響滴巖溜，晴芳飄野叢。","海雲懸颶母，山果屬狙公。","忽憶吳興郡，白蘋正葱蘢。","願言挹風采，邈若窺華嵩。","桂水夏瀾急，火山宵焰紅。","三衣濡菌露，一錫飛煙空。","勿謂翻譯徒，不爲文雅雄。","古來賞音者，燋爨得孤桐。"]', '["昔事廬山远，精舍虎溪东。","朝陽照瀑水，楼閣虹霓中。","騁望羨游云，振衣若秋蓬。","旧房閉松月，远思吟江风。","古寺歷头陀，奇峰扳祝融。","南登小桂嶺，却望归塞鴻。","衣裓貯文章，自言学雕蟲。","搶榆念陵厲，覆簣圖穹崇。","远郡多暇日，有诗訪禪宮。","石门聳峭絕，竹院含空濛。","幽响滴巖溜，晴芳飄野叢。","海云懸颶母，山果屬狙公。","忽憶吳兴郡，白蘋正葱蘢。","願言挹风采，邈若窺华嵩。","桂水夏瀾急，火山宵焰紅。","三衣濡菌露，一錫飞煙空。","勿謂翻譯徒，不爲文雅雄。","古来賞音者，燋爨得孤桐。"]', '诗', 'shi', '', NULL, '送僧方及南謁柳員外 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5863daf6-9ae5-4f51-b3e0-f47679b47b27', '送惟良上人', '送惟良上人', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["高齋灑寒水，是夕山僧至。","玄牝無關鎖，瓊書捨文字。","燈明香滿室，月午霜凝地。","語到不言時，世間人盡睡。"]', '["高斋灑寒水，是夕山僧至。","玄牝無关鎖，瓊书捨文字。","灯明香满室，月午霜凝地。","語到不言时，世间人尽睡。"]', '诗', 'shi', '', NULL, '送惟良上人 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4316a389-61fb-4994-ae88-83831c2ae90d', '翠微寺有感', '翠微寺有感', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["吾王昔遊幸，離宮雲際開。","朱旗迎夏早，涼軒避暑來。","湯餅賜都尉，寒冰頒上才。","龍髯不可望，玉座生塵埃。"]', '["吾王昔游幸，離宮云際开。","朱旗迎夏早，涼軒避暑来。","湯餅賜都尉，寒冰頒上才。","龙髯不可望，玉座生塵埃。"]', '诗', 'shi', '', NULL, '翠微寺有感 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e471da14-19ce-41bb-ab7e-0455aed83758', '觀柘枝舞二首 一', '观柘枝舞二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["胡服何葳蕤，僊僊登綺墀。","神飆獵紅蕖，龍燭暎金枝。","垂帶覆纖腰，安鈿當嫵眉。","翹袖中繁鼓，傾眸遡華榱。","燕秦有舊曲，淮南多冶詞。","欲見傾城處，君看赴節時。"]', '["胡服何葳蕤，僊僊登綺墀。","神飆獵紅蕖，龙燭暎金枝。","垂带覆纖腰，安鈿當嫵眉。","翹袖中繁鼓，傾眸遡华榱。","燕秦有旧曲，淮南多冶词。","欲见傾城处，君看赴節时。"]', '诗', 'shi', '', NULL, '觀柘枝舞二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2404a4f-f825-4d29-ba99-f3807ca3951e', '觀柘枝舞二首 二', '观柘枝舞二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["山雞臨清鏡，石燕赴遙津。","何如上客會，長袖入華裀。","體輕似無骨，觀者皆聳神。","曲盡回身處，層波猶注人。"]', '["山雞臨清镜，石燕赴遙津。","何如上客會，长袖入华裀。","體轻似無骨，观者皆聳神。","曲尽回身处，層波猶注人。"]', '诗', 'shi', '', NULL, '觀柘枝舞二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3c3efef-0365-4eda-8187-8890a0f407db', '連州臘日觀莫徭臘西山', '連州臘日观莫徭臘西山', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["海天殺氣薄，蠻軍步伍囂。","林紅葉盡變，原黑草初燒。","圍合繁鉦息，禽興大斾搖。","張羅依道口，嗾犬上山腰。","猜鷹慮奮迅，驚鹿時跼跳。","瘴雲四面起，臘雪半空消。","箭頭餘鵠血，鞍傍見雉翹。","日暮還城邑，金笳發麗譙。"]', '["海天殺氣薄，蠻軍步伍囂。","林紅葉尽变，原黑草初燒。","圍合繁鉦息，禽兴大斾搖。","張羅依道口，嗾犬上山腰。","猜鷹慮奮迅，驚鹿时跼跳。","瘴云四面起，臘雪半空消。","箭头餘鵠血，鞍傍见雉翹。","日暮還城邑，金笳發丽譙。"]', '诗', 'shi', '', NULL, '連州臘日觀莫徭臘西山 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03209ef5-4294-43fa-aace-c03cd0f2fb6e', '寄陝州姚中丞', '寄陝州姚中丞', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["八月天氣肅，二陵風雨收。","旌旗闕下來，雲日關東秋。","禹跡想前事，漢臺餘故丘。","俳徊襟帶地，左右帝王州。","留滯悲昔老，恩光榮徹侯。","相思望棠樹，一寄商聲謳。"]', '["八月天氣肅，二陵风雨收。","旌旗闕下来，云日关东秋。","禹跡想前事，漢台餘故丘。","俳徊襟带地，左右帝王州。","留滯悲昔老，恩光榮徹侯。","相思望棠樹，一寄商声謳。"]', '诗', 'shi', '', NULL, '寄陝州姚中丞 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7bd65ca-4ccd-42db-82ec-b7115a53fc7c', '奉酬湖州崔郎中見寄五韻', '奉酬湖州崔郎中见寄五韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["山陽昔相遇，灼灼晨葩鮮。","同遊翰墨場，和樂塤箎然。","一落名宦途，浩如乘風船。","行當衰暮日，臥理淮海邊。","猶期謝病後，共樂桑榆年。"]', '["山陽昔相遇，灼灼晨葩鲜。","同游翰墨場，和乐塤箎然。","一落名宦途，浩如乘风船。","行當衰暮日，臥理淮海邊。","猶期謝病後，共乐桑榆年。"]', '诗', 'shi', '', NULL, '奉酬湖州崔郎中見寄五韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d74a45e-2147-4c0a-9356-57571cfc232a', '學阮公體三首 一', '学阮公體三首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["少年負志氣，信道不從時。","只言繩自直，安知室可欺。","百勝難慮敵，三折乃良醫。","人生不失意，焉能慕知己。"]', '["少年負志氣，信道不從时。","只言繩自直，安知室可欺。","百勝难慮敵，三折乃良醫。","人生不失意，焉能慕知己。"]', '诗', 'shi', '', NULL, '學阮公體三首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8bfb247-859a-43e7-99fa-16f4eec18dc0', '學阮公體三首 二', '学阮公體三首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["朔風悲老驥，秋霜動鷙禽。","出門有遠道，平野多層陰。","滅沒馳絕塞，振迅拂華林。","不因感衰節，安能激壯心。"]', '["朔风悲老驥，秋霜动鷙禽。","出门有远道，平野多層陰。","滅沒驰絕塞，振迅拂华林。","不因感衰節，安能激壯心。"]', '诗', 'shi', '', NULL, '學阮公體三首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6a8ee98-9353-4283-9aed-dd14084ebced', '學阮公體三首 三', '学阮公體三首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["昔賢多使氣，憂國不謀身。","目覽千載事，心交上古人。","侯門有仁義，靈臺多苦辛。","不學腰如磬，徒使甑生塵。"]', '["昔賢多使氣，憂国不謀身。","目覽千載事，心交上古人。","侯门有仁義，靈台多苦辛。","不学腰如磬，徒使甑生塵。"]', '诗', 'shi', '', NULL, '學阮公體三首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eac3d32-e1f3-4258-9938-26f828aaa26e', '秋晚題湖城驛池上亭', '秋晚題湖城驛池上亭', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["秋次池上館，林塘照南榮。","塵衣紛未解，幽思浩已盈。","風蓮墜故萼，露菊含晚英。","恨爲一夕客，愁聽晨雞鳴。"]', '["秋次池上館，林塘照南榮。","塵衣紛未解，幽思浩已盈。","风蓮墜故萼，露菊含晚英。","恨爲一夕客，愁听晨雞鳴。"]', '诗', 'shi', '', NULL, '秋晚題湖城驛池上亭 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40cb2f52-4361-4f0d-9b37-519a7c0b0e74', '賈客詞', '賈客词', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["賈客無定遊，所遊唯利幷。","眩俗雜良苦，乘時取重輕。","心計析秋毫，搖鉤侔懸衡。","錐刀既無棄，轉化日已盈。","邀福禱波神，施財遊化城。","妻約雕金釧，女垂貫珠纓。","高貲比封君，奇貨通倖卿。","趨時鷙鳥思，藏鏹盤龍形。","大艑浮通川，高樓次旗亭。","行止皆有樂，關梁自無征。","農夫何爲者，辛苦事寒耕。"]', '["賈客無定游，所游唯利幷。","眩俗杂良苦，乘时取重轻。","心計析秋毫，搖鉤侔懸衡。","錐刀既無棄，轉化日已盈。","邀福禱波神，施財游化城。","妻約雕金釧，女垂貫珠纓。","高貲比封君，奇貨通倖卿。","趨时鷙鸟思，藏鏹盤龙形。","大艑浮通川，高楼次旗亭。","行止皆有乐，关梁自無征。","農夫何爲者，辛苦事寒耕。"]', '诗', 'shi', '', NULL, '賈客詞 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('089b5bfb-83e2-4d94-ab79-9b0dfdde3575', '調瑟詞', '調瑟词', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["調瑟在張弦，弦平音自足。","朱弦二十五，缺一不成曲。","美人愛高張，瑤軫再三促。","上弦雖獨響，下應不相屬。","日暮聲未和，寂寥一枯木。","却顧膝上弦，流淚難相續。"]', '["調瑟在張弦，弦平音自足。","朱弦二十五，缺一不成曲。","美人愛高張，瑤軫再三促。","上弦雖独响，下應不相屬。","日暮声未和，寂寥一枯木。","却顧膝上弦，流泪难相續。"]', '诗', 'shi', '', NULL, '調瑟詞 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d0dba7d-6ac7-46d2-b49d-ba4be9b7b66b', '讀張曲江集作', '读張曲江集作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["聖言貴忠恕，至道重觀身。","法在何所恨，色相斯爲仁。","良時難久恃，陰謫豈無因。","寂寞韶陽廟，魂歸不見人。"]', '["聖言貴忠恕，至道重观身。","法在何所恨，色相斯爲仁。","良时难久恃，陰謫豈無因。","寂寞韶陽廟，魂归不见人。"]', '诗', 'shi', '', NULL, '讀張曲江集作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed07986b-0256-4bcf-8b27-e633e3785ad2', '偶作二首 一', '偶作二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["終朝對尊酒，嗜興非嗜甘。","終日偶衆人，縱言不縱談。","世情閑靜見，藥性病多諳。","寄謝嵇中散，予無甚不堪。"]', '["終朝对尊酒，嗜兴非嗜甘。","終日偶衆人，縱言不縱談。","世情闲静见，藥性病多諳。","寄謝嵇中散，予無甚不堪。"]', '诗', 'shi', '', NULL, '偶作二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb874241-6d70-495b-91e1-2b24aadd8c9c', '偶作二首 二', '偶作二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["萬卷堆牀書，學者識其真。","萬里長江水，征夫渡要津。","養生非但藥，悟佛不因人。","燕石何須辨，逢時即至珍。"]', '["万卷堆牀书，学者識其真。","万里长江水，征夫渡要津。","養生非但藥，悟佛不因人。","燕石何須辨，逢时即至珍。"]', '诗', 'shi', '', NULL, '偶作二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31119bd8-3cf0-402d-8e6f-6ebfdda3c423', '昏鏡詞', '昏镜词', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["昏鏡非美金，漠然喪其晶。","陋容多自欺，謂若他鏡明。","瑕疵既不見，妍態隨意生。","一日四五照，自言美傾城。","飾帶以紋繡，裝匣以瓊瑛。","秦宮豈不重，非適乃爲輕。"]', '["昏镜非美金，漠然喪其晶。","陋容多自欺，謂若他镜明。","瑕疵既不见，妍態隨意生。","一日四五照，自言美傾城。","飾带以紋繡，裝匣以瓊瑛。","秦宮豈不重，非適乃爲轻。"]', '诗', 'shi', '', NULL, '昏鏡詞 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0072b076-9763-4af6-8e62-36cd23362157', '詠古二首有所寄 一', '詠古二首有所寄 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["車音想轔轔，不見綦下塵。","可憐平陽第，歌舞嬌青春。","金屋容色在，文園詞賦新。","一朝復得幸，應知失意人。"]', '["车音想轔轔，不见綦下塵。","可怜平陽第，歌舞嬌青春。","金屋容色在，文园词賦新。","一朝复得幸，應知失意人。"]', '诗', 'shi', '', NULL, '詠古二首有所寄 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f95a0f0-b062-4734-98a4-9646fc613d73', '詠古二首有所寄 二', '詠古二首有所寄 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["寂寥照鏡臺，遺基古南陽。","真人昔來遊，翠鳳相隨翔。","目成在桑野，志遂貯椒房。","豈無三千女，初心不可忘。"]', '["寂寥照镜台，遺基古南陽。","真人昔来游，翠鳳相隨翔。","目成在桑野，志遂貯椒房。","豈無三千女，初心不可忘。"]', '诗', 'shi', '', NULL, '詠古二首有所寄 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebf7d326-1e94-4b70-a1e0-80419c25df45', '磨鏡篇', '磨镜篇', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["流塵翳明鏡，歲久看如漆。","門前負局人，爲我一磨拂。","萍開綠池滿，暈盡金波溢。","白日照空心，圓光走幽室。","山神妖氣沮，野魅真形出。","却思未磨時，瓦礫來唐突。"]', '["流塵翳明镜，歲久看如漆。","门前負局人，爲我一磨拂。","萍开綠池满，暈尽金波溢。","白日照空心，圓光走幽室。","山神妖氣沮，野魅真形出。","却思未磨时，瓦礫来唐突。"]', '诗', 'shi', '', NULL, '磨鏡篇 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93f9980c-8c38-4f07-a2e7-0ad9ec4e080f', '登司馬錯古城', '登司马錯古城', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["將軍將秦師，西南奠遐服。","故壘清江上，蒼烟晦喬木。","登臨直蕭辰，周覽壯前躅。","塹平陳葉滿，墉高秋蔓綠。","廢井抽寒菜，毀臺生魯穀。","耕人得古器，宿雨多遺鏃。","楚塞鬱重疊，蠻溪紛詰曲。","留此數仞基，幾人傷遠目。"]', '["將軍將秦師，西南奠遐服。","故壘清江上，蒼烟晦喬木。","登臨直蕭辰，周覽壯前躅。","塹平陳葉满，墉高秋蔓綠。","廢井抽寒菜，毀台生魯穀。","耕人得古器，宿雨多遺鏃。","楚塞鬱重叠，蠻溪紛詰曲。","留此數仞基，幾人傷远目。"]', '诗', 'shi', '', NULL, '登司馬錯古城 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3db77b89-08a0-4ae3-bf83-c5c1468c555d', '謁柱山會禪師', '謁柱山會禪師', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["我本山東人，平生多感慨。","弱冠遊咸京，上書金馬外。","結交當世賢，馳聲溢四塞。","勉修貴及早，狃捷不知退。","錙銖揚芬馨，尋尺招瑕纇。","淹留郢南都，摧頹羽翰碎。","安能咎往事，且欲去沈痗。","吾師得真如，寄在人寰內。","哀我墮名網，有如翾飛輩。","瞳瞳揭智燭，照使出昏昧。","靜見玄關啓，歆然初心會。","夙尚一何微，今得信可大。","覺路明證入，便門通懺悔。","悟理言自忘，處屯道猶泰。","色身豈吾寶，慧性非形礙。","思此靈山期，未卜何年載。"]', '["我本山东人，平生多感慨。","弱冠游咸京，上书金马外。","結交當世賢，驰声溢四塞。","勉修貴及早，狃捷不知退。","錙銖揚芬馨，尋尺招瑕纇。","淹留郢南都，摧頹羽翰碎。","安能咎往事，且欲去沈痗。","吾師得真如，寄在人寰內。","哀我墮名網，有如翾飞輩。","瞳瞳揭智燭，照使出昏昧。","静见玄关啓，歆然初心會。","夙尚一何微，今得信可大。","覺路明證入，便门通懺悔。","悟理言自忘，处屯道猶泰。","色身豈吾寶，慧性非形礙。","思此靈山期，未卜何年載。"]', '诗', 'shi', '', NULL, '謁柱山會禪師 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b6c65cd-f742-4c07-8da3-c815fcf6b9ab', '臥病聞常山旋師策勳宥過王澤大洽因寄李六侍郎', '臥病闻常山旋師策勳宥過王澤大洽因寄李六侍郎', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["寂寂重寂寂，病夫臥秋齋。","夜蛩思幽壁，槁葉鳴空堦。","南國異氣候，火旻尚昏霾。","瘴煙跕飛羽，沴氣傷百骸。","昨聞凱歌旋，飲至酒如淮。","無戰陋丹水，垂仁輕槀街。","清廟既策勳，圓丘俟燔柴。","車書一以混，幽遠靡不懷。","逐客顦顇久，故鄉雲雨乖。","禽魚各有化，予欲問齊諧。"]', '["寂寂重寂寂，病夫臥秋斋。","夜蛩思幽壁，槁葉鳴空堦。","南国異氣候，火旻尚昏霾。","瘴煙跕飞羽，沴氣傷百骸。","昨闻凱歌旋，饮至酒如淮。","無戰陋丹水，垂仁轻槀街。","清廟既策勳，圓丘俟燔柴。","车书一以混，幽远靡不懷。","逐客顦顇久，故乡云雨乖。","禽鱼各有化，予欲问齊諧。"]', '诗', 'shi', '', NULL, '臥病聞常山旋師策勳宥過王澤大洽因寄李六侍郎 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20c8844d-531e-4037-8a64-54930a37939e', '善卷壇下作', '善卷壇下作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["先生見堯心，相與去九有。","斯民既已治，我得安林藪。","道爲自然貴，名是無窮壽。","瑤壇在此山，識者常回首。"]', '["先生见堯心，相與去九有。","斯民既已治，我得安林藪。","道爲自然貴，名是無窮壽。","瑤壇在此山，識者常回首。"]', '诗', 'shi', '', NULL, '善卷壇下作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7545d07f-17d2-47df-89d1-ed639aeff478', '武陵觀火詩', '武陵观火诗', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["楚鄉祝融分，炎火常爲虞。","是時直突煙，發自晨炊徒。","盲風扇其威，白晝曛陽鳥。","操綆不暇汲，循牆還避踰。","怒如列缺光，迅與芬輪俱。","聯延掩四遠，赫弈成洪鑪。","洶疑雲濤翻，颯若鬼神趨。","當前迎惞𨹮，是物同膏腴。","金烏入梵天，赤龍遊玄都。","騰煙透窻戶，飛燄生欒櫨。","火山摧半空，星雨灑中衢。","瑤壇被髹漆，寶樹攢珊瑚。","光縣與琴焦，旗亭無酒濡。","市人委百貨，邑令遺雙鳧。","餘勢下隈隩，長熛烘舳艫。","吹焚照水府，炙浪愁天吳。","災罷雲日晚，心驚視聽殊。","高灰辨廩庾，黑土連闉闍。","衆燼合星羅，遊氛鑠人膚。","厚地藏宿熱，遙林呈驟枯。","火德資生人，庸可一日無。","御之失其道，敲石彌天隅。","晉庫走龍劒，吳宮傷燕雛。","五行有沴氣，先哲垂訏謨。","宋鄭同日起，時當賢大夫。","無苛自可樂，弭患非所圖。","賢守恤人瘼，臨煙駐驪駒。","弔場色慘忸，顏失詞劬愉。","下令蠲里布，指期輕市租。","閈垣適未立，苫蓋自相娛。","山木行剪伐，江泥宜墐途。","邑臣不必曾，何用徵越巫。"]', '["楚乡祝融分，炎火常爲虞。","是时直突煙，發自晨炊徒。","盲风扇其威，白晝曛陽鸟。","操綆不暇汲，循牆還避踰。","怒如列缺光，迅與芬輪俱。","聯延掩四远，赫弈成洪鑪。","洶疑云濤翻，颯若鬼神趨。","當前迎惞𨹮，是物同膏腴。","金烏入梵天，赤龙游玄都。","腾煙透窻戶，飞燄生欒櫨。","火山摧半空，星雨灑中衢。","瑤壇被髹漆，寶樹攢珊瑚。","光縣與琴焦，旗亭無酒濡。","市人委百貨，邑令遺雙鳧。","餘勢下隈隩，长熛烘舳艫。","吹焚照水府，炙浪愁天吳。","災罷云日晚，心驚視听殊。","高灰辨廩庾，黑土連闉闍。","衆燼合星羅，游氛鑠人膚。","厚地藏宿熱，遙林呈驟枯。","火德資生人，庸可一日無。","御之失其道，敲石彌天隅。","晉庫走龙劒，吳宮傷燕雛。","五行有沴氣，先哲垂訏謨。","宋鄭同日起，时當賢大夫。","無苛自可乐，弭患非所圖。","賢守恤人瘼，臨煙駐驪駒。","弔場色慘忸，顏失词劬愉。","下令蠲里布，指期轻市租。","閈垣適未立，苫蓋自相娛。","山木行剪伐，江泥宜墐途。","邑臣不必曾，何用徵越巫。"]', '诗', 'shi', '', NULL, '武陵觀火詩 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c70f3ee7-ba98-4fbd-a6af-46f4fa583e23', '崔元受少府自貶所還遺山薑花以詩答之', '崔元受少府自貶所還遺山薑花以诗答之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["故人博羅尉，遺我山薑花。","採從碧海上，來自謫仙家。","雲濤潤孤根，陰火照晨葩。","靜搖扶桑日，豔對瀛洲霞。","世人愛芳辛，搴擷忘幽遐。","傳名入帝里，飛驛辭天涯。","王濟本尚味，石崇方鬬奢。","雕盤多不識，綺席乃增華。","驛馬損筋骨，貴人滋齒牙。","顧予藜藿士，持此重咨嗟。"]', '["故人博羅尉，遺我山薑花。","採從碧海上，来自謫仙家。","云濤潤孤根，陰火照晨葩。","静搖扶桑日，豔对瀛洲霞。","世人愛芳辛，搴擷忘幽遐。","傳名入帝里，飞驛辞天涯。","王濟本尚味，石崇方鬬奢。","雕盤多不識，綺席乃增华。","驛马損筋骨，貴人滋齒牙。","顧予藜藿士，持此重咨嗟。"]', '诗', 'shi', '', NULL, '崔元受少府自貶所還遺山薑花以詩答之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5f6df2d-9c5b-460c-985c-c4f6513b40a9', '途中早發', '途中早發', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["馬踏塵上霜，月明江頭路。","行人朝氣銳，宿鳥相辭去。","流水隔遠村，縵山多紅樹。","悠悠關塞內，往來無閑步。"]', '["马踏塵上霜，月明江头路。","行人朝氣銳，宿鸟相辞去。","流水隔远村，縵山多紅樹。","悠悠关塞內，往来無闲步。"]', '诗', 'shi', '', NULL, '途中早發 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f60d494-257c-43bf-b877-9088019bea69', '和董庶中古散調詞贈尹果毅', '和董庶中古散調词贈尹果毅', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["昔聽東武吟，壯年心已悲。","如何今濩落，聞君辛苦辭。","言有窮巷士，弱齡頗尚奇。","讀得玄女符，生當事邊時。","借名遊俠窟，結客幽幷兒。","往來長楸間，能帶雙鞬馳。","崩騰天寶末，塵暗燕南垂。","爟火入咸陽，詔徵神武師。","是時占軍幕，插羽揚金羈。","萬夫列轅門，觀射中戟支。","誓當雪國讐，親愛從此辭。","中宵倚長劒，起視蚩尤旗。","介馬晨蕭蕭，陣雲竟天涯。","陰風獵白草，旗槊光參差。","勇氣貫中腸，視身忽如遺。","生擒白馬將，虜騎不敢追。","貴臣上戰功，名姓隨意移。","終歲肌骨苦，他人印纍纍。","謁者既清宮，諸侯各罷戲。","上將賜甲第，門戟不可窺。","眥血下沾襟，天高問無期。","却尋故鄉路，孤影空相隨。","行逢里中舊，撲遬昔所嗤。","一言合侯王，腰佩黃金龜。","問我何自苦，可憐真數奇。","遲回顧徒御，得色懸雙眉。","翻然悟世途，撫己昧所宜。","田園已蕪沒，流浪江海湄。","鷙禽毛翮摧，不見翔雲姿。","衰容蔽逸氣，孑孑無人知。","寂寞草玄徒，長吟下書帷。","爲君發哀韻，若扣瑤林枝。","有客識其真，潺湲涕交頤。","飲爾一杯酒，陶然足自怡。"]', '["昔听东武吟，壯年心已悲。","如何今濩落，闻君辛苦辞。","言有窮巷士，弱齡頗尚奇。","读得玄女符，生當事邊时。","借名游俠窟，結客幽幷兒。","往来长楸间，能带雙鞬驰。","崩腾天寶末，塵暗燕南垂。","爟火入咸陽，詔徵神武師。","是时占軍幕，插羽揚金羈。","万夫列轅门，观射中戟支。","誓當雪国讐，親愛從此辞。","中宵倚长劒，起視蚩尤旗。","介马晨蕭蕭，陣云竟天涯。","陰风獵白草，旗槊光參差。","勇氣貫中腸，視身忽如遺。","生擒白马將，虜騎不敢追。","貴臣上戰功，名姓隨意移。","終歲肌骨苦，他人印纍纍。","謁者既清宮，諸侯各罷戲。","上將賜甲第，门戟不可窺。","眥血下沾襟，天高问無期。","却尋故乡路，孤影空相隨。","行逢里中旧，撲遬昔所嗤。","一言合侯王，腰佩黄金龟。","问我何自苦，可怜真數奇。","遲回顧徒御，得色懸雙眉。","翻然悟世途，撫己昧所宜。","田园已蕪沒，流浪江海湄。","鷙禽毛翮摧，不见翔云姿。","衰容蔽逸氣，孑孑無人知。","寂寞草玄徒，长吟下书帷。","爲君發哀韻，若扣瑤林枝。","有客識其真，潺湲涕交頤。","饮爾一杯酒，陶然足自怡。"]', '诗', 'shi', '', NULL, '和董庶中古散調詞贈尹果毅 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf28f023-f007-48ac-8e71-96c1cce3bf53', '望衡山', '望衡山', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["東南倚蓋卑，維嶽資柱石。","前當祝融居，上拂朱鳥翮。","青冥結精氣，磅礴宣地脉。","還聞膚寸陰，能致彌天澤。"]', '["东南倚蓋卑，維嶽資柱石。","前當祝融居，上拂朱鸟翮。","青冥結精氣，磅礴宣地脉。","還闻膚寸陰，能致彌天澤。"]', '诗', 'shi', '', NULL, '望衡山 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c57a579-0494-41cf-a174-6472ac4f2e8e', '遊桃源一百韻', '游桃源一百韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["沅江清悠悠，連山鬱岑寂。","回流抱絕巘，皎鏡含虛碧。","昏旦遞明媚，煙嵐分委積。","香蔓垂綠潭，暴龍照孤磧。","淵明著前志，子驥思遠蹠。","寂寂無何鄉，密爾天地隔。","金行太元歲，漁者偶探賾。","尋花得幽踪，窺洞穿闇隙。","依微聞雞犬，豁達值阡陌。","居人互將迎，笑語如平昔。","廣樂雖交奏，海禽心不懌。","揮手一來歸，故溪無處覓。","綿綿五百載，市朝幾遷革。","有路在壺中，無人知地脉。","皇家感至道，聖祚自天錫。","金闕傳本枝，玉函留寶曆。","禁山開秘宇，復戶潔靈宅。","蘂檢香氛氳，醮壇煙冪冪。","我來塵外躅，瑩若朝星析。","崖轉對翠屏，水窮留畫鷁。","三休俯喬木，千級扳峭壁。","旭日聞撞鐘，綵雲迎躡屐。","遂登最高頂，縱目還楚澤。","平湖見草青，遠岸連霞赤。","幽尋如夢想，綿思屬空闃。","夤緣且忘疲，耽玩近成癖。","清猨伺曉發，瑤草凌寒坼。","祥禽舞葱蘢，珠樹搖玓瓅。","羽人顧我笑，勸我稅歸軛。","霓裳何飄颻，童顏潔白皙。","重巖是藩屏，馴鹿受羈靮。","樓居彌清霄，蘿蔦成翠帟。","仙翁遺竹杖，王母留桃核。","姹女飛丹砂，青童護金液。","寶氣浮鼎耳，神光生劒脊。","虛無天樂來，僁窣鬼兵役。","丹丘肅朝禮，玉札工紬繹。","枕中淮南方，牀下阜鄉舄。","明燈坐遙夜，幽籟聽淅瀝。","因話近世仙，聳然心神惕。","乃言瞿氏子，骨狀非凡格。","往事黃先生，羣兒多侮劇。","謷然不屑意，元氣貯肝膈。","往往游不歸，洞中觀博弈。","言高未易信，猶復加訶責。","一旦前致辭，自云仙期迫。","言師有道骨，前事常被謫。","如今三山上，名字在真籍。","悠然謝主人，後歲當來覿。","言畢依庭樹，如煙去無跡。","觀者皆失次，驚追紛絡繹。","日暮山徑窮，松風自蕭槭。","適逢脩蛇見，瞋目光激射。","如嚴三清居，不使恣搜索。","唯餘步綱勢，八趾在沙礫。","至今東北隅，表以壇上石。","列仙徒有名，世人非目擊。","如何庭廡際，白日振飛翮。","洞天豈幽遠，得道如咫尺。","一氣無死生，三光自遷易。","因思人間世，前路何狹窄。","瞥然此生中，善祝期滿百。","大方播羣類，秀氣肖翕闢。","性靜本同和，物牽成阻厄。","是非鬬方寸，葷血昏精魄。","遂令多夭傷，猶喜見斑白。","喧喧車馬馳，苒苒桑榆夕。","共安緹繡榮，不悟泥途適。","紛吾本孤賤，世業在逢掖。","九流宗指歸，百氏旁捃摭。","公卿偶慰薦，鄉曲繆推擇。","居安白社貧，至傲玄纁辟。","功名希自取，簪組俟揚歷。","書府蚤懷鉛，射宮曾發的。","起草香生帳，坐曹烏集柏。","賜燕聆簫韶，侍祠閱琮璧。","嘗聞履忠信，可以行蠻貊。","自述希古心，忘恃干時畫。","巧言忽成錦，苦志徒食蘗。","平地生峰巒，深心有矛戟。","層波一震盪，弱植忽淪溺。","北渚弔靈均，長岑思亭伯。","禍來昧幾兆，事去空歎息。","塵累與時深，流年隨漏滴。","才能疑木鴈，報施迷夷跖。","楚奏縶鍾儀，商歌勞甯戚。","稟生非懸解，對鏡方感激。","自從嬰網羅，每事問龜策。","王正降雷雨，環玦賜遷斥。","倘伏夷平人，誓將依羽客。","買山構精舍，領徒開講席。","冀無身外憂，自有閑中益。","道芽期日就，塵慮乃冰釋。","且欲遺姓名，安能慕竹帛。","長生尚學致，一溉豈虛擲。","芝朮資糇糧，煙霞拂巾幘。","黃石履看墮，洪崖肩可拍。","聊復嗟蜉蝣，何煩哀虺蜴。","青囊既深味，瓊葩亦屢摘。","縱無西山資，猶免長戚戚。"]', '["沅江清悠悠，連山鬱岑寂。","回流抱絕巘，皎镜含虛碧。","昏旦遞明媚，煙嵐分委積。","香蔓垂綠潭，暴龙照孤磧。","淵明著前志，子驥思远蹠。","寂寂無何乡，密爾天地隔。","金行太元歲，漁者偶探賾。","尋花得幽踪，窺洞穿闇隙。","依微闻雞犬，豁達值阡陌。","居人互將迎，笑語如平昔。","廣乐雖交奏，海禽心不懌。","揮手一来归，故溪無处覓。","綿綿五百載，市朝幾遷革。","有路在壺中，無人知地脉。","皇家感至道，聖祚自天錫。","金闕傳本枝，玉函留寶曆。","禁山开秘宇，复戶潔靈宅。","蘂檢香氛氳，醮壇煙冪冪。","我来塵外躅，瑩若朝星析。","崖轉对翠屏，水窮留畫鷁。","三休俯喬木，千級扳峭壁。","旭日闻撞鐘，綵云迎躡屐。","遂登最高頂，縱目還楚澤。","平湖见草青，远岸連霞赤。","幽尋如梦想，綿思屬空闃。","夤緣且忘疲，耽玩近成癖。","清猨伺晓發，瑤草凌寒坼。","祥禽舞葱蘢，珠樹搖玓瓅。","羽人顧我笑，勸我稅归軛。","霓裳何飄颻，童顏潔白皙。","重巖是藩屏，馴鹿受羈靮。","楼居彌清霄，蘿蔦成翠帟。","仙翁遺竹杖，王母留桃核。","姹女飞丹砂，青童護金液。","寶氣浮鼎耳，神光生劒脊。","虛無天乐来，僁窣鬼兵役。","丹丘肅朝禮，玉札工紬繹。","枕中淮南方，牀下阜乡舄。","明灯坐遙夜，幽籟听淅瀝。","因話近世仙，聳然心神惕。","乃言瞿氏子，骨狀非凡格。","往事黄先生，羣兒多侮劇。","謷然不屑意，元氣貯肝膈。","往往游不归，洞中观博弈。","言高未易信，猶复加訶責。","一旦前致辞，自云仙期迫。","言師有道骨，前事常被謫。","如今三山上，名字在真籍。","悠然謝主人，後歲當来覿。","言畢依庭樹，如煙去無跡。","观者皆失次，驚追紛絡繹。","日暮山徑窮，松风自蕭槭。","適逢脩蛇见，瞋目光激射。","如嚴三清居，不使恣搜索。","唯餘步綱勢，八趾在沙礫。","至今东北隅，表以壇上石。","列仙徒有名，世人非目擊。","如何庭廡際，白日振飞翮。","洞天豈幽远，得道如咫尺。","一氣無死生，三光自遷易。","因思人间世，前路何狹窄。","瞥然此生中，善祝期满百。","大方播羣類，秀氣肖翕闢。","性静本同和，物牽成阻厄。","是非鬬方寸，葷血昏精魄。","遂令多夭傷，猶喜见斑白。","喧喧车马驰，苒苒桑榆夕。","共安緹繡榮，不悟泥途適。","紛吾本孤賤，世業在逢掖。","九流宗指归，百氏旁捃摭。","公卿偶慰薦，乡曲繆推擇。","居安白社貧，至傲玄纁辟。","功名希自取，簪組俟揚歷。","书府蚤懷鉛，射宮曾發的。","起草香生帳，坐曹烏集柏。","賜燕聆簫韶，侍祠閱琮璧。","嘗闻履忠信，可以行蠻貊。","自述希古心，忘恃干时畫。","巧言忽成錦，苦志徒食蘗。","平地生峰巒，深心有矛戟。","層波一震盪，弱植忽淪溺。","北渚弔靈均，长岑思亭伯。","禍来昧幾兆，事去空歎息。","塵累與时深，流年隨漏滴。","才能疑木鴈，報施迷夷跖。","楚奏縶鍾儀，商歌勞甯戚。","稟生非懸解，对镜方感激。","自從嬰網羅，每事问龟策。","王正降雷雨，环玦賜遷斥。","倘伏夷平人，誓將依羽客。","買山構精舍，領徒开講席。","冀無身外憂，自有闲中益。","道芽期日就，塵慮乃冰釋。","且欲遺姓名，安能慕竹帛。","长生尚学致，一溉豈虛擲。","芝朮資糇糧，煙霞拂巾幘。","黄石履看墮，洪崖肩可拍。","聊复嗟蜉蝣，何煩哀虺蜴。","青囊既深味，瓊葩亦屢摘。","縱無西山資，猶免长戚戚。"]', '诗', 'shi', '', NULL, '遊桃源一百韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('099d1af5-6cb8-4e04-b199-2c6a7b4fca72', '客有爲余話登天壇遇雨之狀因以賦之', '客有爲余話登天壇遇雨之狀因以賦之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["清晨登天壇，半路逢陰晦。","疾行穿雨過，却立視雲背。","白日照其上，風雷走於內。","滉瀁雪海翻，槎牙玉山碎。","蛟龍露鬐鬣，神鬼含變態。","萬狀互生滅，百音以繁會。","俯觀羣動靜，始覺天宇大。","山頂自晶明，人間已霶霈。","豁然重昏歛，渙若春冰潰。","反照入松門，瀑流飛縞帶。","遙光泛物色，餘韻吟天籟。","洞府撞仙鐘，村墟起夕靄。","却見山下侶，已如迷世代。","問我何處來，我來雲雨外。"]', '["清晨登天壇，半路逢陰晦。","疾行穿雨過，却立視云背。","白日照其上，风雷走於內。","滉瀁雪海翻，槎牙玉山碎。","蛟龙露鬐鬣，神鬼含变態。","万狀互生滅，百音以繁會。","俯观羣动静，始覺天宇大。","山頂自晶明，人间已霶霈。","豁然重昏歛，渙若春冰潰。","反照入松门，瀑流飞縞带。","遙光泛物色，餘韻吟天籟。","洞府撞仙鐘，村墟起夕靄。","却见山下侶，已如迷世代。","问我何处来，我来云雨外。"]', '诗', 'shi', '', NULL, '客有爲余話登天壇遇雨之狀因以賦之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2c99e3f-9661-4fff-a6fd-28a591ff7e68', '秋江早發', '秋江早發', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["輕陰迎曉日，霞霽秋江明。","草樹含遠思，襟懷有餘清。","凝睇萬象起，郎吟孤憤平。","渚鴻未矯翼，而我已遐征。","因思市朝人，方聽晨雞鳴。","昏昏戀衾枕，安見元氣英。","納爽耳目變，玩奇筋骨輕。","滄洲有奇趣，浩然吾將行。"]', '["轻陰迎晓日，霞霽秋江明。","草樹含远思，襟懷有餘清。","凝睇万象起，郎吟孤憤平。","渚鴻未矯翼，而我已遐征。","因思市朝人，方听晨雞鳴。","昏昏戀衾枕，安见元氣英。","納爽耳目变，玩奇筋骨轻。","滄洲有奇趣，浩然吾將行。"]', '诗', 'shi', '', NULL, '秋江早發 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da9d7556-8296-4658-8f9f-d05ed47f75b9', '有僧言羅浮事因爲詩以寫之', '有僧言羅浮事因爲诗以寫之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["君言羅浮上，容易見九垠。","漸高元氣壯，洶湧來翼身。","夜宿最高峰，瞻望浩無鄰。","海黑天宇曠，星辰來逼人。","是時當朏魄，陰物恣騰振。","日光吐鯨背，劒影開龍鱗。","倏若萬馬馳，旌旗聳奫淪。","又如廣樂奏，金石含悲辛。","疑其有巨靈，怪物盡來賓。","陰陽迭用事，乃俾夜作晨。","咿喔天雞鳴，扶桑色昕昕。","赤波千萬里，湧出黃金輪。","下視生物息，霏如隙中塵。","醯雞仰甕口，亦謂雲漢津。","世人信耳目，方寸度大鈞。","安知視聽外，怪愕不可陳。","悠悠想大方，此乃桮水濱。","知小天地大，安能識其真。"]', '["君言羅浮上，容易见九垠。","漸高元氣壯，洶湧来翼身。","夜宿最高峰，瞻望浩無鄰。","海黑天宇曠，星辰来逼人。","是时當朏魄，陰物恣腾振。","日光吐鯨背，劒影开龙鱗。","倏若万马驰，旌旗聳奫淪。","又如廣乐奏，金石含悲辛。","疑其有巨靈，怪物尽来賓。","陰陽迭用事，乃俾夜作晨。","咿喔天雞鳴，扶桑色昕昕。","赤波千万里，湧出黄金輪。","下視生物息，霏如隙中塵。","醯雞仰甕口，亦謂云漢津。","世人信耳目，方寸度大鈞。","安知視听外，怪愕不可陳。","悠悠想大方，此乃桮水濱。","知小天地大，安能識其真。"]', '诗', 'shi', '', NULL, '有僧言羅浮事因爲詩以寫之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fb04b5e-76d3-4734-92a3-64194ad4f47e', '裴祭酒尚書見示春歸城南青松塢別墅寄王左丞高侍郎之什命同作', '裴祭酒尚书见示春归城南青松塢別墅寄王左丞高侍郎之什命同作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["蚤宦閱人事，晚懷生道機。","時從學省出，獨望郊園歸。","野彴度春水，山花映巖扉。","石頭解金章，林下步綠薇。","青松鬱成塢，脩竹盈尺圍。","吟風起天籟，蔽日無炎威。","危徑盤羊腸，連甍聳翬飛。","幽谷響樵斧，澄潭環釣磯。","因高見帝城，冠蓋揚光輝。","白雲難持寄，清韻投所希。","二公如長離，比翼翔太微。","含情謝林壑，酬贈駢珠璣。","顧予久郎潛，愁寂對芳菲。","一聞丘中趣，再撫黃金徽。"]', '["蚤宦閱人事，晚懷生道機。","时從学省出，独望郊园归。","野彴度春水，山花映巖扉。","石头解金章，林下步綠薇。","青松鬱成塢，脩竹盈尺圍。","吟风起天籟，蔽日無炎威。","危徑盤羊腸，連甍聳翬飞。","幽谷响樵斧，澄潭环釣磯。","因高见帝城，冠蓋揚光輝。","白云难持寄，清韻投所希。","二公如长離，比翼翔太微。","含情謝林壑，酬贈駢珠璣。","顧予久郎潛，愁寂对芳菲。","一闻丘中趣，再撫黄金徽。"]', '诗', 'shi', '', NULL, '裴祭酒尚書見示春歸城南青松塢別墅寄王左丞高侍郎之什命同作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('401979bb-d903-4216-a5f4-a6ad30066367', '和河南裴尹侍郎宿齋天平寺詣九龍祠祈雨二十韻', '和河南裴尹侍郎宿斋天平寺詣九龙祠祈雨二十韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["有事九龍廟，潔齋梵王祠。","玉簫何時絕，碧樹空涼颸。","吏散埃𡏖息，月高庭宇宜。","重城肅穆閉，澗水潺湲時。","人希夜復閑，慮靜境亦隨。","緬懷斷鰲足，凝想乘鸞姿。","朱明盛農節，膏澤方愆期。","瞻言五靈瑞，能救百穀萎。","咿喔晨雞鳴，闌干斗柄垂。","修容謁神像，注意陳正詞。","驚飆起泓泉，若調雷雨師。","黑煙聳鱗甲，灑液如棼絲。","豐隆震天衢，列缺揮火旗。","炎空忽淒緊，高霤懸綆縻。","生物已霶霈，濕雲稍離披。","丹霞啓南陸，白水含東菑。","熙熙飛走適，藹藹草樹滋。","浮光動宮觀，遠思盈川坻。","吳公敏於政，謝守工爲詩。","商山有病客，言賀舒龐眉。"]', '["有事九龙廟，潔斋梵王祠。","玉簫何时絕，碧樹空涼颸。","吏散埃𡏖息，月高庭宇宜。","重城肅穆閉，澗水潺湲时。","人希夜复闲，慮静境亦隨。","緬懷斷鰲足，凝想乘鸾姿。","朱明盛農節，膏澤方愆期。","瞻言五靈瑞，能救百穀萎。","咿喔晨雞鳴，闌干斗柄垂。","修容謁神像，注意陳正词。","驚飆起泓泉，若調雷雨師。","黑煙聳鱗甲，灑液如棼絲。","豐隆震天衢，列缺揮火旗。","炎空忽淒緊，高霤懸綆縻。","生物已霶霈，濕云稍離披。","丹霞啓南陸，白水含东菑。","熙熙飞走適，藹藹草樹滋。","浮光动宮观，远思盈川坻。","吳公敏於政，謝守工爲诗。","商山有病客，言賀舒龐眉。"]', '诗', 'shi', '', NULL, '和河南裴尹侍郎宿齋天平寺詣九龍祠祈雨二十韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26f8cc2d-235a-4544-a87c-c8caee8665f8', '冬夜宴河中李相公中堂命箏歌送酒', '冬夜宴河中李相公中堂命箏歌送酒', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["朗朗鵾雞弦，華堂夜多思。","簾外雪已深，座中人半醉。","翠蛾發清響，曲盡有餘意。","酌我莫憂狂，老來無逸氣。"]', '["朗朗鵾雞弦，华堂夜多思。","簾外雪已深，座中人半醉。","翠蛾發清响，曲尽有餘意。","酌我莫憂狂，老来無逸氣。"]', '诗', 'shi', '', NULL, '冬夜宴河中李相公中堂命箏歌送酒 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('310818b1-54a0-4da1-9d20-bd1e3264d10a', '重至衡陽傷柳儀曹', '重至衡陽傷柳儀曹', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["憶昨與故人，湘江岸頭別。","我馬映林嘶，君帆轉山滅。","馬嘶循古道，帆滅如流電。","千里江蘺春，故人今不見。"]', '["憶昨與故人，湘江岸头別。","我马映林嘶，君帆轉山滅。","马嘶循古道，帆滅如流電。","千里江蘺春，故人今不见。"]', '诗', 'shi', '', NULL, '重至衡陽傷柳儀曹 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c172a642-3aa3-4760-a26a-0c85ad9d5a0e', '謫居悼往二首 一', '謫居悼往二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["邑邑何邑邑，長沙地卑濕。","樓上見春多，花前恨風急。","猿愁腸斷呌，鶴病翹趾立。","牛衣獨自眠，誰哀仲卿泣。"]', '["邑邑何邑邑，长沙地卑濕。","楼上见春多，花前恨风急。","猿愁腸斷呌，鹤病翹趾立。","牛衣独自眠，誰哀仲卿泣。"]', '诗', 'shi', '', NULL, '謫居悼往二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e005f7b5-b3ad-45de-90a8-4b78085e47cf', '謫居悼往二首 二', '謫居悼往二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鬱鬱何鬱鬱，長安遠如日。","終日念鄉關，燕來鴻復還。","潘岳歲寒思，屈平顦顇顏。","殷勤望歸路，無雨即登山。"]', '["鬱鬱何鬱鬱，长安远如日。","終日念乡关，燕来鴻复還。","潘岳歲寒思，屈平顦顇顏。","殷勤望归路，無雨即登山。"]', '诗', 'shi', '', NULL, '謫居悼往二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f22f1d6b-e5b0-402e-8c3a-16555badf9b7', '有獺吟', '有獺吟', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["有獺得嘉魚，自謂天見憐。","先祭不敢食，捧鱗望青玄。","人立寒沙上，心專眼悁悁。","漁翁以爲妖，舉塊投其咽。","呼兒貫魚歸，與獺同烹煎。","關關黃金鶚，大[翅]搖江煙。","下見盈尋魚，投身擘洪連。","攫拏隱鱗去，哺雛林岳巔。","鴟烏欲伺隙，遙噪莫敢前。","長居青雲路，彈射無由緣。","何地無江湖，何水無鮪鱣。","天意不宰割，菲祭徒虔虔。","空餘知禮重，載在淹中篇。"]', '["有獺得嘉鱼，自謂天见怜。","先祭不敢食，捧鱗望青玄。","人立寒沙上，心專眼悁悁。","漁翁以爲妖，舉塊投其咽。","呼兒貫鱼归，與獺同烹煎。","关关黄金鶚，大[翅]搖江煙。","下见盈尋鱼，投身擘洪連。","攫拏隐鱗去，哺雛林岳巔。","鴟烏欲伺隙，遙噪莫敢前。","长居青云路，彈射無由緣。","何地無江湖，何水無鮪鱣。","天意不宰割，菲祭徒虔虔。","空餘知禮重，載在淹中篇。"]', '诗', 'shi', '', NULL, '有獺吟 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71c65693-2472-41bb-ab62-dc408ae1de65', '白太守行', '白太守行', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["聞有白太守，拋官歸舊谿。","蘇州十萬戶，盡作嬰兒啼。","太守駐行舟，閶門草萋萋。","揮袂謝啼者，依然兩眉低。","朱戶非不崇，我心如重狴。","華池非不清，意在寥廓栖。","夸者竊所怪，賢者默思齊。","我爲太守行，題在隱起珪。"]', '["闻有白太守，拋官归旧谿。","蘇州十万戶，尽作嬰兒啼。","太守駐行舟，閶门草萋萋。","揮袂謝啼者，依然兩眉低。","朱戶非不崇，我心如重狴。","华池非不清，意在寥廓栖。","夸者竊所怪，賢者默思齊。","我爲太守行，題在隐起珪。"]', '诗', 'shi', '', NULL, '白太守行 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5fc05cc-5bc0-4a5c-9008-687fe9b413c7', '樂天寄洛下新詩兼喜微之欲到因以抒懷也', '乐天寄洛下新诗兼喜微之欲到因以抒懷也', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["松間風未起，萬葉不自吟。","池上月未來，清輝同夕陰。","宮徵不獨運，塤篪自相尋。","一從別樂天，詩思日已沈。","吟君洛中作，精絕百鍊金。","乃知孤鶴情，月露爲知音。","微之從東來，威鳳鳴歸林。","羨君先相見，一豁平生心。"]', '["松间风未起，万葉不自吟。","池上月未来，清輝同夕陰。","宮徵不独運，塤篪自相尋。","一從別乐天，诗思日已沈。","吟君洛中作，精絕百鍊金。","乃知孤鹤情，月露爲知音。","微之從东来，威鳳鳴归林。","羨君先相见，一豁平生心。"]', '诗', 'shi', '', NULL, '樂天寄洛下新詩兼喜微之欲到因以抒懷也 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3560e744-2c02-4f0c-b419-d665be2c9eff', '月夜憶樂天兼寄微之', '月夜憶乐天兼寄微之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["今宵帝城月，一望雪相似。","遙想洛陽城，清光正如此。","知君當此夕，亦望鏡湖水。","展轉相憶心，月明千萬里。"]', '["今宵帝城月，一望雪相似。","遙想洛陽城，清光正如此。","知君當此夕，亦望镜湖水。","展轉相憶心，月明千万里。"]', '诗', 'shi', '', NULL, '月夜憶樂天兼寄微之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea84ab89-235d-47bb-a079-054a4155ed71', '早夏郡中書事', '早夏郡中书事', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["水禽渡殘月，飛雨灑高城。","華堂對嘉樹，簾廡含曉清。","拂鏡整危冠，振衣步前楹。","將吏儼成列，簿書紛來縈。","言下辨曲直，筆端破交爭。","虛懷詢病苦，懷律操剽輕。","閽吏告無事，歸來解簪纓。","高簾覆朱閣，忽爾聞調笙。"]', '["水禽渡殘月，飞雨灑高城。","华堂对嘉樹，簾廡含晓清。","拂镜整危冠，振衣步前楹。","將吏儼成列，簿书紛来縈。","言下辨曲直，笔端破交爭。","虛懷詢病苦，懷律操剽轻。","閽吏告無事，归来解簪纓。","高簾覆朱閣，忽爾闻調笙。"]', '诗', 'shi', '', NULL, '早夏郡中書事 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef112fc7-86a9-4f07-a14c-495af494e2a8', '詶樂天七月一日夜即事見寄', '詶乐天七月一日夜即事见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["夜樹風韻清，天河雲彩輕。","故苑多露草，隔城聞鶴鳴。","搖落從此始，別離含遠情。","聞君當是夕，倚瑟吟商聲。","外物豈不足，中懷向誰傾。","秋來念歸去，同聽嵩陽笙。"]', '["夜樹风韻清，天河云彩轻。","故苑多露草，隔城闻鹤鳴。","搖落從此始，別離含远情。","闻君當是夕，倚瑟吟商声。","外物豈不足，中懷向誰傾。","秋来念归去，同听嵩陽笙。"]', '诗', 'shi', '', NULL, '詶樂天七月一日夜即事見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3c3df89-405e-427d-8e67-d2c854c9bb9e', '令狐相公見示贈竹二十韻仍命繼和', '令狐相公见示贈竹二十韻仍命繼和', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["高人必愛竹，寄興良有以。","峻節可臨戎，虛心宜待士。","衆芳信妍媚，威鳳難棲止。","遂於鼙鼓間，移植東南美。","封以梁國土，澆之浚泉水。","得地色不移，凌空勢方起。","新青排故葉，餘粉籠疎理。","猶復隔牆藩，何因出塵滓。","茲辰去前蔽，永日勞瞪視。","槭槭林已成，熒熒玉相似。","規摹起心匠，洗滌在頤指。","曲直既瞭然，孤高何卓爾。","垂梢覆內屏，迸笋侵前戺。","妓席拂雲鬢，賓階蔭珠履。","抱琴恣閑翫，執卷堪斜倚。","露下懸明璫，風來韻清徵。","堅貞貫四候，標格殊百卉。","歲晚當自知，繁華豈云比。","古詩無贈竹，高唱從此始。","一聽清瑤音，崢然長在耳。"]', '["高人必愛竹，寄兴良有以。","峻節可臨戎，虛心宜待士。","衆芳信妍媚，威鳳难棲止。","遂於鼙鼓间，移植东南美。","封以梁国土，澆之浚泉水。","得地色不移，凌空勢方起。","新青排故葉，餘粉籠疎理。","猶复隔牆藩，何因出塵滓。","茲辰去前蔽，永日勞瞪視。","槭槭林已成，熒熒玉相似。","規摹起心匠，洗滌在頤指。","曲直既瞭然，孤高何卓爾。","垂梢覆內屏，迸笋侵前戺。","妓席拂云鬢，賓階蔭珠履。","抱琴恣闲翫，執卷堪斜倚。","露下懸明璫，风来韻清徵。","堅貞貫四候，標格殊百卉。","歲晚當自知，繁华豈云比。","古诗無贈竹，高唱從此始。","一听清瑤音，崢然长在耳。"]', '诗', 'shi', '', NULL, '令狐相公見示贈竹二十韻仍命繼和 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f93b8d3-e1c7-4de4-a55b-c203873beb6f', '和令狐相公晚泛漢江書懷寄洋州崔侍郎閬州高舍人二曹長', '和令狐相公晚泛漢江书懷寄洋州崔侍郎閬州高舍人二曹长', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["雨過遠山出，江澄暮霞生。","因浮濟川舟，遂作適野行。","郊樹映緹騎，水禽避紅旌。","田夫捐畚鍤，織婦窺柴荆。","古岸夏花發，遙林晚蟬清。","沿洄方翫境，鼓角已登城。","部內有良牧，望中寄深情。","臨觴念佳期，泛瑟動離聲。","寂寞一病士，夙昔接羣英。","多謝謫仙侶，幾時還玉京。"]', '["雨過远山出，江澄暮霞生。","因浮濟川舟，遂作適野行。","郊樹映緹騎，水禽避紅旌。","田夫捐畚鍤，织婦窺柴荆。","古岸夏花發，遙林晚蟬清。","沿洄方翫境，鼓角已登城。","部內有良牧，望中寄深情。","臨觴念佳期，泛瑟动離声。","寂寞一病士，夙昔接羣英。","多謝謫仙侶，幾时還玉京。"]', '诗', 'shi', '', NULL, '和令狐相公晚泛漢江書懷寄洋州崔侍郎閬州高舍人二曹長 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2bbf79c-32ad-47f9-83a8-c5fdb3c7d3c7', '和樂天洛城春齊梁體八韻', '和乐天洛城春齊梁體八韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["帝城宜春入，遊人喜意長。","草生季倫谷，花出莫愁坊。","斷雲發山色，輕風漾水光。","樓前戲馬地，樹下鬬雞場。","白頭自爲侶，綠酒亦滿觴。","潘園觀種植，謝墅閱池塘。","至閑似隱逸，過老不悲傷。","相問焉功德，銀黃遊故鄉。"]', '["帝城宜春入，游人喜意长。","草生季倫谷，花出莫愁坊。","斷云發山色，轻风漾水光。","楼前戲马地，樹下鬬雞場。","白头自爲侶，綠酒亦满觴。","潘园观種植，謝墅閱池塘。","至闲似隐逸，過老不悲傷。","相问焉功德，銀黄游故乡。"]', '诗', 'shi', '', NULL, '和樂天洛城春齊梁體八韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c570244-3e71-484b-86a7-d6ed74378cc3', '洛中早春贈樂天', '洛中早春贈乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["漠漠復靄靄，半晴將半陰。","春來自何處，無迹日以深。","韶嫩冰後木，輕盈煙際林。","藤生欲有託，柳弱不自任。","花意已含蓄，鳥言尚沈吟。","期君當此時，與我恣追尋。","翻愁爛熳後，春暮却傷心。"]', '["漠漠复靄靄，半晴將半陰。","春来自何处，無迹日以深。","韶嫩冰後木，轻盈煙際林。","藤生欲有託，柳弱不自任。","花意已含蓄，鸟言尚沈吟。","期君當此时，與我恣追尋。","翻愁爛熳後，春暮却傷心。"]', '诗', 'shi', '', NULL, '洛中早春贈樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5753f4b7-f085-4a30-8698-f3ae049f655d', '和樂天讌李周美中丞宅池上賞櫻桃花', '和乐天讌李周美中丞宅池上賞櫻桃花', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["櫻桃千萬枝，照耀如雪天。","王孫讌其下，隔水疑神仙。","宿露發清香，初陽動暄妍。","妖姬滿髻插，酒客折枝傳。","同此賞芳月，幾人有華筵。","杯行勿遽辭，好醉逸三年。"]', '["櫻桃千万枝，照耀如雪天。","王孫讌其下，隔水疑神仙。","宿露發清香，初陽动暄妍。","妖姬满髻插，酒客折枝傳。","同此賞芳月，幾人有华筵。","杯行勿遽辞，好醉逸三年。"]', '诗', 'shi', '', NULL, '和樂天讌李周美中丞宅池上賞櫻桃花 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afe72329-d8ba-4812-aed2-0cac0af992ef', '詶樂天聞新蟬見贈', '詶乐天闻新蟬见贈', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["碧樹鳴蟬後，煙雲改容光。","瑟然引秋氣，芳草日夜黃。","夾道喧古槐，臨池思垂楊。","離人下憶淚，志士激剛腸。","昔聞阻山川，今聽同匡牀。","人情便所遇，音韻豈殊常。","因之比笙竽，送我遊醉鄉。"]', '["碧樹鳴蟬後，煙云改容光。","瑟然引秋氣，芳草日夜黄。","夾道喧古槐，臨池思垂楊。","離人下憶泪，志士激剛腸。","昔闻阻山川，今听同匡牀。","人情便所遇，音韻豈殊常。","因之比笙竽，送我游醉乡。"]', '诗', 'shi', '', NULL, '詶樂天聞新蟬見贈 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42a626db-68ab-4a41-8e85-f4d9f6cf7d94', '和樂天秋涼閑臥', '和乐天秋涼闲臥', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["暑退人體輕，雨餘天色改。","荷珠貫索斷，竹粉殘粧在。","高僧掃室請，逸客登樓待。","槐柳漸蕭疎，閑門少光彩。"]', '["暑退人體轻，雨餘天色改。","荷珠貫索斷，竹粉殘粧在。","高僧掃室請，逸客登楼待。","槐柳漸蕭疎，闲门少光彩。"]', '诗', 'shi', '', NULL, '和樂天秋涼閑臥 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d90bc824-730a-4fb6-b910-28f4ad514141', '詶樂天詠老見示', '詶乐天詠老见示', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["人誰不願老，老去有誰憐。","身瘦帶頻減，髪稀冠自偏。","廢書緣惜眼，多炙爲隨年。","經事還諳事，閱人如閱川。","細思皆幸矣，下此便翛然。","莫道桑榆晚，微霞尚滿天。"]', '["人誰不願老，老去有誰怜。","身瘦带頻減，髪稀冠自偏。","廢书緣惜眼，多炙爲隨年。","經事還諳事，閱人如閱川。","細思皆幸矣，下此便翛然。","莫道桑榆晚，微霞尚满天。"]', '诗', 'shi', '', NULL, '詶樂天詠老見示 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e605a143-612c-4801-b1be-88601c88c648', '歲夜詠懷', '歲夜詠懷', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["彌年不得意，新歲又如何。","念昔同遊者，而今有幾多。","以閑爲自在，將壽補蹉跎。","春色無情故，幽居亦見過。"]', '["彌年不得意，新歲又如何。","念昔同游者，而今有幾多。","以闲爲自在，將壽補蹉跎。","春色無情故，幽居亦见過。"]', '诗', 'shi', '', NULL, '歲夜詠懷 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e29869e-9dda-4b25-a5f4-70496a04ac9e', '詶牛相公獨飲偶醉寓言見示', '詶牛相公独饮偶醉寓言见示', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["宮漏夜丁丁，千門閉霜月。","華堂列紅燭，絲管靜中發。","歌眉低有思，舞體輕無骨。","主人啓酡顏，酣暢浹肌髪。","猶思城外客，阡陌不可越。","春意日夕深，此歡無斷絕。"]', '["宮漏夜丁丁，千门閉霜月。","华堂列紅燭，絲管静中發。","歌眉低有思，舞體轻無骨。","主人啓酡顏，酣暢浹肌髪。","猶思城外客，阡陌不可越。","春意日夕深，此歡無斷絕。"]', '诗', 'shi', '', NULL, '詶牛相公獨飲偶醉寓言見示 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b334891f-03ed-4411-b8a5-206cfe5b60fa', '萋兮吟', '萋兮吟', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["天涯浮雲生，爭蔽日月光。","窮巷秋風起，先摧蘭蕙芳。","萬貨列旗亭，恣心注明璫。","名高毀所集，言巧智難防。","勿謂行大道，斯須成太行。","莫吟萋兮什，徒使君子傷。"]', '["天涯浮云生，爭蔽日月光。","窮巷秋风起，先摧蘭蕙芳。","万貨列旗亭，恣心注明璫。","名高毀所集，言巧智难防。","勿謂行大道，斯須成太行。","莫吟萋兮什，徒使君子傷。"]', '诗', 'shi', '', NULL, '萋兮吟 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('796c677d-66cc-47e2-886a-8cacb408f3ac', '韓十八侍御見示岳陽樓別竇司直詩因令屬和重以自述故足成六十二韻', '韓十八侍御见示岳陽楼別竇司直诗因令屬和重以自述故足成六十二韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["楚望何蒼然，曾瀾七百里。","孤城寄遠目，一寫無窮已。","蕩漾浮天蓋，四環宣地理。","積漲在三秋，混成非一水。","冬遊見清淺，春望多洲沚。","雲錦遠沙明，風煙青草靡。","火星忽南見，月硤方東迤。","雪波西山來，隱若長城起。","獨專朝宗路，駛悍不可止。","支川讓其威，蓄縮至南委。","熊武走蠻落，瀟湘來奧鄙。","炎蒸動泉源，積潦搜山趾。","歸往無旦夕，包含通遠邇。","行當白露時，眇視秋光裏。","曙色未昭晰，露華遙斐舋。","浩爾神骨清，如觀混元始。","北風忽震盪，驚浪迷津涘。","怒激鼓鏗訇，蹙成山巋硊。","鵾鵬疑變化，罔象何恢詭。","噓吸寫樓臺，騰驤露鬐尾。","景移羣動息，波靜繁音弭。","明月出中央，青天絕纖滓。","素光淡無際，綠靜平如砥。","空影渡鵷鴻，秋聲思蘆葦。","鮫人弄機杼，貝闕駢紅紫。","珠蛤吐玲瓏，文鰩翔旖旎。","水鄉吳蜀限，地勢東南庳。","翼軫粲垂精，衡巫屹環峙。","名雄七澤藪，國辨三苗氏。","唐羿斷修虵，荆王憚青兕。","秦狩跡猶在，虞巡路從此。","軒后奏宮商，騷人詠蘭芷。","茅嶺潛相應，橘洲傍可指。","郭璞驗幽經，羅含著前紀。","觀津戚里族，按道侯家子。","聯袂登高樓，臨軒笑相視。","假守亦高臥，墨曹正垂耳。","契闊話涼溫，壺觴慰遷徙。","地偏山水秀，客重杯盤侈。","紅袖花欲然，銀燈晝相似。","興酣更抵掌，樂極同啓齒。","筆鋒不能休，藻思一何綺。","伊余負微尚，夙昔慙知己。","出入金馬門，交結青雲士。","襲芳踐蘭室，學古遊槐市。","策慕宋前軍，文師漢中壘。","陋容昧俯仰，孤志無依倚。","衛足不如葵，漏川空歎蟻。","幸逢萬物泰，獨處窮途否。","鍛翮重疊傷，兢魂再三褫。","蘧璦亦屢化，左丘猶有恥。","桃源訪仙宮，薜服祠山鬼。","故人南臺舊，一別如弦矢。","今朝會荆巒，斗酒相宴喜。","爲余出新什，笑抃隨伸紙。","曄若觀五色，歡然臻四美。","委曲風濤事，分明窮達旨。","洪韻發華鐘，淒音激清徵。","羊濬要共和，江淹多雜擬。","徒欲仰高山，焉能追逸軌。","湘洲路四達，巴陵城百雉。","何必顏光祿，留詩張內史。"]', '["楚望何蒼然，曾瀾七百里。","孤城寄远目，一寫無窮已。","蕩漾浮天蓋，四环宣地理。","積漲在三秋，混成非一水。","冬游见清淺，春望多洲沚。","云錦远沙明，风煙青草靡。","火星忽南见，月硤方东迤。","雪波西山来，隐若长城起。","独專朝宗路，駛悍不可止。","支川讓其威，蓄縮至南委。","熊武走蠻落，瀟湘来奧鄙。","炎蒸动泉源，積潦搜山趾。","归往無旦夕，包含通远邇。","行當白露时，眇視秋光裏。","曙色未昭晰，露华遙斐舋。","浩爾神骨清，如观混元始。","北风忽震盪，驚浪迷津涘。","怒激鼓鏗訇，蹙成山巋硊。","鵾鵬疑变化，罔象何恢詭。","噓吸寫楼台，腾驤露鬐尾。","景移羣动息，波静繁音弭。","明月出中央，青天絕纖滓。","素光淡無際，綠静平如砥。","空影渡鵷鴻，秋声思蘆葦。","鮫人弄機杼，貝闕駢紅紫。","珠蛤吐玲瓏，文鰩翔旖旎。","水乡吳蜀限，地勢东南庳。","翼軫粲垂精，衡巫屹环峙。","名雄七澤藪，国辨三苗氏。","唐羿斷修虵，荆王憚青兕。","秦狩跡猶在，虞巡路從此。","軒后奏宮商，騷人詠蘭芷。","茅嶺潛相應，橘洲傍可指。","郭璞驗幽經，羅含著前紀。","观津戚里族，按道侯家子。","聯袂登高楼，臨軒笑相視。","假守亦高臥，墨曹正垂耳。","契闊話涼溫，壺觴慰遷徙。","地偏山水秀，客重杯盤侈。","紅袖花欲然，銀灯晝相似。","兴酣更抵掌，乐極同啓齒。","笔鋒不能休，藻思一何綺。","伊余負微尚，夙昔慙知己。","出入金马门，交結青云士。","襲芳踐蘭室，学古游槐市。","策慕宋前軍，文師漢中壘。","陋容昧俯仰，孤志無依倚。","衛足不如葵，漏川空歎蟻。","幸逢万物泰，独处窮途否。","鍛翮重叠傷，兢魂再三褫。","蘧璦亦屢化，左丘猶有恥。","桃源訪仙宮，薜服祠山鬼。","故人南台旧，一別如弦矢。","今朝會荆巒，斗酒相宴喜。","爲余出新什，笑抃隨伸紙。","曄若观五色，歡然臻四美。","委曲风濤事，分明窮達旨。","洪韻發华鐘，淒音激清徵。","羊濬要共和，江淹多杂擬。","徒欲仰高山，焉能追逸軌。","湘洲路四達，巴陵城百雉。","何必顏光祿，留诗張內史。"]', '诗', 'shi', '', NULL, '韓十八侍御見示岳陽樓別竇司直詩因令屬和重以自述故足成六十二韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d658e8a-d266-4733-b8fe-acad101db2ad', '和郴州楊侍郎翫郡齋紫薇花十四韻', '和郴州楊侍郎翫郡斋紫薇花十四韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["幾年丹霄上，出入金華省。","暫別萬年枝，看花桂陽嶺。","南方足奇樹，公府成佳境。","綠陰交廣除，明豔透蕭屏。","雨餘人吏散，燕語簾櫳靜。","懿此含曉芳，翛然忘簿領。","紫茸垂組縷，金[縷]攢鋒頴。","露溽暗傳香，風輕徐就影。","苒弱多意思，從容占光景。","得地在侯家，移根近仙井。","開尊好凝睇，倚瑟仍回頸。","遊蜂駐綵冠，舞鶴迷煙頂。","興生紅藥後，愛與甘棠並。","不學夭桃姿，浮榮在俄頃。"]', '["幾年丹霄上，出入金华省。","暫別万年枝，看花桂陽嶺。","南方足奇樹，公府成佳境。","綠陰交廣除，明豔透蕭屏。","雨餘人吏散，燕語簾櫳静。","懿此含晓芳，翛然忘簿領。","紫茸垂組縷，金[縷]攢鋒頴。","露溽暗傳香，风轻徐就影。","苒弱多意思，從容占光景。","得地在侯家，移根近仙井。","开尊好凝睇，倚瑟仍回頸。","游蜂駐綵冠，舞鹤迷煙頂。","兴生紅藥後，愛與甘棠並。","不学夭桃姿，浮榮在俄頃。"]', '诗', 'shi', '', NULL, '和郴州楊侍郎翫郡齋紫薇花十四韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('116dc987-3391-4e82-a01e-c452ee2ee523', '春日寄楊八唐州二首 一', '春日寄楊八唐州二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["淮西春草長，淮水逶迤光。","燕入新村落，人耕舊戰場。","可憐行春守，立馬看斜桑。"]', '["淮西春草长，淮水逶迤光。","燕入新村落，人耕旧戰場。","可怜行春守，立马看斜桑。"]', '诗', 'shi', '', NULL, '春日寄楊八唐州二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0933c1a1-20b9-4f6a-b8df-20435c9f52ad', '春日寄楊八唐州二首 二', '春日寄楊八唐州二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["漠漠淮上春，莠苗生故壘。","梨花方城路，荻笋蕭陂水。","高齋有謫仙，坐嘯清風起。"]', '["漠漠淮上春，莠苗生故壘。","梨花方城路，荻笋蕭陂水。","高斋有謫仙，坐嘯清风起。"]', '诗', 'shi', '', NULL, '春日寄楊八唐州二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0444cedd-91f3-4952-9da9-b407658b5708', '詶馮十七舍人宿衛贈別五韻', '詶馮十七舍人宿衛贈別五韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["少年爲別日，隋宮楊柳陰。","白首相逢處，巴江煙浪深。","使星上三蜀，春雨霑衣襟。","王程促速意，夜語殷勤心。","却歸天上去，遺我雲間音。"]', '["少年爲別日，隋宮楊柳陰。","白首相逢处，巴江煙浪深。","使星上三蜀，春雨霑衣襟。","王程促速意，夜語殷勤心。","却归天上去，遺我云间音。"]', '诗', 'shi', '', NULL, '詶馮十七舍人宿衛贈別五韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbe87938-659f-4a87-b641-6fb3c0d5c956', '詶湖州崔郎中見寄', '詶湖州崔郎中见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["風箏吟秋空，不肖指爪聲。","高人靈府間，律呂伴咸英。","昔年與兄遊，文似馬長卿。","今來寄新詩，乃類陶淵明。","磨礱老益智，吟詠閑彌精。","豈非山水鄉，蕩漾神機清。","渚煙蕙蘭動，溪雨虹蜺生。","馮君虛上舍，待余乘興行。"]', '["风箏吟秋空，不肖指爪声。","高人靈府间，律呂伴咸英。","昔年與兄游，文似马长卿。","今来寄新诗，乃類陶淵明。","磨礱老益智，吟詠闲彌精。","豈非山水乡，蕩漾神機清。","渚煙蕙蘭动，溪雨虹蜺生。","馮君虛上舍，待余乘兴行。"]', '诗', 'shi', '', NULL, '詶湖州崔郎中見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32355410-2319-4233-a69d-32f7a397a1df', '秋日書懷寄河南王尹', '秋日书懷寄河南王尹', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["公府想無事，西池秋水清。","去年爲狎客，永日奉高情。","況有臺上月，如聞雲外笙。","不知桑落酒，今歲與誰傾。"]', '["公府想無事，西池秋水清。","去年爲狎客，永日奉高情。","況有台上月，如闻云外笙。","不知桑落酒，今歲與誰傾。"]', '诗', 'shi', '', NULL, '秋日書懷寄河南王尹 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38247dd3-e47b-4bbd-8763-e6e9da70062d', '詶留守牛相公宮城早秋寓言見寄', '詶留守牛相公宮城早秋寓言见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["曉月映宮樹，秋光起天津。","涼風稍動葉，宿露未生塵。","星氣尚芳麗，曠望感心神。","揮毫成逸韻，開閤遲來賓。","擺去將相印，漸爲逍遙身。","如招後房宴，却要白頭人。"]', '["晓月映宮樹，秋光起天津。","涼风稍动葉，宿露未生塵。","星氣尚芳丽，曠望感心神。","揮毫成逸韻，开閤遲来賓。","擺去將相印，漸爲逍遙身。","如招後房宴，却要白头人。"]', '诗', 'shi', '', NULL, '詶留守牛相公宮城早秋寓言見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5132c354-4f96-49e3-ba14-6a5a4da489ac', '海陽十詠 吏隱亭', '海陽十詠 吏隐亭', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["結構得奇勢，朱門交碧潯。","外來始一望，寫盡平生心。","日軒漾波影，月砌鏤松陰。","幾度欲歸去，回眸情更深。"]', '["結構得奇勢，朱门交碧潯。","外来始一望，寫尽平生心。","日軒漾波影，月砌鏤松陰。","幾度欲归去，回眸情更深。"]', '诗', 'shi', '', NULL, '海陽十詠 吏隱亭 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e995682a-7dd4-4ea8-8fe7-3436cb13581e', '海陽十詠 切雲亭', '海陽十詠 切云亭', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["逈破林煙出，俯窺石潭空。","波搖杏梁日，松韻碧窻風。","隔水生別島，帶橋如斷虹。","九疑南面事，盡入寸眸中。"]', '["逈破林煙出，俯窺石潭空。","波搖杏梁日，松韻碧窻风。","隔水生別島，带橋如斷虹。","九疑南面事，尽入寸眸中。"]', '诗', 'shi', '', NULL, '海陽十詠 切雲亭 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9283ad0c-0911-451f-8d27-771a345aa31f', '海陽十詠 雲英潭', '海陽十詠 云英潭', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["芳幄覆雲屏，石奩開碧鏡。","支流日飛灑，深處自疑瑩。","潛去不見跡，清音常滿聽。","有時病朝酲，來此心神醒。"]', '["芳幄覆云屏，石奩开碧镜。","支流日飞灑，深处自疑瑩。","潛去不见跡，清音常满听。","有时病朝酲，来此心神醒。"]', '诗', 'shi', '', NULL, '海陽十詠 雲英潭 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1008ad9b-afc3-47c8-9627-74cf7dcbae7a', '海陽十詠 玄覽亭', '海陽十詠 玄覽亭', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["瀟灑青林際，夤緣碧潭隈。","淙流冒石下，輕波觸砌回。","香風逼人度，幽花覆水開。","故令無四壁，晴夜月光來。"]', '["瀟灑青林際，夤緣碧潭隈。","淙流冒石下，轻波觸砌回。","香风逼人度，幽花覆水开。","故令無四壁，晴夜月光来。"]', '诗', 'shi', '', NULL, '海陽十詠 玄覽亭 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e173ac3f-ed84-41ad-b98d-586121353591', '海陽十詠 裴溪', '海陽十詠 裴溪', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["楚客憶關中，疏溪想汾水。","縈紆非一曲，意態如千里。","倒影羅文動，微波笑顏起。","君今賜環歸，何人承玉趾。"]', '["楚客憶关中，疏溪想汾水。","縈紆非一曲，意態如千里。","倒影羅文动，微波笑顏起。","君今賜环归，何人承玉趾。"]', '诗', 'shi', '', NULL, '海陽十詠 裴溪 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f7ea5ae-988e-4851-9346-a52c1278ed46', '海陽十詠 飛練瀑', '海陽十詠 飞練瀑', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["晶晶擲巖端，潔光如可把。","瓊枝曲不折，雲片晴猶下。","石堅激清響，葉動承餘灑。","前時明月中，見是銀河瀉。"]', '["晶晶擲巖端，潔光如可把。","瓊枝曲不折，云片晴猶下。","石堅激清响，葉动承餘灑。","前时明月中，见是銀河瀉。"]', '诗', 'shi', '', NULL, '海陽十詠 飛練瀑 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fc46f47-97b2-4291-934b-ad1e5bffbd6a', '海陽十詠 蒙池', '海陽十詠 蒙池', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["瀠渟幽壁下，深淨如無力。","風起不成文，月來同一色。","地靈草木瘦，人遠煙霞逼。","往往疑列仙，圍碁在巖側。"]', '["瀠渟幽壁下，深淨如無力。","风起不成文，月来同一色。","地靈草木瘦，人远煙霞逼。","往往疑列仙，圍碁在巖側。"]', '诗', 'shi', '', NULL, '海陽十詠 蒙池 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('260cc902-f037-49ce-8380-2d7ce420cdb2', '海陽十詠 棼絲瀑', '海陽十詠 棼絲瀑', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["飛流透嵌隙，噴灑如絲棼。","含暈迎初旭，翻光破夕曛。","餘波遶石去，碎響隔溪聞。","却望瓊沙際，逶迤見脉分。"]', '["飞流透嵌隙，噴灑如絲棼。","含暈迎初旭，翻光破夕曛。","餘波遶石去，碎响隔溪闻。","却望瓊沙際，逶迤见脉分。"]', '诗', 'shi', '', NULL, '海陽十詠 棼絲瀑 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19b859e2-431b-4171-9221-99eabfd4068e', '海陽十詠 雙溪', '海陽十詠 雙溪', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["流水遶雙島，碧溪相並深。","浮花擁曲處，遠影落中心。","閑鷺久獨立，曝龜驚復沈。","蘋風有時起，滿谷簫韶音。"]', '["流水遶雙島，碧溪相並深。","浮花擁曲处，远影落中心。","闲鷺久独立，曝龟驚复沈。","蘋风有时起，满谷簫韶音。"]', '诗', 'shi', '', NULL, '海陽十詠 雙溪 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5a4af38-32a5-4e3a-af05-bfa38302f854', '海陽十詠 月窟', '海陽十詠 月窟', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["濺濺漱幽石，注入團圓處。","有如常滿杯，承彼清夜露。","巖曲月斜照，林寒春晚煦。","遊人不敢觸，恐有蛟龍護。"]', '["濺濺漱幽石，注入團圓处。","有如常满杯，承彼清夜露。","巖曲月斜照，林寒春晚煦。","游人不敢觸，恐有蛟龙護。"]', '诗', 'shi', '', NULL, '海陽十詠 月窟 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c26d1f0-4543-4b5b-a456-32639a1c73b2', '武夫詞', '武夫词', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["武夫何洸洸，衣紫襲絳裳。","借問胡爲爾，列校在鷹揚。","依倚將軍勢，交結少年場。","探丸害公吏，抽刃妒名倡。","家產既不事，顧盼自生光。","酣歌高樓上，袒裼大道傍。","昔爲編戶人，秉耒甘哺糠。","今來從軍樂，躍馬飫膏粱。","猶思風塵起，無種取侯王。"]', '["武夫何洸洸，衣紫襲絳裳。","借问胡爲爾，列校在鷹揚。","依倚將軍勢，交結少年場。","探丸害公吏，抽刃妒名倡。","家產既不事，顧盼自生光。","酣歌高楼上，袒裼大道傍。","昔爲編戶人，秉耒甘哺糠。","今来從軍乐，躍马飫膏粱。","猶思风塵起，無種取侯王。"]', '诗', 'shi', '', NULL, '武夫詞 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a8bee71-a907-43c9-9b7c-9b575df2cac3', '虎丘寺路宴', '虎丘寺路宴', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["青林虎丘寺，林際翠微路。","立見山僧來，遙從鳥飛處。","茲峰淪寶玉，千載惟丘墓。","埋劒人空傳，鑿山龍已去。","捫蘿披翳薈，路轉夕陰遽。","虎嘯崖谷寒，猿鳴松杉暮。","徘徊北樓上，海江窮一顧。","日映千里帆，鴉歸萬家樹。","暫因愜所適，果得捐外慮。","庭暗棲還雲，簷香滴甘露。","久迷空寂理，多爲聲華故。","永欲投此山，餘生豈能悞。"]', '["青林虎丘寺，林際翠微路。","立见山僧来，遙從鸟飞处。","茲峰淪寶玉，千載惟丘墓。","埋劒人空傳，鑿山龙已去。","捫蘿披翳薈，路轉夕陰遽。","虎嘯崖谷寒，猿鳴松杉暮。","徘徊北楼上，海江窮一顧。","日映千里帆，鴉归万家樹。","暫因愜所適，果得捐外慮。","庭暗棲還云，簷香滴甘露。","久迷空寂理，多爲声华故。","永欲投此山，餘生豈能悞。"]', '诗', 'shi', '', NULL, '虎丘寺路宴 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08e7ade0-3403-406e-9d74-679e48d898c7', '缺題', '缺題', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["故人日已遠，窻下塵滿琴。","坐對一撙酒，恨多無力斟。","幕疎螢色逈，露重月華深。","萬境與羣籟，此時情豈任。"]', '["故人日已远，窻下塵满琴。","坐对一撙酒，恨多無力斟。","幕疎螢色逈，露重月华深。","万境與羣籟，此时情豈任。"]', '诗', 'shi', '', NULL, '缺題 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1209f202-5321-4254-91ca-4477d547cfa2', '晚步揚子游南塘望沙尾', '晚步揚子游南塘望沙尾', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["淮海多夏雨，曉來天始晴。","蕭條長風至，千里孤雲生。","卑濕久喧濁，搴開偶虛清。","客遊廣陵郡，晚出臨江城。","郊外綠楊陰，江中沙嶼明。","歸帆翳盡日，去櫂聞遺聲。","鄉國殊渺漫，羈心目懸旌。","悠然京華意，悵望懷遠程。","薄暮大山上，翩翩雙鳥征。"]', '["淮海多夏雨，晓来天始晴。","蕭條长风至，千里孤云生。","卑濕久喧濁，搴开偶虛清。","客游廣陵郡，晚出臨江城。","郊外綠楊陰，江中沙嶼明。","归帆翳尽日，去櫂闻遺声。","乡国殊渺漫，羈心目懸旌。","悠然京华意，悵望懷远程。","薄暮大山上，翩翩雙鸟征。"]', '诗', 'shi', '', NULL, '晚步揚子游南塘望沙尾 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08a8ab7b-fb84-4a05-8b4e-177f2728bdbf', '和浙西李大夫晚下北固山喜徑松成陰悵然懷古偶題臨江亭幷浙東元相公所和依本韻', '和浙西李大夫晚下北固山喜徑松成陰悵然懷古偶題臨江亭幷浙东元相公所和依本韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["一辭溫室樹，幾見武昌柳。","荀謝年何少，韋平望已久。","種松夾石道，紆組臨沙阜。","目覽帝王州，心存股肱守。","葉動驚綵翰，波澄見頳首。","晉宋齊梁都，千山萬江口。","煙散隋宮出，濤來海門吼。","風俗太伯餘，衣冠永嘉後。","江長天作限，山固壤無朽。","自古稱佳麗，非賢誰奄有。","八元邦族盛，萬石門風厚。","天柱揭東溟，文星照北斗。","高亭一騁望，舉酒共爲壽。","因賦詠懷詩，遠寄同心友。","禁中晨夜直，江左東西偶。","將手握兵符，儒腰盤貴綬。","頒條風有自，立事言無苟。","農野聞讓耕，軍人不使酒。","用材當構廈，知道寧窺牖。","誰謂青雲高，鵬飛終背負。"]', '["一辞溫室樹，幾见武昌柳。","荀謝年何少，韋平望已久。","種松夾石道，紆組臨沙阜。","目覽帝王州，心存股肱守。","葉动驚綵翰，波澄见頳首。","晉宋齊梁都，千山万江口。","煙散隋宮出，濤来海门吼。","风俗太伯餘，衣冠永嘉後。","江长天作限，山固壤無朽。","自古稱佳丽，非賢誰奄有。","八元邦族盛，万石门风厚。","天柱揭东溟，文星照北斗。","高亭一騁望，舉酒共爲壽。","因賦詠懷诗，远寄同心友。","禁中晨夜直，江左东西偶。","將手握兵符，儒腰盤貴綬。","頒條风有自，立事言無苟。","農野闻讓耕，軍人不使酒。","用材當構廈，知道寧窺牖。","誰謂青云高，鵬飞終背負。"]', '诗', 'shi', '', NULL, '和浙西李大夫晚下北固山喜徑松成陰悵然懷古偶題臨江亭幷浙東元相公所和依本韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d50762ec-f4d1-4b75-bc09-a29d6ff59ccc', '始至雲安寄兵部韓侍郎中書白舍人二公近曾遠守故有屬焉', '始至云安寄兵部韓侍郎中书白舍人二公近曾远守故有屬焉', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["天外巴子國，山頭白帝城。","波清蜀[柹]盡，雲散楚臺傾。","迅瀨下哮吼，兩岸勢爭衡。","陰風鬼神過，暴雨蛟龍生。","硤斷見孤邑，江流照飛甍。","蠻軍擊嚴鼓，笮馬引雙旌。","望闕遙拜舞，分庭備將迎。","銅符一以合，文墨紛來縈。","暮色四山起，愁猿數處聲。","重關羣吏散，靜視寒燈明。","故人青霞意，飛舞集蓬瀛。","昔曾在池籞，應知魚鳥情。"]', '["天外巴子国，山头白帝城。","波清蜀[柹]尽，云散楚台傾。","迅瀨下哮吼，兩岸勢爭衡。","陰风鬼神過，暴雨蛟龙生。","硤斷见孤邑，江流照飞甍。","蠻軍擊嚴鼓，笮马引雙旌。","望闕遙拜舞，分庭備將迎。","銅符一以合，文墨紛来縈。","暮色四山起，愁猿數处声。","重关羣吏散，静視寒灯明。","故人青霞意，飞舞集蓬瀛。","昔曾在池籞，應知鱼鸟情。"]', '诗', 'shi', '', NULL, '始至雲安寄兵部韓侍郎中書白舍人二公近曾遠守故有屬焉 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee4d3074-c68a-4d86-9bef-b59cf2eb5c18', '更衣曲', '更衣曲', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["博山炯炯吐香霧，紅燭引至更衣處。","夜如何其夜漫漫，鄰雞未鳴寒雁度。","庭前雪壓松桂叢，廊下點點懸紗籠。","滿堂醉客爭笑語，嘈囋琵琶青幕中。"]', '["博山炯炯吐香霧，紅燭引至更衣处。","夜如何其夜漫漫，鄰雞未鳴寒雁度。","庭前雪壓松桂叢，廊下点点懸紗籠。","满堂醉客爭笑語，嘈囋琵琶青幕中。"]', '诗', 'shi', '', NULL, '更衣曲 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a85b1aa-f7e3-46c6-9d47-c032a38ee885', '桃源行', '桃源行', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["漁舟何招招，浮在武陵水。","拖綸擲餌信流去，誤入桃源行數里。","清源尋盡花綿綿，踏花覓徑至洞前。","洞門蒼黑煙霧生，暗行數步逢虛明。","俗人毛骨驚仙子，爭來致詞何至此。","須臾皆破冰雪顏，笑言委曲問人間。","因嗟隱身來種玉，不知人世如風燭。","筵羞石髓勸客餐，燈爇松脂留客宿。","雞聲犬聲遙相聞，曉色葱蘢開五雲。","漁人振衣起出戶，滿庭無路花紛紛。","翻然恐失鄉懸處，一息不肯桃源住。","桃花滿溪水似鏡，塵心如垢洗不去。","仙家一出尋無踪，至今流水山重重。"]', '["漁舟何招招，浮在武陵水。","拖綸擲餌信流去，誤入桃源行數里。","清源尋尽花綿綿，踏花覓徑至洞前。","洞门蒼黑煙霧生，暗行數步逢虛明。","俗人毛骨驚仙子，爭来致词何至此。","須臾皆破冰雪顏，笑言委曲问人间。","因嗟隐身来種玉，不知人世如风燭。","筵羞石髓勸客餐，灯爇松脂留客宿。","雞声犬声遙相闻，晓色葱蘢开五云。","漁人振衣起出戶，满庭無路花紛紛。","翻然恐失乡懸处，一息不肯桃源住。","桃花满溪水似镜，塵心如垢洗不去。","仙家一出尋無踪，至今流水山重重。"]', '诗', 'shi', '', NULL, '桃源行 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('039f4ee1-4354-458d-975a-53f6c9d98bd9', '洞庭秋月行', '洞庭秋月行', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["洞庭秋月生湖心，層波萬頃如鎔金。","孤輪徐轉光不定，遊氣濛濛隔寒鏡。","是時白露三秋中，湖平月上天地空。","岳陽樓頭暮角絕，蕩漾已過君山東。","山城蒼蒼夜寂寂，水月逶迤繞城白。","蕩槳巴童歌竹枝，連檣估客吹羗笛。","勢高夜久陰力全，金氣肅肅開星躔。","浮雲野馬歸四裔，遙望星斗當中天。","天雞相呼曙霞出，歛影含光讓朝日。","日出喧喧人不閑，夜來清景非人間。"]', '["洞庭秋月生湖心，層波万頃如鎔金。","孤輪徐轉光不定，游氣濛濛隔寒镜。","是时白露三秋中，湖平月上天地空。","岳陽楼头暮角絕，蕩漾已過君山东。","山城蒼蒼夜寂寂，水月逶迤繞城白。","蕩槳巴童歌竹枝，連檣估客吹羗笛。","勢高夜久陰力全，金氣肅肅开星躔。","浮云野马归四裔，遙望星斗當中天。","天雞相呼曙霞出，歛影含光讓朝日。","日出喧喧人不闲，夜来清景非人间。"]', '诗', 'shi', '', NULL, '洞庭秋月行 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0db86e9-c5a7-4390-a016-22a26d44043a', '九華山歌', '九华山歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["奇峰一見驚魂魄，意想洪罏始開闢。","疑是九龍夭矯欲攀天，忽逢霹靂一聲化爲石。","不然何至今，悠悠億萬年，氣勢不死如騰仚。","雲含幽兮月添冷，月凝暉兮江漾影。","結根不得要路津，逈秀長在無人境。","軒皇封禪登雲亭，大禹會寄臨東溟。","乘樏不來廣樂絕，獨與猨鳥愁青熒。","君不見敬亭之山黃索漠，兀如斷岸無稜角。","宣城謝守一首詩，遂使聲名齊五岳。","九華山，九華山。","自是造化一尤物，焉能籍甚乎人間。"]', '["奇峰一见驚魂魄，意想洪罏始开闢。","疑是九龙夭矯欲攀天，忽逢霹靂一声化爲石。","不然何至今，悠悠億万年，氣勢不死如腾仚。","云含幽兮月添冷，月凝暉兮江漾影。","結根不得要路津，逈秀长在無人境。","軒皇封禪登云亭，大禹會寄臨东溟。","乘樏不来廣乐絕，独與猨鸟愁青熒。","君不见敬亭之山黄索漠，兀如斷岸無稜角。","宣城謝守一首诗，遂使声名齊五岳。","九华山，九华山。","自是造化一尤物，焉能籍甚乎人间。"]', '诗', 'shi', '', NULL, '九華山歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72463bb5-a9de-40d1-b41a-30d873fcf1f9', '泰娘歌', '泰娘歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["泰娘家本閶門西，門前綠水環金隄。","有時妝成好天氣，走上臯橋折花戲。","風流太守韋尚書，路傍忽見停隼旟。","斗量明珠鳥傳意，紺幰迎入專城居。","長鬟如雲衣似霧，錦茵羅薦承輕步。","舞學驚鴻水榭春，歌傳上客蘭堂暮。","從郎西入帝城中，貴遊簪組香簾櫳。","低鬟緩視抱明月，纖指破拔生胡風。","繁華一旦有消歇，題劍無光履聲絕。","洛陽舊宅生草萊，杜陵蕭蕭松柏哀。","妝奩蟲網厚如繭，博山爐側傾寒灰。","蘄州刺史張公子，白馬新到銅駝里。","自言買笑擲黃金，月墮雲中從此始。","安知鵩鳥座隅飛，寂寞旅魂招不歸。","秦嘉鏡有前時結，韓壽香銷故篋衣。","山城少人江水碧，斷鴈哀猨風雨夕。","朱弦已絕爲知音，雲鬢未秋私自惜。","舉目風煙非舊時，夢尋歸路鄉多參差。","如何將此千行淚，更灑湘江斑竹枝。"]', '["泰娘家本閶门西，门前綠水环金隄。","有时妝成好天氣，走上臯橋折花戲。","风流太守韋尚书，路傍忽见停隼旟。","斗量明珠鸟傳意，紺幰迎入專城居。","长鬟如云衣似霧，錦茵羅薦承轻步。","舞学驚鴻水榭春，歌傳上客蘭堂暮。","從郎西入帝城中，貴游簪組香簾櫳。","低鬟緩視抱明月，纖指破拔生胡风。","繁华一旦有消歇，題劍無光履声絕。","洛陽旧宅生草萊，杜陵蕭蕭松柏哀。","妝奩蟲網厚如繭，博山爐側傾寒灰。","蘄州刺史張公子，白马新到銅駝里。","自言買笑擲黄金，月墮云中從此始。","安知鵩鸟座隅飞，寂寞旅魂招不归。","秦嘉镜有前时結，韓壽香銷故篋衣。","山城少人江水碧，斷鴈哀猨风雨夕。","朱弦已絕爲知音，云鬢未秋私自惜。","舉目风煙非旧时，梦尋归路乡多參差。","如何將此千行泪，更灑湘江斑竹枝。"]', '诗', 'shi', '', NULL, '泰娘歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b1e42d7-b559-4c0f-b568-b441d89b4d39', '龍陽縣歌', '龙陽縣歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["縣門白日無塵土，百姓縣前挽魚罟。","主人引客登大隄，小兒縱觀黃犬怒。","鷓鴣驚鳴繞籬落，橘柚垂芳照窗戶。","沙平草綠見吏稀，寂歷斜陽照縣鼓。"]', '["縣门白日無塵土，百姓縣前挽鱼罟。","主人引客登大隄，小兒縱观黄犬怒。","鷓鴣驚鳴繞籬落，橘柚垂芳照窗戶。","沙平草綠见吏稀，寂歷斜陽照縣鼓。"]', '诗', 'shi', '', NULL, '龍陽縣歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bc37c7b-af6e-4a86-9d48-c558c25293a8', '牆陰歌', '牆陰歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["白日左右浮天潢，朝晡影入東西牆。","昔爲兒童在陰戲，當時意小覺日長。","東鄰侯家吹笙簧，隨陰促促移象牀。","西鄰田舍乏糟糠，就影汲汲舂黃粱。","因思九州四海外，家家只占牆陰內。","莫言牆陰數尺間，老却主人如等閑。","君看眼前光陰促，中心莫學太行山。"]', '["白日左右浮天潢，朝晡影入东西牆。","昔爲兒童在陰戲，當时意小覺日长。","东鄰侯家吹笙簧，隨陰促促移象牀。","西鄰田舍乏糟糠，就影汲汲舂黄粱。","因思九州四海外，家家只占牆陰內。","莫言牆陰數尺间，老却主人如等闲。","君看眼前光陰促，中心莫学太行山。"]', '诗', 'shi', '', NULL, '牆陰歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eb8766b-62b4-4026-b369-781c37d63957', '踏潮歌', '踏潮歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["屯門積日無回飆，滄波不歸成踏潮。","轟如鞭矻石且搖，亘空欲駕黿鼉橋。","驚湍蹙縮悍而驕，大陵高岸失岧嶤。","四邊無阻音響調，背負元氣掀重霄。","介鯨得性方逍遙，仰鼻噓吸揚朱翹。","海人狂顧迭相招，罽衣髽首聲嘵嘵。","征南將軍登麗譙，赤旗指麾不敢囂。","翌日風回沴氣消，歸濤納納景昭昭。","烏泥白沙復滿海，海色不動如青瑤。"]', '["屯门積日無回飆，滄波不归成踏潮。","轟如鞭矻石且搖，亘空欲駕黿鼉橋。","驚湍蹙縮悍而驕，大陵高岸失岧嶤。","四邊無阻音响調，背負元氣掀重霄。","介鯨得性方逍遙，仰鼻噓吸揚朱翹。","海人狂顧迭相招，罽衣髽首声嘵嘵。","征南將軍登丽譙，赤旗指麾不敢囂。","翌日风回沴氣消，归濤納納景昭昭。","烏泥白沙复满海，海色不动如青瑤。"]', '诗', 'shi', '', NULL, '踏潮歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2875908a-c8e1-4dc5-9048-625d430eb1a5', '白鷺兒', '白鷺兒', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["白鷺兒，最高格。","毛衣新成雪不敵，衆禽喧呼獨凝寂。","孤眠芊芊草，久立潺潺石。","前山正無雲，飛去入遙碧。"]', '["白鷺兒，最高格。","毛衣新成雪不敵，衆禽喧呼独凝寂。","孤眠芊芊草，久立潺潺石。","前山正無云，飞去入遙碧。"]', '诗', 'shi', '', NULL, '白鷺兒 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0d148c2-0a75-4cf9-b3e7-e0532476db99', '平齊行二首 一', '平齊行二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["胡塵昔起薊北門，河南地屬平盧軍。","貂裘代馬繞東岳，嶧陽孤桐削爲角。","地形十二虜意驕，恩澤含容歷四朝。","魯人皆解帶弓箭，齊人不復聞簫韶。","今朝天子聖神武，手握玄符平九土。","初哀狂童襲故事，文告不來方振怒。","去秋詔下誅東平，官軍四合猶嬰城。","春來羣烏噪且驚，氣如壞山墮其庭。","牙門大將有劉生，夜半射落欃槍星。","帳中虜血流滿地，門外三軍舞連臂。","驛騎函首過黃河，城中無賊天氣和。","朝廷侍郎來慰撫，耕夫滿野行人歌。"]', '["胡塵昔起薊北门，河南地屬平盧軍。","貂裘代马繞东岳，嶧陽孤桐削爲角。","地形十二虜意驕，恩澤含容歷四朝。","魯人皆解带弓箭，齊人不复闻簫韶。","今朝天子聖神武，手握玄符平九土。","初哀狂童襲故事，文告不来方振怒。","去秋詔下誅东平，官軍四合猶嬰城。","春来羣烏噪且驚，氣如壞山墮其庭。","牙门大將有劉生，夜半射落欃槍星。","帳中虜血流满地，门外三軍舞連臂。","驛騎函首過黄河，城中無賊天氣和。","朝廷侍郎来慰撫，耕夫满野行人歌。"]', '诗', 'shi', '', NULL, '平齊行二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd285a68-be33-4ac0-b7ca-0dbd2b19b885', '平齊行二首 二', '平齊行二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["泰山沈寇六十年，旅祭不享生愁煙。","今逢聖君欲封禪，神使陰兵來阻戰。","妖氛掃盡河水清，日觀杲杲卿雲見。","開元黃帝東封時，百神受職爭奔馳。","千鈞猛簴順流下，洪波涵淡浮熊羆。","侍臣燕公秉文筆，玉檢告天無媿詞。","當今睿孫承聖祖，岳神望幸河宗舞。","青門大道屬車塵，共待葳蕤翠華舉。"]', '["泰山沈寇六十年，旅祭不享生愁煙。","今逢聖君欲封禪，神使陰兵来阻戰。","妖氛掃尽河水清，日观杲杲卿云见。","开元黄帝东封时，百神受職爭奔驰。","千鈞猛簴順流下，洪波涵淡浮熊羆。","侍臣燕公秉文笔，玉檢告天無媿词。","當今睿孫承聖祖，岳神望幸河宗舞。","青门大道屬车塵，共待葳蕤翠华舉。"]', '诗', 'shi', '', NULL, '平齊行二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73b23b38-fc4c-4aed-80ec-8da99789e13e', '送裴處士應制舉詩', '送裴处士應制舉诗', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["裴生久在風塵裏，氣勁言高少知己。","注書曾學鄭司農，歷國多於孔夫子。","往年訪我到連州，無窮絕境終日遊。","登山雨中試蠟屐，入洞夏裏披貂裘。","白帝城邊又相遇，歛翼三年不飛去。","忽然結束如秋蓬，自稱對策明光宮。","人言策中說何事，掉頭不答看飛鴻。","彤庭翠松迎曉日，鳳銜金榜雲間出。","中貴腰鞭立傾酒，宰臣委佩觀搖筆。","古稱射策如彎弧，一發偶中何時無。","由來草澤無忌諱，努力滿挽當亨衢。","憶得當年識君處，嘉禾驛後聯牆住。","垂鉤釣得王餘魚，踏芳共登蘇小墓。","此事今同夢想間，相看一笑且開顏。","老大希逢舊鄰里，爲君扶病到方山。"]', '["裴生久在风塵裏，氣勁言高少知己。","注书曾学鄭司農，歷国多於孔夫子。","往年訪我到連州，無窮絕境終日游。","登山雨中試蠟屐，入洞夏裏披貂裘。","白帝城邊又相遇，歛翼三年不飞去。","忽然結束如秋蓬，自稱对策明光宮。","人言策中说何事，掉头不答看飞鴻。","彤庭翠松迎晓日，鳳銜金榜云间出。","中貴腰鞭立傾酒，宰臣委佩观搖笔。","古稱射策如彎弧，一發偶中何时無。","由来草澤無忌諱，努力满挽當亨衢。","憶得當年識君处，嘉禾驛後聯牆住。","垂鉤釣得王餘鱼，踏芳共登蘇小墓。","此事今同梦想间，相看一笑且开顏。","老大希逢旧鄰里，爲君扶病到方山。"]', '诗', 'shi', '', NULL, '送裴處士應制舉詩 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf7821d0-4630-4e62-8462-c3e189277a4e', '三鄉驛樓伏覩玄宗望女几山詩小臣斐然有感', '三乡驛楼伏覩玄宗望女几山诗小臣斐然有感', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["開元天子萬事足，唯惜當時光景促。","三鄉陌上望仙山，歸作霓裳羽衣曲。","仙心從此在瑤池，三清八景相追隨。","天上忽乘白雲去，世間空有秋風詞。"]', '["开元天子万事足，唯惜當时光景促。","三乡陌上望仙山，归作霓裳羽衣曲。","仙心從此在瑤池，三清八景相追隨。","天上忽乘白云去，世间空有秋风词。"]', '诗', 'shi', '', NULL, '三鄉驛樓伏覩玄宗望女几山詩小臣斐然有感 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aa0052e-eb21-4a5a-97d2-c90283c12aae', '城西行', '城西行', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["城西簇簇三叛族，叛者爲誰蔡吳蜀。","中使提刀出禁來，九衢車馬轟如雷。","臨刑與酒杯未覆，讐家白官先請肉。","守吏能然董卓臍，饑烏來覘桓玄目。","城西人散泰階平，雨洗血痕春草生。"]', '["城西簇簇三叛族，叛者爲誰蔡吳蜀。","中使提刀出禁来，九衢车马轟如雷。","臨刑與酒杯未覆，讐家白官先請肉。","守吏能然董卓臍，饑烏来覘桓玄目。","城西人散泰階平，雨洗血痕春草生。"]', '诗', 'shi', '', NULL, '城西行 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('944b70fa-7f5c-4558-b9e0-7b5688eaf601', '武昌老人說笛歌', '武昌老人说笛歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["武昌老人七十餘，手把庾令相問書。","自言少小學吹笛，早事曹王曾賞激。","往年鎮戍到蘄州，楚山蕭蕭笛竹秋。","當時買材恣搜索，典却身上烏貂裘。","古苔蒼蒼封老節，石上孤生飽風雪。","商聲五音隨指發，水中龍應行雲絕。","曾將黃鶴樓上吹，一聲占盡秋江月。","如今老去語尤遲，音韻高低耳不知。","氣力已微心尚在，時時一曲夢中吹。"]', '["武昌老人七十餘，手把庾令相问书。","自言少小学吹笛，早事曹王曾賞激。","往年鎮戍到蘄州，楚山蕭蕭笛竹秋。","當时買材恣搜索，典却身上烏貂裘。","古苔蒼蒼封老節，石上孤生飽风雪。","商声五音隨指發，水中龙應行云絕。","曾將黄鹤楼上吹，一声占尽秋江月。","如今老去語尤遲，音韻高低耳不知。","氣力已微心尚在，时时一曲梦中吹。"]', '诗', 'shi', '', NULL, '武昌老人說笛歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aab2742-0f6f-4708-8db5-19a81dc35be1', '西山蘭若試茶歌', '西山蘭若試茶歌', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["山僧後檐茶數叢，春來映竹抽新茸。","宛然爲客振衣起，自傍芳叢摘鷹觜。","斯須炒成滿室香，便酌砌下金沙水。","驟雨松聲入鼎來，白雲滿盌花俳徊。","悠揚噴鼻宿酲散，清峭徹骨煩襟開。","陽崖陰嶺各殊氣，未若竹下莓苔地。","炎帝雖嘗未解煎，桐君有籙那知味。","新芽連拳半未舒，自摘至煎俄頃餘。","木蘭霑露香微似，瑤草臨波色不如。","僧言靈味宜幽寂，采采翹英爲嘉客。","不辭緘封寄郡齋，甎井銅爐損標格。","何況蒙山顧渚春，白泥赤印走風塵。","欲知花乳清泠味，須是眠雲跂石人。"]', '["山僧後檐茶數叢，春来映竹抽新茸。","宛然爲客振衣起，自傍芳叢摘鷹觜。","斯須炒成满室香，便酌砌下金沙水。","驟雨松声入鼎来，白云满盌花俳徊。","悠揚噴鼻宿酲散，清峭徹骨煩襟开。","陽崖陰嶺各殊氣，未若竹下莓苔地。","炎帝雖嘗未解煎，桐君有籙那知味。","新芽連拳半未舒，自摘至煎俄頃餘。","木蘭霑露香微似，瑤草臨波色不如。","僧言靈味宜幽寂，采采翹英爲嘉客。","不辞緘封寄郡斋，甎井銅爐損標格。","何況蒙山顧渚春，白泥赤印走风塵。","欲知花乳清泠味，須是眠云跂石人。"]', '诗', 'shi', '', NULL, '西山蘭若試茶歌 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acc05c3d-7f73-4966-9ef6-7893ba9d636a', '聚蚊謠', '聚蚊謠', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["沈沈夏夜蘭堂開，飛蚊伺暗聲如雷。","嘈然歘起初駭聽，殷殷若自南山來。","喧騰鼓舞喜昏黑，昧者不分聽者惑。","露花滴瀝月上天，利觜迎人著不得。","我軀七尺爾如芒，我孤爾衆能我傷。","天生有時不可遏，爲爾設幄潛匡牀。","清商一來秋日曉，羞爾微形飼丹鳥。"]', '["沈沈夏夜蘭堂开，飞蚊伺暗声如雷。","嘈然歘起初駭听，殷殷若自南山来。","喧腾鼓舞喜昏黑，昧者不分听者惑。","露花滴瀝月上天，利觜迎人著不得。","我軀七尺爾如芒，我孤爾衆能我傷。","天生有时不可遏，爲爾設幄潛匡牀。","清商一来秋日晓，羞爾微形飼丹鸟。"]', '诗', 'shi', '', NULL, '聚蚊謠 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b08422c8-4123-4327-a69e-32f21f2dce00', '百舌吟', '百舌吟', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["曉星寥落春雲低，初聞百舌間關啼。","花樹滿空迷處所，搖動繁英墜紅雨。","笙簧百囀音韻多，黃鸝吞聲燕無語。","東方朝日遲遲升，迎風弄景如自矜。","數聲不盡又飛去，何許相逢綠楊路。","綿蠻宛轉似娛人，一心百舌何紛紛。","酡顏俠少停歌聽，墜珥妖姬和睡聞。","可憐光景何時盡，誰能低回避鷹隼。","廷尉張羅自不關，潘郎挾彈無情損。","天生羽族爾何微，舌端萬變乘春暉。","南方朱鳥一朝見，索漠無言蒿下飛。"]', '["晓星寥落春云低，初闻百舌间关啼。","花樹满空迷处所，搖动繁英墜紅雨。","笙簧百囀音韻多，黄鸝吞声燕無語。","东方朝日遲遲升，迎风弄景如自矜。","數声不尽又飞去，何許相逢綠楊路。","綿蠻宛轉似娛人，一心百舌何紛紛。","酡顏俠少停歌听，墜珥妖姬和睡闻。","可怜光景何时尽，誰能低回避鷹隼。","廷尉張羅自不关，潘郎挾彈無情損。","天生羽族爾何微，舌端万变乘春暉。","南方朱鸟一朝见，索漠無言蒿下飞。"]', '诗', 'shi', '', NULL, '百舌吟 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06c80145-5ba1-4266-badf-d498cacff961', '飛鳶操', '飞鳶操', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鳶飛杳杳青雲裏，鳶鳴蕭蕭風四起。","旗尾飄揚勢漸高，箭頭砉劃聲相似。","長空悠悠霽日懸，六翮不動凝風煙。","遊鵾翔鴈出其下，慶雲清景相回旋。","忽聞饑烏一噪聚，瞥下雲中爭腐鼠。","騰音礪吻相喧呼，仰天大嚇疑鵷鶵。","畏人避犬投高處，俛啄無聲猶屢顧。","青鳥自愛玉山禾，仙禽徒貴華亭露。","樸遬危巢向暮時，毰毸飽腹蹲枯枝。","遊童挾彈一麾肘，臆碎羽分人不悲。","天生衆禽各有類，威鳳文章在仁義。","鷹隼儀形螻蟻心，雖能戾天何足貴。"]', '["鳶飞杳杳青云裏，鳶鳴蕭蕭风四起。","旗尾飄揚勢漸高，箭头砉劃声相似。","长空悠悠霽日懸，六翮不动凝风煙。","游鵾翔鴈出其下，慶云清景相回旋。","忽闻饑烏一噪聚，瞥下云中爭腐鼠。","腾音礪吻相喧呼，仰天大嚇疑鵷鶵。","畏人避犬投高处，俛啄無声猶屢顧。","青鸟自愛玉山禾，仙禽徒貴华亭露。","樸遬危巢向暮时，毰毸飽腹蹲枯枝。","游童挾彈一麾肘，臆碎羽分人不悲。","天生衆禽各有類，威鳳文章在仁義。","鷹隼儀形螻蟻心，雖能戾天何足貴。"]', '诗', 'shi', '', NULL, '飛鳶操 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa308cb2-c342-4a5f-a110-e48d22ba22e0', '秋螢引', '秋螢引', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["漢陵秦苑遙蒼蒼，陳根腐葉秋螢光。","夜空寥寂金氣淨，千門九陌飛悠揚。","紛綸暉映互明滅，金爐星噴鐙花發。","露華洗濯清風吹，低昂不定招搖垂。","高麗罘罳照蛛網，斜歷璇題舞羅幌。","曝衣樓上拂香帬，承露臺前轉仙掌。","槐市諸生夜讀書，北窗分明辨魯魚。","行子東山起征思，中郎騎省悲秋氣。","銅雀人歸自入簾，長門帳開來照淚。","誰言向晦常自明，兒童走步嬌女爭。","天生有光非自衒，遠近低昂暗中見。","撮蚊妖鳥亦夜起，翅如車輪而已矣。"]', '["漢陵秦苑遙蒼蒼，陳根腐葉秋螢光。","夜空寥寂金氣淨，千门九陌飞悠揚。","紛綸暉映互明滅，金爐星噴鐙花發。","露华洗濯清风吹，低昂不定招搖垂。","高丽罘罳照蛛網，斜歷璇題舞羅幌。","曝衣楼上拂香帬，承露台前轉仙掌。","槐市諸生夜读书，北窗分明辨魯鱼。","行子东山起征思，中郎騎省悲秋氣。","銅雀人归自入簾，长门帳开来照泪。","誰言向晦常自明，兒童走步嬌女爭。","天生有光非自衒，远近低昂暗中见。","撮蚊妖鸟亦夜起，翅如车輪而已矣。"]', '诗', 'shi', '', NULL, '秋螢引 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37cb8473-c572-4fa0-95f2-dfc8ad04d1c8', '傷秦姝行', '傷秦姝行', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["長安二月花滿城，插花女兒彈銀箏。","南宮仙郎下朝晚，曲頭駐馬聞新聲。","馬蹄逶遲心蕩漾，高樓已遠猶頻望。","此時意重千金輕，鳥傳消息紺輪迎。","芳筵銀燭一相見，淺笑低鬟初目成。","蜀弦錚摐指如玉，皇帝弟子韋家曲。","青牛文梓赤金簧，玫瑰寶柱秋鴈行。","歛蛾收[袂]凝清光，抽弦緩調怨且長。","八鸞鏘鏘渡銀漢，九雛威鳳鳴朝陽。","曲終韻盡意不足，餘思悄絕愁空堂。","從郎鎮南別城闕，樓船理曲瀟湘月。","馮夷蹁躚舞淥波，鮫人出聽停綃梭。","北池含煙瑤草短，萬松亭下清風滿。","秦聲一曲此時聞，嶺泉嗚咽南雲斷。","來自長陵小市東，蕣華零落瘴江風。","侍兒掩泣收銀甲，鸚鵡不言愁玉籠。","博山爐中香自滅，鏡奩塵暗同心結。","從此東山非昔遊，長嗟人與弦俱絕。"]', '["长安二月花满城，插花女兒彈銀箏。","南宮仙郎下朝晚，曲头駐马闻新声。","马蹄逶遲心蕩漾，高楼已远猶頻望。","此时意重千金轻，鸟傳消息紺輪迎。","芳筵銀燭一相见，淺笑低鬟初目成。","蜀弦錚摐指如玉，皇帝弟子韋家曲。","青牛文梓赤金簧，玫瑰寶柱秋鴈行。","歛蛾收[袂]凝清光，抽弦緩調怨且长。","八鸾鏘鏘渡銀漢，九雛威鳳鳴朝陽。","曲終韻尽意不足，餘思悄絕愁空堂。","從郎鎮南別城闕，楼船理曲瀟湘月。","馮夷蹁躚舞淥波，鮫人出听停綃梭。","北池含煙瑤草短，万松亭下清风满。","秦声一曲此时闻，嶺泉嗚咽南云斷。","来自长陵小市东，蕣华零落瘴江风。","侍兒掩泣收銀甲，鸚鵡不言愁玉籠。","博山爐中香自滅，镜奩塵暗同心結。","從此东山非昔游，长嗟人與弦俱絕。"]', '诗', 'shi', '', NULL, '傷秦姝行 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30704557-6ff6-482b-aa1d-b98e5295546f', '競渡曲', '競渡曲', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["沅江五月平堤流，邑人相將浮綵舟。","靈均何年歌已矣，哀謠振檝從此起。","楊桴擊節雷闐闐，亂流齊進聲轟然。","蛟龍得雨鬐鬛動，螮蝀飲河形影聯。","刺史臨流褰翠幃，揭竿命爵分雄雌。","先鳴餘勇爭鼓舞，未至銜枚顏色沮。","百勝本自有前期，一飛由來無定所。","風俗如狂重此時，縱觀雲委江之湄。","綵旂夾岸照蛟室，羅襪凌波呈水嬉。","曲終人散空愁暮，招屈亭前水東注。"]', '["沅江五月平堤流，邑人相將浮綵舟。","靈均何年歌已矣，哀謠振檝從此起。","楊桴擊節雷闐闐，亂流齊進声轟然。","蛟龙得雨鬐鬛动，螮蝀饮河形影聯。","刺史臨流褰翠幃，揭竿命爵分雄雌。","先鳴餘勇爭鼓舞，未至銜枚顏色沮。","百勝本自有前期，一飞由来無定所。","风俗如狂重此时，縱观云委江之湄。","綵旂夾岸照蛟室，羅襪凌波呈水嬉。","曲終人散空愁暮，招屈亭前水东注。"]', '诗', 'shi', '', NULL, '競渡曲 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8fe387c-8c72-416e-9923-e72a07241a74', '翰林白二十二學士見寄詩一百篇因以答貺', '翰林白二十二学士见寄诗一百篇因以答貺', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["吟君遺我百篇詩，使我獨坐形神馳。","玉琴清夜人不語，琪樹春朝風正吹。","郢人斤斵無痕跡，仙人衣裳棄刀尺。","世人方內欲相尋，行盡四維無處覓。"]', '["吟君遺我百篇诗，使我独坐形神驰。","玉琴清夜人不語，琪樹春朝风正吹。","郢人斤斵無痕跡，仙人衣裳棄刀尺。","世人方內欲相尋，行尽四維無处覓。"]', '诗', 'shi', '', NULL, '翰林白二十二學士見寄詩一百篇因以答貺 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41bb21a6-136e-40c7-8a74-cd23630f8740', '憶春草', '憶春草', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["憶春草，處處多情洛陽道。","金谷園中見日遲，銅駝陌上迎風早。","河南大尹頻出難，只得池塘十步看。","府門閉後滿街月，幾處遊人草頭歇。","館娃宮外姑蘇臺，鬱鬱芊芊撥不開。","無風自偃君知否，西子帬裾曾拂來。"]', '["憶春草，处处多情洛陽道。","金谷园中见日遲，銅駝陌上迎风早。","河南大尹頻出难，只得池塘十步看。","府门閉後满街月，幾处游人草头歇。","館娃宮外姑蘇台，鬱鬱芊芊撥不开。","無风自偃君知否，西子帬裾曾拂来。"]', '诗', 'shi', '', NULL, '憶春草 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe0ab8e8-3cda-465a-9bc6-bafd8c39ae39', '樂天寄憶舊遊因作報白君以答', '乐天寄憶旧游因作報白君以答', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["報白君，別來已渡江南春。","江南春色何處好，燕子雙飛故官道。","春城三百七十橋，夾岸朱樓隔柳條。","丫頭小兒蕩畫槳，長袂女郎簪翠翹。","郡齋北軒卷羅幕，碧池逶迤遶畫閣。","池邊綠竹桃李花，花下舞筵鋪彩霞。","吳娃足情言語黠，越客有酒巾冠斜。","坐中皆言白太守，不負風光向杯酒。","酒酣襞牋飛逸韻，至今傳在人人口。","報白君，相思空望嵩丘雲。","其奈錢塘蘇小小，憶君淚點石榴帬。"]', '["報白君，別来已渡江南春。","江南春色何处好，燕子雙飞故官道。","春城三百七十橋，夾岸朱楼隔柳條。","丫头小兒蕩畫槳，长袂女郎簪翠翹。","郡斋北軒卷羅幕，碧池逶迤遶畫閣。","池邊綠竹桃李花，花下舞筵鋪彩霞。","吳娃足情言語黠，越客有酒巾冠斜。","坐中皆言白太守，不負风光向杯酒。","酒酣襞牋飞逸韻，至今傳在人人口。","報白君，相思空望嵩丘云。","其奈錢塘蘇小小，憶君泪点石榴帬。"]', '诗', 'shi', '', NULL, '樂天寄憶舊遊因作報白君以答 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eff1157-2720-48bc-b75a-79cf04a087f7', '兩如何詩謝裴令公贈別二首 一', '兩如何诗謝裴令公贈別二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["一言一顧重，重何如。","今日陪遊清洛苑，昔年別入承明廬。"]', '["一言一顧重，重何如。","今日陪游清洛苑，昔年別入承明廬。"]', '诗', 'shi', '', NULL, '兩如何詩謝裴令公贈別二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83e1f2ff-46ab-4e68-b5b8-a1dc7b38554c', '兩如何詩謝裴令公贈別二首 二', '兩如何诗謝裴令公贈別二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["一東一西別，別何如。","終期大冶再熔鍊，願託扶搖翔碧虛。"]', '["一东一西別，別何如。","終期大冶再熔鍊，願託扶搖翔碧虛。"]', '诗', 'shi', '', NULL, '兩如何詩謝裴令公贈別二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('891701e1-57c1-4d2a-82c0-253c1e6e934b', '唐侍御寄遊道林嶽麓二寺詩幷沈中丞姚員外所和見徵繼作', '唐侍御寄游道林嶽麓二寺诗幷沈中丞姚員外所和见徵繼作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["湘西古剎雙蹲蹲，羣峰朝拱如駿奔。","青松步障深五里，龍宮黯黯神爲閽。","高殿呀然壓蒼巘，俯瞰長江疑欲吞。","橘洲泛浮金實動，水郭繚繞朱樓騫。","語餘百響入天籟，衆奇引步輕翩翻。","泉清石布博棋子，蘿密鳥韻如簧言。","回廊架險高且曲，新徑穿林明復昏。","淺流忽濁山獸過，古木半空天火痕。","星使雙飛出禁垣，元侯餞之遊石門。","紫髯翼從紅袖舞，竹風松雪香溫黁。","遠持清瑣照巫峽，一戞驚斷三聲猨。","靈山會中身不預，吟想峭絕愁精魂。","恨無黃金千萬餅，布地買取爲丘園。"]', '["湘西古剎雙蹲蹲，羣峰朝拱如駿奔。","青松步障深五里，龙宮黯黯神爲閽。","高殿呀然壓蒼巘，俯瞰长江疑欲吞。","橘洲泛浮金實动，水郭繚繞朱楼騫。","語餘百响入天籟，衆奇引步轻翩翻。","泉清石布博棋子，蘿密鸟韻如簧言。","回廊架險高且曲，新徑穿林明复昏。","淺流忽濁山獸過，古木半空天火痕。","星使雙飞出禁垣，元侯餞之游石门。","紫髯翼從紅袖舞，竹风松雪香溫黁。","远持清瑣照巫峽，一戞驚斷三声猨。","靈山會中身不預，吟想峭絕愁精魂。","恨無黄金千万餅，布地買取爲丘园。"]', '诗', 'shi', '', NULL, '唐侍御寄遊道林嶽麓二寺詩幷沈中丞姚員外所和見徵繼作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0b06a9e-8464-4cf4-9fb3-d986dfc388ff', '將赴汝州途出浚下留辭李相公', '將赴汝州途出浚下留辞李相公', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["長安舊遊四十載，鄂渚一別十四年。","後來富貴已零落，歲寒松柏猶依然。","初逢貞元尚文主，雲闕天池共翔舞。","相看却數六朝臣，屈指如今無四五。","夷門天下之咽喉，昔時往往生瘡疣。","聯翩舊相來鎮壓，四海吐納皆通流。","久別凡經幾多事，何由說得平生意。","千思萬慮盡如空，一笑一言真可貴。","世間何事最殷勤，白頭將相逢故人。","功成名遂會歸老，請問東山爲近鄰。"]', '["长安旧游四十載，鄂渚一別十四年。","後来富貴已零落，歲寒松柏猶依然。","初逢貞元尚文主，云闕天池共翔舞。","相看却數六朝臣，屈指如今無四五。","夷门天下之咽喉，昔时往往生瘡疣。","聯翩旧相来鎮壓，四海吐納皆通流。","久別凡經幾多事，何由说得平生意。","千思万慮尽如空，一笑一言真可貴。","世间何事最殷勤，白头將相逢故人。","功成名遂會归老，請问东山爲近鄰。"]', '诗', 'shi', '', NULL, '將赴汝州途出浚下留辭李相公 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32bc7df7-81de-4db7-b425-eade43f5e593', '平蔡州三首 一', '平蔡州三首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["蔡州城中衆心死，妖星夜落照壕水。","漢家飛將下天來，馬箠一揮門洞開。","賊徒崩騰望旗拜，有若羣蟄驚春雷。","狂童面縛登檻車，太白夭矯垂捷書。","相公從容來鎮撫，常侍郊迎負文弩。","四人歸業閭里閑，小兒跳浪健兒舞。"]', '["蔡州城中衆心死，妖星夜落照壕水。","漢家飞將下天来，马箠一揮门洞开。","賊徒崩腾望旗拜，有若羣蟄驚春雷。","狂童面縛登檻车，太白夭矯垂捷书。","相公從容来鎮撫，常侍郊迎負文弩。","四人归業閭里闲，小兒跳浪健兒舞。"]', '诗', 'shi', '', NULL, '平蔡州三首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fc03d87-be07-4e07-b260-781c6d428f30', '平蔡州三首 二', '平蔡州三首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["汝南晨雞喔喔鳴，城頭鼓角音和平。","路傍老人憶舊事，相與感激皆涕零。","老人收泣前致辭，官軍入城人不知。","忽驚元和十二載，重見天寶承平時。"]', '["汝南晨雞喔喔鳴，城头鼓角音和平。","路傍老人憶旧事，相與感激皆涕零。","老人收泣前致辞，官軍入城人不知。","忽驚元和十二載，重见天寶承平时。"]', '诗', 'shi', '', NULL, '平蔡州三首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c61235e-e714-4033-9ba5-34ef1dda7ebb', '平蔡州三首 三', '平蔡州三首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["九衢車馬渾渾流，使臣來獻淮西囚。","四夷聞風失匕筯，天子受賀登高樓。","妖童擢髪不足數，血污城西一抔土。","南峯無火楚澤閑，夜行不鎖穆陵關。","策勳禮畢天下泰，猛士按劒看恒山。"]', '["九衢车马渾渾流，使臣来獻淮西囚。","四夷闻风失匕筯，天子受賀登高楼。","妖童擢髪不足數，血污城西一抔土。","南峯無火楚澤闲，夜行不鎖穆陵关。","策勳禮畢天下泰，猛士按劒看恒山。"]', '诗', 'shi', '', NULL, '平蔡州三首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a23157ca-918b-4f3e-a209-ea155dafb11c', '送僧仲剬東遊兼寄呈靈澈上人', '送僧仲剬东游兼寄呈靈澈上人', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["釋子道成神氣閑，住持曾上清涼山。","晴空禮拜見真像，金毛五髻卿雲間。","西遊長安隸僧籍，本寺門前曲江碧。","松間白月照寶書，竹下香泉灑瑤席。","前時學得經論成，奔馳象馬開禪扃。","高筵談柄一麾拂，講下門徒如醉醒。","舊聞南方多長老，次第來入荆門道。","荆州本自重彌天，南朝塔廟猶依然。","宴坐東陽枯樹下，經行居止故臺邊。","忽憶遺民社中客，爲我衡陽駐飛錫。","講罷同尋相鶴經，閑來共蠟登山屐。","一旦揚眉望沃州，自言王謝許同遊。","憑將雜擬三十首，寄與江南湯慧休。"]', '["釋子道成神氣闲，住持曾上清涼山。","晴空禮拜见真像，金毛五髻卿云间。","西游长安隸僧籍，本寺门前曲江碧。","松间白月照寶书，竹下香泉灑瑤席。","前时学得經論成，奔驰象马开禪扃。","高筵談柄一麾拂，講下门徒如醉醒。","旧闻南方多长老，次第来入荆门道。","荆州本自重彌天，南朝塔廟猶依然。","宴坐东陽枯樹下，經行居止故台邊。","忽憶遺民社中客，爲我衡陽駐飞錫。","講罷同尋相鹤經，闲来共蠟登山屐。","一旦揚眉望沃州，自言王謝許同游。","憑將杂擬三十首，寄與江南湯慧休。"]', '诗', 'shi', '', NULL, '送僧仲剬東遊兼寄呈靈澈上人 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34351239-a415-44df-9131-f7f1cc55612b', '觀棋歌送儇師西遊', '观棋歌送儇師西游', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["長沙男子東林師，閑讀藝經工弈棋。","有時凝思如入定，暗覆一局誰能知。","今年訪予來小桂，方袍袖中貯新勢。","山人無事秋日長，白晝懵懵眠匡牀。","因君臨局看鬬智，不覺遲景沈西牆。","自從仙人遇樵子，直到開元王長史。","前身後身付餘習，百變千化無窮已。","初疑磊落曙天星，次見搏擊三秋兵。","鴈行布陳衆未曉，虎穴得子人皆驚。","行盡三湘不逢敵，終日饒人損機格。","自言臺閣有知音，悠然遠起西遊心。","商山夏木陰寂寂，好處俳徊駐飛錫。","忽思爭道畫平沙，獨笑無言心有適。","藹藹京城在九天，貴遊豪士足華筵。","此時一行出人意，賭取聲名不要錢。"]', '["长沙男子东林師，闲读藝經工弈棋。","有时凝思如入定，暗覆一局誰能知。","今年訪予来小桂，方袍袖中貯新勢。","山人無事秋日长，白晝懵懵眠匡牀。","因君臨局看鬬智，不覺遲景沈西牆。","自從仙人遇樵子，直到开元王长史。","前身後身付餘習，百变千化無窮已。","初疑磊落曙天星，次见搏擊三秋兵。","鴈行布陳衆未晓，虎穴得子人皆驚。","行尽三湘不逢敵，終日饒人損機格。","自言台閣有知音，悠然远起西游心。","商山夏木陰寂寂，好处俳徊駐飞錫。","忽思爭道畫平沙，独笑無言心有適。","藹藹京城在九天，貴游豪士足华筵。","此时一行出人意，賭取声名不要錢。"]', '诗', 'shi', '', NULL, '觀棋歌送儇師西遊 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdf49a1c-c6fe-4239-8607-8007bc43bc24', '吐綬鳥詞', '吐綬鸟词', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["越山有鳥翔寥廓，嗉中天綬光若若。","越人偶見而奇之，因名吐綬江南知。","四明天姥神仙地，朱鳥星精鍾異氣。","赤玉彫成彪炳毛，紅綃翦出玲瓏翅。","湖煙始開山日高，迎風吐綬盤花絛。","臨波似染瑯琊草，映葉疑開阿母桃。","花紅草綠人間事，未若靈禽自然貴。","鶴吐明珠暫報恩，鵲銜金印空爲瑞。","春和秋霽野花開，翫景尋芳處處來。","翠幕雕籠非所慕，珠丸柘彈莫相猜。","棲月啼煙凌縹緲，高林先見金霞曉。","三山仙路寄遙情，刷羽揚翹欲上征。","不學碧雞依井絡，願隨青鳥向層城。","太液池中有黃鵠，憐君長向高枝宿。","如何一借羊角風，來聽簫韶九成曲。"]', '["越山有鸟翔寥廓，嗉中天綬光若若。","越人偶见而奇之，因名吐綬江南知。","四明天姥神仙地，朱鸟星精鍾異氣。","赤玉彫成彪炳毛，紅綃翦出玲瓏翅。","湖煙始开山日高，迎风吐綬盤花絛。","臨波似染瑯琊草，映葉疑开阿母桃。","花紅草綠人间事，未若靈禽自然貴。","鹤吐明珠暫報恩，鵲銜金印空爲瑞。","春和秋霽野花开，翫景尋芳处处来。","翠幕雕籠非所慕，珠丸柘彈莫相猜。","棲月啼煙凌縹緲，高林先见金霞晓。","三山仙路寄遙情，刷羽揚翹欲上征。","不学碧雞依井絡，願隨青鸟向層城。","太液池中有黄鵠，怜君长向高枝宿。","如何一借羊角风，来听簫韶九成曲。"]', '诗', 'shi', '', NULL, '吐綬鳥詞 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12f2af31-9401-4281-a410-55843039d6b1', '八月十五日夜桃源翫月', '八月十五日夜桃源翫月', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["塵中見月心亦閑，況是清秋仙府間。","凝光悠悠寒露墜，此時立在最高山。","碧虛無雲風不起，山上長松山下水。","羣動翛然一顧中，天高地平千萬里。","少君引我昇玉壇，禮空遙請真仙官。","雲軿欲下星斗動，天樂一聲肌骨寒。","金霞昕昕漸東上，輪欹影促猶頻望。","絕景良時難再幷，他年此日應惆悵。"]', '["塵中见月心亦闲，況是清秋仙府间。","凝光悠悠寒露墜，此时立在最高山。","碧虛無云风不起，山上长松山下水。","羣动翛然一顧中，天高地平千万里。","少君引我昇玉壇，禮空遙請真仙官。","云軿欲下星斗动，天乐一声肌骨寒。","金霞昕昕漸东上，輪欹影促猶頻望。","絕景良时难再幷，他年此日應惆悵。"]', '诗', 'shi', '', NULL, '八月十五日夜桃源翫月 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df7ccf42-3d7d-4927-a388-43ec90d7ec7b', '送鴻舉遊江[西]', '送鴻舉游江[西]', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["禪客學禪兼學文，出山初似無心雲。","從風卷舒來何處，繚繞巴山不得去。","山州古寺好閑居，讀盡龍王宮裏書。","使君灘頭揀石硯，白帝城邊尋野蔬。","忽然登高心瞥起，又欲浮杯信流水。","煙波浩淼魚鳥情，東去三千三百里。","荆門峽斷無盤渦，湘平漢闊清光多。","廬山霧開見瀑布，江西月淨聞漁歌。","鍾陵八郡多名守，半是西方社中友。","與師相見便談空，想得高齋獅子吼。"]', '["禪客学禪兼学文，出山初似無心云。","從风卷舒来何处，繚繞巴山不得去。","山州古寺好闲居，读尽龙王宮裏书。","使君灘头揀石硯，白帝城邊尋野蔬。","忽然登高心瞥起，又欲浮杯信流水。","煙波浩淼鱼鸟情，东去三千三百里。","荆门峽斷無盤渦，湘平漢闊清光多。","廬山霧开见瀑布，江西月淨闻漁歌。","鍾陵八郡多名守，半是西方社中友。","與師相见便談空，想得高斋獅子吼。"]', '诗', 'shi', '', NULL, '送鴻舉遊江[西] 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba8cd1f5-00f4-4926-a69e-8eedcd3465c6', '採菱行', '採菱行', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["白馬湖平秋日光，紫菱如錦彩鴛翔。","蕩舟遊女滿中央，採菱不顧馬上郎。","爭多逐勝紛相向，時轉蘭橈破輕浪。","長鬟弱袂動參差，釵影釧文浮蕩漾。","笑語哇咬顧晚暉，蓼花緣岸扣舷歸。","歸來共到市橋步，野蔓繫船萍滿衣。","家家竹樓臨廣陌，下有連檣多估客。","攜觴薦芰夜經過，醉踏大隄相應歌。","屈平祠下沅江水，月照寒波白煙起。","一曲南音此地聞，長安北望三千里。"]', '["白马湖平秋日光，紫菱如錦彩鴛翔。","蕩舟游女满中央，採菱不顧马上郎。","爭多逐勝紛相向，时轉蘭橈破轻浪。","长鬟弱袂动參差，釵影釧文浮蕩漾。","笑語哇咬顧晚暉，蓼花緣岸扣舷归。","归来共到市橋步，野蔓繫船萍满衣。","家家竹楼臨廣陌，下有連檣多估客。","携觴薦芰夜經過，醉踏大隄相應歌。","屈平祠下沅江水，月照寒波白煙起。","一曲南音此地闻，长安北望三千里。"]', '诗', 'shi', '', NULL, '採菱行 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81e71dc4-6fb5-4335-bb83-93166ef970aa', '和牛相公溪醉歌見寄', '和牛相公溪醉歌见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["脫屣將相守沖謙，唯於山水獨不廉。","枕伊背洛得勝地，鳴臯少室來軒簷。","相形面勢默指畫，言下變化隨顧瞻。","清池曲榭人所致，野趣幽芳天與添。","有時轉入潭島間，珍木如幄藤爲簾。","忽然便有江湖思，沙礫平淺草纖纖。","怪石釣出太湖底，珠樹移自天台尖。","崇蘭迎風綠泛豔，坼蓮含露紅𧞋襜。","脩廊架空遠岫入，弱柳覆檻流波霑。","渚蒲抽芽劒脊動，岸荻迸笋錐頭銛。","攜觴命侶極永日，此會雖數心無厭。","人皆置莊身不到，富貴難與逍遙兼。","唯公出處得自在，決就放曠辭炎炎。","座賓盡歡恣談謔，媿我掉頭還奮髯。","能令商於多病客，亦覺自適非沈潛。"]', '["脫屣將相守沖謙，唯於山水独不廉。","枕伊背洛得勝地，鳴臯少室来軒簷。","相形面勢默指畫，言下变化隨顧瞻。","清池曲榭人所致，野趣幽芳天與添。","有时轉入潭島间，珍木如幄藤爲簾。","忽然便有江湖思，沙礫平淺草纖纖。","怪石釣出太湖底，珠樹移自天台尖。","崇蘭迎风綠泛豔，坼蓮含露紅𧞋襜。","脩廊架空远岫入，弱柳覆檻流波霑。","渚蒲抽芽劒脊动，岸荻迸笋錐头銛。","携觴命侶極永日，此會雖數心無厭。","人皆置莊身不到，富貴难與逍遙兼。","唯公出处得自在，決就放曠辞炎炎。","座賓尽歡恣談謔，媿我掉头還奮髯。","能令商於多病客，亦覺自適非沈潛。"]', '诗', 'shi', '', NULL, '和牛相公溪醉歌見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a86f9164-209f-4467-8335-0dc990241eff', '和浙西李大夫霜夜對月聽小童吹觱篥歌依本韻', '和浙西李大夫霜夜对月听小童吹觱篥歌依本韻', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["海門雙青暮煙歇，萬頃金波湧明月。","侯家小兒能觱篥，對此清光天性發。","長江凝練樹無風，瀏慄一聲霄漢中。","涵胡畫角怨邊草，蕭瑟清蟬吟野叢。","沖融頓挫心使指，雄吼如風轉如水。","思婦多情珠淚垂，仙禽欲舞雙翅起。","郡人寂聽衣滿霜，江城月斜樓影長。","纔驚指下繁韻息，已見樹杪明星光。","謝公高齋吟激楚，戀闕心同在羈旅。","一奏荆人白雪歌，如聞雒客扶風鄔。","吳門水驛按山陰，文字殷勤寄意深。","欲識陽陶能絕處，少年榮貴道傷心。"]', '["海门雙青暮煙歇，万頃金波湧明月。","侯家小兒能觱篥，对此清光天性發。","长江凝練樹無风，瀏慄一声霄漢中。","涵胡畫角怨邊草，蕭瑟清蟬吟野叢。","沖融頓挫心使指，雄吼如风轉如水。","思婦多情珠泪垂，仙禽欲舞雙翅起。","郡人寂听衣满霜，江城月斜楼影长。","纔驚指下繁韻息，已见樹杪明星光。","謝公高斋吟激楚，戀闕心同在羈旅。","一奏荆人白雪歌，如闻雒客扶风鄔。","吳门水驛按山陰，文字殷勤寄意深。","欲識陽陶能絕处，少年榮貴道傷心。"]', '诗', 'shi', '', NULL, '和浙西李大夫霜夜對月聽小童吹觱篥歌依本韻 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('045f4f0f-2b75-495a-a1db-987d6900874e', '歎水別白二十二', '歎水別白二十二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["水，至清，盡美。","從一勺，至千里。","利人利物，時行時止。","道性淨皆然，交情淡如此。","君遊金谷堤上，我在石渠署裏。","兩心相憶似流波，潺湲日夜無窮已。"]', '["水，至清，尽美。","從一勺，至千里。","利人利物，时行时止。","道性淨皆然，交情淡如此。","君游金谷堤上，我在石渠署裏。","兩心相憶似流波，潺湲日夜無窮已。"]', '诗', 'shi', '', NULL, '歎水別白二十二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46119a54-3e3f-4f72-963e-b53fd23b4d84', '同留守王僕射各賦春中一物從一韻至七', '同留守王僕射各賦春中一物從一韻至七', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鶯，能語，多情。","春將半，天欲明。","始逢南陌，復集東城。","林疎時見影，花密但聞聲。","營中緣催短笛，樓上來定哀箏。","千門萬戶垂楊裏，百轉如簧煙景晴。"]', '["鶯，能語，多情。","春將半，天欲明。","始逢南陌，复集东城。","林疎时见影，花密但闻声。","營中緣催短笛，楼上来定哀箏。","千门万戶垂楊裏，百轉如簧煙景晴。"]', '诗', 'shi', '', NULL, '同留守王僕射各賦春中一物從一韻至七 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('784ead6f-4847-40d7-8d1a-a1c0eedc0066', '傷我馬詞', '傷我马词', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["生於磧礰善馳走，萬里南來困丘阜。","青菰寒菽非適口，病聞北風猶舉首。","金臺已平骨空朽，投之龍淵從爾友。"]', '["生於磧礰善驰走，万里南来困丘阜。","青菰寒菽非適口，病闻北风猶舉首。","金台已平骨空朽，投之龙淵從爾友。"]', '诗', 'shi', '', NULL, '傷我馬詞 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff7a5220-ab0f-455f-bce6-33d84a12d0b1', '清湘詞二首 一', '清湘词二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["湘水流，湘水流，九疑雲物至今愁。","君問二妃何處所，零陵香草雨中收。"]', '["湘水流，湘水流，九疑云物至今愁。","君问二妃何处所，零陵香草雨中收。"]', '诗', 'shi', '', NULL, '清湘詞二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6038218e-598f-426c-b7c6-6f3493876bc7', '清湘詞二首 二', '清湘词二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["斑竹枝，斑竹枝，淚痕點點寄相思。","楚客欲聞瑤瑟怨，瀟湘深夜月明時。"]', '["斑竹枝，斑竹枝，泪痕点点寄相思。","楚客欲闻瑤瑟怨，瀟湘深夜月明时。"]', '诗', 'shi', '', NULL, '清湘詞二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ff97b0c-62c9-47c7-a828-c76a04c0bdbb', '和樂天春詞依憶江南曲拍爲句 一', '和乐天春词依憶江南曲拍爲句 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["春去也，多謝洛城人。","弱柳從風疑舉袂，叢蘭裛露似霑巾，獨坐亦含嚬。"]', '["春去也，多謝洛城人。","弱柳從风疑舉袂，叢蘭裛露似霑巾，独坐亦含嚬。"]', '诗', 'shi', '', NULL, '和樂天春詞依憶江南曲拍爲句 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb372fbc-a9b2-48a7-8d49-23ff0b695a85', '和樂天春詞依憶江南曲拍爲句 二', '和乐天春词依憶江南曲拍爲句 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["春過也，笑惜豔陽年。","猶有桃花流水上，無辭竹葉醉樽前，惟待見青天。"]', '["春過也，笑惜豔陽年。","猶有桃花流水上，無辞竹葉醉樽前，惟待见青天。"]', '诗', 'shi', '', NULL, '和樂天春詞依憶江南曲拍爲句 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6116503-3328-441c-85b4-bf2d1d9ee882', '澤宮詩 一', '澤宮诗 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["秩秩澤宮，有的維鵠。","祁祁庶士，於以干祿。"]', '["秩秩澤宮，有的維鵠。","祁祁庶士，於以干祿。"]', '诗', 'shi', '', NULL, '澤宮詩 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cf3337d-44fc-4b4a-a44b-03f0f80463aa', '澤宮詩 二', '澤宮诗 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["彼鵠斯微，若止若翔。","千里之差，起於毫芒。"]', '["彼鵠斯微，若止若翔。","千里之差，起於毫芒。"]', '诗', 'shi', '', NULL, '澤宮詩 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('604c8586-7abd-41ed-b5be-3240efa688c3', '澤宮詩 三', '澤宮诗 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["我矢既直，我弓既良。","依於高墉，因我不臧。"]', '["我矢既直，我弓既良。","依於高墉，因我不臧。"]', '诗', 'shi', '', NULL, '澤宮詩 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cade1a7a-3f1c-4594-9fb0-42eaeab32e17', '澤宮詩 四', '澤宮诗 四', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["高墉伊何，維器與時。","視之以心，誰謂鵠微。"]', '["高墉伊何，維器與时。","視之以心，誰謂鵠微。"]', '诗', 'shi', '', NULL, '澤宮詩 四 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fbcb3d0-f752-4276-9e20-971e82b36b3e', '酬令狐相公六言見寄', '酬令狐相公六言见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["已嗟別離太遠，更被光陰苦催。","吳苑燕辭人去，汾川鴈帶書來。","愁吟月落猶望，憶夢天明未回。","今日便令歌者，唱兄詩送一杯。"]', '["已嗟別離太远，更被光陰苦催。","吳苑燕辞人去，汾川鴈带书来。","愁吟月落猶望，憶梦天明未回。","今日便令歌者，唱兄诗送一杯。"]', '诗', 'shi', '', NULL, '酬令狐相公六言見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd46e20e-7309-4695-935d-8a90c4f6a0db', '荅樂天臨都驛見贈', '荅乐天臨都驛见贈', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["北固山邊波浪，東都城裏風塵。","世事不同心事，新人何似故人。"]', '["北固山邊波浪，东都城裏风塵。","世事不同心事，新人何似故人。"]', '诗', 'shi', '', NULL, '荅樂天臨都驛見贈 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('226c0600-b0d9-44bc-9992-042ac9579e97', '再贈樂天', '再贈乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["一政政官軋軋，一年年老駸駸。","身外名何足算，別來詩且同吟。"]', '["一政政官軋軋，一年年老駸駸。","身外名何足算，別来诗且同吟。"]', '诗', 'shi', '', NULL, '再贈樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e89ae7e3-795f-464c-9b6b-bd8a6ad653e3', '酬楊侍郎憑見寄', '酬楊侍郎憑见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["十年毛羽催頹，一旦天書召回。","看看瓜時欲到，故侯也好歸來。"]', '["十年毛羽催頹，一旦天书召回。","看看瓜时欲到，故侯也好归来。"]', '诗', 'shi', '', NULL, '酬楊侍郎憑見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c76a826-8bf3-44ee-840b-c3c67231a6fe', '春有情篇', '春有情篇', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["爲問遊春侶，春情何處尋。","花含欲語意，草有鬬生心。","雨頻催發色，雲輕不作陰。","縱令無月夜，芳興暗中深。"]', '["爲问游春侶，春情何处尋。","花含欲語意，草有鬬生心。","雨頻催發色，云轻不作陰。","縱令無月夜，芳兴暗中深。"]', '诗', 'shi', '', NULL, '春有情篇 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01d2faf1-f9c9-4fc3-bc7b-9b1e72d59f2d', '七夕二首 一', '七夕二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["河鼓靈旗動，嫦娥破鏡斜。","滿空天是幕，徐轉斗爲車。","機罷猶安石，橋成不礙槎。","誰知觀津女，竟夕望雲涯。"]', '["河鼓靈旗动，嫦娥破镜斜。","满空天是幕，徐轉斗爲车。","機罷猶安石，橋成不礙槎。","誰知观津女，竟夕望云涯。"]', '诗', 'shi', '', NULL, '七夕二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f28dfaa3-ff90-42e3-923d-63a5635afab8', '七夕二首 二', '七夕二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["天衢啓雲帳，神馭上星橋。","初喜渡河漢，頻驚轉斗杓。","餘霞張錦幛，輕電閃紅綃。","非是人間世，還悲後會遙。"]', '["天衢啓云帳，神馭上星橋。","初喜渡河漢，頻驚轉斗杓。","餘霞張錦幛，轻電閃紅綃。","非是人间世，還悲後會遙。"]', '诗', 'shi', '', NULL, '七夕二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be69c8f7-40a1-4f39-a1a5-e9abe30a24c1', '邊風行', '邊风行', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["邊馬蕭蕭鳴，邊風滿磧生。","暗添弓箭力，斗上鼓鼙聲。","襲月寒暈起，吹雲陰陣成。","將軍占氣候，出號夜翻營。"]', '["邊马蕭蕭鳴，邊风满磧生。","暗添弓箭力，斗上鼓鼙声。","襲月寒暈起，吹云陰陣成。","將軍占氣候，出號夜翻營。"]', '诗', 'shi', '', NULL, '邊風行 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('309e6aa0-2139-4c70-a935-9f98b0bbb56c', '送工部蕭郎中刑部李郎中並以本官兼中丞分命充京西京北覆糧使', '送工部蕭郎中刑部李郎中並以本官兼中丞分命充京西京北覆糧使', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["霜簡映金章，相輝同舍郎。","天威巡虎落，星使出鴛行。","尊俎成全策，京坻閱見糧。","歸來虜塵滅，畫地奏明光。"]', '["霜簡映金章，相輝同舍郎。","天威巡虎落，星使出鴛行。","尊俎成全策，京坻閱见糧。","归来虜塵滅，畫地奏明光。"]', '诗', 'shi', '', NULL, '送工部蕭郎中刑部李郎中並以本官兼中丞分命充京西京北覆糧使 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39679101-7fdc-45ae-a58c-80099b8e007a', '送太常蕭博士棄官歸養赴東都', '送太常蕭博士棄官归養赴东都', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["兄弟盡鴛鸞，歸心切問安。","貪榮五綵服，遂掛兩梁冠。","侍膳曾調鼎，循陔更握蘭。","從今別君後，長憶德星看。"]', '["兄弟尽鴛鸾，归心切问安。","貪榮五綵服，遂掛兩梁冠。","侍膳曾調鼎，循陔更握蘭。","從今別君後，长憶德星看。"]', '诗', 'shi', '', NULL, '送太常蕭博士棄官歸養赴東都 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f37014d2-3c5d-43ac-a441-6832ae1d89bf', '送河南皇甫少尹赴絳州', '送河南皇甫少尹赴絳州', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["祖帳臨周道，前旌指晉城。","午橋羣吏散，亥字老人迎。","詩酒同行樂，別離方見情。","從此洛陽社，吟詠屬書生。"]', '["祖帳臨周道，前旌指晉城。","午橋羣吏散，亥字老人迎。","诗酒同行乐，別離方见情。","從此洛陽社，吟詠屬书生。"]', '诗', 'shi', '', NULL, '送河南皇甫少尹赴絳州 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8db19185-3753-4e89-8a9d-6c4fbe40b98f', '發華州留別張侍御', '發华州留別張侍御', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["束簡下延閣，買符驅短轅。","同人惜分袂，結念醉芳樽。","切切別弦急，蕭蕭征騎煩。","臨岐無限意，相視却忘言。"]', '["束簡下延閣，買符驱短轅。","同人惜分袂，結念醉芳樽。","切切別弦急，蕭蕭征騎煩。","臨岐無限意，相視却忘言。"]', '诗', 'shi', '', NULL, '發華州留別張侍御 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbb8df67-b1cb-4b86-8ea4-ad63fc4bfe97', '奉送家兄歸王屋山隱居二首 一', '奉送家兄归王屋山隐居二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["洛陽天壇上，依稀似玉京。","夜分先見日，月靜遠聞笙。","雲路將雞犬，丹臺有姓名。","古來成道者，兄弟亦同行。"]', '["洛陽天壇上，依稀似玉京。","夜分先见日，月静远闻笙。","云路將雞犬，丹台有姓名。","古来成道者，兄弟亦同行。"]', '诗', 'shi', '', NULL, '奉送家兄歸王屋山隱居二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74a0da61-9487-417a-ac6a-e468c35114a9', '奉送家兄歸王屋山隱居二首 二', '奉送家兄归王屋山隐居二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["春來山事好，歸去亦逍遙。","水淨苔莎色，露香芝朮苗。","登臺吸瑞景，飛步翼神飆。","願薦塤篪曲，相將學玉簫。"]', '["春来山事好，归去亦逍遙。","水淨苔莎色，露香芝朮苗。","登台吸瑞景，飞步翼神飆。","願薦塤篪曲，相將学玉簫。"]', '诗', 'shi', '', NULL, '奉送家兄歸王屋山隱居二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2be36bb1-fc64-4a1c-b627-ceb6eb84a047', '送王師魯協律赴湖南使幕', '送王師魯協律赴湖南使幕', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["翩翩馬上郎，驅傳渡三湘。","橘樹沙洲暗，松醪酒肆香。","素風傳竹帛，高價聘琳瑯。","楚水多蘭芷，何人事搴芳。"]', '["翩翩马上郎，驱傳渡三湘。","橘樹沙洲暗，松醪酒肆香。","素风傳竹帛，高價聘琳瑯。","楚水多蘭芷，何人事搴芳。"]', '诗', 'shi', '', NULL, '送王師魯協律赴湖南使幕 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52119dc8-6af9-49b7-9905-9da1c39360fd', '送趙中丞自司金郎轉官參山南令狐僕射幕府', '送趙中丞自司金郎轉官參山南令狐僕射幕府', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["綠樹滿褒斜，西南蜀路賒。","驛門臨白草，縣道入黃花。","相府開油幕，門生逐絳紗。","行看布政後，還從入京華。"]', '["綠樹满褒斜，西南蜀路賒。","驛门臨白草，縣道入黄花。","相府开油幕，门生逐絳紗。","行看布政後，還從入京华。"]', '诗', 'shi', '', NULL, '送趙中丞自司金郎轉官參山南令狐僕射幕府 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('377feb9c-f041-4601-bb90-03c23352a86f', '送盧處士歸嵩山別業', '送盧处士归嵩山別業', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["世業嵩山隱，雲深無四鄰。","藥爐燒姹女，酒甕貯賢人。","晚日華陰霧，秋風函谷塵。","送君從此去，鈴閣少談賓。"]', '["世業嵩山隐，云深無四鄰。","藥爐燒姹女，酒甕貯賢人。","晚日华陰霧，秋风函谷塵。","送君從此去，鈴閣少談賓。"]', '诗', 'shi', '', NULL, '送盧處士歸嵩山別業 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98a63a38-a99e-4c6d-8a82-efcc5008768e', '洛中送崔司業使君扶侍赴唐州', '洛中送崔司業使君扶侍赴唐州', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["綠野芳城路，殘春柳絮飛。","風鳴驌驦馬，日照老萊衣。","洛苑魚書至，江村鴈戶歸。","相思望淮水，雙鯉不應稀。"]', '["綠野芳城路，殘春柳絮飞。","风鳴驌驦马，日照老萊衣。","洛苑鱼书至，江村鴈戶归。","相思望淮水，雙鯉不應稀。"]', '诗', 'shi', '', NULL, '洛中送崔司業使君扶侍赴唐州 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfda74a7-9e96-48ed-bbd6-b7bcc1af85df', '送李友路秀才赴舉', '送李友路秀才赴舉', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["誰憐相門子，不語望秋山。","生長綺紈內，辛勤筆硯間。","榮親在名字，好學棄官班。","佇俟明年桂，高堂開笑顏。"]', '["誰怜相门子，不語望秋山。","生长綺紈內，辛勤笔硯间。","榮親在名字，好学棄官班。","佇俟明年桂，高堂开笑顏。"]', '诗', 'shi', '', NULL, '送李友路秀才赴舉 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f78dbd2-d34c-414c-b29d-65656729231a', '送從弟郎中赴浙西', '送從弟郎中赴浙西', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["銜命出尚書，新恩換使車。","漢庭無右者，梁苑重歸歟。","又食建業水，曾依京口居。","共經何限事，賓主兩如初。"]', '["銜命出尚书，新恩換使车。","漢庭無右者，梁苑重归歟。","又食建業水，曾依京口居。","共經何限事，賓主兩如初。"]', '诗', 'shi', '', NULL, '送從弟郎中赴浙西 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b85e18f3-6951-49f8-a5f7-6a78f35e37f8', '送元上人歸稽亭', '送元上人归稽亭', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["重疊稽亭路，山僧歸獨行。","遠峰斜日影，本寺舊鐘聲。","徒侶問新事，煙雲愴別情。","應誇乞食處，踏遍鳳凰城。"]', '["重叠稽亭路，山僧归独行。","远峰斜日影，本寺旧鐘声。","徒侶问新事，煙云愴別情。","應誇乞食处，踏遍鳳凰城。"]', '诗', 'shi', '', NULL, '送元上人歸稽亭 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7d05fac-c532-4b7e-9b00-ff54216c5df3', '贈別君素上人詩', '贈別君素上人诗', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["窮巷唯秋草，高僧獨扣門。","相歡如舊識，問法到無言。","水爲風生浪，珠非塵可昏。","悟來皆是道，此別不銷魂。"]', '["窮巷唯秋草，高僧独扣门。","相歡如旧識，问法到無言。","水爲风生浪，珠非塵可昏。","悟来皆是道，此別不銷魂。"]', '诗', 'shi', '', NULL, '贈別君素上人詩 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4b6647b-265f-41c2-ab67-ec867eb5e03a', '送深法師遊南岳', '送深法師游南岳', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["師在白雲鄉，名登善法堂。","十方傳句偈，八部會壇場。","飛錫無定所，寶書留舊房。","唯應銜果鴈，相送至衡陽。"]', '["師在白云乡，名登善法堂。","十方傳句偈，八部會壇場。","飞錫無定所，寶书留旧房。","唯應銜果鴈，相送至衡陽。"]', '诗', 'shi', '', NULL, '送深法師遊南岳 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df751ccc-0157-467b-b525-01c8ee9c0693', '贈別約師', '贈別約師', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["師逢吳興守，相伴住禪扃。","春雨同栽樹，秋燈對講經。","廬山曾結社，桂水遠揚舲。","話舊還惆悵，天南望柳星。"]', '["師逢吳兴守，相伴住禪扃。","春雨同栽樹，秋灯对講經。","廬山曾結社，桂水远揚舲。","話旧還惆悵，天南望柳星。"]', '诗', 'shi', '', NULL, '贈別約師 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('757a180d-55eb-4931-9f10-c71649f6a06d', '秋日過鴻舉法師寺院便送歸江陵', '秋日過鴻舉法師寺院便送归江陵', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["看畫長廊遍，尋僧一徑幽。","小池兼鶴淨，古木帶蟬秋。","客至茶煙起，禽歸講席收。","浮杯明日去，相望水悠悠。"]', '["看畫长廊遍，尋僧一徑幽。","小池兼鹤淨，古木带蟬秋。","客至茶煙起，禽归講席收。","浮杯明日去，相望水悠悠。"]', '诗', 'shi', '', NULL, '秋日過鴻舉法師寺院便送歸江陵 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bba0e13e-b062-4234-bcec-fe616bceb769', '春日退朝', '春日退朝', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["紫陌夜來雨，南山朝下看。","戟枝迎日動，閣影助松寒。","瑞氣轉綃縠，遊光泛波瀾。","御溝新柳色，處處拂歸鞍。"]', '["紫陌夜来雨，南山朝下看。","戟枝迎日动，閣影助松寒。","瑞氣轉綃縠，游光泛波瀾。","御溝新柳色，处处拂归鞍。"]', '诗', 'shi', '', NULL, '春日退朝 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f37297b-77d5-412b-bc73-105bfa4d011d', '蜀先主廟', '蜀先主廟', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["天地英雄氣，千秋尚凜然。","勢分三足鼎，業復五銖錢。","得相能開國，生兒不象賢。","淒涼蜀故妓，來舞魏宮前。"]', '["天地英雄氣，千秋尚凜然。","勢分三足鼎，業复五銖錢。","得相能开国，生兒不象賢。","淒涼蜀故妓，来舞魏宮前。"]', '诗', 'shi', '', NULL, '蜀先主廟 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5df40321-e858-4c40-a91b-c97dc443eb5a', '經東都安國觀九仙公主舊院作', '經东都安国观九仙公主旧院作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["仙院御溝東，今來事不同。","門開青草日，樓閉綠楊風。","將犬昇天路，披雲赴月宮。","武皇曾駐蹕，親問主人翁。"]', '["仙院御溝东，今来事不同。","门开青草日，楼閉綠楊风。","將犬昇天路，披云赴月宮。","武皇曾駐蹕，親问主人翁。"]', '诗', 'shi', '', NULL, '經東都安國觀九仙公主舊院作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bfa0919-c33a-4fd2-a1ee-67cf7f0c4e83', '觀八陣圖', '观八陣圖', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["軒皇傳上略，蜀相運神機。","水落龍蛇出，沙平鵝鸛飛。","波濤無動勢，鱗介避餘威。","會有知兵者，臨流指是非。"]', '["軒皇傳上略，蜀相運神機。","水落龙蛇出，沙平鵝鸛飞。","波濤無动勢，鱗介避餘威。","會有知兵者，臨流指是非。"]', '诗', 'shi', '', NULL, '觀八陣圖 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('477ee8be-062e-41d1-97c3-301165ef61bb', '八月十五日夜翫月', '八月十五日夜翫月', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["天將今夜月，一遍洗寰瀛。","暑退九霄淨，秋澄萬景清。","星辰讓光彩，風露發晶英。","能變人間世，翛然是玉京。"]', '["天將今夜月，一遍洗寰瀛。","暑退九霄淨，秋澄万景清。","星辰讓光彩，风露發晶英。","能变人间世，翛然是玉京。"]', '诗', 'shi', '', NULL, '八月十五日夜翫月 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae2ea063-a899-442d-9a59-27eef726f78f', '太和戊申歲大有年詔賜百僚出城觀秋稼謹書盛事以俟采詩者', '太和戊申歲大有年詔賜百僚出城观秋稼謹书盛事以俟采诗者', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["長安銅雀鳴，秋稼與雲平。","玉燭調寒暑，金風報順成。","川原呈上瑞，恩澤賜閑行。","欲反重城掩，猶聞歌吹聲。"]', '["长安銅雀鳴，秋稼與云平。","玉燭調寒暑，金风報順成。","川原呈上瑞，恩澤賜闲行。","欲反重城掩，猶闻歌吹声。"]', '诗', 'shi', '', NULL, '太和戊申歲大有年詔賜百僚出城觀秋稼謹書盛事以俟采詩者 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d9dad77-234d-4ba2-8402-206d9d7bca67', '金陵懷古', '金陵懷古', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["潮滿冶城渚，日斜征虜亭。","蔡洲新草綠，幕府舊煙青。","興廢由人事，山川空地形。","後庭花一曲，幽怨不堪聽。"]', '["潮满冶城渚，日斜征虜亭。","蔡洲新草綠，幕府旧煙青。","兴廢由人事，山川空地形。","後庭花一曲，幽怨不堪听。"]', '诗', 'shi', '', NULL, '金陵懷古 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdf4338a-51dc-44af-90ef-bbe1e30cd759', '晝居池上亭獨吟', '晝居池上亭独吟', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["日午樹陰正，獨吟池上亭。","靜看蜂教誨，閒想鶴儀形。","法酒調神氣，清琴入性靈。","浩然機已息，几杖復何銘。"]', '["日午樹陰正，独吟池上亭。","静看蜂教誨，閒想鹤儀形。","法酒調神氣，清琴入性靈。","浩然機已息，几杖复何銘。"]', '诗', 'shi', '', NULL, '晝居池上亭獨吟 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fd099d5-42b1-471c-a22d-4f50be11b73e', '分司東都蒙襄陽李司徒相公書問因以奉寄', '分司东都蒙襄陽李司徒相公书问因以奉寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["早忝金馬客，晚爲商洛翁。","知名四海內，多病一生中。","舉世往還盡，何人心事同。","幾時登峴首，恃舊揖三公。"]', '["早忝金马客，晚爲商洛翁。","知名四海內，多病一生中。","舉世往還尽，何人心事同。","幾时登峴首，恃旧揖三公。"]', '诗', 'shi', '', NULL, '分司東都蒙襄陽李司徒相公書問因以奉寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc80d1dc-739b-44cf-a1be-7c017455432c', '門下相公榮加册命天下同歡忝沐眷私輒感申賀', '门下相公榮加册命天下同歡忝沐眷私輒感申賀', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["冊命出宸衷，官儀自古崇。","特膺平土拜，光贊格天功。","再佩扶陽印，常乘鮑氏驄。","七賢遺老在，猶得詠清風。"]', '["冊命出宸衷，官儀自古崇。","特膺平土拜，光贊格天功。","再佩扶陽印，常乘鲍氏驄。","七賢遺老在，猶得詠清风。"]', '诗', 'shi', '', NULL, '門下相公榮加册命天下同歡忝沐眷私輒感申賀 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3de21225-e6fd-4a26-be65-fe25d6ea5e53', '病中一二禪客見問因以謝之', '病中一二禪客见问因以謝之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["勞動諸賢者，同來問病夫。","添爐烹雀舌，灑水淨龍鬚。","身是芭蕉喻，行須筇竹扶。","醫王有妙藥，能乞一丸無。"]', '["勞动諸賢者，同来问病夫。","添爐烹雀舌，灑水淨龙鬚。","身是芭蕉喻，行須筇竹扶。","醫王有妙藥，能乞一丸無。"]', '诗', 'shi', '', NULL, '病中一二禪客見問因以謝之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b64829f8-7516-4872-8439-08a28558ed95', '秋江晚泊', '秋江晚泊', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["長泊起秋色，空江涵霽暉。","暮霞千萬狀，賓鴻次第飛。","古戍見旗逈，荒村聞犬稀。","軻峨艑上客，勸酒夜相依。"]', '["长泊起秋色，空江涵霽暉。","暮霞千万狀，賓鴻次第飞。","古戍见旗逈，荒村闻犬稀。","軻峨艑上客，勸酒夜相依。"]', '诗', 'shi', '', NULL, '秋江晚泊 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18134617-3a61-4d5a-a0c2-3d80b54099f6', '步出武陵東亭臨江寓望', '步出武陵东亭臨江寓望', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鷹至感風候，霜餘變林麓。","孤颿帶日來，寒江轉沙曲。","戍搖旗影動，津晚櫓聲促。","月上彩霞收，漁歌遠相續。"]', '["鷹至感风候，霜餘变林麓。","孤颿带日来，寒江轉沙曲。","戍搖旗影动，津晚櫓声促。","月上彩霞收，漁歌远相續。"]', '诗', 'shi', '', NULL, '步出武陵東亭臨江寓望 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fca5d8bf-885f-487c-85ad-89bebff8e289', '秋日送客至潛水驛', '秋日送客至潛水驛', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["候吏立沙際，田家連竹溪。","楓林社日鼓，茅屋午時雞。","鵲噪晚禾地，蝶飛秋草畦。","驛樓宮樹近，疲馬再三嘶。"]', '["候吏立沙際，田家連竹溪。","楓林社日鼓，茅屋午时雞。","鵲噪晚禾地，蝶飞秋草畦。","驛楼宮樹近，疲马再三嘶。"]', '诗', 'shi', '', NULL, '秋日送客至潛水驛 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8291399e-7492-4563-964b-5da69a8358d6', '湖州崔郎中曹長寄三癖詩自言癖在詩與琴酒其詞逸而高吟詠不足昔柳吳興亭臯隴首之句王融書之白團扇故爲四韻以謝之', '湖州崔郎中曹长寄三癖诗自言癖在诗與琴酒其词逸而高吟詠不足昔柳吳兴亭臯隴首之句王融书之白團扇故爲四韻以謝之', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["視事畫屏中，自稱三癖翁。","管弦泛春渚，旌斾拂晴虹。","酒對青山月，琴韻白蘋風。","會書團扇上，知君文字工。"]', '["視事畫屏中，自稱三癖翁。","管弦泛春渚，旌斾拂晴虹。","酒对青山月，琴韻白蘋风。","會书團扇上，知君文字工。"]', '诗', 'shi', '', NULL, '湖州崔郎中曹長寄三癖詩自言癖在詩與琴酒其詞逸而高吟詠不足昔柳吳興亭臯隴首之句王融書之白團扇故爲四韻以謝之 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfc9c57a-a65f-464d-aa59-b10ab8922873', '爲郎分司寄上都同舍', '爲郎分司寄上都同舍', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["籍通金馬門，家在銅駞陌。","省闥晝無塵，宮樹朝凝碧。","荒街淺深轍，古渡潺湲石。","唯有嵩丘雲，堪誇早朝客。"]', '["籍通金马门，家在銅駞陌。","省闥晝無塵，宮樹朝凝碧。","荒街淺深轍，古渡潺湲石。","唯有嵩丘云，堪誇早朝客。"]', '诗', 'shi', '', NULL, '爲郎分司寄上都同舍 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a17a8071-b012-4749-87ae-34f1ceff1304', '登陝州北樓却憶京師親友', '登陝州北楼却憶京師親友', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["獨上百尺樓，目窮思亦愁。","初日徧露草，野田荒悠悠。","塵息長道白，林清宿煙收。","回首雲深處，永懷鄉舊遊。"]', '["独上百尺楼，目窮思亦愁。","初日徧露草，野田荒悠悠。","塵息长道白，林清宿煙收。","回首云深处，永懷乡旧游。"]', '诗', 'shi', '', NULL, '登陝州北樓却憶京師親友 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69ff1ba3-3359-48cb-81de-aa79ea8e8206', '途中早發', '途中早發', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["中庭望啓明，促促事晨征。","寒樹鳥初動，霜橋人未行。","水流白煙起，日上彩霞生。","隱士應高枕，無人問姓名。"]', '["中庭望啓明，促促事晨征。","寒樹鸟初动，霜橋人未行。","水流白煙起，日上彩霞生。","隐士應高枕，無人问姓名。"]', '诗', 'shi', '', NULL, '途中早發 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('651722dd-f3fc-479a-9392-5c09c55c513e', '陝州河亭陪韋五大夫雪後眺望因以留別與韋有布衣之舊一別二紀經遷貶而歸', '陝州河亭陪韋五大夫雪後眺望因以留別與韋有布衣之旧一別二紀經遷貶而归', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["雪霽太陽津，城池表裏春。","河流添馬頰，原色動龍鱗。","萬里獨歸客，一杯逢故人。","登高向西望，關路正飛塵。"]', '["雪霽太陽津，城池表裏春。","河流添马頰，原色动龙鱗。","万里独归客，一杯逢故人。","登高向西望，关路正飞塵。"]', '诗', 'shi', '', NULL, '陝州河亭陪韋五大夫雪後眺望因以留別與韋有布衣之舊一別二紀經遷貶而歸 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a154e82e-209c-43b1-8f31-dc81252bc17a', '城東閑遊', '城东闲游', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["借問池臺主，多居要路津。","千金買絕境，永日屬閑人。","竹徑縈紆入，花林委曲巡。","斜陽衆客散，空鎖一園春。"]', '["借问池台主，多居要路津。","千金買絕境，永日屬闲人。","竹徑縈紆入，花林委曲巡。","斜陽衆客散，空鎖一园春。"]', '诗', 'shi', '', NULL, '城東閑遊 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('affaf4b2-bac5-4b35-b1c6-67dbd0176844', '罷郡歸洛陽閑居', '罷郡归洛陽闲居', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["十年江海守，旦夕有歸心。","及此西還日，空成東武吟。","花間數杯酒，月下一張琴。","聞說功名事，依前惜寸陰。"]', '["十年江海守，旦夕有归心。","及此西還日，空成东武吟。","花间數杯酒，月下一張琴。","闻说功名事，依前惜寸陰。"]', '诗', 'shi', '', NULL, '罷郡歸洛陽閑居 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dc5ae3a-b7b8-4d31-bdbd-f423e81d63fe', '晚泊牛渚', '晚泊牛渚', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["蘆葦晚風起，秋江鱗甲生。","殘霞忽變色，遊雁有餘聲。","戍鼓音響絕，漁家燈火明。","無人能詠史，獨自月中行。"]', '["蘆葦晚风起，秋江鱗甲生。","殘霞忽变色，游雁有餘声。","戍鼓音响絕，漁家灯火明。","無人能詠史，独自月中行。"]', '诗', 'shi', '', NULL, '晚泊牛渚 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd3a0a24-fd2c-4aa9-86d9-ff08f158bb61', '宿誠禪師山房題贈二首 一', '宿誠禪師山房題贈二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["宴坐白雲端，清江直下看。","來人望金剎，講席繞香壇。","虎嘯夜林動，鼉鳴秋澗寒。","衆音徒起滅，心在淨中觀。"]', '["宴坐白云端，清江直下看。","来人望金剎，講席繞香壇。","虎嘯夜林动，鼉鳴秋澗寒。","衆音徒起滅，心在淨中观。"]', '诗', 'shi', '', NULL, '宿誠禪師山房題贈二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccd37b05-c9c1-4085-b280-bf755a2b93bd', '宿誠禪師山房題贈二首 二', '宿誠禪師山房題贈二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["不出孤峰上，人間四十秋。","視身如傳舍，閱世似東流。","法爲因緣立，心從次第修。","中宵問真偈，有住是吾憂。"]', '["不出孤峰上，人间四十秋。","視身如傳舍，閱世似东流。","法爲因緣立，心從次第修。","中宵问真偈，有住是吾憂。"]', '诗', 'shi', '', NULL, '宿誠禪師山房題贈二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf3fdab8-8806-4955-94fc-b6c7c2fa2714', '贈澧州高大夫司馬霞[寓]', '贈澧州高大夫司马霞[寓]', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["前年牧錦城，馬蹋血泥行。","千里追戎首，三軍許勇名。","殘兵疑鶴唳，空壘辯烏聲。","一誤雲中級，南遊湘水清。"]', '["前年牧錦城，马蹋血泥行。","千里追戎首，三軍許勇名。","殘兵疑鹤唳，空壘辯烏声。","一誤云中級，南游湘水清。"]', '诗', 'shi', '', NULL, '贈澧州高大夫司馬霞[寓] 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e702c6f-2cdb-4070-8e93-0f4396404340', '聞董評事疾因以書贈', '闻董評事疾因以书贈', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["繁露傳家學，青蓮譯梵書。","火風乖四大，文字廢三餘。","欹枕晝眠靜，折巾秋鬢疎。","武皇思視草，誰許茂陵居。"]', '["繁露傳家学，青蓮譯梵书。","火风乖四大，文字廢三餘。","欹枕晝眠静，折巾秋鬢疎。","武皇思視草，誰許茂陵居。"]', '诗', 'shi', '', NULL, '聞董評事疾因以書贈 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbdd1bd4-58ea-4bd4-a64c-40654f818387', '詠庭梅寄人', '詠庭梅寄人', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["蚤花常犯寒，繁實常苦酸。","何事上春日，坐令芳意闌。","夭桃定相笑，遊妓肯回看。","君問調金鼎，方知正味難。"]', '["蚤花常犯寒，繁實常苦酸。","何事上春日，坐令芳意闌。","夭桃定相笑，游妓肯回看。","君问調金鼎，方知正味难。"]', '诗', 'shi', '', NULL, '詠庭梅寄人 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52efece3-c660-4d9f-9f29-6f22f94cfdc0', '德宗神武孝文皇帝挽歌二首 一', '德宗神武孝文皇帝挽歌二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["出震清多難，乘時播大鈞。","操弦調六氣，揮翰動三辰。","運偶升天日，哀深率土人。","瑤池無轍迹，誰見屬車塵。"]', '["出震清多难，乘时播大鈞。","操弦調六氣，揮翰动三辰。","運偶升天日，哀深率土人。","瑤池無轍迹，誰见屬车塵。"]', '诗', 'shi', '', NULL, '德宗神武孝文皇帝挽歌二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57dd887c-0f37-4c92-99d0-8adc6af9f64e', '德宗神武孝文皇帝挽歌二首 二', '德宗神武孝文皇帝挽歌二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鳳翣擁銘旌，威遲異吉行。","漢儀陳祕器，楚挽咽繁聲。","駐綍辭清廟，凝笳背直城。","唯應留內傳，知是向蓬瀛。"]', '["鳳翣擁銘旌，威遲異吉行。","漢儀陳祕器，楚挽咽繁声。","駐綍辞清廟，凝笳背直城。","唯應留內傳，知是向蓬瀛。"]', '诗', 'shi', '', NULL, '德宗神武孝文皇帝挽歌二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9350c47a-7dd4-4190-9fde-9bb9610b6a90', '敬宗睿武昭愍孝皇帝挽歌三首 一', '敬宗睿武昭愍孝皇帝挽歌三首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["寶曆方無限，仙期忽有涯。","事親崇漢禮，傳聖法殷家。","晚出芙蓉闕，春歸棠棣華。","玉輪今日動，不是畫雲車。"]', '["寶曆方無限，仙期忽有涯。","事親崇漢禮，傳聖法殷家。","晚出芙蓉闕，春归棠棣华。","玉輪今日动，不是畫云车。"]', '诗', 'shi', '', NULL, '敬宗睿武昭愍孝皇帝挽歌三首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84c3e8ec-51c4-408a-b93f-a56ad1360586', '敬宗睿武昭愍孝皇帝挽歌三首 二', '敬宗睿武昭愍孝皇帝挽歌三首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["任賢勞夢寐，登位富春秋。","欲遂東人幸，寧虞杞國憂。","長楊收羽騎，太液泊龍舟。","惟有衣冠在，年年愴月遊。"]', '["任賢勞梦寐，登位富春秋。","欲遂东人幸，寧虞杞国憂。","长楊收羽騎，太液泊龙舟。","惟有衣冠在，年年愴月游。"]', '诗', 'shi', '', NULL, '敬宗睿武昭愍孝皇帝挽歌三首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33d1a0e5-d26e-4ce3-b35c-79be07c28450', '敬宗睿武昭愍孝皇帝挽歌三首 三', '敬宗睿武昭愍孝皇帝挽歌三首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["講學金華殿，親畊鉤盾田。","侍臣容諫獵，方士信求仙。","虹影俄侵日，龍髯不上天。","空餘水銀海，長照夜燈前。"]', '["講学金华殿，親畊鉤盾田。","侍臣容諫獵，方士信求仙。","虹影俄侵日，龙髯不上天。","空餘水銀海，长照夜灯前。"]', '诗', 'shi', '', NULL, '敬宗睿武昭愍孝皇帝挽歌三首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bbc2f50-f732-42f4-b416-7f70d5c5734b', '文宗元聖昭獻孝皇帝挽歌三首', '文宗元聖昭獻孝皇帝挽歌三首', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["繼體三才理，承顏九族親。","禹功留海內，殷曆付天倫。","調露曲常在，秋風詞尚新。","本支方百代，先讓棣華春。"]', '["繼體三才理，承顏九族親。","禹功留海內，殷曆付天倫。","調露曲常在，秋风词尚新。","本支方百代，先讓棣华春。"]', '诗', 'shi', '', NULL, '文宗元聖昭獻孝皇帝挽歌三首 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('882882b6-5458-402b-af71-7cc2de48e0af', '文宗元聖昭獻孝皇帝挽歌三首 二', '文宗元聖昭獻孝皇帝挽歌三首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["月落宮車動，風淒儀杖閑。","路唯瞻鳳翣，人尚想龍顏。","御宇方無事，乘雲遂不還。","聖情悲望處，沈日下西山。"]', '["月落宮车动，风淒儀杖闲。","路唯瞻鳳翣，人尚想龙顏。","御宇方無事，乘云遂不還。","聖情悲望处，沈日下西山。"]', '诗', 'shi', '', NULL, '文宗元聖昭獻孝皇帝挽歌三首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5edf990-6bc6-48a5-a0c9-79c2c963297f', '文宗元聖昭獻孝皇帝挽歌三首 三', '文宗元聖昭獻孝皇帝挽歌三首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["享國十五載，升天千萬年。","龍鑣仙路遠，騎吹禮容全。","日下初陵外，人悲舊劒前。","周南有遺老，掩淚望秦川。"]', '["享国十五載，升天千万年。","龙鑣仙路远，騎吹禮容全。","日下初陵外，人悲旧劒前。","周南有遺老，掩泪望秦川。"]', '诗', 'shi', '', NULL, '文宗元聖昭獻孝皇帝挽歌三首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c280b65-7f21-4058-933e-dc644e22f2a6', '故相國燕國公于司空挽歌二首 一', '故相国燕国公于司空挽歌二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["彫弓封舊國，黑弰繼前功。","十年鎮南雍，九命作司空。","池臺樂事盡，簫鼓葬儀雄。","一代英豪氣，曉散白楊風。"]', '["彫弓封旧国，黑弰繼前功。","十年鎮南雍，九命作司空。","池台乐事尽，簫鼓葬儀雄。","一代英豪氣，晓散白楊风。"]', '诗', 'shi', '', NULL, '故相國燕國公于司空挽歌二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a83ef72-79a5-4bcd-b4a9-bae51a497714', '故相國燕國公于司空挽歌二首 二', '故相国燕国公于司空挽歌二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["陰山貴公子，來葬五陵西。","前馬悲無主，猶帶朔風嘶。","漢水晉山郭，襄楊白銅鞮。","至今有遺愛，日暮人悽悽。"]', '["陰山貴公子，来葬五陵西。","前马悲無主，猶带朔风嘶。","漢水晉山郭，襄楊白銅鞮。","至今有遺愛，日暮人悽悽。"]', '诗', 'shi', '', NULL, '故相國燕國公于司空挽歌二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a5d127e-39f7-4383-806b-6f19581136e4', '傷丘中丞', '傷丘中丞', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鄴下殺才子，蒼茫冤氣凝。","枯楊映漳水，野火上西陵。","馬鬣今無所，龍門昔共登。","何人爲弔客，唯是有青蠅。"]', '["鄴下殺才子，蒼茫冤氣凝。","枯楊映漳水，野火上西陵。","马鬣今無所，龙门昔共登。","何人爲弔客，唯是有青蠅。"]', '诗', 'shi', '', NULL, '傷丘中丞 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5ba89b2-38fe-4f53-a229-99f1448e1ae8', '河南觀察使故相國袁公挽歌三首 一', '河南观察使故相国袁公挽歌三首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["五驅龍虎節，一入鳳凰池。","令尹自無喜，羊公人不疑。","天歸京兆日，葉下洞庭時。","湘水秋風至，淒涼吹素旗。"]', '["五驱龙虎節，一入鳳凰池。","令尹自無喜，羊公人不疑。","天归京兆日，葉下洞庭时。","湘水秋风至，淒涼吹素旗。"]', '诗', 'shi', '', NULL, '河南觀察使故相國袁公挽歌三首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d01c7b7-2e9e-432b-a818-46db0490b207', '河南觀察使故相國袁公挽歌三首 二', '河南观察使故相国袁公挽歌三首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["丹旐發江臯，人悲雁亦號。","湘南罷亥市，漢上改詞曹。","表墓雙碑立，尊名一字褒。","嘗聞平楚獄，爲報里門高。"]', '["丹旐發江臯，人悲雁亦號。","湘南罷亥市，漢上改词曹。","表墓雙碑立，尊名一字褒。","嘗闻平楚獄，爲報里门高。"]', '诗', 'shi', '', NULL, '河南觀察使故相國袁公挽歌三首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43a39cc2-6a8c-45ff-97ee-e40f2f21bcc0', '河南觀察使故相國袁公挽歌三首 三', '河南观察使故相国袁公挽歌三首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["返葬三千里，荆衡達帝畿。","逢人即故吏，拜奠盡沾衣。","地得青烏相，賓驚白鶴飛。","五公碑尚在，今日亦同歸。"]', '["返葬三千里，荆衡達帝畿。","逢人即故吏，拜奠尽沾衣。","地得青烏相，賓驚白鹤飞。","五公碑尚在，今日亦同归。"]', '诗', 'shi', '', NULL, '河南觀察使故相國袁公挽歌三首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('808c6e7d-e6cd-4d42-b249-9a5f8353cf18', '哭王僕射相公', '哭王僕射相公', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["子侯一日病，滕公千載歸。","門庭愴已變，風物澹無輝。","羣吏謁新府，舊賓沾素衣。","歌堂忽暮哭，賀雀盡驚飛。"]', '["子侯一日病，滕公千載归。","门庭愴已变，风物澹無輝。","羣吏謁新府，旧賓沾素衣。","歌堂忽暮哭，賀雀尽驚飞。"]', '诗', 'shi', '', NULL, '哭王僕射相公 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40e0ee9c-cf5c-4c1e-a189-1d8dc67b71a5', '傷韋賓客', '傷韋賓客', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["韋公八十餘，位至六尚書。","五福唯無富，一生誰得如。","桂枝攀最久，蘭省出仍初。","海內時流盡，何人動素車。"]', '["韋公八十餘，位至六尚书。","五福唯無富，一生誰得如。","桂枝攀最久，蘭省出仍初。","海內时流尽，何人动素车。"]', '诗', 'shi', '', NULL, '傷韋賓客 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a29d1e76-453c-4d3a-85f4-17c9d2f8f1fb', '再經故元九相公宅池上作', '再經故元九相公宅池上作', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["故池春又至，一到一傷情。","雁鶩羣猶下，蛙螟衣已生。","竹叢身後長，臺勢雨來傾。","六尺孤安在，人間未有名。"]', '["故池春又至，一到一傷情。","雁鶩羣猶下，蛙螟衣已生。","竹叢身後长，台勢雨来傾。","六尺孤安在，人间未有名。"]', '诗', 'shi', '', NULL, '再經故元九相公宅池上作 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3153881d-954a-4daa-a62e-ce93e15f1405', '請告東歸發灞橋却寄諸僚友', '請告东归發灞橋却寄諸僚友', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["征徒出灞涘，回首傷如何。","故人雲雨散，滿目山川多。","行車無停軌，流景同迅波。","前歡漸成昔，感歎益勞歌。"]', '["征徒出灞涘，回首傷如何。","故人云雨散，满目山川多。","行车無停軌，流景同迅波。","前歡漸成昔，感歎益勞歌。"]', '诗', 'shi', '', NULL, '請告東歸發灞橋却寄諸僚友 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cc26a48-6f8a-44f9-8183-6b1a9859fd2d', '初至長安', '初至长安', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["左遷凡二紀，重見帝城春。","老大歸朝客，平安出嶺人。","每行經舊處，却想似前身。","不改南山色，其餘事事新。"]', '["左遷凡二紀，重见帝城春。","老大归朝客，平安出嶺人。","每行經旧处，却想似前身。","不改南山色，其餘事事新。"]', '诗', 'shi', '', NULL, '初至長安 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03f1917c-1bd3-4e31-a444-8fdb6b408f0f', '歲杪將發楚州呈樂天', '歲杪將發楚州呈乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["楚澤雪初霽，楚城春欲歸。","清淮變寒色，遠樹含清暉。","原野已多思，風霜潛減威。","與君同旅雁，北向刷毛衣。"]', '["楚澤雪初霽，楚城春欲归。","清淮变寒色，远樹含清暉。","原野已多思，风霜潛減威。","與君同旅雁，北向刷毛衣。"]', '诗', 'shi', '', NULL, '歲杪將發楚州呈樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e6a8523-3ce5-4647-93f9-136b9ac18cba', '鶴歎二首 一', '鹤歎二首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["寂寞一雙鶴，主人在西京。","故巢吳苑樹，深院洛陽城。","徐引竹間步，遠含雲外情。","誰憐好風月，鄰舍夜吹笙。"]', '["寂寞一雙鹤，主人在西京。","故巢吳苑樹，深院洛陽城。","徐引竹间步，远含云外情。","誰怜好风月，鄰舍夜吹笙。"]', '诗', 'shi', '', NULL, '鶴歎二首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca7f10d2-31f1-47f5-a043-ed93b15c951c', '鶴歎二首 二', '鹤歎二首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["丹頂宜承日，霜翎不染泥。","愛池能久立，看月未成棲。","一院春草長，三山歸路迷。","主人朝謁早，貪養汝南雞。"]', '["丹頂宜承日，霜翎不染泥。","愛池能久立，看月未成棲。","一院春草长，三山归路迷。","主人朝謁早，貪養汝南雞。"]', '诗', 'shi', '', NULL, '鶴歎二首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb68efa3-9758-4ac2-927c-a0985c84acad', '答白刑部聞新蟬', '答白刑部闻新蟬', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["蟬聲未發前，已自感流年。","一入淒涼耳，如聞斷續弦。","晴清依露葉，晚急畏霞天。","何事秋卿詠，逢時亦悄然。"]', '["蟬声未發前，已自感流年。","一入淒涼耳，如闻斷續弦。","晴清依露葉，晚急畏霞天。","何事秋卿詠，逢时亦悄然。"]', '诗', 'shi', '', NULL, '答白刑部聞新蟬 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ead35b67-5ff2-46d8-92bf-c93eae090b11', '和裴相公寄白侍郎求雙鶴', '和裴相公寄白侍郎求雙鹤', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["皎皎華亭鶴，來隨太守船。","青雲意長在，滄海別經年。","留滯清洛苑，裴回明月天。","何如鳳池上，雙舞入祥煙。"]', '["皎皎华亭鹤，来隨太守船。","青云意长在，滄海別經年。","留滯清洛苑，裴回明月天。","何如鳳池上，雙舞入祥煙。"]', '诗', 'shi', '', NULL, '和裴相公寄白侍郎求雙鶴 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaf62ace-7464-47ef-a354-f952b9e2d2a9', '終南秋雪', '終南秋雪', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["南嶺見秋雪，千門生早寒。","閑時駐馬望，高處卷簾看。","霧散瓊枝出，日斜鉛粉殘。","偏宜曲江上，倒影入清瀾。"]', '["南嶺见秋雪，千门生早寒。","闲时駐马望，高处卷簾看。","霧散瓊枝出，日斜鉛粉殘。","偏宜曲江上，倒影入清瀾。"]', '诗', 'shi', '', NULL, '終南秋雪 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('447b1e07-20c7-4af4-ac7d-4e2c8168f37c', '和樂天早寒', '和乐天早寒', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["雨引苔侵壁，風驅葉擁堦。","久留閑客話，宿請老僧齋。","酒甕新陳接，書籤次第排。","翛然自有處，搖落不傷懷。"]', '["雨引苔侵壁，风驱葉擁堦。","久留闲客話，宿請老僧斋。","酒甕新陳接，书籤次第排。","翛然自有处，搖落不傷懷。"]', '诗', 'shi', '', NULL, '和樂天早寒 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8a38448-cb8f-4fed-8ee5-d1f77ad3ac17', '曲江春望', '曲江春望', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鳳城煙雨歇，萬象含佳氣。","酒後人倒狂，花時天似醉。","三春車馬客，一代繁華地。","何事獨傷懷，少年曾得意。"]', '["鳳城煙雨歇，万象含佳氣。","酒後人倒狂，花时天似醉。","三春车马客，一代繁华地。","何事独傷懷，少年曾得意。"]', '诗', 'shi', '', NULL, '曲江春望 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d109931b-6121-42ea-80d9-f8c53c0cef04', '同樂天和微之深春二十首 一', '同乐天和微之深春二十首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深萬乘家。","宮門皆映柳，輦路盡穿花。","池色連天漢，城形象帝車。","旌旗暖風裏，獵獵向西斜。"]', '["何处深春好，春深万乘家。","宮门皆映柳，輦路尽穿花。","池色連天漢，城形象帝车。","旌旗暖风裏，獵獵向西斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23b288e3-01d9-4688-8f00-8572431a2819', '同樂天和微之深春二十首 二', '同乐天和微之深春二十首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深阿母家。","瑤池長不夜，珠樹正開花。","橋峻通星渚，樓暄近日車。","層城十二闕，相對日西斜。"]', '["何处深春好，春深阿母家。","瑤池长不夜，珠樹正开花。","橋峻通星渚，楼暄近日车。","層城十二闕，相对日西斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7da7530a-7033-43b3-90e3-f37c6baa5bd8', '同樂天和微之深春二十首 三', '同乐天和微之深春二十首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深執政家。","恩光貪捧日，貴重不看花。","玉饌堂交印，沙隄柱礙車。","多門一已閉，直道更無斜。"]', '["何处深春好，春深執政家。","恩光貪捧日，貴重不看花。","玉饌堂交印，沙隄柱礙车。","多门一已閉，直道更無斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8534811a-5ddc-4cb6-aca7-74939e9c2676', '同樂天和微之深春二十首 四', '同乐天和微之深春二十首 四', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深大鎮家。","前旌光照日，後騎蹙成花。","節院收衙隊，毬場簇看車。","廣筵歌舞散，書號夕陽斜。"]', '["何处深春好，春深大鎮家。","前旌光照日，後騎蹙成花。","節院收衙隊，毬場簇看车。","廣筵歌舞散，书號夕陽斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 四 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3317e361-b45c-40b1-82e6-ce523ee6d424', '同樂天和微之深春二十首 五', '同乐天和微之深春二十首 五', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深貴戚家。","櫪嘶無價馬，庭發有名花。","欲進宮人食，先薰命婦車。","晚歸長帶酒，冠蓋任傾斜。"]', '["何处深春好，春深貴戚家。","櫪嘶無價马，庭發有名花。","欲進宮人食，先薰命婦车。","晚归长带酒，冠蓋任傾斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 五 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db700e6b-5b2f-4354-9295-aafa4fdac50e', '同樂天和微之深春二十首 六', '同乐天和微之深春二十首 六', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深恩澤家。","爐添龍腦炷，綬結虎頭花。","賓客珠成履，嬰孩錦縛車。","畫堂簾幕外，來去燕飛斜。"]', '["何处深春好，春深恩澤家。","爐添龙腦炷，綬結虎头花。","賓客珠成履，嬰孩錦縛车。","畫堂簾幕外，来去燕飞斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 六 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('beb2f202-2c2e-429e-bada-58d23707883f', '同樂天和微之深春二十首 七', '同乐天和微之深春二十首 七', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深京兆家。","人眉新柳葉，馬色醉桃花。","盜息無鳴鼓，朝回自走車。","能令帝城外，不敢逕由斜。"]', '["何处深春好，春深京兆家。","人眉新柳葉，马色醉桃花。","盜息無鳴鼓，朝回自走车。","能令帝城外，不敢逕由斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 七 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72a19fe4-7b5e-4285-9bf8-4d2812f89675', '同樂天和微之深春二十首 八', '同乐天和微之深春二十首 八', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深刺史家。","夜闌猶命樂，雨甚亦尋花。","傲客多憑酒，新姬苦上車。","公門吏散後，風擺戟衣斜。"]', '["何处深春好，春深刺史家。","夜闌猶命乐，雨甚亦尋花。","傲客多憑酒，新姬苦上车。","公门吏散後，风擺戟衣斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 八 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72ea76eb-c624-4e9d-b791-4b8438c18605', '同樂天和微之深春二十首 九', '同乐天和微之深春二十首 九', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深羽客家。","芝田繞舍色，杏樹滿山花。","雲是淮王宅，風爲列子車。","古壇操簡處，一逕入林斜。"]', '["何处深春好，春深羽客家。","芝田繞舍色，杏樹满山花。","云是淮王宅，风爲列子车。","古壇操簡处，一逕入林斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 九 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdf6e3ff-c80d-438c-9d6d-a03d4b5d6230', '同樂天和微之深春二十首 十', '同乐天和微之深春二十首 十', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深小隱家。","芟庭留野菜，撼樹去狂花。","醉酒一千日，貯書三十車。","雉衣從露體，不敢有餘斜。"]', '["何处深春好，春深小隐家。","芟庭留野菜，撼樹去狂花。","醉酒一千日，貯书三十车。","雉衣從露體，不敢有餘斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 十 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68bab652-e497-471f-8e4e-eb48eb6fb6ee', '同樂天和微之深春二十首 十一', '同乐天和微之深春二十首 十一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深富室家。","唯多貯金帛，不擬負鶯花。","國樂呼連轡，行廚載滿車。","歸來看理曲，燈下寶釵斜。"]', '["何处深春好，春深富室家。","唯多貯金帛，不擬負鶯花。","国乐呼連轡，行廚載满车。","归来看理曲，灯下寶釵斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 十一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('243fae53-1b7d-41c1-a052-1f8daa6d7e48', '同樂天和微之深春二十首 十二', '同乐天和微之深春二十首 十二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深豪士家。","多沽味濃酒，貴買色深花。","已臂鷹隨馬，連催妓上車。","城南踏青處，村落逐原斜。"]', '["何处深春好，春深豪士家。","多沽味濃酒，貴買色深花。","已臂鷹隨马，連催妓上车。","城南踏青处，村落逐原斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 十二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61e989b9-18bd-491a-abbc-a64c45061b27', '同樂天和微之深春二十首 十三', '同乐天和微之深春二十首 十三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深貴胄家。","迎呼偏熟客，揀選最多花。","飲饌開華幄，笙歌出鈿車。","興酣罇易罄，連瀉酒瓶斜。"]', '["何处深春好，春深貴胄家。","迎呼偏熟客，揀選最多花。","饮饌开华幄，笙歌出鈿车。","兴酣罇易罄，連瀉酒瓶斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 十三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19cd6d1c-fd8c-4d74-a79d-6177b72c1b3e', '同樂天和微之深春二十首 十四', '同乐天和微之深春二十首 十四', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深唱第家。","名傳一紙榜，興管九衢花。","薦聽諸侯樂，來隨計吏車。","杏園拋曲處，揮袖向風斜。"]', '["何处深春好，春深唱第家。","名傳一紙榜，兴管九衢花。","薦听諸侯乐，来隨計吏车。","杏园拋曲处，揮袖向风斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 十四 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7ec76b2-0a7d-4769-828a-451d5775f2bf', '同樂天和微之深春二十首 十五', '同乐天和微之深春二十首 十五', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深少婦家。","能偷新禁曲，自剪入時花。","追逐同遊伴，平章貴價車。","從來不墮馬，故譴髻鬟斜。"]', '["何处深春好，春深少婦家。","能偷新禁曲，自剪入时花。","追逐同游伴，平章貴價车。","從来不墮马，故譴髻鬟斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 十五 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d842e734-ca12-43de-a4ea-b7b48c2ff1fd', '同樂天和微之深春二十首 十六', '同乐天和微之深春二十首 十六', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深幼女家。","雙鬟梳頂髻，兩面繡帬花。","妝壞頻臨鏡，身輕不占車。","鞦韆爭次第，牽拽綵繩斜。"]', '["何处深春好，春深幼女家。","雙鬟梳頂髻，兩面繡帬花。","妝壞頻臨镜，身轻不占车。","鞦韆爭次第，牽拽綵繩斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 十六 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('379d9a4d-c126-44e6-b632-f4d45ad8111f', '同樂天和微之深春二十首 十七', '同乐天和微之深春二十首 十七', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深蘭若家。","當香收柏葉，養蜜近梨花。","野逕宜行樂，遊人盡駐車。","菜園籬落短，遙見桔槔斜。"]', '["何处深春好，春深蘭若家。","當香收柏葉，養蜜近梨花。","野逕宜行乐，游人尽駐车。","菜园籬落短，遙见桔槔斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 十七 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7c21de5-b9f7-40e9-9e86-4a6bb501ad72', '同樂天和微之深春二十首 十八', '同乐天和微之深春二十首 十八', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深老宿家。","小欄圍蕙草，高架引藤花。","四字香書印，三乘壁畫車。","遲回聽句偈，雙樹晚陰斜。"]', '["何处深春好，春深老宿家。","小欄圍蕙草，高架引藤花。","四字香书印，三乘壁畫车。","遲回听句偈，雙樹晚陰斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 十八 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6af1ead-26f2-4762-9cea-bd841de31686', '同樂天和微之深春二十首 十九', '同乐天和微之深春二十首 十九', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處深春好，春深種蒔家。","分畦十字水，接樹兩般花。","櫛比栽籬槿，咿啞轉井車。","可憐高處望，棊布不曾斜。"]', '["何处深春好，春深種蒔家。","分畦十字水，接樹兩般花。","櫛比栽籬槿，咿啞轉井车。","可怜高处望，棊布不曾斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 十九 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80ce1d3d-d35a-427f-b85b-db8923949c05', '同樂天和微之深春二十首 二十', '同乐天和微之深春二十首 二十', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["何處春深好，春深稚子家。","爭騎一竿竹，偷折四鄰花。","笑擊羊皮鼓，行牽犢頷車。","中庭貪夜戲，不覺玉繩斜。"]', '["何处春深好，春深稚子家。","爭騎一竿竹，偷折四鄰花。","笑擊羊皮鼓，行牽犢頷车。","中庭貪夜戲，不覺玉繩斜。"]', '诗', 'shi', '', NULL, '同樂天和微之深春二十首 二十 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d7e40d7-86c3-49dd-9949-dc6291a41185', '贈眼醫婆羅門僧', '贈眼醫婆羅门僧', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["三秋傷望眼，終日哭途窮。","兩目今先暗，中年似老翁。","看朱漸成碧，羞日不禁風。","師有金篦術，如何爲發蒙。"]', '["三秋傷望眼，終日哭途窮。","兩目今先暗，中年似老翁。","看朱漸成碧，羞日不禁风。","師有金篦術，如何爲發蒙。"]', '诗', 'shi', '', NULL, '贈眼醫婆羅門僧 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ab5e94e-0af0-4eb7-aebe-94952155bc06', '海門潮別浩初師', '海门潮別浩初師', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["前日過蕭寺，看師上講筵。","都人禮白足，施者散金錢。","方便無非教，經行不廢禪。","還知習居士，發論侍彌天。"]', '["前日過蕭寺，看師上講筵。","都人禮白足，施者散金錢。","方便無非教，經行不廢禪。","還知習居士，發論侍彌天。"]', '诗', 'shi', '', NULL, '海門潮別浩初師 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0780e393-42ed-4de4-9a7d-a5c501420b47', '始聞蟬有懷白賓客去歲白有聞蟬見寄詩云秖應催我老兼遣報君知之句', '始闻蟬有懷白賓客去歲白有闻蟬见寄诗云秖應催我老兼遣報君知之句', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["蟬韻極清切，始聞何處悲。","人含不平意，景值欲秋時。","此歲方晼晚，誰家無別離。","君言催我老，已是去年詩。"]', '["蟬韻極清切，始闻何处悲。","人含不平意，景值欲秋时。","此歲方晼晚，誰家無別離。","君言催我老，已是去年诗。"]', '诗', 'shi', '', NULL, '始聞蟬有懷白賓客去歲白有聞蟬見寄詩云秖應催我老兼遣報君知之句 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e308a55-cbe9-4a84-809c-a02db184bcbc', '贈樂天', '贈乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["一別舊遊盡，相逢俱涕零。","在人雖晚達，於樹似冬青。","痛飲連宵醉，狂吟滿坐聽。","終期拋印綬，共占少微星。"]', '["一別旧游尽，相逢俱涕零。","在人雖晚達，於樹似冬青。","痛饮連宵醉，狂吟满坐听。","終期拋印綬，共占少微星。"]', '诗', 'shi', '', NULL, '贈樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58ca8b46-9f12-44d1-a31a-6ec77c001a8d', '到郡未浹日登西樓見樂天題詩因即事因寄', '到郡未浹日登西楼见乐天題诗因即事因寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["湖上收宿雨，城中無晝塵。","樓依新柳貴，池帶亂苔春。","雲水正一望，簿書來繞身。","烟波洞庭路，愧彼扁舟人。"]', '["湖上收宿雨，城中無晝塵。","楼依新柳貴，池带亂苔春。","云水正一望，簿书来繞身。","烟波洞庭路，愧彼扁舟人。"]', '诗', 'shi', '', NULL, '到郡未浹日登西樓見樂天題詩因即事因寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('471b85aa-25ec-415f-b305-f22f35249b13', '秋夕不寐寄樂天', '秋夕不寐寄乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["洞戶夜簾卷，華堂秋簟清。","螢飛過池影，蛩思繞階聲。","老枕知將雨，高窗報欲明。","何人諳此景，遠問白先生。"]', '["洞戶夜簾卷，华堂秋簟清。","螢飞過池影，蛩思繞階声。","老枕知將雨，高窗報欲明。","何人諳此景，远问白先生。"]', '诗', 'shi', '', NULL, '秋夕不寐寄樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8125932-c457-4eed-9772-311144659aed', '冬日晨興寄樂天', '冬日晨兴寄乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["庭樹曉禽動，郡樓殘點聲。","燈挑紅燼落，酒煖白光生。","髪少嫌梳利，顏衰恨鏡明。","獨吟誰應和，須寄洛陽城。"]', '["庭樹晓禽动，郡楼殘点声。","灯挑紅燼落，酒煖白光生。","髪少嫌梳利，顏衰恨镜明。","独吟誰應和，須寄洛陽城。"]', '诗', 'shi', '', NULL, '冬日晨興寄樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3d914d8-b1a9-4911-9b9c-52d27471dd12', '答樂天見憶', '答乐天见憶', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["與老無期約，到來如等閑。","偏傷朋友盡，移興子孫間。","筆底心無毒，杯前膽不{犭豖}。","唯餘憶君夢，飛過武牢關。"]', '["與老無期約，到来如等闲。","偏傷朋友尽，移兴子孫间。","笔底心無毒，杯前膽不{犭豖}。","唯餘憶君梦，飞過武牢关。"]', '诗', 'shi', '', NULL, '答樂天見憶 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12f10b51-3e41-441a-9249-f68d07f4fa63', '和樂天誚失婢牓者', '和乐天誚失婢牓者', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["把鏡朝猶在，添香夜不歸。","鴛鴦拂瓦去，鸚鵡透籠飛。","不逐張公子，即隨劉武威。","新知正相樂，從此脫青衣。"]', '["把镜朝猶在，添香夜不归。","鴛鴦拂瓦去，鸚鵡透籠飞。","不逐張公子，即隨劉武威。","新知正相乐，從此脫青衣。"]', '诗', 'shi', '', NULL, '和樂天誚失婢牓者 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8fc5f39-46b6-4b4f-a8fc-015229c25da9', '八月十五日夜半雲開然後翫月因書一時之景寄呈樂天', '八月十五日夜半云开然後翫月因书一时之景寄呈乐天', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["半夜碧雲收，中天素月流。","開城邀好客，置酒賞清秋。","影透衣香潤，光凝歌黛愁。","斜輝猶可翫，移宴上西樓。"]', '["半夜碧云收，中天素月流。","开城邀好客，置酒賞清秋。","影透衣香潤，光凝歌黛愁。","斜輝猶可翫，移宴上西楼。"]', '诗', 'shi', '', NULL, '八月十五日夜半雲開然後翫月因書一時之景寄呈樂天 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('044d7c1c-3445-430c-aa4d-800f5904ac77', '秋日書懷寄白賓客', '秋日书懷寄白賓客', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["州遠雄無益，年高健亦衰。","興情逢酒在，筋力上樓知。","蟬噪芳意盡，鴈來愁望時。","商山紫芝客，應不向秋悲。"]', '["州远雄無益，年高健亦衰。","兴情逢酒在，筋力上楼知。","蟬噪芳意尽，鴈来愁望时。","商山紫芝客，應不向秋悲。"]', '诗', 'shi', '', NULL, '秋日書懷寄白賓客 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f444611-635b-4274-92d1-a9a33efd32b0', '詶樂天初冬早寒見寄', '詶乐天初冬早寒见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["乍起衣猶冷，微吟帽半欹。","霜凝南屋瓦，雞唱後園枝。","洛水碧雲曉，吳宮黃葉時。","兩傳千里意，書札不如詩。"]', '["乍起衣猶冷，微吟帽半欹。","霜凝南屋瓦，雞唱後园枝。","洛水碧云晓，吳宮黄葉时。","兩傳千里意，书札不如诗。"]', '诗', 'shi', '', NULL, '詶樂天初冬早寒見寄 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d862e17f-e7da-43f5-a1f8-e537e482e953', '和令狐相公郡齋對紫薇花', '和令狐相公郡斋对紫薇花', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["明麗碧天霞，丰茸紫綬花。","香聞荀令宅，豔入孝王家。","幾歲自榮樂，高情方歎嗟。","有人移上苑，猶足占年華。"]', '["明丽碧天霞，丰茸紫綬花。","香闻荀令宅，豔入孝王家。","幾歲自榮乐，高情方歎嗟。","有人移上苑，猶足占年华。"]', '诗', 'shi', '', NULL, '和令狐相公郡齋對紫薇花 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ea6fac3-e3d7-4be0-9a91-da96abf23fda', '令狐相公俯贈篇章斐然仰謝', '令狐相公俯贈篇章斐然仰謝', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鄂渚臨流別，梁園衝雪來。","旅愁隨凍釋，歡意待花開。","城曉烏頻起，池春鴈欲回。","飲和心自醉，何必管弦催。"]', '["鄂渚臨流別，梁园衝雪来。","旅愁隨凍釋，歡意待花开。","城晓烏頻起，池春鴈欲回。","饮和心自醉，何必管弦催。"]', '诗', 'shi', '', NULL, '令狐相公俯贈篇章斐然仰謝 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9015a136-058d-4c3b-9540-6cf29ff7b899', '酬令狐相公早秋見寄', '酬令狐相公早秋见寄', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["公來第四秋，樂國號無愁。","軍士遊書肆，商人占酒樓。","熊羆交黑矟，賓客滿青油。","今日文章主，梁王不姓劉。"]', '["公来第四秋，乐国號無愁。","軍士游书肆，商人占酒楼。","熊羆交黑矟，賓客满青油。","今日文章主，梁王不姓劉。"]', '诗', 'shi', '', NULL, '酬令狐相公早秋見寄 劉禹錫 shi');
